// 判断推理 3200 题册（自动从 PDF 提取，全部单选；图推题 img=整题大图）
window.KG_JUDGMENT = {"updatedAt":"2026-10-16","total":793,"sections":[{"id":"graph","name":"图形推理","items":[{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】数量类。数三角形个数寻找规律，三角形个数依次为3、3、4、4、4，没有\n规律。此时还可以数每个图中三角形个数最多的情况，依次是3、4、5、6、7，所以要选\n有8 个三角形的图形。\n故正确答案为A。","img":"assets/data/judgment_img/j_0000.png"},{"q":"请从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】属性类。发现每幅图均是对称图形，对称轴方向依次为：横轴、竖轴、横竖\n轴、横竖轴、竖轴，问号处应填入横轴对称图形。\n故正确答案为D。","img":"assets/data/judgment_img/j_0001.png"},{"q":"请从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】位置类。每个黑色图形与其中一个图形的外框形状是一样的。\n故正确答案为D。","img":"assets/data/judgment_img/j_0002.png"},{"q":"请从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】位置类。题干每图均由两个元素组成，其相对位置关系依次为：右内接、下\n内接、左内接、上内接、右内接，故问号处图形的两元素位置关系应为下内接。\n故正确答案为B。","img":"assets/data/judgment_img/j_0003.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】位置类。横向观察，黑点逆时针每次移动两步，且只在有点的地方移动，问\n号前一图移动两步可以到达的位置只有C 项。\n故正确答案为C。","img":"assets/data/judgment_img/j_0004.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】样式类。观察图形发现，每一行中均有相同元素出现，第一行图形均有圆，\n第二行均有三角形，而第三行的特点是均有菱形。\n故正确答案为B。","img":"assets/data/judgment_img/j_0005.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】样式类。由第一行可知其规律为求异，第二行验证发现规律成立，因此第三\n行去同存异得到的是A。\n故正确答案为A。","img":"assets/data/judgment_img/j_0006.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】属性类。每个图都是轴对称图形，对称轴依次逆时针旋转45°，问号处图\n形的对称轴方向应为纵向，只有A 项符合。\n故正确答案为A。","img":"assets/data/judgment_img/j_0157.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】数量类。每个图形均有一个圆与直线相切，考虑数切点。每个图形均有且只\n有两个曲直交点，且其中一个为切点，观察选项，只有C 项符合。\n故正确答案为C。","img":"assets/data/judgment_img/j_0007.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】观察发现，第一图内部的小图形是第二图外围的大图形，以此类推，问号处\n图形外围为方块，排除AC 项；内部小图形颜色依次为黑、白、线条、黑、白，因此为\n“黑、白、线条”颜色循环，问号处图形内部小图形颜色为线条，排除D。\n故正确答案为B。\n第二组：","img":"assets/data/judgment_img/j_0008.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】数量类。图形凌乱且元素较多，考虑元素规律，每格中有四种不同元素，符\n合此规律的为D 项。\n故正确答案为D。","img":"assets/data/judgment_img/j_0009.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】位置类。题干图形各部分都是点相交，选择C 项。A 项三角形与梯形间为线\n相交，B 项四图形间均为线相交，D 项上部分两个三角形存在线相交。\n故正确答案为C。","img":"assets/data/judgment_img/j_0010.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】数量类。图形凌乱，第一行三图都为一笔画，第二行图一由两部分组成为两\n笔画，第三行图二由三部分组成为三笔画，总结规律，第一行均为一笔画图形，第二行两\n笔画，第三行三笔画；A 项两笔画，B 项两笔画，C 项一笔画，D 项三笔画，当选。\n故正确答案为D。","img":"assets/data/judgment_img/j_0011.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】数量类。每个汉字封闭空间数量依次为2、3、4、5，问号处应填入有6 个\n封闭空间的汉字，A、B、C、D 四个选项的封闭空间数依次为4，6，4，3。\n故正确答案为B。","img":"assets/data/judgment_img/j_0012.png"},{"q":"把下面的六组图形分为两类，使每一类图形都有各自的共同特征和规律，分类正确的一项是（  ）","options":["①④⑥，②③⑤","①④⑤，②③⑥","①③⑤，②④⑥","①②③，④⑤⑥"],"a":2,"e":"【答案】C\n【解析】位置类。6 个图形组成元素完全相同，但每个元素的位置不同。仔细观察发\n现三角形和正方形所在的封闭空间不同，考虑功能信息。第二步，根据规律进行分组。图\n①③⑤中，小正方形位于大长方形这一单独区域内，小三角形位于圆形和小长方形的公共\n区域内；图②④⑥中，小正方形位于圆形与大长方形公共区域内，小三角形位于两个长方\n形的公共区域内，分成两组。\n故正确答案为C。","img":"assets/data/judgment_img/j_0013.png"},{"q":"把下面的六个图形分为两类，使每一类都有各自共同的特征或规律，分类正确的一项是（  ）","options":["①②⑥，③④⑤","①③⑤，②④⑥","①②④，③⑤⑥","①③④，②⑤⑥"],"a":3,"e":"【答案】D\n【解析】位置类。①③④黑点都在三角形左侧，②⑤⑥黑点在三角形右侧。\n故正确答案为D。","img":"assets/data/judgment_img/j_0155.png"},{"q":"把下面的六个图形分为两类，使每一类都有各自共同的特征和规律，分类正确的一项是（  ）","options":["①③④，②⑤⑥","①③⑥，②④⑤","①④⑥，②③⑤","①③⑤，②④⑥"],"a":2,"e":"【答案】C\n【解析】属性类。观察可知①④⑥都为轴对称，②③⑤为中心对称。\n故正确答案是C。","img":"assets/data/judgment_img/j_0156.png"},{"q":"把下面的六个图形分为两类，使每一类都有各自共同的特征和规律，分类正确的一项是（  ）","options":["①⑤⑥，②③④","①③⑤，②④⑥","①②③，④⑤⑥","①②⑥，③④⑤"],"a":1,"e":"【答案】B\n【解析】属性类。观察发现①③⑤均为曲线图形，②④⑥均为直线图形。\n故正确答案是B。","img":"assets/data/judgment_img/j_0164.png"},{"q":"把下面的六个图形分为两类，使每一类都有各自共同的特征和规律，分类正确的一项（  ）","options":["①②③，④⑤⑥","①⑤⑥，②③④","①②④，③⑤⑥","①④⑥，②③⑤"],"a":2,"e":"【答案】C\n【解析】数量类。观察发现①②④图形均由一个整体构成，③⑤⑥由多部分构成。\n故正确答案为C。","img":"assets/data/judgment_img/j_0158.png"},{"q":"把下面的六组图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①④⑥，②③⑤","①③⑥，②④⑤","①③④，②⑤⑥","①②④，③⑤⑥"],"a":0,"e":"【答案】A\n【解析】位置类。每幅图都由左右两图形组成，观察发现①④⑥左图内部图形为右图\n外部图形，②③⑤左侧外部图形为右侧内部图形。\n故正确答案为A。\n第三组：","img":"assets/data/judgment_img/j_0159.png"},{"q":"从所给出的四个选项中，选择最合适的一个填入问号处，使之呈现一定规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】样式类。第三幅图为第一幅图逆时针转90°与第二幅图顺时针转90°叠加\n得到。按此规律，第二段图形问号处应为D 项。\n故正确答案为D。","img":"assets/data/judgment_img/j_0014.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】样式类。第一段中1 图和2 图求异得到3 图；第二段应用此规律，只有A 项\n符合。\n故正确答案为A。","img":"assets/data/judgment_img/j_0015.png"},{"q":"从所给出的四个选项中，选择最合适的一个填入问号处，使之呈现一定规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】位置类。图形从左到右为相离相交循环。故问号处应填两个图形相交。匹配\n答案为C。\n故正确答案为C。","img":"assets/data/judgment_img/j_0016.png"},{"q":"从所给出的四个选项中，选择最合适的一个填入问号处，使之呈现一定规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】位置类。第一横行第一幅图顺时针转90°构成第二幅图。第二幅图左右翻\n转构成第三幅图。故问号处应填入与前图左右翻转的图形，故答案为A。\n故正确答案为A。","img":"assets/data/judgment_img/j_0017.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】样式类。第一段中1 图和2 图求同，只保留白色部分得到3 图；第二段应用\n此规律，只有A 项符合。\n故正确答案为A。","img":"assets/data/judgment_img/j_0018.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①③④，②⑤⑥","①③⑤，②④⑥","①②⑥，③④⑤","①④⑥，②③⑤"],"a":1,"e":"【答案】B\n【解析】属性类。①③⑤为中心对称图形，②④⑥为轴对称图形。\n故正确答案为B。","img":"assets/data/judgment_img/j_0162.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①④⑥，②③⑤","①②③，④⑤⑥","①③⑥，②④⑤","①⑤⑥，②③④"],"a":0,"e":"【答案】A\n【解析】位置类。①④⑥为线相交图形，②③⑤为点相交图形。\n故正确答案为A。","img":"assets/data/judgment_img/j_0163.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①②⑥，③④⑤","①③⑥，②④⑤","①④⑤，②③⑥","①③④，②⑤⑥"],"a":1,"e":"【答案】B\n【解析】位置类。两条线没有形成三角形，考虑线之间位置，\n在经过三个面公共点的线上画箭头，另外带线的面在箭头左的①③⑥分一组，在箭头\n右的②④⑤分另一组。\n故正确答案为B。","img":"assets/data/judgment_img/j_0169.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①③⑤，②④⑥","①②⑤，③④⑥","①④⑤，②③⑥","①③④，②⑤⑥"],"a":2,"e":"【答案】C\n【解析】位置类。①④⑤两个箭头的位置关系为垂直，②③⑥两个箭头的位置关系为\n平行。\n故正确答案为C。","img":"assets/data/judgment_img/j_0165.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①③⑤，②④⑥","①③⑥，②④⑤","①③④，②⑤⑥","①④⑤，②③⑥"],"a":2,"e":"【答案】C\n【解析】数量类。①③④三个相同颜色的连在一起，②⑤⑥两个相同颜色的连在一\n起。\n故正确答案为C。\n第四组：","img":"assets/data/judgment_img/j_0166.png"},{"q":"从所给四个选项中，选择最合适的一个填入问号处，使之呈现一定规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】数量类。第一幅图3 个圆、1 个直角三角形、1 个五角星；第二幅图2 个\n圆、2 个五角星、1 个六角星；第三幅图3 个五角星、1 个六角形、1 个直角三角形，存在\n相同元素数量规律具有周期性：311；221；311，依照此规律，问号处填221。\n故正确答案为B。","img":"assets/data/judgment_img/j_0019.png"},{"q":"从所给四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】属性类。第一行图形的对称轴分别为横、斜、竖，规律为对称轴顺时针旋转\n45 度；第二行对称轴依然为顺时针旋转45 度；依照此规律，第三行问号处填横向对称轴\n的图形。\n故正确答案为B。","img":"assets/data/judgment_img/j_0020.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】数量类。第一段所有图形均由13 条直线构成；第二段前两个图形均由14 条\n直线构成，问号处图形应由14 条直线构成，只有C 项符合。\n故正确答案为C。","img":"assets/data/judgment_img/j_0021.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】位置类。第一段，图形中第一列和第三列黑格向上移动一格，第二列和第四\n列黑格向下移动一格；第二段应用此规律，只有D 项符合。\n故正确答案为D。","img":"assets/data/judgment_img/j_0022.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】位置类。第一段中都是两个图形线相交在一起，相交的位置为上、左、下，\n第二段前两个图形都是点相交，相交的位置为上和左，问号处图形应为点相交且相交位置\n在下方，且题干图形均为直线图形，只有C 项符合。\n故正确答案为C。","img":"assets/data/judgment_img/j_0023.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①②④，③⑤⑥","①②⑤，③④⑥","①③④，②⑤⑥","①③⑥，②④⑤"],"a":3,"e":"【答案】D\n【解析】数量类。发现①③⑥三图每个图的曲线与直线的交点均为2；②④⑤三图每\n个图的曲线与直线交点均为1。\n故正确答案为D。","img":"assets/data/judgment_img/j_0167.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①④⑥，②③⑤","①③⑤，②④⑥","①②④，③⑤⑥","①②③，④⑤⑥"],"a":3,"e":"【答案】D\n【解析】属性类。每组图都有曲线图形和直线图形，发现①②③中每图包含1 个直线\n图形；④⑤⑥中每图包含2 个直线图形。\n故正确答案为D。","img":"assets/data/judgment_img/j_0168.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①③④，②⑤⑥","①④⑥，②③⑤","①②④，③⑤⑥","①③⑥，②④⑤"],"a":0,"e":"【答案】A\n【解析】属性类。①③④对称轴的方向为斜向；②⑤⑥三图对称轴的方向为竖向，故\n可以按照对称轴方向来分组。\n故正确答案为A。","img":"assets/data/judgment_img/j_0174.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①②④，③⑤⑥","①③⑥，②④⑤","①③⑤，②④⑥","①⑤⑥，②③④"],"a":0,"e":"【答案】A\n【解析】位置类。①②④三图内部元素无包含关系；③⑤⑥三图内部元素存在包含关\n系。\n故正确答案为A。","img":"assets/data/judgment_img/j_0170.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①④⑥，②③⑤","①③⑤，②④⑥","①②⑤，③④⑥","①②④，③⑤⑥"],"a":3,"e":"【答案】D\n【解析】数量类。①②④均为一笔画构成，③⑤⑥均为两笔画构成。\n故正确答案为D。\n第五组：","img":"assets/data/judgment_img/j_0171.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】位置类。图形依次逆时针旋转90 度，第一个图到第二个图眼睛翻转，嘴巴\n不变，第二个图到第三个图眼睛不变，嘴巴翻转；第二行验证后，跟第一行规律一样。\n故正确答案为C。","img":"assets/data/judgment_img/j_0024.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】数量类。第一段中图形均有14 条直线，第二段运用此规律，前两个图形均\n有12 条直线，问号处图形应有12 条直线，只有D 项符合。\n故正确答案为D。","img":"assets/data/judgment_img/j_0025.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】数量类。相同形状面的个数，分别为1、2、3、4、5。问号处图形应该有6\n个相同形状的面。\n故正确答案为A。","img":"assets/data/judgment_img/j_0026.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】样式类。第一个图形中的“辶”和第二个图形中的“云”组成了第三个图\n“运”，\n去同求异。“目”和“夫”去掉相同元素“二”，得到“囚”。\n故正确答案为B。","img":"assets/data/judgment_img/j_0027.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】数量类。给出图形均由外部图形和内部图形构成，公共边呈现0、1、2 的规\n律，第二组图形应该也是0、1、2 的规律，排除A、D 项。观察公共边为两条的图形会发\n现，黑色图形占用了外边图形的部分边长。\n故正确答案为C。","img":"assets/data/judgment_img/j_0028.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①③④，②⑤⑥","①⑤⑥，②③④","①②⑥，③④⑤","①②④，③⑤⑥"],"a":1,"e":"【答案】B\n【解析】位置类。观察6 组图形，属于分组分类题型，进一步观察特征，会发现每个\n图形中都有两个元素相同，而这相同的元素有的是相邻的，有的是相隔的。相邻为一组，\n相隔为一组。\n故正确答案为B。","img":"assets/data/judgment_img/j_0029.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①②⑤，③④⑥","①④⑥，②③⑤","①③④，②⑤⑥","①③⑤，②④⑥"],"a":1,"e":"【答案】B\n【解析】属性类。题干给出的所有图形都是轴对称图形。横向对称轴的是②③⑤；而\n有竖向对称轴①④⑥是一组。\n故正确答案为B。","img":"assets/data/judgment_img/j_0030.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①③⑥，②④⑤","①③⑤，②④⑥","①③④，②⑤⑥","①⑤⑥，②③④"],"a":2,"e":"【答案】C\n【解析】位置类。题干出现功能信息，小黑点。每个图形中均有两个黑点，如果将黑\n点连线，与图形内部线条有垂直或平行两种位置关系。在①③④中，黑点连线与图形内部\n线条平行，而在②⑤⑥中，黑点连线与图形内部线条垂直。由此可以将①③④分为一组，\n②⑤⑥分为一组。\n故正确答案为C。","img":"assets/data/judgment_img/j_0179.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①②⑥，③④⑤","①②③，④⑤⑥","①④⑤，②③⑥","①④⑥，②③⑤"],"a":3,"e":"【答案】D\n【解析】位置类。①④⑥元素不同，②③⑤元素相同。\n故正确答案为D。","img":"assets/data/judgment_img/j_0175.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①③⑥，②④⑤","①②⑤，③④⑥","①③④，②⑤⑥","①④⑤，②③⑥"],"a":0,"e":"【答案】A\n【解析】位置类。①③⑥两个小黑点标记不同面；②④⑤标记相同面。\n故正确答案为A。\n第六组：","img":"assets/data/judgment_img/j_0176.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】属性类，对称性。图段一每幅图对称轴方向是依次顺时针旋转45°。依照\n此规律图段二问号处是右上至左下的一条对称轴。\n故正确答案为C。","img":"assets/data/judgment_img/j_0031.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】位置类。黑圆每次逆时针移动两格，空位每次顺时针移动一格，问号处应该\n出现在第三行中间位置。\n故正确答案为C。","img":"assets/data/judgment_img/j_0032.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】属性类。每幅图均由曲线图形和直线图形构成，曲线图形和直线图形，上下\n交替出现，可排除BC。且每幅图均由三个面组成，排除D。\n故正确答案为A。","img":"assets/data/judgment_img/j_0033.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】数量类。每一行曲线数量均为1、2、3，因此问号处曲线数也应为3。\n故正确答案为B。","img":"assets/data/judgment_img/j_0034.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】样式类，黑白叠加。黑白叠加规律：黑+白=黑，黑+黑=白，白+黑=黑，白+\n白=白。第二行验证此规律可行，第三行运用此规律。\n故正确答案为A。","img":"assets/data/judgment_img/j_0035.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】数量类。小正方形外部与直线的交点个数依次为：1、2、3、4，问号处小正\n方形外部与直线的交点个数应为5，只有D 项符合。\n故正确答案为D。","img":"assets/data/judgment_img/j_0036.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】数量类。所有图形均为一笔画图形，故问号处应为一笔画图形，只有C 项符\n合。\n故正确答案为C。","img":"assets/data/judgment_img/j_0037.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①④⑥，②③⑤","①②③，④⑤⑥","①⑤⑥，②③④","①③⑤，②④⑥"],"a":3,"e":"【答案】D\n【解析】位置类。①③⑤中黑点处于线条上，②④⑥中黑点处于线条的交点处。\n故正确答案为D。","img":"assets/data/judgment_img/j_0184.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①②⑤，③④⑥","①②③，④⑤⑥","①③⑤，②④⑥","①②⑥，③④⑤"],"a":2,"e":"【答案】C\n【解析】数量类，笔画数。②④⑥为一笔画，①③⑤均有4 个奇点两笔构成。\n故正确答案为C。","img":"assets/data/judgment_img/j_0180.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①③④，②⑤⑥","①②⑤，③④⑥","①③⑥，②④⑤","①④⑤，②③⑥"],"a":0,"e":"【答案】A\n【解析】位置类。①③④中小圆处于较小的面中，②⑤⑥中小圆处于较大的面中。\n故正确答案为A。\n第七组：","img":"assets/data/judgment_img/j_0181.png"},{"q":"从所给的四个选项中，选出最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】位置类。题干图形相交、相切交替出现，所以问号处应该选相切的图形。\n故正确答案为D。","img":"assets/data/judgment_img/j_0038.png"},{"q":"从所给的四个选项中，选出最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】数量类。圆内交点的数量依次为0、1、2、3、4，所以问号处应选择圆内有\n5 个点的图形。\n故正确答案为C。","img":"assets/data/judgment_img/j_0039.png"},{"q":"从所给的四个选项中，选出最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】属性类，对称性。第一段图一2 个图形对称轴平行，图二2 个图形对称轴相\n交，图三2 个图形对称轴垂直；第二段图一2 个图形对称轴平行，二图2 个图形对称轴相\n交，三图应该选择2 个图形对称轴垂直的D 项。\n故正确答案为D。","img":"assets/data/judgment_img/j_0040.png"},{"q":"从所给的四个选项中，选出最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】样式类。图一和图二内部线条求异得到图三；第三行按照此规律只有C 符\n合。\n故正确答案为C。","img":"assets/data/judgment_img/j_0041.png"},{"q":"从所给的四个选项中，选出最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】数量类，面。题干图形均有4 个面，因此问号处应该也是4 个面的图形。\n故正确答案为C。","img":"assets/data/judgment_img/j_0042.png"},{"q":"从所给的四个选项中，选出最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】数量类，线。第一段中，三个图形的笔画数均为1，第二段中前两个图形的\n笔画数也为1，所以问号处的图形笔画数应为1。\n故正确答案为C。","img":"assets/data/judgment_img/j_0043.png"},{"q":"从所给的四个选项中，选出最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】属性类，对称性。第一段中，三个图形均为轴对称图形，第二段前两个图形\n均为轴对称图形，所以问号处的图形也应为轴对称图形。\n故正确答案为B。","img":"assets/data/judgment_img/j_0044.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①②⑥，③④⑤","①③④，②⑤⑥","①④⑤，②③⑥","①④⑥，②③⑤"],"a":0,"e":"【答案】A\n【解析】位置类，静态位置。①②⑥相交于一条线，③④⑤相交于一点。\n故正确答案为A。","img":"assets/data/judgment_img/j_0187.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①②⑥，③④⑤","①②⑤，③④⑥","①②③，④⑤⑥","①③⑤，②④⑥"],"a":1,"e":"【答案】B\n【解析】数量类，笔画数。图形的笔画数，①②⑤为一笔画，③④⑥为两笔画。\n故正确答案为B。","img":"assets/data/judgment_img/j_0185.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①③④，②⑤⑥","①③⑥，②④⑤","①②③，④⑤⑥","①③⑤，②④⑥"],"a":0,"e":"【答案】A\n【解析】位置类。①③④的小圆标识三角形最大的内角，②⑤⑥的小圆标识三角形最\n小的内角。\n故正确答案为A。\n第八组：","img":"assets/data/judgment_img/j_0186.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】位置类。小三角形与正方形重合边的位置沿顺时针方向平移，所以问号处图\n形重合边的位置应该如AB 两项图形所示，排除CD。三角形的顶点（正方形内部的顶点）\n沿顺时针方向平移，所以问号处顶点应该在正方形的左下位置，排除A。\n故正确答案为B。","img":"assets/data/judgment_img/j_0045.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】属性类。图形的对称轴每次沿顺时针方向旋转45°，所以问号处图形的对\n称轴应该是右上方到左下方，所以排除AC。且图一、图三、图五中有一条线与图形对称\n轴重合，图二、图四则不重合，故问号处图形应该不重合，排除D。\n故正确答案为B。","img":"assets/data/judgment_img/j_0046.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】数量类，部分数。第一段中三幅图，黑点部分数依次为1 部分、2 部分、3\n部分。将此规律应用到第二段中，则问号处应填入3 部分的图形，只有A 项符合。\n故正确答案为A。","img":"assets/data/judgment_img/j_0047.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】样式类。将图一和图二求异得到的图形，顺时针旋转90 度可得图三。\n故正确答案为D。","img":"assets/data/judgment_img/j_0048.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①②⑤，③④⑥","①④⑤，②③⑥","①③⑥，②④⑤","①②③，④⑤⑥"],"a":2,"e":"【答案】C\n【解析】属性类，对称性。图形①③⑥既是轴对称图形又是中心对称图形，图形②④\n⑤均为轴对称图形，分为两组。\n故正确答案为C。","img":"assets/data/judgment_img/j_0049.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】数量类，面。每幅图均出现黑色粗线条和空白区域，优先考虑面数量。题干\n图形均只有1 个面，问号处应填入只有1 个面的图形\n故正确答案为A。","img":"assets/data/judgment_img/j_0172.png"},{"q":"下从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】位置类。题干中图1 到图3，三个小图形依次顺时针移动一步。因此问号处\n正方形应位于右上方，圆形应位于左上方，三角形应位于左下方。\n故正确答案为C。","img":"assets/data/judgment_img/j_0173.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①②③，④⑤⑥","①②⑥，③④⑤","①④⑥，②③⑤","①③④，②⑤⑥"],"a":1,"e":"【答案】B\n【解析】数量类。①②⑥中黑色图形的形状、个数与白色图形相同，③④⑤中黑色图\n形形状与白色图形不完全相同。\n故正确答案为B。","img":"assets/data/judgment_img/j_0190.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①④⑤，②③⑥","①②⑤，③④⑥","①④⑥，②③⑤","①③④，②⑤⑥"],"a":0,"e":"【答案】A\n【解析】位置类。①④⑤中黑点出现在特殊三角形的左边，②③⑥中黑点出现在特殊\n三角形的右边。\n故正确答案为A。","img":"assets/data/judgment_img/j_0188.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①③④，②⑤⑥","①②⑥，③④⑤","①③⑤，②④⑥","①④⑥，②③⑤"],"a":2,"e":"【答案】C\n【解析】数量类。每幅图内部均有与外框形状相同的图形，且其所占面积大小不同。\n①③⑤中该图形是内部所有图形中面积最小的，②④⑥中是面积最大的。\n故正确答案为C。\n第九组：","img":"assets/data/judgment_img/j_0189.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】数量类，笔画数。题干均为一笔画图形，只有C 符合。\n故正确答案为C。","img":"assets/data/judgment_img/j_0050.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】数量类。直线与曲线的交点数，分别为：4、6、2、4、8，并且已知图形中\n的曲线数量依次为：2、3、1、2、4。曲直交点数为曲线数的两倍，所以问号处图形也应\n该符合该规律。只有D 项符合。\n故正确答案为D。","img":"assets/data/judgment_img/j_0051.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】位置类。1 图中白色部分不变，黑色部分顺时针旋转90°即可得到2 图，2\n图中黑色部分不变，白色逆时针旋转90°即可得到3 图，3 图白色部分不变，黑色部分顺\n时针旋转90°即可得4 图，4 图中黑色部分不变，白色逆时针旋转90°即可得5 图，所\n以图5 白色部分不变，黑色部分顺时针旋转90°即可得到问号处答案，A 项符合。\n故正确答案为A。","img":"assets/data/judgment_img/j_0052.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】数量类，素。题干图形内部小元素种类，依次为1、2、3，则问号处的图形\n应有4 种小元素。故正确答案为D。","img":"assets/data/judgment_img/j_0053.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】样式类，黑白叠加。黑白叠加规律：黑+白=黑；黑+黑=白；白+黑=黑；白+\n白=黑。在第三行应用此规律，只有C 项符合。\n故正确答案为C。","img":"assets/data/judgment_img/j_0054.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①②③，④⑤⑥","①③⑥，②④⑤","①⑤⑥，②③④","①④⑥，②③⑤"],"a":2,"e":"【答案】C\n【解析】位置类，功能元素。图形①⑤⑥中黑点标记的是曲直交点，图形②③④中黑\n点标记的是直线交点，分为两组。\n故正确答案为C。","img":"assets/data/judgment_img/j_0055.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①②④，③⑤⑥","①③⑤，②④⑥","①②⑥，③④⑤","①④⑥，②③⑤"],"a":0,"e":"【答案】A\n【解析】位置类。图形④顺时针旋转90 度得到图形①，图形①顺时针旋转90 度得到\n图形②；图形③逆时针旋转90 度得到图形⑥，图形⑥逆时针旋转90 度得到图形⑤。因此\n分为两组，即①②④一组，③⑤⑥一组。\n故正确答案为A。","img":"assets/data/judgment_img/j_0056.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①②⑥，③④⑤","①③④，②⑤⑥","①④⑥，②③⑤","①③⑤，②④⑥"],"a":2,"e":"【答案】C\n【解析】数量类。规律一：①④⑥三图内部线条均为4 条，②③⑤内部线条均为3\n条。C 项符合；规律二：①④⑥三图外部线条均为7 条，②③⑤外部线条均为8 条。C 项\n符合。\n故正确答案为C。","img":"assets/data/judgment_img/j_0193.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①③④，②⑤⑥","①②⑥，③④⑤","①④⑤，②③⑥","①④⑥，②③⑤"],"a":2,"e":"【答案】C\n【解析】属性类，对称性。①④⑤三图对称轴均与图形中两条线构成垂直位置关系，\n②③⑥三图对称轴均经过图形两个顶点。\n故正确答案为C。","img":"assets/data/judgment_img/j_0191.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①②③，④⑤⑥","①②⑤，③④⑥","①③⑤，②④⑥","①③④，②⑤⑥"],"a":3,"e":"【答案】D\n【解析】数量类。①③④三图中黑色块形状相同，②⑤⑥三图中黑色块的形状均不相\n同。\n故正确答案为D。\n第十组：","img":"assets/data/judgment_img/j_0192.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】属性类，对称性。白色圆点组成的图形，依次为轴对称、中心对称、轴对\n称、中心对称，交替出现，问号处选择一个白色圆点组成的图形是中心对称的图形，只有\nA 项符合。\n故正确答案为A。","img":"assets/data/judgment_img/j_0057.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】数量类。题干中图形均为一笔画，A 项图形奇点数为2，为一笔画图形，符\n合。而B、C、D 项图形奇点数均为4，为两笔画图形。\n故正确答案为A。","img":"assets/data/judgment_img/j_0058.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】数量类。题干图形扇形的角度，依次为0°、45°、90°、135°、\n180°、？问号扇形的角度为225°，只有A 项符合。\n故正确答案为A。","img":"assets/data/judgment_img/j_0059.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】样式类，去同求异。第一段图形1 图与2 图去同求异得到3 图，第二段应用\n此规律，只有D 项符合。\n故正确答案为D。","img":"assets/data/judgment_img/j_0060.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】数量类。所给图形中小黑点的数量依次为1、2、3、4，直线数量依次为4、\n3、2、1，均呈等差规律，所以问号处应填入一个小黑点数量为5、直线数量为0 的图\n形。\n故正确答案为C。","img":"assets/data/judgment_img/j_0061.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】数量类。题干图形面的数量均为3，故问号处应填入一个含有3 个面的图\n形。\n故正确答案为B。","img":"assets/data/judgment_img/j_0062.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】属性类。中心对称且轴对称、仅中心对称、中心对称且轴对称、仅中心对\n称、中心对称且轴对称，问号处图形应为仅中心对称的图形。\n故正确答案为B。","img":"assets/data/judgment_img/j_0063.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①②③，④⑤⑥","①②④，③⑤⑥","①③④，②⑤⑥","①③⑤，②④⑥"],"a":2,"e":"【答案】C\n【解析】数量类，面的数量。①③④两个面，②⑤⑥四个面。\n故正确答案为C。","img":"assets/data/judgment_img/j_0064.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①②④，③⑤⑥","①③⑤，②④⑥","①③⑥，②④⑤","①⑤⑥，②③④"],"a":3,"e":"【答案】D\n【解析】位置类，连接性。①⑤⑥为1 条边连接在一起，②③④为两条边连接在一\n起。\n故正确答案为D。","img":"assets/data/judgment_img/j_0065.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["①②⑥，③④⑤","①④⑥，②③⑤","①③④，②⑤⑥","①③⑤，②④⑥"],"a":0,"e":"【答案】A\n【解析】数量类，笔画数。题干黑色小点连接成以后的图形，①②⑥是2 笔画，③④\n⑤是1 笔画。\n故正确答案为A。\n第十一组：","img":"assets/data/judgment_img/j_0066.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】数量类。题干面的数量均为4，所以“？”处也应该有4 个面。A 为6 个\n面、B 为6 个面、C 为4 个面、D 为8 个面。\n故正确答案为C。","img":"assets/data/judgment_img/j_0067.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】位置类。两个黑格之间的间距分别为：0、1、2、3，构成等差数列。则\n“？”处两个黑格的间距应该为4。\n故正确答案为A。","img":"assets/data/judgment_img/j_0068.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】数量类。题干都只有4 种元素，且各个图之间并没有重复的元素。只有A 项\n符合。\n故正确答案为A。","img":"assets/data/judgment_img/j_0069.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】数量类。九宫格的命题形式，先横着看发现元素的数量分别为1、1、2，第\n二行的规律为1、2、5，是很明显的平方数相加，那么？应该选一个元素数量为10 的，\n只有C 选项符合。\n故正确答案为C。","img":"assets/data/judgment_img/j_0070.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】数量类。每个图左侧点的个数，第一行：3、2、5；第二行：1、3、4。前两\n个图相加等于第三个图。故最后一行：4+？=4，“？”处左侧有“0”个点。\n故正确答案为D。","img":"assets/data/judgment_img/j_0071.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】数量类。图形都是由一种元素组成，所以问号处也是一种元素组成，只有A\n项符合。\n故正确答案为A。","img":"assets/data/judgment_img/j_0072.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】样式类。黑＋黑=白，白+白=黑，黑+白=黑，白+黑=白，只有A 项符合。\n故正确答案为A。","img":"assets/data/judgment_img/j_0073.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】位置类。小竖线，每次顺时针每次走一个三角形，小横线，每次逆时针走一\n个三角形。\n故正确答案为C。","img":"assets/data/judgment_img/j_0074.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】数量类。部分数依次是1，2，3，4，5，？。问号处填入有6 部分的图形，\n只有D 项符合。\n故正确答案为D。","img":"assets/data/judgment_img/j_0194.png"},{"q":"请从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】数量类。圆—方=2，只有D 项符合。\n故正确答案为D。\n第十二组：","img":"assets/data/judgment_img/j_0075.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】属性类。对称轴在九宫格中呈现“米”字形，因此问号处应填横轴对称图\n形。只有A 项符合。\n故正确答案为A。","img":"assets/data/judgment_img/j_0076.png"},{"q":"请从所给的四个选项中，选择最合适的一项填在问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】样式类。第一组三幅图形的规律是第一幅图逆时针旋转90 度，第二幅图向\n右翻转再逆时针旋转90 度之后，两幅图拼在一起得到第三幅。只有A 项符合。\n故正确答案为A。","img":"assets/data/judgment_img/j_0077.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】属性类。图形都有竖对称轴，第二段都有横对称轴，只有D 项符合。\n故正确答案为D。","img":"assets/data/judgment_img/j_0078.png"},{"q":"从所给四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】考察面的数量规律。发现每个图形都有一个面，仅有D 选项符合。\n故正确答案为C。","img":"assets/data/judgment_img/j_0079.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】数量类。整体数：3，4，5，？。排除AB。然后分开数，分别是：２个白\n球，\n３个黑球，４个白球，接下来应该是５个黑球。\n故正确答案为D。","img":"assets/data/judgment_img/j_0080.png"},{"q":"从所给四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）A      B      C       D","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】样式类。第一列前两个图求异得到第三个图，第二列验证规律成立。第三列\n求异得到向左的箭头。\n故正确答案为C。","img":"assets/data/judgment_img/j_0081.png"},{"q":"从所给四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）A      B      C       D","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】数量类。题干全部为一笔画，选项中是一笔画的只有D 项。\n故正确答案为D。","img":"assets/data/judgment_img/j_0082.png"},{"q":"从所给四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）A      B      C       D","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】数量类。第一段直线数3、4、5 为等差数列，第二段直线数也为等差数列，\n8、10、所以问号处为12 条直线构成得到图形。\n故正确答案为C。","img":"assets/data/judgment_img/j_0083.png"},{"q":"从所给四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）A     B     C      D","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】数量类。每个图形均有小方块构成，第一段小方块个数都为5，第二段小方\n块数都为6。\n故正确答案为D。","img":"assets/data/judgment_img/j_0084.png"},{"q":"从所给四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】数量类。竖列第一图和第二图的黑点数相加等于第三幅图。第二列验证规律\n成立，所以问号处应该是2 个黑点，排除A 项。再观察发现每个图形都有角和直线。先数\n内角，横行观察没有规律，竖列观察，第一列3、4、7 是加法运算，第二列4、4、8，规\n律成立。第三列5+4=9。所以选2 个点9 个角的图形。\n故正确答案为D。\n第十三组：","img":"assets/data/judgment_img/j_0085.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】数量类。图形面的个数为：3、4、5、6、7，构成等差数列，问号处的图形\n应该有8 个面。\n故正确答案为B。","img":"assets/data/judgment_img/j_0086.png"},{"q":"把下面的六个图形分为两类，使每一类图形都由各自的共同特征成规律，分类正确的是（  ）","options":["①②④，③⑤⑥","①②⑥，③④⑤","①⑤⑥，②③④","①④⑤，②③⑥"],"a":3,"e":"【答案】D\n【解析】属性类。②③⑥图对称轴条数均为1 条，①④⑤对称轴条数均为2 条。\n故正确答案为D。","img":"assets/data/judgment_img/j_0087.png"},{"q":"把下面的六个图形分为两类，使每一类图形都由各自的共同特征成规律，分类正确的一项是（  ）","options":["①②④，③⑤⑥","①②⑤，③④⑥","①③⑤，②④⑥","①③⑥，②④⑤"],"a":3,"e":"【答案】D\n【解析】位置类。①③⑥图中两个图形由一条线连接，②④⑤图中两个图形由两条线\n连接。\n故正确答案为D。","img":"assets/data/judgment_img/j_0088.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】样式类，黑白叠加。白色长方形+白色椭圆形=白色五角星；白色三角形+白\n色三角形=白色椭圆；黑色椭圆+黑色五角星=黑色长方形；白色椭圆+黑色长方形=黑色三\n角形。照此规律仅C 项符合。\n故正确答案为C。","img":"assets/data/judgment_img/j_0153.png"},{"q":"从所给四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】样式类。元素组成不同，且属性和数量无规律，题干均为汉字，有相同部分\n“匕”，则？处应该有“匕”，只有C 项有“匕”。\n故正确答案为C。","img":"assets/data/judgment_img/j_0089.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】数量类。每一个图形分为两个部分，外面的图形的边的数量为3、4、5、\n6、7 所以排除掉C、D 选项，比较图形内部的点数，每一个图形中黑点的数目与白点的数\n目比较可以发现依次为黑点=白点，黑点<白点，黑点>白点，黑点=白点，黑点<白点所以\n再找一个黑点数目大于白点的即为正确答案。\n故正确答案为B。","img":"assets/data/judgment_img/j_0090.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】数量类。每幅图都包含一个封闭空间，封闭空间边数依次为3、4、5、6，\n问号处应填入有7 条边的选项。\n故正确答案为A。","img":"assets/data/judgment_img/j_0178.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】属性类，曲直性。所给图形由内外两部分组成，外部均为直线图形，内部均\n为曲线图形，问号处遵循同样规律。\n故正确答案为B。","img":"assets/data/judgment_img/j_0091.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】数量类。图形内部线条数量依次为2、3、4、5、6，问号处应选择内部线条\n有7 根的。\n故正确答案为D。","img":"assets/data/judgment_img/j_0092.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】第一段中，图一图二求同再顺时针旋转90°。第二段遵循同样的规律。\n故正确答案为B。\n第十四组：","img":"assets/data/judgment_img/j_0093.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】样式类。第一横行箭头有三个方向，向上、左上、右上，第二横行同样具有\n此规律，那么第三行缺一个左上的。符合规律的只有D 项。\n故正确答案为D。","img":"assets/data/judgment_img/j_0094.png"},{"q":"从所给四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】数量类。已知图形中3 类小图形的个数均为8，选A 选项，可保持3 类小图\n形数量相同，均为9，形成规律，当选。\n故正确答案为A。","img":"assets/data/judgment_img/j_0095.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①②⑥，③④⑤","①②⑤，③④⑥","①③④，②⑤⑥","①②③，④⑤⑥"],"a":1,"e":"【答案】B\n【解析】数量类。①②⑤元素数量乘积为8，③④⑥元素数量乘积为12。\n故正确答案为B。","img":"assets/data/judgment_img/j_0096.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①③⑤，②④⑥","①②④，③⑤⑥","①④⑥，②③⑤","①④⑤，②③⑥"],"a":2,"e":"【答案】C\n【解析】样式类。图形①④⑥中存在相同的正方形，图形②③⑤中不存在正方形。\n故正确答案为C。","img":"assets/data/judgment_img/j_0097.png"},{"q":"从所给四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】题干笔画数为：2、1、2、1，因此应该选一个笔画数为2 的，只有B 选项符\n合。\n故正确答案为B。","img":"assets/data/judgment_img/j_0098.png"},{"q":"从所给四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】考察数字规律。每幅图当中有很多数字，发现第一幅图当中的是1+3=第二\n幅图当中3 位置的4，3 和5 相加等于第二幅图5 位置的8，在其他图中验证此规律，符\n合，因此只有D 项符合。\n故正确答案为D。","img":"assets/data/judgment_img/j_0099.png"},{"q":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是（  ）","options":["①③⑤，②④⑥","①④⑤，②③⑥","①②⑥，③④⑤","①②③，④⑤⑥"],"a":2,"e":"【答案】C\n【解析】数量类。①②⑥有五个面，③④⑤有四个面。\n故正确答案为C。","img":"assets/data/judgment_img/j_0100.png"},{"q":"从所给四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】样式类。图一竖轴翻转与图二求异得到图三，只有D 项符合。\n故正确答案为D。","img":"assets/data/judgment_img/j_0101.png"},{"q":"从所给四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】属性类。图形组成凌乱，优先考虑属性，没有明显的对称性、曲直性的规\n律，发现图形全部为开放图形，那么？处应该也是一个开放图形，C 项符合。\n故正确答案为C。","img":"assets/data/judgment_img/j_0102.png"},{"q":"从所给四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】样式类。第一行中，前三图依次竖向排列，组合出图四，颜色由上至下分别\n为前三图，二、三、一的颜色。由此对应第二行问号处图形应为A 项。\n故正确答案为A。\n第十五组：","img":"assets/data/judgment_img/j_0103.png"},{"q":"请从所给的四个选项中，选择最适合的一项填在问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】样式类。题干中所有图形都是一笔画图形，故问号处应填入一个一笔画图\n形。\n故正确答案为D。","img":"assets/data/judgment_img/j_0104.png"},{"q":"请从所给的四个选项中，选择最适合的一项填在问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】样式类。第一段，第一行和第三行的黑圆每次向右移动一格，第二行和第四\n行的黑圆每次向左移动一格；第二段，第一行和第二行的黑圆每次向左移动一格，第三行\n和第四行的黑圆每次向右移动一格，问号处图形应符合此移动规律。\n故正确答案为D。","img":"assets/data/judgment_img/j_0105.png"},{"q":"请从所给的四个选项中，选择最适合的一项填在问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】数量类。题干图形均有交点，交点数分别为：2、3、4、5、6，呈等差数\n列，问号处图形交点数为7。\n故正确答案为C。","img":"assets/data/judgment_img/j_0106.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】数量类。题干面的数量依次为1、2、3、4，问号处填具有5 个面的图形，\n对应选项D。\n故正确答案为D。","img":"assets/data/judgment_img/j_0107.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】数量类。题干中每个图形均有3 个灰色面，故选项也须有3 个灰色面，对应\n选项C。\n故正确答案为C。","img":"assets/data/judgment_img/j_0108.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】数量类。题干面的数量依次为2、2、2、2，问号处也应具有2 个面，排除\nAD。再观察题干发现，均有2 个图形，排除B。\n故正确答案为C。","img":"assets/data/judgment_img/j_0177.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】位置类。黑块每次顺时针移动一个三角形，白块每次顺时针移动一个三角\n形。把此规律用在第二段，左上角黑块每次顺时针移动一个正方形，排除BC。右上角半\n黑半块每次顺时针移动一个正方形，对应A 选项。\n故正确答案为A。","img":"assets/data/judgment_img/j_0109.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】数量类。第一段，每个图形存在两个交点，第二段，每个图形存在4 个交\n点，对应D 选项。\n故正确答案为D。","img":"assets/data/judgment_img/j_0110.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】题干图形全部为封闭图形，那么？处应该也是一个封闭图形，C 项符合。\n故正确答案为C。","img":"assets/data/judgment_img/j_0111.png"}]},{"id":"graph3d","name":"图形推理·立体重构","items":[{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】数量类。题干图形均为1 笔画图形。AD 均为2 笔画，C 为3 笔画，B 为1 笔\n画。\n故正确答案为B。\n第二节立体重构\n第一组：","img":"assets/data/judgment_img/j_0112.png"},{"q":"左边给定的是纸盒的外表面，下面哪一项能由它折叠而成（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】空间重构。将题干六面体的展开图标注编号，得到下图：\n题干中5 面和6 面为相对面，所以在立体图形中不可能同时出现，排除AD 选项；C\n选项中2 面和5 面的两条线相交于一点，因此可以确定C 选项的三个面为1、2、5。题干\n中从这个三个面的公共点引出两条线，而选项中公共点没有引出线条，排除；B 选项2、\n3、6 三个面的相对位置与题干一致，当选。\n故正确答案为B。","img":"assets/data/judgment_img/j_0113.png"},{"q":"左边是给定纸盒的外表面，右边哪一项能由它折叠而成（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】空间重构类。\nA 项，面4 与面5 为“Z”字形两端，即相对面，不能同时出现，排除；\nB 项，正面和上面图形特征相同，而题干中只有一个此特征的面，排除；\nC 项，面2 与面3 为“Z”字形两端，即相对面，不能同时出现，排除；\nD 项，面1、面2 和面5 的位置关系与题干中一致，当选。\n故正确答案为D。","img":"assets/data/judgment_img/j_0114.png"},{"q":"左边给定的是纸盒的外表面，下面哪一项能由它折叠而成（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】空间重构。从选项带入题干，小黑三角形的面与横线的面没有公共边，故排\n除B，在展开图中其中一个黑色三角形已明确公共点，故两个黑色三角形的面没有公共\n点，排除C，中心有白色三角形的面与一条横线面的横线没有相交，排除D。\n故正确答案为A。","img":"assets/data/judgment_img/j_0115.png"},{"q":"左边给定的是纸盒的外表面，下面哪一项能由它折叠而成（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】立体重构。对每个面进行标号，如图所示。\nA 项，三个面可以同时出现的情况共有4 种，第一种：1、2、4；第二种：1、3、4；\n第三种：1、3、5；第四种：1、2、5。\n第一种情况：运用双面箭头法，从4 面向1 面画箭头（如图一所示），A 项中，箭头\n左面是2 面，原图箭头右面是2 面，排除；\n第二种情况：运用公共点法，B 选项中，1、3、4 这三个面的公共点向面中引出1 条\n线，而原图中共点向这三个面引出了2 条线，排除；\n第三种情况：A 项中3 面中的线和5 面中的线不平行，而将原图中的5 面顺时针旋转\n90°，1 面逆时针旋转90°后（如图二所示），3 面和5 面中的两条线平行，排除；\n第\n四种情况：运用公共点法，A 项中，公共点向1、2、5 三个面中引出1 条线，而原图中公\n共点没有向面中引出线（如图三所示），排除；\n图一图二图三\nB 项，三个面的位置关系与平面图形相符，当选；\nC 项，6 面的面与1 面为相对面，不能同时出现，排除；D 项，6 面的面与1 面为相\n对面，不能同时出现，排除。\n故正确答案为B。","img":"assets/data/judgment_img/j_0116.png"},{"q":"左边给定的是纸盒的外表面，下面哪一项能由它折叠而成（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】空间重构。可以采用坐标法。选择白色梯形为坐标面，由下底向上底画坐\n标。如图\n观察选项发现，原图中坐标左边是由一条线连接上下底的梯形，而在A、B 中却变成\n了连接两个腰的梯形，故排除。D 项中上面和右面中的线平行，而原图是垂直，故排除。\n故正确答案为C。","img":"assets/data/judgment_img/j_0117.png"},{"q":"左边给定的是纸盒外表面的展开图，右边哪一项能由它折叠而成？请把它找出来（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】立体图形题\nA 项，题干3 面的左面应该是2 面，而选项是4 面，排除；\nB 项，题干1 面黑色三角形和2 面黑色三角形的公共点没有重合，选项重合，排除；\nD 项，题干4 面的左面是1 面，而选项4 面的左面是2 面，排除。\n故正确答案为C。","img":"assets/data/judgment_img/j_0118.png"},{"q":"以下是给定纸盒的外表面，下列哪一个纸盒能由以下表面折叠而成（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】A 项，对应1、4、5 三个面，将平面图形1 面进行移面后，三个面的位置关系正确，\n当选；\nB 项，平面图形中的1 面与6 面是相对面，在立体图形中不能同时出现，而B 项中同\n时出现了1 面与6 面，所以错误，排除；\nC 项，对应2、3、6 三个面，将平面图形6 面移面后（如下图），平面图形中3 面与\n6 面的位置关系与立体图形中的位置关系不一致，排除；\nD 项，对应1、2、5 三个面，在平面图形和立体图形中的1 面与2 面画坐标（如下\n图），平面图形中坐标右方是3 面，而立体图形中坐标右方是5 面，位置错误，排除。\n故正确答案为A。","img":"assets/data/judgment_img/j_0119.png"},{"q":"左边给定的是正方体纸盒，下面哪项可能是其正确的外面表面展开图（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】立体重构。\nB 项，①面与②面的相对位置与题干不一致，排除；\nC 项，②面与③面的相对位置与题干不一致，排除；\nD 项，②面与③面的相对位置与题干不一致，排除；\n故正确答案为A。","img":"assets/data/judgment_img/j_0120.png"},{"q":"左边给定的是纸盒的外表面，下列哪一项能由它折叠而成（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】立体重构。如下图所示：\n在展开图椭圆面画一个向上的箭头，此时箭头左侧的面为空白面，右侧的面为b 面；\nA 项，选项中箭头左侧的面不是空白面，与题干不符，排除；B 项，展开图中C 面与\n黑面为相间排列，为相对面，选项中黑面与C 面同时出现，排除；C 项，选项中箭头左侧\n的面不是空白面，与题干不符，排除。\n故正确答案为D。","img":"assets/data/judgment_img/j_0121.png"},{"q":"左边给定的是纸盒外表面的展开图，右边哪一项能由它折叠而成？请把它找出来（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】此题出现了多个小直角三角形的面（例如面5 和面6），可以通过对小直角\n三角形画时针进行判断。在面5 上以小直角三角形的短直角边为起点，沿直角向长直角边\n的方向画时针，如图所示，面6 同理，两个面画出来均为逆时针。注意：与题干时针方向\n不一致的选项一定错，但与题干时针方向一致的选项不一定对。\nA 项，如果在小三角形面画箭头发现与题干是一致的，排除不了。考虑其他方法，在\n题干与选项中找到面3 的同一条边（如图A 所示），发现相邻面不一致，故排除；\nB 项，在小直角三角形的面，以小直角三角形的短直角边为起点，沿直角向长直角边\n的方向画时针（如图B 所示）,为顺时针，与题干时针方向不一致，排除；\nC 项，分别在两个小直角三角形的面上画时针（如图C 所示），均为顺时针，与题干\n时针方向不一致，排除。\n故正确答案选D。\n第二组：","img":"assets/data/judgment_img/j_0122.png"},{"q":"左边给定的是正方体的外表面展开图，下面哪一项能由它折叠而成（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】空间重构，为了便于区分可以将每个面做标记。如图\nA 项，原图中2、4 面公共边两侧为两个白三角，而选项中2、4 面公共边挨着一个白\n三角和一个黑三角，排除；\nB 项，选项前面可能为1 面或6 面，当前面是1 面，那么原图中1 面右侧为3 面，选\n项不符合；当前面是6 面，右面只能是4 面，在4 面由黑三角底边向顶点画箭头，6 面在\n箭头左侧，而选项6 面在箭头右侧，排除；\nC 项，当选项是1、3、6 面，原图三个面的共用点没有引出线，选项引出两条，错\n误；当选项是1、5、6 面，原图三个面的共用点引出三条线，选项错误，排除；\n故正确答案为D。","img":"assets/data/judgment_img/j_0123.png"},{"q":"左边给定的是纸盒的外表面，下面哪一项能由它折叠而成（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】空间重构。在展开图给它进行编号，如图所示：\nA 项，选项的上面在原图中只出现一个，选项中出现两个相同面，排除；\nB 项，选项中的面1，3，4 与题干展开图一致，当选；\nC 项，选项中的面3 的顶点的三角形顶点与面4 三角形的角顶点相连，而C 项中面3\n的三角形角顶点与面4 三角形的直角边相连，排除；\nD 项，选项中面1 三角形的直角顶点与面1、2、3 的公共点相连，而题干中的面1 三\n角形的锐角顶点与面1、2、3 的公共点相连，不符合，排除。\n故正确答案为B。","img":"assets/data/judgment_img/j_0124.png"},{"q":"下图是立体图形，下列哪个选项可以折叠成该立体图形（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】重构类。\nA 项，题干展开图与选项一致，当选；\nB 项，如下图所示，图中虚线为公共边，但长度不一致，排除；\nC 项，选项中梯形与三角形有公共边，而题干中没有，选项与题干不一致，排除；\nD 项，选项中梯形与三角形有公共边，而题干中没有，选项与题干不一致，排除。\n故正确答案为A。","img":"assets/data/judgment_img/j_0125.png"},{"q":"左边给定的是纸盒的外表面，下面哪一项能由它折叠而成（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】立体重构，六面体。如下图所示，将题干进行标记：\nA 项：选项与展开图一致，当选；\nB 项：正面为面5，所以其顶面应当为面3（面5 和面1 为相对面，不可能同时出\n现），此时右面为面2 或者面4。若右面为面2，则B 项是由2、3、5 这三个面组成。展\n开图中，这三个面的公共点没有经过面3 中的小黑点，而选项中这三个面的公共点经过了\n面3 中的小黑点，选项与展开图不一致；若右面为面4，则B 项是由3、4、5 这三个面组\n成。此时面3 和面4 公共边两侧的小黑点的位置不对，选项与展开图不一致。综上，B 项\n排除；\nC 项：正面为面5，顶面的黑点与面5 比较近，所以顶面为面4，右面为面3（面5 和\n面1 为相对面，不可能同时出现），则B 项是由345 这三个面组成。此时，展开图和选项\n中，面3 和面4 公共边两侧的小黑点的位置不一致，选项与展开图不一致，排除；\nD 项：由面1、面3 和另外一个面组成，展开图中，面1 与面3 不存在挨在一起的黑\n点，选项中面1 黑点与面3 黑点之间有一个是挨着的，选项与展开图不一致，排除。\n故正确答案为A。","img":"assets/data/judgment_img/j_0126.png"},{"q":"左边给定的是纸盒外表面的展开图，下列哪项能由它折叠而成（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】立体重构。将题干展开图中的面依次标注为面a、b、c、d，如下图：\nA 项，由面b 和面c 构成，以面c 中的点1 为起点，顺时针画边，如下图：\n题干展开图中与边2 相邻的面是面d，而选项中与边2 相邻的面是面b，与题干不\n符，排除；\nB 项，选项与题干一致，当选；\nC 项，由面c 和面d 构成，以面d 中的点3 为起点，顺时针画边，如下图：\n题干展开图中与边4 相邻的面是面a，而选项中与边4 相邻的面是面c，与题干不\n符，排除；\nD 项，由面a 和面d 构成，以面a 中的点5 为起点，顺时针画边，如下图：\n题干展开图中与边6 相邻的面是面b，而选项中与边6 相邻的面是面d，与题干不\n符，排除。\n故正确答案为B。","img":"assets/data/judgment_img/j_0127.png"},{"q":"左边给定的是纸盒的外表面，右边哪一项能由它折叠而成（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】立体重构。\nA 项，如图所示，在三角形面画箭头，箭头右边是圆，而题干当中，箭头左边是圆，\n排除；\nB 项，箭头图案的左边是直线，而题干中箭头图案的左边是正方形，排除；\nC 项，带有一条直线的面，与带有正方形的面为相对面，排除；\nD 项，可由题干平面图折成，当选。\n故正确答案为D。","img":"assets/data/judgment_img/j_0128.png"},{"q":"左边给定的是纸盒的外表面，下列哪一项能由它折叠而成（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】重构类。\nA 项，在1 面上画箭头，由黑色指向白色，题干箭头指向3 面，而A 项箭头指向4\n面，排除；\nB 项，与题干的相对位置关系一致，当选；\nC 项，在1 面上画箭头，由黑色指向白色，题干箭头指向3 面，而C 项3 面在箭头的\n“脚底”，排除；\nD 项，面3 和面5 是相对面，不能同时出现，所以白色面应该为面2，该项面2、面\n3 和面6 的公共点引出1 条线，而题干没有引出线条，排除。\n故正确答案为B。","img":"assets/data/judgment_img/j_0129.png"},{"q":"左图给定的是正方体纸盒的外表面，下面哪一项能由它折叠而成（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】空间重构。\nA 项，1 号点连接的是上表面黑色三角形的直角，展开图形中1 点有两种可能，无论\n哪个1 点都连接的是黑色三角形的锐角，排除；\nB 项，m 面展开图中没有出现过，排除；\nC 项，3 号点是三个面的共同点，其中3 号点连接的是n 面的黑三角形的直角，和展\n开图相比较，3 号点有两种可能性，但是无论哪个3 号点都连接的是n 面的白色三角形的\n直角，排除。\n故正确答案为D。","img":"assets/data/judgment_img/j_0130.png"},{"q":"左边是给定的纸盒的外表面，下列哪一项能由它折叠而成（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】本题考查空间重构，如图所示：\nA 项，展示的是1、3、4 三个面，与题干中三个面的相对位置关系一致，当选；\nB 项，展示的是1、2、5 三个面，题干中在2 上面是1 的情况下，2 的右侧应该为\n3，而B 选项中2 右侧为5，排除；\nC 项，展示的是4、5、6 三个面，题干中从5 指向4 画箭头，6 在箭头左侧，而C 选\n项中，用同样的方式（从5 指向4）画箭头，6 在箭头的右侧，排除；\nD 项，展示的是3、4、5 三个面，其中3 和5 两个面为相对面，排除；\n故正确答案为A。","img":"assets/data/judgment_img/j_0131.png"}]},{"id":"graphview","name":"图形推理·三视图","items":[{"q":"左边给定的是纸盒外表面的展开图，右边哪一项能由它折叠而成（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】空间重构。在原图横线所在面画箭头，如下图所示：\nA 项，箭头的右侧为黑色面，题干展开图中箭头面的右侧为灰色面，排除；\nB 项，各个面相对位置与题干展开图一致，当选；\nC 项，箭头左侧为白色面，而题干平面展开图中箭头面的左侧为黑色面，排除；\nD 项，箭头左侧为灰色面，而题干平面展开图中箭头面的右侧为灰色面，排除。\n故正确答案为B。\n第三节三视图\n第一组：","img":"assets/data/judgment_img/j_0132.png"},{"q":"下图是给定的立体图形，它的主视图和左视图是（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】三视图。题干当中右侧的“L”型的高度应高于左侧的立方体，且从整个图\n形的左侧看过去，立方体与“L”型的立体图形的宽度是一样的，对应C 选项。\n故正确答案为C。","img":"assets/data/judgment_img/j_0133.png"},{"q":"左图为给定的多面体，从任意角度观看，下面哪项可能是该多面体的视图（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】三视图。B 项为原图的主视图。A、C、D 不符合立体图形视图，排除。\n故正确答案为B。","img":"assets/data/judgment_img/j_0134.png"},{"q":"左图为给定的多面体，从任一角度观看，下面哪一项不可能是该多面体的视图（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】三视图。\nA 项，从正前向后看的视图结果，排除；\nB 项，从下向上看的视图结果，排除；\nC 项，从右向左看的视图结果，排除；\nD 项，无论从哪个角度都得不到，当选。\n故正确答案为D。","img":"assets/data/judgment_img/j_0135.png"},{"q":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】三视图。此题为立体结构图中的三视图前半段第一个图为侧视图，第二图为\n该图形的俯视图，第三图为主视图或左视图。按照此规律问号处应该是主视图或左视图。\nA、B 为主视图，正面看过去，能看到一条连接两个竖边的线条且线条不连通，排除B\n项。在左视图中是看不到长方形的右边的，因此C、D 排除。\n故正确答案为A。","img":"assets/data/judgment_img/j_0136.png"},{"q":"从所给出的四个选项中，选择最合适的一个填入问号处，使之呈现一定规律性（  ）A         B         C        D","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】三视图。第一段图形的第一幅图为立体图形，第二幅图为立体图形的俯视\n图，第三幅图为立体图形的正视图。第二段图形第二幅图为第一幅立体图形的俯视图，故\n问号处应填立体图形的正视图。圆形正面看应为直线。\n故正确答案为D。","img":"assets/data/judgment_img/j_0137.png"},{"q":"从所给四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】三视图。第二、三图分别是一图的正视图和俯视图，问号处是第一幅图形的\n俯视图。\n故正确答案为C。","img":"assets/data/judgment_img/j_0138.png"},{"q":"从所给四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】三视图。问号处的图形为第二组的第1 幅立体图形的正视图。\n故正确答案为B。","img":"assets/data/judgment_img/j_0139.png"},{"q":"如图所示是一个圆台，则下列选项不可能属于该圆台视图的是（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】三视图，选非题。\nA 项，该项是圆台的俯视图，正确，排除；\nB 项，从任意一角度都无法看到两个大小不同的椭圆视图面，错误，当选；\nC 项，该项是圆台的主视图，正确，排除；\nD 项，该项是圆台的仰视图，正确，排除。\n故正确答案为B。","img":"assets/data/judgment_img/j_0195.png"},{"q":"下图右侧的4 个图形中，除了哪项，都是左侧立体物体的投影图（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】三视图，选非题。\nA 项，图形为立体物体的俯视图，正确，排除；\nB、D 两项中，外轮廓一模一样，区别在于中间的实线与虚线，由于选项中图形的轮\n廓是左高右低，因此该投影应该是从立体图形的后方观看所得，而后方看立体图形的凹处\n是看不见的，应该为虚线条，因此B 项正确，排除，D 项错误，当选；\nC 项，图形为立体物体的正视图，正确，排除；\n故正确答案为D。","img":"assets/data/judgment_img/j_0196.png"}]},{"id":"graphsec","name":"图形推理·截面图","items":[{"q":"右图各选项中，哪个不是左面立体图的投影图（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】三视图，选非题。\nA 项，矩形在左边，小三角在右边，应在2 的位置观察得到的，为右视图，正确，排\n除；\nB 项，前面是横的矩形，应在3 的位置观察得到的，为后视图，正确，排除；\nC 项，小三角为左边，应该是从4 的位置观察的，但是左视图应该为圆锥挡住了长方\n体，三角形在矩形的前面，与选项不符，选项不是左面立体图的投影图，错误，当选；\nD 项，三角和矩形在横着的矩形前面，应在1 的位置观察得到的，为正视图，正确，\n排除；\n故正确答案为C。\n第四节截面图\n第一组：","img":"assets/data/judgment_img/j_0140.png"},{"q":"下列的立体图形是立方体中挖出一个圆锥台孔后形成的，如果从任一面剖开，以下哪一个不可能是该立体图形的截面（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】截面图，选非题。方法如图：\n故正确答案为C。","img":"assets/data/judgment_img/j_0150.png"},{"q":"如图所示，立方体上叠加圆柱体再打通一个圆柱孔，然后从任意面剖开，下面哪一项不可能是该立体的截面（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】A、C、D 均可截出，如下图。\n故正确答案为B。","img":"assets/data/judgment_img/j_0141.png"},{"q":"一个正棱锥如图所示，正中被挖去一个圆锥体，然后从任意面剖开，下面哪一项不可能是该物体的截面（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】立体类。如下图所示，A、B、C 项均可得到，只有D 项截不出来。\n故正确答案为D。","img":"assets/data/judgment_img/j_0142.png"},{"q":"左图给定的是由4 个相同正方体组合成的立体图形，将其从任一面剖开，下面哪一项不可能是该立体图形的截面（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】剖面图，选非题。选项B、C、D 都是能切出的，只有A 项无法切出。\n故正确答案为A。","img":"assets/data/judgment_img/j_0143.png"},{"q":"下面的立体图形如果从任一面剖开，以下哪一项不可能是该立体图形的截面（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】截面图，选非题。截面图如下图所示，只有D 项不可能是该立体图形的截\n面。\n故正确答案为D。","img":"assets/data/judgment_img/j_0144.png"},{"q":"左图是给定的多面体，将其从任一面剖开，下面哪一项不可能是该多面体得截面（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】剖面图，如下图：\nA 项，如图，可切出\nB 项，如图，可切出\nC 项，如图，可切出\n故正确答案为D。","img":"assets/data/judgment_img/j_0145.png"},{"q":"左图为6 个相同小正方体组合成的多面体，将其从任一面剖开，以下哪一项不可能是该多面体的截面（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】剖面图。只有D 项无法切出。\n故正确答案为D。","img":"assets/data/judgment_img/j_0146.png"},{"q":"左图是给定的立方体图形，将其从任一面剖开，下面哪一项可能是该立方体的截面（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】剖面图。把题干立体图沿其右侧或者左侧沿竖直方向剖开，均可得到A 项；\nBCD 从任何方向剖开均不可得。\n故正确答案为A。","img":"assets/data/judgment_img/j_0147.png"},{"q":"一个圆锥台如下图所示，从正中心挖掉一个小圆锥体，然后从任意面剖开，下面不可能是该圆锥台的截面的是（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】剖面图。只有D 项无法切出。\n故正确答案为D。","img":"assets/data/judgment_img/j_0148.png"}]},{"id":"graphfit","name":"图形推理·立体拼接","items":[{"q":"左图是给定的立体图形，将其从任一面剖开，下面哪一项不可能是该立体图形的截面（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】剖面图。只有C 项无法切出。\n故正确答案为C。\n第五节立体拼接\n第一组：","img":"assets/data/judgment_img/j_0149.png"},{"q":"如下图所示，左侧为大立方体，右侧为其部分立体截面，问哪个选项能够与其拼成完整的大立方体（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":2,"e":"【答案】C\n【解析】立体拼接。所缺部分为图1，经过旋转后得到图2，将图2 旋转后得到C 项\n中的立体图形。\n故正确答案为C。","img":"assets/data/judgment_img/j_0160.png"},{"q":"左边的立体图形是由①、②和③组成的，下列哪项不能填入问号处（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】立体拼接，选非题。只有B 项无法组成左边的立体图形。\n故正确答案为B。","img":"assets/data/judgment_img/j_0151.png"},{"q":"下图为给定的多面体，下面哪项多面体能与该多面体拼接成实心的长方体（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】空间重构。选项结合原图能够拼接成实心长方体的立体图形，利用凹凸原\n则，如图所示，只有A 选项符合。\n故正确答案为A。","img":"assets/data/judgment_img/j_0152.png"},{"q":"左图给定的是由18 个相同大小的正方体组成的多面体，这个多面体可以切割为3个完全相同的小多面体，问切割成的小多面体是（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":0,"e":"【答案】A\n【解析】立体拼接。A 选项，拼接方式如下。\n故正确答案为A。","img":"assets/data/judgment_img/j_0161.png"},{"q":"左图给定的是由相同正方体堆叠而成多面体的正视图和后视图。该多面体可以由①、②和③三个多面体组合而成，问以下哪一项能填入问号处（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】立体拼接，如下图：\n所以，问号处补充B 选项即可与1、2 拼接为左侧立体图形。\n故正确答案为B。","img":"assets/data/judgment_img/j_0154.png"},{"q":"下图中的立体图形①是由立体图形②，③和④组合而成，下列哪一项不能填入问号处（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】立体拼合。由②，③和④组合形成①。\nA 项，与②组合后放在下层，③横过来放在上层即可拼合成①，排除；\nB 项，无论放在什么位置均不能与②，③拼合形成①，当选；\nC 项，③放在②的左边，之后将其放在C 项下层的凹槽处，便可组合形成①，排除；\nD 项，将②放在D 项的凹槽处，其后横着放③便可拼合形成①，排除。\n故正确答案为B。","img":"assets/data/judgment_img/j_0182.png"},{"q":"①、②、③、④为四个多面体零件，问A、B、C、D 四个多面体零件中的哪一个与①、②、③、④中的任一个都不能组成长方体（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】立体拼接。可以考虑凹凸位置相互组合。①和C 项组合，③和B 组合，④和\nA 组合。\n故正确答案为D。","img":"assets/data/judgment_img/j_0183.png"},{"q":"下列中的立体图形①是由立体图形②、③和④组合而成，下列哪一项能够填入问号处（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":1,"e":"【答案】B\n【解析】立体拼接。第一图为完整的立体图形，观察发现第二幅图带有圆锥尖，而第\n三幅图并没有与之相应的凹槽，故问号处应填带有凹槽的图形。匹配答案为B。\n故正确答案为B。","img":"assets/data/judgment_img/j_0197.png"},{"q":"左图为同样大小的正方体堆叠而成的多面体正视图和后视图，该多面体可拆分为①、②、③和④共4 个多面体组合，问下列哪一项能填入问号处（  ）","options":["A（见图）","B（见图）","C（见图）","D（见图）"],"a":3,"e":"【答案】D\n【解析】立体拼合。左侧多面体由22 个方块构成，①②③共出现16 个方块，缺6 个\n方块。A 项方块数量为4 个；B 项为5 个；C 项为5 个方块；D 项为6 个。\n故正确答案为D。","img":"assets/data/judgment_img/j_0198.png"}]},{"id":"lunzheng","name":"论证推理","items":[{"q":"美国一项新研究发现，人体生理反应的节奏跟昼夜交替一致，一旦这个节奏被破坏，人们免疫系统的抗病能力就会降低。如果以下各项为真，最能削弱上述观点的是（  ）","options":["坐飞机到不同时区易产生头疼反胃等时差综合症","熬夜易使胃酸分泌过多而诱发胃溃疡病症","长跑运动后立即大量饮水容易破坏体内代谢平衡而致病","免疫系统先天缺陷的病人，即使正常饮食患病概率也很高"],"a":3,"e":"【答案】D\n【解析】削弱论证。论点：人体的生理反应一旦被破坏，免疫力就会下降。论据：人\n体生理反应的节奏与昼夜交替一致。\nA 项，坐飞机到不同时区易产生头疼反胃等时差综合症。到不同时区会导致昼夜变\n化，继而引发人体生理反应发生变化，导致免疫力下降产生综合症，说明不遵守昼夜交替\n节奏，就会引发病症，可以加强，排除；\nB 项，说明人体生理反应与昼夜交替的节奏一致，若不遵守交替节奏，便会引发病\n症，可以加强，排除；\nC 项，说明在特殊条件下“运动后”，运动对“代谢平衡”的影响，与人体新陈代谢\n无关，论题不一致，排除；\nD 项，免疫系统先天缺陷病人并非没有遵守昼夜交替节奏，即没有打乱人体的生理反\n应。说明人体的生理反应没被破坏，免疫力也下降了，举例削弱，当选。\n故正确答案为D。"},{"q":"研究发现，大西洋、太平洋海面水温的微小变化与南美洲亚马逊热带雨林地区火灾的积具有密切联系，将这种联系建立数学模型，可以用来预测亚马逊热带雨林地区来年的火灾情况。以下哪项如果为真，最能支持上述观点（  ）","options":["大西洋海水温度升高0.2℃，亚马逊雨林次年火灾发生面积增加11%","海水温度增高会引起水分蒸发，导致降水减少，发生干旱或致火灾","海水温度变化虽然微小，但可能对热带雨林生态系统造成重要影响","北冰洋等海面水温可预测其附近的西伯利亚雨林火灾发生率和面积"],"a":0,"e":"【答案】A\n【解析】加强论证。论点：将这种联系建立数学模型，可以用来预测亚马逊热带雨林\n地区来年的火灾情况。论据：研究发现，大西洋、太平洋海面水温的微小变化与南美洲亚\n马逊热带雨林地区火灾的面积具有密切联系。\nA 项，举例说明海水温度的变化与亚马逊雨林火灾之间的关系，可以加强，当选；\nB 项，海水温度增高导致干旱或火灾，只能用来证明海水温度的变化和火灾之间可能\n有联系，但不必然一定有关系，不可预见，排除；\nC 项，热带雨林生态系统与题干无关，论题不一致，排除；\nD 项，北冰洋海面海水温度与“温度变化”并非同一范畴，另外，此选项试图以类比\n的形式来加强，类比论证是较弱的支持形式，也没有A 项直接，排除。\n故正确答案A。"},{"q":"研究者发现细菌就像人类的简化版本，它们有自我意识，有自己的语言，群居，既交友也树敌，喜欢偷窥邻居家的隐私，还能以讹传讹，甚至杀害手足。各种细菌在自己的地盘上各司其职，相互配合，促进社会的稳定。如果以下各项为真，最能质疑上述论断的是（  ）","options":["通过释放某种物质，细菌可召集群体成员执行各种任务","新型研制的阻断细菌交流的药物可以代替普通的抗菌素","细菌的生活极其单调，不是在单独进食，就是在自我繁殖","霍乱、肺炎和食物中毒，实际就是各种细菌聚集的后果"],"a":2,"e":"【答案】C\n【解析】削弱论证。论点：各种细菌在自己的地盘上各司其职，相互配合，促进社会\n的稳定。\nA 项，说明细菌可以群体活动，互相配合，可以加强，排除；\nB 项，阻断交流可以抗菌，说明交流确实是存在的，可以加强，排除；\nC 项，说明细菌生活单调，各自行动，削弱论点，当选；\nD 项，讨论细菌聚集的危害，也在印证前文“群居”的说法，不能削弱，排除。\n故正确答案为C。"},{"q":"科学就是不断接近真理的过程，我们深信不疑的事情中很大部分是会过期的，所以理解这一点的人都明白在发展过程中不断更新知识才是科学进步的正道。然而这个过程有时会令人困惑和不安。如果以下各项为真，最能质疑上述论断的是（  ）","options":["婴儿该仰睡还是趴着睡，孕妇抽烟喝酒是否安全，答案一代和一代不同","医学院的老师会告诉学生，五年内他们所学的知识里有一半都不会适用","我一直以为“雷龙”这个名字正确无误，但后来才发现根本没有雷龙","吸烟有害健康被大量科学研究和事实所证实，这一结论至今难以改变"],"a":3,"e":"【答案】D\n【解析】削弱论证。论点：理解这一点的人都明白在发展过程中不断更新知识才是科\n学进步的正道。论据：深信不疑的事情中很大部分是会过期的。\nA 项，举例说明对婴儿如何入睡和孕妇是否抽烟的认识是在不断变化的，支持论点，\n排除；\nB 项，所学知识五年后不适用，说明知识确实会过期，支持论点，排除；\nC 项，是自己的认知错误，与论点无关，论题不一致，排除；\nD 项，吸烟有害健康这一事实一直没有发生改变，即没有过期，削弱论据，当选。\n故正确答案D。"},{"q":"有关研究表明，手机比电脑更伤人，因为手机屏幕小，玩手机时注意力更投入，目不转睛，因此更伤眼。使用电脑时，人们的肢体还能活动活动，可是“手机控”往往很少活动，这对身心健康更为不利。如果以下各项为真，最能削弱上述论断的是（  ）","options":["电脑在使用过程中，显示屏会发出电磁、电离辐射","科学研究表明使用手机与脑瘤和癌症的发病率无关","电脑背景光比手机更容易引起使用者视力下降和头痛","长期使用电脑人群容易患鼠标手、颈椎病等“电脑病”"],"a":2,"e":"【答案】C\n【解析】削弱论证。论点：手机比电脑更伤人。论据：手机屏幕小，玩手机时注意力\n更投入，目不转睛，因此更伤眼。使用电脑时，人们的肢体还能活动活动，可是“手机\n控”往往很少活动。\nA 项，只提到了电脑会发射电离辐射，但未提及其对人体是否有害，论题不一致，排\n除；\nB 项，手机与脑瘤和癌症无关，但其是否会对人体健康造成其他损坏，不得而知，论\n题不一致，排除；\nC 项，电脑背景光比手机更容易引起头痛，举例证明在某些方面电脑比手机更伤人，\n可以削弱，当选；\nD 项，长期使用电脑会对人体造成伤害，但是未提及与手机相比谁的伤害更大，论题\n不一致，排除。\n故正确答案为C。"},{"q":"干细胞遍布人体，因为拥有变成任何类型细胞的能力而令科学家们着迷，这种能力意味着它们有可能修复或者取代受损的组织。而通过激光刺激干细胞生长很有可能实现组织生长，因此研究人员认为激光技术或许将成为医学领域的一种变革工具。以下哪项如果为真，最能支持上述结论（  ）","options":["不同波段的激光对机体组织作用的原理尚不清楚","已有病例表明，激光会对儿童视网膜造成损伤，影响视力","目前激光刺激生长法尚未在人类机体上进行试验，风险还待评估","用激光治疗带有牙洞的臼齿，受损的牙体组织能逐渐恢复"],"a":3,"e":"【答案】D\n【解析】加强论证。论点：研究人员认为激光技术或许将成为医学领域的一种变革工\n具。论据：通过激光刺激干细胞生长很有可能实现组织生长。\nA 项，论点讨论的是激光技术是否能成为变革工具，其“原理”是什么，不是讨论的\n重点，论题不一致，排除；\nB 项，激光对视网膜造成损伤，削弱论据，排除；\nC 项，“风险还待评估”，有什么风险不知道，属于不可预见，排除；\nD 项，“用激光治疗，受损的牙体组织能逐渐恢复”，举例证明激光能帮助组织恢\n复，属于举例加强，当选。\n故正确答案为D。"},{"q":"有报道称，由于人类大量排放温室气体，过去150 多年中全球气温一直在持续上升。但与1970 至1998 年相比，1999 年至今全球表面平均气温的上升速度明显放缓，近15 年来该平均气温的上升幅度不明显，因此全球变暖并不是那么严重。如果以下各项为真，最能削弱上述论证的是（  ）","options":["海洋和气候系统的调整过程使得海洋表层热量向深海输送","此现象在上世纪50—70 年代曾出现过，随后又开始加速变暖","联合国气候专家指出，空气中的二氧化碳浓度处于80 万年来的最高点","近几年发生多起因气候变暖而产生的自然灾害"],"a":1,"e":"【答案】B\n【解析】削弱论证。论点：全球变暖并不是那么严重。论据：与1970 至1998 年相\n比，1999 年至今全球表面平均气温的上升速度明显放缓，近15 年来该平均气温的上升幅\n度不明显。\nA 项，论点讨论的是全球变暖是否严重，与海洋热量无关，论题不一致，排除；\nB 项，此现象即论据所提到的平均气温上升速度放缓，随后开始加速变暖，也就是说\n即使现在增速慢，之后可能会快速增长，给出一个之后气温可能加快变暖的理由，起到削\n弱作用，当选；\nC 项，二氧化碳浓度和气温是否有变化，与论点无关，论题不一致，排除；\nD 项，论点讨论的是全球变暖是不是很严重，而选项谈论的是全球变暖造成的后果，\n论题不一致，排除。\n故正确答案为B。"},{"q":"某市为了发展文化强市战略，在2008 年、2010 年先后建成了两个图书馆，2008年底共办理市民借书证7 万余个，到2010 年底共办理市民借书证13 万个。2011 年，该市又在新区建立了第三个图书馆，于2012 年初落成开放。截至2012 年底，全市共计办理市民借书证20 余万个。市政府由此认为，该项举措是有实效的，因为在短短的4 年间，光顾图书馆的市民增加了近两倍。以下哪项如果为真，最能削弱上述结论（  ）","options":["图书馆要不断购置新书，维护成本也很高，这会影响该市其他文化设施建设","该市有两所高等学校，许多在校生也办理了这3 个图书馆的借书证","很多办理了第一个图书馆借书证的市民又办理了另外两个图书馆的借书证","该市新区建设发展迅速，4 年间很多外来人口大量涌入新区"],"a":2,"e":"【答案】C\n【解析】削弱论证。论点：该项举措是有实效的。论据：在短短的4 年间，光顾图书\n馆的市民增加了近两倍。\nA 项，论点讨论的是建立图书馆是否有效，至于图书馆维护成本是否高，是否会对其\n他造成影响，不在讨论范围内，排除；\nB 项，学生办理了借书证，说明增加图书馆有效果，有加强作用，排除；\nC 项，说明虽然增加了图书馆，但是办理借书证的人并没有增加很多，否定了论据\n“光顾图书馆的市民增加了近两倍”，可以削弱，当选；\nD 项，与图书馆无关，是说外来人口的事，外来人口是否会办理图书证，不可预见，\n排除。\n故正确答案为C。"},{"q":"X 分子具有Y 结构，串联起了大量的原子，由该分子组成的某种物质在同类型的物质中具有很强的导热性。很明显，分子内包含大量原子是使得该物质拥有极强的导热性所必不可少的。以下哪项如果为真，最能削弱上述结论（  ）","options":["有的分子拥有别的结构，也串联起了大量的原子，并拥有很强的导热性","有的物质导热性不强，但是它的分子中包含了大量的原子","有的物质导热性很强，但是其分子不具备Y 结构","有的物质导热性不强，但是其分子具备类似的结构"],"a":2,"e":"【答案】C\n【解析】削弱论证。论点：分子内包含大量原子是使得该物质拥有极强的导热性所必\n不可少的。（可翻译为：导热性→Y 结构串联大量原子）\nA 项，说明无论结构如何，只要有大量原子就有好的导热性，举例加强项，排除；\nB 项，表明有大量原子但是导热性不强，题干说的是导热性强的物质，论题不一致，\n排除；\nC 项，导热性强且不具备Y 结构，即A 且-B，削弱项，当选；\nD 项，论点讨论的是导热性与原子之间的关系，选项讨论的是导热性和结构的关系，\n论题不一致，排除。\n故正确答案为C。"},{"q":"酒精本身没有明显的致癌能力。但是许多流行病学调查发现，喝酒与多种癌症的发生风险正相关——也就是说，喝酒的人群中，多种癌症的发病率升高了。以下哪项如果为真，最能支持上述发现（  ）","options":["酒精在体内的代谢产物乙醛可以稳定地附着在DNA 分子上，导致癌变或者突变","东欧地区的人广泛食用甜烈性酒，该地区的食管癌发病率很高","烟草中含有多种致癌成分，其在人体内代谢物与酒精在人体内代谢物相似","有科学家估计，如果美国人都戒掉烟酒，那么80%的消化道癌可以避免"],"a":0,"e":"【答案】A\n【解析】加强论证。论点：喝酒与多种癌症的发生风险正相关。\nA 项，解释说明了为什么喝酒容易引发癌变，可以加强，保留；\nB 项，东欧地区食用甜性烈酒发生食道癌概率高，是酒起作用还是“甜”的糖起作用\n不可预见，排除；\nC 项，提到了烟草有致癌成分，其在人体内代谢物与酒精在人体内的代谢物相似，具\n有加强作用，但是以类比的形式来加强的，保留；\nD 项，戒掉烟和酒可以避免大部分消化道癌，起作用的到底是烟还是酒不可预见，排\n除；对比A、C 项，解释说明最强。\n故正确答案为A。\n第二组："},{"q":"一项研究显示，先让受试者参加消除某项偏见的学习，并给受试者播放与消除该偏见学习相关联的声音。之后，让受试者进入深度睡眠状态，同时重复播放那些相关联的声音，以重新激活消除该偏见的学习。结果发现，该偏见比睡眠前大大减少，且睡眠质量越高，偏见减少得越多。研究人员由此推测，睡眠干预可减少社会偏见与歧视。以下哪项如果为真，最能支持上述论证（  ）","options":["普通民众难以得到消除偏见学习的睡眠干预","睡眠充足、睡眠质量高的人比其他人更不易产生偏见与歧视","有身高歧视、相貌歧视的人经过睡眠干预后，歧视程度明显降低","在接受睡眠干预的受试者中，有一部分人并不存在明显的偏见或歧视"],"a":2,"e":"【答案】C\n【解析】加强论证。论点：睡眠干预可减少社会偏见与歧视。论据：让受试者进入深\n度睡眠状态，同时重复播放那些相关联的声音，以重新激活消除该偏见的学习，发现该偏\n见比睡眠前大大减少，且睡眠质量越高，偏见减少得越多。\nA 项，讨论的是获得睡眠干预学习的难易程度，与论点讨论的睡眠干预对于偏见和歧\n视的作用无关，论题不一致，排除；\nB 项，睡眠质量好的人不易产生偏见和歧视，但是是否能消除已有的偏见并不能确\n定，论据不可预见，排除；\nC 项，有身高、相貌歧视的人经过睡眠干预程度降低，说明睡眠干预确实可以消除偏\n见，举例加强，当选；\nD 项，接受实验的受试者有一部分人不存在偏见或者歧视，说明实验主体不典型，削\n弱论据，排除。\n故正确答案为C。"},{"q":"提高能源使用效率、鼓励能源灵活利用是英国减少温室气体排放政策的一个必要环节，它需要采用智能技术，包括通过智能表将能源使用信息从需求方面或客户发送到能源公司等。该信息可用于制定和实施更高效的能源使用条例。但英国消费者对此态度不一，因为该技术用于监控和支持能源高效率使用行为时，居民个人及家庭的能源数据不得不被动分享。所以，个人使用能源相关数据的被动分享有可能成为推广智能技术的最主要障碍。以下哪项如果为真，最能支持上述结论（  ）","options":["60%的调查者表示，不愿意因数据被动分享而降低个人能源使用比例","60%的调查者认为，数据的被动分享大大增加个人隐私被侵犯的风险","60%的调查者表示，那些关心气候变化的人更可能接受数据被动分享","60%的调查者认为，数据不可能不被分享，否则智能技术不可能应用"],"a":1,"e":"【答案】B\n【解析】加强论证。论点：个人使用能源相关数据的被动分享有可能成为推广智能技\n术的最主要障碍。论据：该技术用于监控和支持能源高效率使用行为时，居民个人及家庭\n的能源数据不得不被动分享。\nA 项，不愿意因数据被动分享而导致个人能源使用比例下降，但能源比例下降对推广\n智能技术的影响我们无从得知，论题不一致，排除；\nB 项，数据的被动分享会增加个人隐私被侵犯的风险，所以人们不愿意被动分享个人\n数据，而该技术在实行过程中不得不分享个人数据，因此可能成为推广智能技术的最主要\n障碍，有加强作用，当选；\nC 项，讨论的是关心气候变化的人更可能接受数据被动分享，说明有部分人可以接受\n数据被动分享，对论点有削弱作用，排除；\nD 项，数据被分享，智能技术才能应用，说明数据被分享的必要性，但是与数据被分\n享能否阻碍推广智能技术无直接联系，论题不一致，排除。\n故正确答案为B。"},{"q":"英国一项研究发现，人只要在每餐饭前半小时喝一杯500 毫升的水，并坚持3 个月，体重就能减轻2 至4 公斤。研究团队邀请了84 位超重的成人，随机分成2 组，其中41 位被要求在餐前喝500 毫升水，另外43 位则照常生活。3 个月后，团队发现三餐前喝水的人，平均体重下降了4.3 公斤；而餐前没喝水的人，平均体重只下降了0.81 公斤。研究人员说，没有喝水的那组人，“平均运动量”比餐前饮水的人更高，这说明餐前喝适当的水真能减肥。以下哪项如果为真，最能支持上述结论（  ）","options":["餐前喝水的那组人同时也注意控制饮食","餐前没喝水的人中有的体重减轻了4 公斤","除了餐前喝水，两组的其他情况都是一样的","餐前没喝水的人就餐中会喝更多的汤和饮料"],"a":2,"e":"【答案】C\n【解析】加强论证。论点：餐前喝适当的水真能减肥。论据：餐前喝水的人比餐前没\n喝水的人平均体重下降得要多，且没有喝水的那组人平均运动量比餐前饮水的人更高。\nA 项，餐前喝水的那组人同时在控制饮食，说明除了喝水还可能存在其他原因导致体\n重下降，削弱了论点，排除；\nB 项，餐前没喝水的个别人体重减了4 公斤，但是题干讨论的是平均体重，论题不一\n致，排除；\nC 项，除了餐前喝水，两组其他条件都一样，说明只有喝水这个因素在变化，导致体\n重减轻，有加强作用，当选；\nD 项，餐前没喝水的人喝了更多的汤和饮料，我们讨论的是水对体重的影响，汤和饮\n料对体重的影响我们无从得知，论题不一致，排除。\n故正确答案为C。"},{"q":"很多家长认为，孩子不听话，“打屁屁”惩罚一下，至少能让孩子注意到自己的行为不当，变得更听话一些。还有一些人坚持“不严加管教会惯坏孩子”的传统信念，认为“打屁屁”是为孩子好。研究者对16 万名儿童在过去5 年里的经历进行研究，通过收集“打屁屁”行为的元数据加以分析，发现：打屁股会在儿童成长过程中造成智商低、攻击性行为高等多种负面影响。以下哪项如果为真，最能支持上述结论（  ）","options":["最新调查显示，智商相对较低的孩子大多数经常被家长打屁股","本身不听话且更容易惹祸的孩子更有可能受到父母的严厉惩罚","研究报告称全球大约80%的父母都有以打屁股管教孩子的经历","被打屁股而困惑的孩子只懂得按家长要求去做而不会独立思考"],"a":3,"e":"【答案】D\n【解析】加强论证。论点：打屁股会在儿童成长过程中造成智商低、攻击性行为高等\n多种负面影响。\nA 项，论点说打屁股会造成智商低，而选项说智商低的孩子容易被打，因果倒置，有\n削弱作用，排除；\nB 项，不听话惹祸的孩子可能受到父母严厉惩罚，而严厉惩罚和打屁股之间的联系我\n们无从得知，论题不一致，排除；\nC 项，大部分父母都以打屁股管教孩子，但是造成的后果没有明确说明，论据不可预\n见，排除；\nD 项，被打屁股而困惑的孩子只懂得按家长要求去做而不会独立思考，不会独立思考\n属于负面影响中的一种，加强论点，当选。\n故正确答案为D。"},{"q":"荷兰研究人员一直在试图模拟月球和火星的土壤条件进行农作物栽培实验。他们对该项实验种出的小红萝卜、豌豆、黑麦和西红柿进行初步分析。实验结果令人充满希望，这些产品不仅安全，而且可能比在地球土壤种出的农作物更健康。英国媒体称，能在火星土壤种出可食用作物，殖民火星的希望又向前迈进了一步。如果以下各项为真，不能质疑英国媒体说法的是（  ）","options":["火星土壤重金属占比和地球土壤不一样","在另一个同类实验中土豆的长势很糟糕","从实验到真正付诸实践还有很长的路要走","月球、火星、地球的气候条件有很大不同"],"a":2,"e":"【答案】C\n【解析】削弱论证，选非题。论点：能在火星土壤种出可食用作物，殖民火星的希望\n又向前迈进了一步。论据：试图模拟月球和火星的土壤条件进行农作物栽培实验，对该项\n实验种出产品进行初步分析，这些产品不仅安全，而且可能比在地球土壤种出的农作物更\n健康。\nA 项，该项指出火星土壤和地球土壤重金属占比不一样，也就是说地球土壤无法模拟\n出真正的火星土壤，所以土壤模拟实验不科学，具有削弱作用，排除；\nB 项，在另一个同类实验中土豆的长势很糟糕，说明火星土壤不能种出更好的农作\n物，举反例削弱，排除；\nC 项，从实验到真正付诸实践还有很长的路要走，而论点说“殖民火星的希望又向前\n迈进了一步”，题干论点并没有强调现在就要移民火星，只是强调有希望，所以该项没有\n削弱作用，当选；\nD 项，月球、火星、地球的气候条件有很大不同，而气候对于人类生活有很大影响，\n有削弱作用，排除。\n故正确答案为C。"},{"q":"某科研机构提出潮湿的沙子是古埃及人在沙漠中搬运巨大石块和雕像的关键。研究人员指出，古埃及人将沉重的石块放上滑橇后，先在滑橇前铺设一层潮湿的沙子，再牵引它们，这种搬运方式起到了意想不到的效果。在实验中，研究人员使用流变仪测试沙子的硬度，以证实需要多少牵引力才能使一定数量的沙子变形，并在此基础上设计了牵引模型，从中发现将潮湿的沙子铺在滑橇前能更容易移动重物，而且沙子所含水分决定了沙子的硬度和牵引力。如果以下哪项为真，最能支持上述结论（  ）","options":["在一幅古埃及墓室壁画中，一名男子站在滑橇前方，似乎正在浇水","滑橇牵引力与沙子硬度成反比，潮湿沙子的硬度是干燥沙子的两倍","实验证明，铺设在滑橇前的潮湿沙子容易堆积，形成较大滑动阻力","一个实验室版的埃及滑橇被成功建造，能够模拟古埃及工地的实况"],"a":1,"e":"【答案】B\n【解析】加强论证。论点：潮湿的沙子是古埃及人在沙漠中搬运巨大石块和雕像的关\n键。论据：古埃及人将沉重的石块放上滑橇后，先在滑橇前铺设一层潮湿的沙子，再牵引\n它们，这种搬运方式起到了意想不到的效果。\nA 项，只是描述了一幅壁画的内容，与潮湿的沙子在搬运中的作用无关，论题不一\n致，排除；\nB 项，滑橇牵引力与沙子硬度成反比，潮湿沙子的硬度是干燥沙子的两倍，说明沙子\n硬度越硬，则牵引力越小，解释了为什么潮湿的沙子成为搬运关键，当选；\nC 项，铺设在滑橇前的潮湿沙子容易堆积，形成较大滑动阻力，会使搬运变得更加困\n难，属于削弱论点，排除；\nD 项，实验室版的埃及滑橇被成功建造，但是没有提到利用潮湿沙子搬运的论题，排\n除。\n故正确答案为B。"},{"q":"如果向大气排放的CO2 累积超过32000 亿吨，那么到本世纪末，将升温控制在2℃以内的门槛就守不住了。有科学家认为，为了达到将升温幅度控制在2℃以内的目标，仅仅限制CO2 排放是不够的，必须在全球范围内大规模开展大气CO2 的回收行动，使大气污染程度得到有效控制和缓解。若要使上述科学家的想法成立，最需要补充以下哪项作为前提（  ）","options":["全球范围内普及关于气候变化的科学知识","各国政府推出有效政策来控制CO2 排放量","科学界整合资源来支持发展地球工程技术","各地都建立能有效回收和储存CO2 的机制"],"a":3,"e":"【答案】D\n【解析】加强论证。论点：在全球范围内大规模开展大气CO2 的回收行动，使大气\n污染程度得到有效控制和缓解。\nA 项，普及气候变化的科学知识与大气CO2 的回收行动无直接联系，论题不一致，排\n除；\nB 项，推出有效政策来控制CO2 排放量与回收无直接联系，论题不一致，排除；\nC 项，科学界整合资源来支持发展地球工程技术，但是与回收大气CO2 有无关系无从\n得知，排除；\nD 项，如果各地不能建立有效回收和储存CO2 的机制，那么就无法再全球范围内大规\n模开展大气CO2 的回收行动，所以此选项是论点成立的必要条件，当选。\n故正确答案为D。"},{"q":"我们身体的生物钟系统会受到许多因素的影响，其中之一就是光照。研究表明，光照可以有效地欺骗大脑进入“白昼模式”，哪怕当时人的眼睛是闭着的也没关系。研究人员发现可以用光照疗法来帮助我们调整时差，包括持续光照和不同间隔的闪光，而每10 秒一次持续仅2 毫秒的闪光最有效。研究还发现，在睡眠时经历过“闪光处理”的人出现困意的周期会延后两个小时。以下哪项如果为真，最能支持上述观点（  ）","options":["每次闪光间隙的黑暗都有助于让眼睛重启，从而恢复眼睛对光照的敏感","大部分睡眠时经历“闪光处理”的人的睡眠质量都不会受到闪光的影响","去时区早两小时的城市，启程日日出前两小时经光照疗法的人无时差感","依靠自身来调节时差耗时良久，大概平均每天只能倒过一个小时的时差"],"a":2,"e":"【答案】C\n【解析】加强论证。论点：我们身体的生物钟系统会受到许多因素的影响，其中之一\n就是光照。论据：研究表明，光照可以有效地欺骗大脑进入“白昼模式”，可以用光照疗\n法来帮助我们调整时差，在睡眠时经历过“闪光处理”的人出现困意的周期会延后两个小\n时。\nA 项，讨论眼睛对光的敏感，和题干论题不一致，排除；\nB 项，讨论的是闪光对睡眠质量的影响，与论点光照是否影响生物钟无关，论题不一\n致，排除；\nC 项，时差提早两个小时，经过光照治疗的人没有时差感，举例证明光照影响生物\n钟，举例加强，当选；\nD 项，题干讨论光照是否影响生物钟系统，和自身调整时差没关系，论题不一致，排\n除。\n故正确答案为C。"},{"q":"某研究团队让两批测试者分别进入睡眠实验室里睡上一夜，第一批被安排睡得很晚，从而减少总睡眠时间；第二批被安排睡得早，但在睡眠过程中多次被吵醒。第二晚过后，结果就已经显现：第二批测试者的积极情绪受到严重影响。他们的精力水平较低，同情心和友善度等积极情绪指数有所下滑。部分研究者据此认为，被吵醒导致了测试者无法得到足够的慢波睡眠，而慢波睡眠是恢复精力感的关键，但也有研究者对此项研究的可信度提出质疑。以下哪项如果为真，最能反驳质疑者（  ）","options":["第一批测试者积极情绪的指数下滑程度不太明显","第二批测试者中大部分人长期以来情绪不够积极","两批测试者的健康状况和心理素质原本就很接近","两批测试者在参与睡眠实验前精力水平参差不齐"],"a":0,"e":"【答案】A\n【解析】削弱论证。反驳质疑者即加强“被吵醒导致了测试者无法得到足够的慢波睡\n眠，而慢波睡眠是恢复精力感的关键”。\nA 项，第一批积极情绪指数下滑不明显，第二批下滑明显，才能证明确实是“被吵\n醒”导致了测试者积极情绪下滑，精力水平低，无法得到足够的睡眠，可以加强，当选；\nB 项，研究者选取的实验对象情绪不积极，说明实验选取对象不够典型。削弱“被吵\n醒导致了测试者无法得到足够的慢波睡眠，而慢波睡眠是恢复精力感的关键”即加强质疑\n者的观点，排除；\nC 项，实验对比每批测试者实验前后情绪变化差别，与两批测试者之间心理健康差异\n无关，论题不一致，排除；\nD 项，实验对比每批测试者实验前后自身情绪变化差别，与两批测试者在实验前的精\n力水平无关，论题不一致，排除。\n故正确答案为A。"},{"q":"东亚人看起来更谦虚，但心理学研究表明，和接受其他文化熏陶的人相比，他们也一样充满骄傲和自信。某研究团队招募了40 名志愿者参与研究，其中一半来自东亚国家，剩下的来自西方国家。他们向这些志愿者展示大量正面和负面的词语，并询问他们哪些形容词适合自己，结果，志愿者们无论有什么样的文化背景，他们倾向于用更多正面的形容词来描述自己，认为一些较为负面的特征不适合自己。研究者认为，这表明参与测试的人无论具有何种文化背景，他们同样都有美化自己的动机。以下哪项如果为真，最能削弱上述论证（  ）","options":["东亚人习惯负面评价自己，而西方人往往对自己的能力言过其实","当志愿者被要求用正面词汇形容自己时，他们的反应都是一样的","东亚人谦逊只是一种文化惯例，他们有着和西方人一样的自尊心","研究发现，无论来自何种文化背景，志愿者们的脑电波都很相似"],"a":0,"e":"【答案】A\n【解析】削弱论证。论点：无论具有何种文化背景，他们同样都有美化自己的动机。\n论据：志愿者们无论有什么样的文化背景，他们都倾向于用更多正面的形容词来描述自\n己，认为一些较为负面的特征不适合自己。\nA 项，东亚人习惯负面评价自己，而西方人往往言过其实，说明东亚人和西方人并不\n都有美化自己的动机，可以削弱，当选；\nB 项，要求用正面词汇形容自己，他们的反应一样，并不能说明他们是否都具有美化\n自己的动机，论据不可预见，排除；\nC 项，东亚人与西方人具有一样的自尊心，但有自尊心不一定会美化自己，论据不可\n预见，排除；\nD 项，脑电波相似与是否具有美化自己的动机无关，论题不一致，排除。\n故正确答案为A。\n第三组："},{"q":"一项调查发现，在牛奶人均消费量大的地区，癌症的发病率较高；而牛奶人均消费量少的地区，癌症发病率极低。有人据此得出结论：饮用牛奶会使癌症的发病率上升。以下哪项如果为真，最能质疑上述结论（  ）","options":["癌症发病率高的地区，其他疾病的发病率相对较低","牛奶含钙量高、吸收好，而且睡前喝牛奶有助于睡眠","调查中牛奶人均消费量大的地区，人口总数也相对较大","牛奶人均消费量大的地区居民寿命较长，且罹患癌症的主要是中老年人"],"a":3,"e":"【答案】D\n【解析】削弱论证。论点：饮用牛奶会使癌症的发病率上升。论据：在牛奶人均消费\n量大的地区，癌症的发病率较高；而牛奶人均消费量少的地区，癌症发病率极低。\nA 项，选项说的是癌症发病率与其他疾病关系，与论点当中所讨论的饮用牛奶是否会\n影响癌症的发病率无关，论题不一致，排除；\nB 项，选项说的是牛奶的功效，与论点当中所讨论的饮用牛奶是否会影响癌症的发病\n率无关，论题不一致，排除；\nC 项，选项说的是人口总数与牛奶消费量之间的关系，与论点当中所讨论的饮用牛奶\n是否会影响癌症的发病率无关，论题不一致，排除；\nD 项，选项说的牛奶消费量大的地区居民的寿命都较长，且患罹患癌症的都是老年\n人，说明患罹患癌症的原因可能是因为年龄的问题，而不是喝牛奶所导致，另有他因，具\n有削弱作用，当选。\n故正确答案为D。"},{"q":"为了解对学校食堂的满意度，某大学进行了一项“我最满意的食堂”评比活动。通过让学生对食堂的饭菜质量、价格、服务态度、卫生状况等10 项指标进行评分来反映其对食堂的满意度，学生给每个评分指标赋以1 到10 分的某一个分值，然后计算出10 项评分指标的平均得分，从而得出学生对食堂的满意度。实施这一项评比活动需要假设的前提是（  ）I．对饭菜质量，服务态度等指标的评价可以用数字来表述II．上述10 项指标对学生来说同等重要III．该大学的每个学生都参与了这次评比活动","options":["仅Ⅰ","仅Ⅱ","仅Ⅰ和Ⅱ","Ⅰ、Ⅱ和Ⅲ"],"a":2,"e":"【答案】C\n【解析】加强论证。论点：通过学生为饭菜质量、价格、服务态度、卫生状况等10\n项指标打分，计算出10 项评分指标的平均得分，从而得出学生对食堂的满意度。\nⅠ：采用否定带入，如果对饭菜质量，服务态度等指标的评价不可以用数字来从而无\n法得到对食堂的满意度，因此，该项为活动需要假设的前提。\nⅡ：采用否定带入，如果上述10 项指标对学生来说不同等重要，那么通过各项的平\n均分就无法反映学生的满意度，因此，该项为活动需要假设的前提。\nⅢ：采用否定带入，有学生没有参与这项调查，我们最终每项指标取的是平均值，所\n以学校依然可以依据其他学生的评分了解到学生对于食堂是否满意，因此，该项不是假设\n的前提。\n故正确答案为C。"},{"q":"毛囊干细胞是在毛囊中长期生活的细胞，终身为我们产生毛发。毛囊干细胞从血液中吸收葡萄糖，经过代谢，葡萄糖变为丙酮酸。这些丙酮酸一部分被细胞运输进线粒体，在线粒体中，丙酮酸进一步的代谢能够为细胞提供能量。另一部分丙酮酸将在细胞内进行后续的变化，产生新的代谢产物——乳酸，乳酸可以激活毛囊干细胞，使毛发生长得更快速。据此，有研究人员认为，通过药物提高乳酸的含量可以治疗脱发。以下哪项如果为真，最能支持上述结论（  ）","options":["葡萄糖的代谢功能是生命体自我修复的重要方式","通过药物提供的乳酸能够直接作用于毛囊干细胞","人为增加乳酸的含量不会对毛囊干细胞产生其他影响","减少丙酮酸进入线粒体，可以使毛囊干细胞产生更多乳酸"],"a":1,"e":"【答案】B\n【解析】加强论证。论点：通过药物提高乳酸含量可以治疗脱发。论据：乳酸可以激\n活毛囊干细胞，使毛发生长得更快速。\nA 项，葡萄糖的代谢功能是生命体自我修复的重要方式，与论点所讨论的乳酸能否治\n愈脱发没有关系，论题不一致，排除；\nB 项，药物提供的乳酸能够直接作用于毛囊干细胞，说明药物可以用于治愈脱发，提\n供前提，可以加强，当选；\nC 项，人为的增加乳酸到底会不会对于我们毛囊干细胞产生影响与论点所讨论的乳酸\n能否治愈脱发没有关系，论题不一致，排除；\nD 项，减少丙酮酸可以产生更多乳酸，与论点所讨论的乳酸能否治愈脱发没有关系，\n论题不一致，排除。\n故正确答案为B。"},{"q":"德国经济在席卷全球的金融危机当中受到的冲击与其他发达国家相比较小，主要原因是德国经济建立在先进的制造业的基础上，德国的机械装备和汽车制造业保持了很强的竞争力。一些人根据德国的例子得出结论：只有具备强大的制造业竞争水平，一个国家的经济才有高度的稳定性。如果以下各项为真，哪项能够质疑上述结论（  ）","options":["有些制造业不发达的国家在金融危机中受影响较小","某国制造业不发达，该国经济一直动荡不安","有些国家保持长期经济稳定，却没有发达的制造业","有些国家制造业很发达，但经济并没有长期保持稳定"],"a":2,"e":"【答案】C\n【解析】削弱论证。论点：只有具备强大的制造业竞争水平，一个国家的经济才有高\n度的稳定性。经济稳定→具备强大的制造业竞争水平。\nA 项，有些制造业不发达的国家情况与论点无关，论题不一致，排除；\nB 项，某国制造业不发达，否定翻译的后件，否后必否前，得出该国经济一直动荡不\n安，可以加强，排除；\nC 项，有些国家保持长期经济稳定，却没有发达的制造业，翻译：经济稳定且没有发\n达的制造业，可以削弱，当选；\nD 项，有些国家制造业很发达，肯定了翻译的后件，所以经济有没有稳定增长都有可\n能，不能削弱，排除。\n故正确答案为C。"},{"q":"医生告诫人们，抽烟喝酒有害健康，但又有学者从统计学角度发现，一些根据习俗从不抽烟不喝酒的民族，平均寿命要比经常抽烟喝酒的民族短5—10 岁。因此学者推测，抽烟喝酒虽然可能损伤肺和肝的功能，但不一定会影响人的寿命。以下哪项如果为真，最能质疑上述观点（  ）","options":["抽烟和喝酒的时候能让大脑获得欣快感，排解压力，感到愉悦","那些根据习俗而杜绝烟酒的民族其饮食也相对单一，并且热量极高","抽烟喝酒是肺癌和肝癌的重要原因，而这两种疾病位于疾病死亡谱的前两位","烟酒可以刺激大脑分泌多巴胺，让人体各器官进入放松状态，促进身体修复"],"a":2,"e":"【答案】C\n【解析】削弱论证。论点：抽烟喝酒虽然可能损伤肺和肝的功能，但不一定会影响人\n的寿命。论据：一些根据习俗从不抽烟不喝酒的民族，平均寿命要比经常抽烟喝酒的民族\n短5—10 岁。\nA 项，选项讨论抽烟喝酒会让人愉悦，能排解压力，题干当中讨论抽烟喝酒对寿命的\n影响，论题不一致，排除；\nB 项，选项提到“饮食单一”、“热量极高”并未涉及到抽烟喝酒对寿命的影响，论\n题不一致，排除；\nC 项，论点中“抽烟喝酒对寿命不一定有影响”，抽烟喝酒会导致肺癌和肝癌两种癌\n症，而这两种癌症死亡率高说明对寿命有很大的影响，可以削弱，当选；\nD 项，指出烟酒让器官放松，但本题论点为烟酒对寿命的影响，论题不一致，排除。\n故正确答案为C。"},{"q":"科学家重建地球地质历史上的大气成分面临的难题之一就是——缺少可用样品。近年来，不少人开始关注琥珀，他们认为相比其他有机材料，琥珀在长久的地质年代内，所保存的化学和同位素信息几乎不会改变。因此可以用于揭示不同年代的全球大气成分。以下哪项如果为真，最能质疑上述结论（  ）","options":["由于琥珀内部常保留着生物的形体，故能反映当时生态环境与生物的关系","琥珀主要诞生于约四千万至六千万年前的始新世纪，其他年份并没有形成琥珀","琥珀是由松柏科植物的树脂经压力和热力作用形成，由于时间漫长，数量极少","琥珀的硬度较低，如果因搬运、储存不当而造成损害，会影响同位素检测的准确性"],"a":1,"e":"【答案】B\n【解析】削弱论证。论点：琥珀可以用于揭示不同年代的全球大气成分。论据：琥珀\n在长久的地质年代内，所保存的化学和同位素信息几乎不会改变。\nA 项，选项讨论的是琥珀能反映当时的生态环境和生物的关系，而题干中讨论的是琥\n珀可以揭示不同年代的全球大气成分，论题不一致，排除；\nB 项，琥珀在其他年份没有形成，因此只能显示形成时期的大气成分，无法揭示不同\n年代的全球大气成分，削弱论据，当选；\nC 项，琥珀的数量少，与论点中是否揭示不同年代的全球大气成分无关，论题不一\n致，排除；\nD 项，只是提到“如果储存不当”会影响同位素检测，并没有提及所有的琥珀都被搬\n运损害，不可预见，排除。\n故正确答案为B。"},{"q":"胎儿大脑发育需要一种重要的营养物质w-3 脂防酸即二十二碳六烯酸（DHA）。有人建议，孕妇在孕期服用富含DHA 的鱼油补充剂有利于胎儿的大脑发育。临床试验中，两组孕妇每日服用含有800 毫克DHA 的补充剂或安慰剂。两组孩子在18 个月大时，其平均的认知、语言及运动评分之间没有差别。此后，研究人员对这些孩子在4 岁时的表现进行了跟踪评估，大多数（91.9%）家庭参与了该研究。研究人员发现，对认知、从事复杂思维处理、语言及执行功能（如记忆、推理、解决问题）的检测结果在两组间没有显著差异。研究者认为，母亲妊娠期补充DHA 不能使孩子更聪明。以下哪项如果为真，最能驳斥研究者观点（  ）","options":["胎儿的DHA 来自母亲的饮食，但母亲需要摄入的DHA 的确切数量目前难以确定","DHA 补充剂可能降低早产的风险，也可能降低那些有家族过敏史的孩子患过敏的风险","7 岁才是能够预测智力的最早年龄，4 岁时各种因素对发育的影响尚未充分表现，不能可靠评估","研究证明，孩子出生后补充DHA 有益于认知能力发展，该国婴儿出生后常规服用富含DHA 的补充剂"],"a":2,"e":"【答案】C\n【解析】削弱论证。论点：母亲妊娠期补充DHA 不能使孩子更聪明。论据：临床试\n验中，两组孕妇每日服用含有800 毫克DHA 的补充剂或安慰剂。两组孩子在18 个月大\n时，其平均的认知、语言及运动评分之间没有差别。此后，研究人员对这些孩子在4 岁时\n的表现进行了跟踪评估，大多数（91.9%）家庭参与了该研究。研究人员发现，对认知、\n从事复杂思维处理、语言及执行功能（如记忆、推理、解决问题）的检测结果在两组间没\n有显著差异。\nA 项，母亲需要摄入的DHA 的确切数量目前难以确定，与论点讨论的母亲妊娠期补\n充DHA 不能使孩子更聪明无关，论题不一致，排除；\nB 项，与论点讨论的母亲妊娠期补充DHA 对孩子的聪明与否无关，论题不一致，排\n除；\nC 项，断开了论据和论点之间的联系，拆桥项，可以削弱，当选；\nD 项，孩子出生后补充DHA 与论点讨论的母亲妊娠期补充DHA 对孩子的聪明与否无\n关，论题不一致，排除。\n故正确答案为C。"},{"q":"考古学家通过对消失已久的鹦鹉嘴龙进行体色重建，发现其腹部颜色为浅色而背部颜色较深。这是一种保护色，作用是通过在身体上形成阴影，让动物自身在其他动物眼中失去立体效果，因此也被称为反荫蔽体色，这在现代动物中也较为常见。据此分析，考古学家推测鹦鹉嘴龙最有可能居住在森林里。要得到上述结论，最需要补充的前提条件是（  ）","options":["生活在森林中的动物其体色模式大多为反荫蔽体色","恐龙包含许多种类，其中大部分都生活在森林和草原中","在一发现恐龙化石的地区，考古推测该区域曾有大片的森林","鹦鹉嘴龙是一种小型恐龙，这种体色对于逃避天敌有天然的伪装作用"],"a":0,"e":"【答案】A\n【解析】加强论证。论点：考古学家推测鹦鹉嘴龙最有可能居住在森林里。论据：考\n古学家通过对消失已久的鹦鹉嘴龙进行体色重建，发现其腹部颜色为浅色而背部颜色较\n深。这是一种保护色，作用是通过在身体上形成阴影，让动物自身在其他动物眼中失去立\n体效果，因此也被称为反荫蔽体色，这在现代动物中也较为常见。\nA 项，论据是鹦鹉嘴龙有反荫蔽体色，论点是鹦鹉嘴龙最有可能居住在森林里，选项\n建立了论点和论据之间的联系，搭桥项，可以加强，当选；\nB 项，恐龙大部分都生活在森林和草原，但并不能推出鹦鹉嘴龙生活在草原还是森\n林，论据不可预见，排除；\nC 项，该区域曾有大片的森林不能代表鹦鹉嘴龙生活在森林，论题不一致，排除；\nD 项，该体色对鹦鹉嘴龙的作用与鹦鹉嘴龙的生活地点无关，论题不一致，排除。\n故正确答案为A。"},{"q":"某研究小组在1984 年挑选了10 万名身体健康的志愿者，在2010 年的反馈调查中，超过2.6 万名志愿者已经离世。研究小组发现，经常食用诸如麦片、糙米、玉米和藜麦等粗粮的志愿者生病和死亡比例比不食用者低，尤其是患血管疾病的比例更低。研究人员认为，食用粗粮有助于身体健康。以下哪项如果为真，不能支持研究人员的结论（  ）","options":["粗粮是运动员和减肥人士的最佳早餐","粗粮是世界上很多国家老百姓的主食","在很多医学典籍里，有食用粗粮治病的记载","经常食用粗粮有助于降低罹患肥胖症的风险"],"a":1,"e":"【答案】B\n【解析】加强论证，选非题。论点：食用粗粮有助于身体健康。论据：经常食用诸如\n麦片、糙米、玉米和藜麦等粗粮的志愿者生病和死亡比例比不食用者低，尤其是患血管疾\n病的比例更低。\nA 项，运动员和减肥人士食用的早餐会相对健康，举例子说明食用粗粮有助于身体健\n康，加强论据，排除；\nB 项，粗粮是世界上很多国家老百姓的主食与食用粗粮健康与否无关，论题不一致，\n当选；\nC 项，举例说明食用粗粮有助于身体健康，加强论据，排除；\nD 项，食用粗粮有助于降低罹患肥胖症的风险，解释说明食用粗粮有助于身体健康，\n加强论据，排除。\n故正确答案为B。"},{"q":"3 月20 日，某网约车公司对北京三环内非京牌车辆停止派单，9 天后，该公司又在客户端上给司机发出了一则通知，宣布从4 月1 日起将在全北京范围内停止向非京牌车辆派单。这说明从4 月1 日起，北京市民将再次面临“叫车难”的问题。以下哪项最能削弱上述预测（  ）","options":["停止向非京牌车辆派单能在一定程度上缓解交通拥堵","在北京运营的网约车中，外地牌照车辆大约占一半以上","该网约车公司表示，将会采取多种措施提升北京市民叫车的效率","很多“京人京牌”并且符合细则规定的网约车司机对未来充满了期待"],"a":2,"e":"【答案】C\n【解析】削弱论证。论点：从4 月1 日起，北京市民将再次面临“叫车难”的问题。\n论据：某网约车公司对北京三环内非京牌车辆停止派单，9 天后，该公司又在客户端上给\n司机发出了一则通知，宣布从4 月1 日起将在全北京范围内停止向非京牌车辆派单。\nA 项，缓解交通拥堵与“叫车难”无关，论题不一致，排除；\nB 项，在北京运营的网约车中，外地牌照车辆大约占一半以上，从4 月1 日起将在全\n北京范围内停止向非京牌车辆派单，那北京市民将再次面临“叫车难”的问题，可以加\n强，排除；\nC 项，采取多种措施提升北京市民叫车的效率，直接否定论点中的“叫车难”的问\n题，削弱论点，当选；\nD 项，符合细则规定的网约车司机对未来充满了期待与“叫车难”问题无关，论题不\n一致，排除。\n故正确答案为C。\n第四组："},{"q":"有一种观点认为，人体缺水是导致感冒的原因。反对者则认为，并非是缺水，受凉才是导致感冒的根本原因。以下哪项如果为真，最能削弱反对者的观点（  ）","options":["人体缺水之后，更容易受凉","感冒往往伴随着发烧，而发烧通常会导致缺水、怕冷","即使没有受凉，人体缺水之后也会出现很多类似感冒的症状","受凉之后，更容易导致人体缺水、抵抗力下降，从而引发感冒"],"a":0,"e":"【答案】A\n【解析】削弱论证。论点：感冒不是缺水导致的，受凉才是导致感冒的根本原因。\nA 项，缺水导致受凉进而导致感冒，因此导致感冒的根本原因是缺水，削弱论点，当\n选；\nB 项，发烧会导致缺水，感冒伴随着发烧，但是未表明感冒与缺水的关系，无法削\n弱，排除；\nC 项，类似感冒的症状并非一定是感冒，论据不可预见，排除；\nD 项，受凉导致人体缺水、抵抗力下降，从而引发感冒，因此受凉才是导致感冒的根\n本原因，加强论点，无法削弱，排除。\n故正确答案为A。"},{"q":"如果专利技术的宣传推广有足够的资金支持，那么专利技术的拥有者将更加关注其专利技术的宣传推广工作。专利技术宣传推广得越充分，其转化为专利产品、创造价值的可能性也就越大，整个社会的创新能力也将得到进一步提高。因此，如果国家增加专利技术宣传推广的补贴，那么将有力增强整个社会的创新能力。以下哪项如果为真，最能支持上述论述（  ）","options":["有些专利技术转换为产品后所带来的收益尚不足以支付其宣传推广费用","专利技术拥有者越关注宣传推广，其专利技术的宣传推广就可以做得越充分","如果国家不增加专利技术宣传推广的补贴，那么将不能增强整个社会的创新能力","如果专利技术拥有者不关注宣传推广工作，那么其专利技术就很难转化为专利产品"],"a":1,"e":"【答案】B\n【解析】加强论证。论点：如果国家增加专利技术宣传推广的补贴，那么将有力增强\n整个社会的创新能力。论据：如果专利技术的宣传推广有足够的资金支持，那么专利技术\n的拥有者将更加关注其专利技术的宣传推广工作。专利技术宣传推广得越充分，其转化为\n专利产品、创造价值的可能性也就越大，整个社会的创新能力也将得到进一步提高。论点\n可以翻译为：国家增加宣传推广的补贴→增强社会的创新能力。论据可以翻译为：宣传推\n广有足够的资金支持→更关注宣传推广工作；宣传推广得越充分→创新能力进一步提高。\n要想得出论点“国家增加宣传推广的补贴→增强社会的创新能力”，需要将论据中的两个\n逻辑表达式建立联系，将“更关注宣传推广工作”与“宣传推广得越充分”建立联系，对\n应B 项。\n故正确答案为B。"},{"q":"一项研究认为，发达国家近20 年来治疗甲状腺肿瘤的病例增多主要是因为过度诊疗。研究人员认为，随着新型成像技术的出现，越来越微小的甲状腺肿瘤被检测出来。大部分过度治疗的方式是完全切除甲状腺，它通常还和其他一些有害处理手段相结合，比如完全切除脖子上的淋巴结或者实施放射疗法。而实际上这些肿瘤大部分是微型乳头状瘤，只需要密切监视，不必立即采取干预性治疗手段。以下哪项如果为真，最能支持上述结论（  ）","options":["过度使用放射疗法会损害人体的免疫系统","在发达国家，乳腺肿瘤也存在过度治疗的问题","完全切除甲状腺并非是治疗所有甲状腺疾病的最佳方式","在不存在过度诊疗的国家，甲状腺肿瘤的发病率及病死率并没有明显增高"],"a":3,"e":"【答案】D\n【解析】加强论证。论点：发达国家近20 年来治疗甲状腺肿瘤的病例增多主要是因\n为过度诊疗。论据：随着新型成像技术的出现，越来越微小的甲状腺肿瘤被检测出来。大\n部分过度治疗的方式是完全切除甲状腺，它通常还和其他一些有害处理手段相结合，比如\n完全切除脖子上的淋巴结或者实施放射疗法。而实际上这些肿瘤大部分是微型乳头状瘤，\n只需要密切监视，不必立即采取干预性治疗手段。\nA 项，题干中未标明论点中讨论的过度诊疗就是过度使用放射疗法，论题不一致，排\n除；\nB 项，在发达国家，乳腺肿瘤也存在过度治疗的问题，与论点讨论的甲状腺肿瘤病例\n增多的原因是否为过度治疗无关，论题不一致，排除；\nC 项，治疗所有甲状腺疾病的最佳方式与论点讨论的甲状腺肿瘤病例增多的原因无\n关，论题不一致，排除；\nD 项，在不存在过度诊疗的国家，甲状腺肿瘤的发病率及病死率并没有明显增高，说\n明甲状腺肿瘤病例增多的原因确实是因为过度诊疗，举不存在过度诊疗的国家的例子，加\n强论据，当选。\n故正确答案为D。"},{"q":"橙腹草原田鼠实行的是动物世界极为罕见的“一夫一妻制”。研究者首先检测了雌性田鼠的内侧前额叶皮层与伏隔核两个区域的“交流”（这两大区域在解剖学上是相连的，伏隔核在大脑的奖励系统中扮演了关键的角色），然后让这些雌性田鼠与雄性田鼠见面，在见面过程中持续检测这两个脑区之间的交流强度。他们发现，那些脑区交流强度更高的田鼠，更容易与另一半快速建立起亲密关系。他们由此认为，这两个脑区之间的环路的激活，能够直接影响动物爱意的产生。以下哪项如果为真，最能支持以上研究者的观点（  ）","options":["在首次性行为后，橙腹草原田鼠的两个脑区交流的强度，与性行为后它们拥抱的速度快慢有直接关联","既往研究发现，与爱情有关的化学物质，无论是多巴胺还是催产素，或多或少都能激活奖励系统，使人对伴侣产生爱意","研究者让雌雄两只田鼠靠近但不能直接接触，给予特定波长的光，激活这条神经通路。次日，相比面对陌生雄性田鼠，雌性田鼠更愿意与昨日见过的雄性田鼠亲昵","和橙腹草原田鼠超过的基因相同的山地鼠，即使给它们注入足量催产素（与爱情有关的化学物质），它们也依旧对伴侣过夜即忘，研究发现山地鼠的大脑相应区域缺乏催产素的受体"],"a":2,"e":"【答案】C\n【解析】加强论证。论点：这两个脑区之间的环路的激活，能够直接影响动物爱意的\n产生。论据：研究者首先检测了雌性田鼠的内侧前额叶皮层与伏隔核两个区域的“交流”\n(这两大区域在解剖学上是相连的，伏隔核在大脑的奖励系统中扮演了关键的角色)，然后\n让这些雌性田鼠与雄性田鼠见面，在见面过程中持续检测这两个脑区之间的交流强度。他\n们发现，那些脑区交流强度更高的田鼠，更容易与另一半快速建立起亲密关系。\nA 项，两个脑区交流的强度与拥抱的速度有直接关联，不知道是何种关联，论据不可\n预见，排除；\nB 项，选项讨论的是多巴胺、催产素对爱意的影响，而论点讨论的是脑区之间环路的\n激活与爱意之间的关系，论题不一致，排除；\nC 项，选项证明两个脑区之间的环路的激活，确实能够直接影响动物爱意的产生，补\n充论据，可以加强，当选；\nD 项，选项讨论山地鼠缺乏催产素受体，而论点讨论的是脑区之间环路的激活与爱意\n之间的关系，论题不一致，排除。\n故正确答案为C。"},{"q":"一项最新研究发现，脑部DNA 的变异是使人们患上抑郁症和焦虑症的原因，而且这种变化会传递给后代。但是，有反对者认为，脑部杏仁核活动的增加会使应对恐慌的大脑区域的活动增强，这是引发抑郁症和焦虑症的原因。以下哪项如果为真，最能削弱反对者的观点（  ）","options":["DNA 的变异是人类许多疾病的罪魁祸首","不健康的生活习惯也会引发抑郁症和焦虑症","脑部DNA 的变异是使杏仁核活动增加的原因","有些抑郁症和焦虑症患者的脑部DNA 会发生变异"],"a":2,"e":"【答案】C\n【解析】削弱论证。论点：脑部杏仁核活动的增加会使应对恐慌的大脑区域的活动增\n强，这是引发抑郁症和焦虑症的原因。\nA 项，选项说的是DNA 变异会导致许多疾病，而论点说的是引发抑郁症和焦虑症的\n原因，论题不一致，排除；\nB 项，选项说的是不健康的生活习惯也会导致抑郁症和焦虑症，论点说的是脑部杏仁\n核活动增加会导致抑郁症和焦虑症，提供了另一种导致抑郁症和焦虑症的可能性，另有他\n因，可以削弱，保留；\nC 项，选项说的是脑部DNA 变异导致了杏仁核活动增加，而论点说的是杏仁核活动增\n加导致了抑郁症和焦虑症，因此脑部DNA 变异是导致抑郁症和焦虑症的根本原因，削弱\n论点，保留；\nD 项，选项说的是有些抑郁症和焦虑症患者的脑部DNA 会变异，即患病后的情况，\n而论点说的是引发抑郁症和焦虑症的原因，话题不一致，无法削弱，排除。对比B、C 两\n项，B 项为他因削弱，C 项为削弱论点，削弱论点力度大于他因削弱。\n故正确答案为C。"},{"q":"某社区近期举行了一项关于家庭饲养宠物与家庭生活幸福感关系的调查。此次调查走访了100 户家庭，调查的内容包括宠物的种类、饲养宠物的时间、家庭成员的学历和职业等诸多方面。调查结果表明，饲养宠物的家庭，其家庭成员的幸福感普遍高于没有饲养宠物的家庭。这说明，家庭饲养宠物有助于提升家庭生活幸福感。以下哪项如果为真，最能削弱上述论证（  ）","options":["该调查所采集样本数量不足","该社区饲养宠物的通常是那些居住条件较好的居民","没有饲养宠物的家庭，其家庭成员通常为工作较为繁忙的在岗职工","家庭饲养宠物通常是因为其成员有充裕的时间并具有较高的家庭生活幸福感"],"a":3,"e":"【答案】D\n【解析】削弱论证。论点：家庭饲养宠物有助于提升家庭生活幸福感。论据：调查结\n果表明，饲养宠物的家庭，其家庭成员的幸福感普遍高于没有饲养宠物的家庭。\nA 项，调查所采集样本数量不足，证明了调查不够科学，削弱论据，可以削弱，保\n留；\nB 项，选项说的居住条件较好的居民会养宠物，论点说的是饲养宠物可以提升家庭生\n活幸福感，论题不一致，排除；\nC 项，选项解释的是不养宠物的原因，论点说的是饲养宠物可以提升家庭生活幸福\n感，论题不一致，排除；\nD 项，选项说明因为家庭生活幸福感较高，所以才饲养宠物，因果倒置进行削弱，保\n留。比较A、D 两项，A 项为削弱论据，D 项为因果倒置，因果倒置削弱力度大于削弱论\n据。\n故正确答案为D。"},{"q":"睡眠呼吸暂停是一种疾病，表现为患者在睡觉时空气进入肺部受阻。一旦短暂中断呼吸，患者会立刻醒来，以便再度呼吸。因此，深受睡眠呼吸暂停之苦的人有时每一两分钟就要醒一次，这样的情况可能会持续一整夜。一项研究发现，被确诊为睡眠呼吸暂停的男性和女性，患上重度抑郁的可能性分别要比睡得好的人高出2.4 倍和5.2 倍。研究人员认为，睡眠断断续续可能会导致抑郁症。以下哪项如果为真，最能支持上述结论（  ）","options":["睡眠呼吸暂停的患者都有睡眠严重不足的问题","全世界患有抑郁症的女性比男性人数高出两倍多","有研究发现，深睡眠时间较长的人第二天精神状态更好","用辅助设备使患者恢复正常呼吸和睡眠，可显著缓解抑郁症状"],"a":3,"e":"【答案】D\n【解析】加强论证。论点：睡眠断断续续可能会导致抑郁症。论据：被确诊为睡眠呼\n吸暂停的男性和女性，患上重度抑郁的可能性分别要比睡得好的人高出2.4 倍和5.2 倍。\nA 项，该项说的是睡眠呼吸暂停的患者存在睡眠严重不足的问题，未涉及睡眠问题是\n否导致抑郁症，论题不一致，无法加强，排除；\nB 项，该项说的是患有抑郁症的女性比男性人数高出两倍多，选项未涉及睡眠问题是\n否导致抑郁症，论题不一致，无法加强，排除；\nC 项，该项说的是深睡眠时间较长的人第二天精神状态更好，选项未涉及睡眠断断续\n续是否导致抑郁症，论题不一致，无法加强，排除；\nD 项，该项说的是用辅助设备使患者恢复正常呼吸和睡眠，可缓解抑郁症状，说明短\n暂中断呼吸是造成抑郁症的原因，可以加强，当选。\n故正确答案为D。"},{"q":"端粒是DNA 片段，其长度在出生时很长，后逐渐变短，被视为衰老的标志。研究人员分析了多年的数据后发现：至少生育一个孩子的女性其端粒的平均长度比未生育的女性缩短。这个百分比相当于11 年的细胞衰老结果，超过了吸烟和肥胖对细胞老化的影响速度。因此有人提出，生育孩子会让女人加速衰老。以下哪项如果为真，不能驳斥上述观点（  ）","options":["细胞衰老并不代表个体衰老，细胞衰老是防止细胞发生癌变的重要方式","怀孕过程中妇女体内的雌激素水平持续剧烈上升，对细胞端粒具有保护作用","人体结构非常复杂，包括各类细胞、组织、器官，衰老不能通过“端粒”来简单解释","生育有助于女性健康，可降低多种疾病风险，母乳喂养一年，可使妇女患乳腺癌的风险降低三成"],"a":3,"e":"【答案】D\n【解析】削弱论证，选非题。论点：生育孩子会让女人加速衰老。论据：至少生育一\n个孩子的女性其端粒的平均长度比未生育的女性缩短4.2%。这个百分比相当于11 年的细\n胞衰老结果，超过了吸烟和肥胖对细胞老化的影响速度。\nA 项，细胞衰老并不代表个体衰老，个体衰老是论点中的关键词，细胞衰老是论据中\n的关键词，切断了论点和论据之间的联系，可以削弱，排除；\nB 项，怀孕过程中妇女体内的雌激素水平持续剧烈上升，对细胞端粒具有保护作用，\n说明女性可能不会因为生育使端粒变短而加速衰老，否定论据，可以削弱，排除；\nC 项，人体衰老不能通过端粒来简单解释，说明端粒变短不一定代表个体衰老，切断\n了论点的个体衰老和论据的端粒缩短的联系，可以削弱，排除；\nD 项，说的是生育有助于女性健康，可降低多种疾病风险，但题干论点说的是生育孩\n子会让女人加速衰老，衰老和患病并不相同，论题不一致，当选。\n故正确答案为D。"},{"q":"近日，科学家首次证实蜥蜴睡眠时存在快速眼动和慢波睡眠两种状态，在快速眼动状态下，大脑产生高频电波且眼睛快速闪动，这些现象与做梦存在关联。科学家据此推测：蜥蜴和人类一样，在睡眠时会做梦。科学家推测的成立，需要补充以下哪项作为前提（  ）","options":["人类做梦出现在快速眼动阶段","蜥蜴和人类有一些共同的生物特性","睡眠期间快速眼动和慢波睡眠交替进行","研究人员已经证实人在睡眠时会经常做梦"],"a":0,"e":"【答案】A\n【解析】加强论证。论点：蜥蜴和人类一样，在睡眠时会做梦。论据：科学家首次证\n实蜥蜴睡眠时存在快速眼动和慢波睡眠两种状态，在快速眼动状态下，大脑产生高频电波\n且眼睛快速闪动，这些现象与做梦存在关联。\nA 项，选项指出人类做梦出现在快速眼动阶段，在论点和论据之间搭桥，说明人类确\n实和蜥蜴一样都是在快速眼动状态做梦，可以加强，当选；\nB 项，该项指出蜥蜴和人类有一些共同的生物特性，不一定指的是蜥蜴和人类睡眠会\n做梦这个特性，论题不一致，排除；\nC 项，该项指出睡眠期间快速眼动和慢波睡眠交替进行，但不清楚人类是否也是这样\n交替进行，论据不可预见，排除；\nD 项，该项指出人类会做梦，但是不清楚蜥蜴是否和人类一样，论据不可预见，排\n除；\n故正确答案为A。"},{"q":"260 万年前灭绝的巨齿鲨体长超过15 米，拥有强大的咬合力，其3 米宽的下颌可压碎一辆小汽车。然而，近期的一项研究显示，巨齿鲨喜欢捕食的是体长小于5 米的小须鲸，而不是体型更为庞大的大须鲸。但是由于气候的变化，小须鲸的数量锐减。研究人员据此认为，巨齿鲨是因缺少食物而灭绝的。以下哪项如果为真，最能削弱上述结论（  ）","options":["小须鲸在260 万年前数量锐减的原因是缺少食物","大须鲸是所有鲸类中游速最快的，很难被巨齿鲨捕食到","巨齿鲨也喜好捕食体型较小的海豹和现已灭绝的侏儒抹香鲸","与巨齿鲨生活在同一时期的座头鲸和蓝鲸等大型鲸鱼都发生了进化"],"a":2,"e":"【答案】C\n【解析】削弱论证。论点：巨齿鲨是因缺少食物而灭绝的。论据：巨齿鲨喜欢捕食的\n是体长小于5 米的小须鲸，而不是体型更为庞大的大须鲸。但是由于气候的变化，小须鲸\n的数量锐减。\nA 项，选项说的是小须鲸的灭绝原因，而论点是巨齿鲨的灭绝原因，论题不一致，排\n除；\nB 项，选项说的是大须鲸不易被巨齿鲨捕食到，只是说明了为什么巨齿鲨不喜欢捕食\n大须鲸，无法确定巨齿鲨的灭绝原因是不是缺少食物，论题不一致，排除;\nC 项，该项说的是巨齿鲨也喜好捕食体型较小的海豹和现已灭绝的侏儒抹香鲸，说明\n巨齿鲨的食物不只有小须鲸，即小须鲸数量减少不代表巨齿鲨会缺少食物，拆桥项，可以\n削弱，当选；\nD 项，该项说的是座头鲸和蓝鲸等大型鲸鱼发生了进化，而论点是巨齿鲨的灭绝原\n因，论题不一致，无法削弱，排除。\n故正确答案为C。\n第五组："},{"q":"有学者认为，文化产品的生产者、消费者和市场管理者并非是导致文化产品低俗化的原因，文化产品的低俗化是由文化产品市场化导致的，因为市场的逐利性会导致文化产品的生产者、消费者和市场管理者忽视文化发展的社会效益，从而导致文化产品低俗化。以下哪项如果为真，最能削弱上述论证（  ）","options":["文化产品市场化发展必然会引起文化体制改革和文化产业的发展","一些没有实行文化产品市场化的国家，并不存在文化产品低俗化的问题","文化产品市场化的决定因素是文化产品的生产者、消费者和市场管理者","文化产品的生产者、消费者和市场管理者均是以文化产品市场化为导向"],"a":2,"e":"【答案】C\n【解析】削弱论证。论点：文化产品的生产者、消费者和市场管理者并非是导致文化\n产品低俗化的原因，文化产品的低俗化是由文化产品市场化导致的。论据：因为市场的逐\n利性会导致文化产品的生产者、消费者和市场管理者忽视文化发展的社会效益，从而导致\n文化产品低俗化。\nA 项，选项讨论的是文化产品市场化会引起文化体制改革和文化产业的发展，而论点\n讨论的是文化产品的低俗化是由文化产品市场化导致的，论题不一致，排除；\nB 项，选项通过举例说明文化产品低俗化与文化产品市场化之间存在关系，具有加强\n作用，排除；\nC 项，选项指出文化产品的生产者、消费者和市场管理者是造成文化产品市场化的决\n定因素，那么文化产品的低俗化是由文化产品市场化导致的意味着文化产品的生产者、消\n费者和市场管理者是导致文化产品低俗化的原因，直接削弱论点，当选；\nD 项，选项指出决定文化产品的生产者、消费者和市场管理者导向的是文化产品市场\n化，证明了文化产品市场化才是决定因素，具有加强作用，排除。\n故正确答案为C。"},{"q":"一般来说，油品质量标准由石化行业确定，环境检测部门并无相关油品质量监督权。因此，面对城市车辆带来的大量污染物排放和空气污染加剧问题，环保部门在这方面很难真正采取有效措施。要得出以上论断，需要补充以下哪选项作为前提（  ）","options":["油品质量提高能有效降低汽车污染物排放","油品质量提高需要石化企业提高相应的行业标准","环保部门对油品质量标准制定拥有决定权","当前环保部门对石化行业的监督力度较弱"],"a":0,"e":"【答案】A\n【解析】加强论证。论点：面对城市车辆带来的大量污染物排放和空气污染加剧问\n题，环保部门在这方面很难真正采取有效措施。论据：油品质量标准由石化行业确定，环\n境检测部门并无相关油品质量监督权。\nA 项，把论据中的关键词“油品质量”和论点中的关键词“汽车污染物排放”建立联\n系，搭桥，可以加强，当选；\nB 项，油品质量提高的条件，与论点讨论的“环保部门能否采取有效措施治理污染”\n无关，论题不一致，排除；\nC 项，环保部门对油品质量标准制定拥有决定权，对论据中“环境检测部门并无相关\n油品质量监督权”直接进行了否定，削弱论据，排除；\nD 项，当前环保部门对石化行业的监管力度较弱，与论点讨论的“环保部门能否采取\n有效措施治理污染”无关，论题不一致，排除。\n故正确答案为A。"},{"q":"服药能否提高一个人对于音高的识别能力？近来一项国外研究对此做出了肯定的回答。研究者将试验参与者分为两组：第一组服用了丙戊酸，第二组服用了安慰剂，所有的试验参与者均未接受系统的音乐训练，结果发现，在识别音高测试中，第一组的正确识别率更高。研究者据此认为，通过药物治疗可以改善人们对于音高的识别能力。以下哪项如果为真，最能质疑研究人员的上述结论（  ）","options":["第一组试验参与者比第二组的人数多","第一组试验参与者与第二组的平均年龄不同","第一组试验参与者裸耳听力测验成绩高于第二组","第一组试验参与者中父母从事音乐工作的比例较高"],"a":2,"e":"【答案】C\n【解析】削弱论证。论点：通过药物治疗可以改善人们对于音高的识别能力。论据：\n第一组服用了丙戊酸，第二组服用了安慰剂，所有的试验参与者均未接受系统的音乐训\n练，结果发现，在识别音高测试中，第一组的正确识别率更高。\nA 项，试验参与者的人数与人们对于音高的识别能力无关，论题不一致，排除；\nB 项，试验参与者的平均年龄与人们对于高音的识别能力的影响不确定，论据不可预\n见，排除；\nC 项，第一组试验参与者的裸耳听力高于第二组，证明第一组本身的听力要优于第二\n组，所以音高测试的识别率可能受裸耳听力的影响，另有他因，削弱作用，当选；\nD 项，父母是否从事音乐工作对于音高测试识别率的影响不确定，论据不可预见，排\n除。\n故正确答案为C。"},{"q":"所有学术水平突出的教授都深受学生爱戴，而所有学术水平突出的教授都注重培养学生的专业基础知识，因此，有些深受学生爱戴的教授不主张只关注学术前沿问题。上述论证的成立需补充的前提是（  ）","options":["只关注学术前沿问题的教授不受学生爱戴","学术水平突出的教授不主张只关注学术前沿问题","注重培养学生专业基础知识的教授都深受学生爱戴","部分注重培养学生专业基础知识的教授不主张只关注学术前沿问题"],"a":1,"e":"【答案】B\n【解析】加强论证。论点：有些深受学生爱戴的教授不主张只关注学术前沿问题。论\n据：①学术水平突出→受学生爱戴；②学术水平突出→注重培养专业基础知识。根据①可\n换位为：有些深受爱戴的教授学术水平突出，因此可以得到：有些深受爱戴的教授→学术\n水平突出→注重培养专业基础知识。论点强调的是，有些受爱戴的教授不主张只关注学术\n前沿问题，因此需要补充的前提是学术水平突出→不主张只关注学术前沿问题，或者是注\n重培养专业基础知识→不主张只关注学术前沿问题。\n故正确答案为B。"},{"q":"有研究人员声称找到了一种全新的控制糖尿病人血糖浓度的方法，这种新疗法的关键就是咖啡因。他们对患有糖尿病的小鼠进行了试验，当小鼠摄入咖啡因的时候，对于血糖浓度的控制能力比没有摄入咖啡因的小鼠好。研究人员据此认为，以往通过注射胰岛素控制糖尿病人血糖浓度的方法在未来也可以被摄入咖啡因替代。以下哪项如果为真，最能支持上述结论（  ）","options":["上述研究成果被发表在全球顶尖的医学期刊上","每天注射胰岛素对于糖尿病患者来说比较麻烦","研究证明咖啡因可以降低直肠癌和黑色素瘤的发病风险","小鼠和人类体内的肾细胞吸收咖啡因会促进胰岛素的产生"],"a":3,"e":"【答案】D\n【解析】加强论证。论点：以往通过注射胰岛素控制糖尿病人血糖浓度的方法在未来\n也可以被摄入咖啡因替代。论据：对患有糖尿病的小鼠进行了试验，当小鼠摄入咖啡因的\n时候，对于血糖浓度的控制能力比没有摄入咖啡因的小鼠好。\nA 项，讨论的是研究被发表在期刊上面，摄入咖啡因有没有作用没有说明，论题不一\n致，排除；\nB 项，强调的是注射胰岛素麻烦，咖啡因是否起作用没有说明，论题不一致，排除；\nC 项，讨论的是咖啡因可以降低直肠癌和黑色素瘤的发病风险，论点讨论的是糖尿\n病，论题不一致，排除；\nD 项，说明肾细胞吸收咖啡因会促进胰岛素的产生，因此可以用咖啡因代替胰岛素，\n可以加强，当选。\n故正确答案为D。"},{"q":"研究证明，用传统方法熬制的骨头汤中，游离钙含量很低，每100 毫升骨头汤中钙含量只有2 毫克左右，因此传统的“喝骨头汤补钙”的观念是错误的。以下哪项如果为真，最能支持上述结论（  ）","options":["只有游离的钙离子才能被人体消化吸收","骨头汤中含有较多脂肪，常喝骨头汤可能引发高脂血症","骨头汤中含有胶原蛋白，能增强人体造血机能","中国居民的钙摄入量普遍不足，而食补最为方便"],"a":0,"e":"【答案】A\n【解析】加强论证。论点：传统的“喝骨头汤补钙”的观念是错误的。论据：传统方\n法熬制的骨头汤中，游离钙含量很低。\nA 项，强调只有游离的钙离子才能被人体消化吸收，因此其他形式的钙是无法被吸收\n的，而论据中说骨头汤的游离钙很少，因此喝骨头汤不能补钙，可以加强，当选；\nB 项，强调骨头汤会引发高脂血，论点讨论骨头汤能否补钙，论题不一致，排除；\nC 项，强调骨头汤能增强人体造血机能，论题不一致，排除；\nD 项，强调需要食补来补钙，骨头汤能否补钙没有说明，论题不一致，排除。\n故正确答案为A。"},{"q":"一般情况下，女性比男性更为健谈。而一项涉及交谈习惯的报告显示，许多时候男性比女性更能主导谈话，在讨论中平均说出更多的词汇。因此，有人认为，以话语量衡量，两性在语言方面的差异并不大。以下哪项如果为真，最不能支持上述结论（  ）","options":["成年人中，女性在和同学、父母、子女谈话时，大多占据主导地位，而男性则较为收敛，要稍逊一筹","在辩论赛或一些富有争议的话题中，男性往往滔滔不绝，而在涉及情感的话题中，女性则发言更多","研究发现，在夫妻之间的交谈中，男女双方的平均谈话量差异不大，只是因地域不同而有差异","一般年纪小的女孩比男孩平均说话更多，这与其语言学习速度较快有关：但13 岁以后，男孩平均比女孩说话更多"],"a":0,"e":"【答案】A\n【解析】加强论证。选非题，论点：以话语量衡量，两性在语言方面的差异并不大。\n论据：女性比男性更为健谈，许多时候男性比女性更能主导谈话。\nA 项，该项说明成年女性谈话时，大多占据主导地位，否定了现有论据，具有削弱作\n用，当选；\nB 项，在辩论赛或者争议话题中，男性和女性之间各有所长，说明两性之间语言方面\n差距不大，具有加强作用，排除；\nC 项，在夫妻之间的交谈，男女话语量差异不大，说明以话语量衡量两性在语言方面\n的差异并不大，具有加强作用，排除；\nD 项，在年纪小时，女孩平均说话多，但是13 岁以后，男孩平均说话多，说明男女\n在不同年龄段期间，男女说话量各有所长，总体来说差异不大，具有加强作用，排除。\n故正确答案为A。"},{"q":"一项调查发现，家长在子女学习音乐上的投资是“物有所值”的，因为那些曾经学习过音乐的孩子，在长大后往往会拥有更高的学历、更好的职业前景，或获得更丰厚的收入。以下哪项为真时，不能作为支持论据（  ）","options":["调查资料中包括很多功成名就的人士，例如知名科学家或历届总统，他们大都在孩提时代学习过音乐","许多成功的被访者表示学音乐令他们身心平衡并容易感到满足，他们的生活因音乐而更加充实","学习音乐需要自律，在音乐学习中常涉及到科学、语言艺术等其他学科的知识，因此对学生的视野开拓和习惯养成颇有益处","在类似大合唱的音乐学习中，学生必须学会和他人合作，学会聆听与帮助，这将有助于一个人的事业发展"],"a":1,"e":"【答案】B\n【解析】加强论证。选非题，论点：家长在子女学习音乐上的投资是“物有所值”\n的。论据：那些曾经学习过音乐的孩子，在长大后往往会拥有更高的学历、更好的职业前\n景，或获得更丰厚的收入。\nA 项，很多功成名就的人士，在孩提时代学习过音乐，说明家长在子女学习音乐投资\n有助于孩子成功，确实是“物有所值”，具有加强作用，排除；\nB 项，该项说明成功人士学习音乐是令他们身心满足、生活充实，与学历、职业前\n景、更丰厚的收入没有必然联系，论题不一致，当选；\nC 项，学习音乐能够增长其他学科的知识，对学生的视野开拓和习惯养成有好处，说\n明家长在子女学习音乐投资确实是“物有所值”，具有加强作用，排除；\nD 项，学习音乐有助于个人事业发展，家长在子女学习音乐投资确实是“物有所\n值”，具有加强作用，排除。\n故正确答案为B。"},{"q":"一项研究中，研究人员想对比蜂蜜和止咳药物对呼吸道感染儿童的治疗效果。结果显示蜂蜜不仅具有镇咳作用，还有助于睡眠，因此研究者认为对于患呼吸道感染的儿童来说，蜂蜜比止咳药更有效。以下哪项如果为真，最能削弱上述结论（  ）","options":["据了解，目前许多药店中治疗咳嗽的药物大都为成人提供，并不适合6 岁以下的儿童","实验表明，一部分儿童的咳嗽是因肺热引起，一周后就可自行痊愈，并不需要用药","研究发现，蜂蜜止咳效果更佳的原因可能是它可以放松受刺激的喉部，并非真正地治疗感染","一些1 周岁以内的幼儿不宜食用蜂蜜，因为蜂蜜可能对幼儿的肠道产生刺激作用，引发小儿腹泻"],"a":2,"e":"【答案】C\n【解析】削弱论证。论点：对于患呼吸道感染的儿童来说，蜂蜜比止咳药更有效。论\n据：蜂蜜不仅具有镇咳作用，还有助于睡眠。\nA 项，该项讨论的是止咳药不适合6 岁以下的儿童使用，并没有说明蜂蜜和止咳药当\n中哪个更有效，属于论题不一致，排除；\nB 项，该项说肺热咳嗽不需要用药，可自愈，但是没有说明蜂蜜和止咳药当中哪个更\n有效，属于论题不一致，排除；\nC 项，该项说明蜂蜜并非真正地治疗感染，直接否定了蜂蜜的治疗效果，具有削弱作\n用，当选；\nD 项，该项讨论的是蜂蜜会引发小儿腹泻，而论点讨论的是蜂蜜和止咳药谁更有效，\n止咳与腹泻不是同一种病症，论题不一致，排除。\n故正确答案为C。"},{"q":"二氧化碳的排放量剧增导致全球气候变暖，使珠穆朗玛峰所在的喜马拉雅地区冰川正面临急剧缩小的危险。研究显示，珠峰海拔在5000 米到6000 米的冰川集中区域出现冰川快速融化的现象，这些地方将只在冬季而不是在温暖的季节时看到结冰。专家推论说，根据未来的气候变化趋势，喜马拉雅地区的冰川减少的速度还有可能加快，如果本世纪内气温如预测的一样继续升高，该地区的冰川最终将消失殆尽。如果以下各项为真，最能削弱上述论证的是（  ）","options":["喜马拉雅冰川面积每年缩小0.1%到0.6%","喜马拉雅其他地方的冰川对气温变化不敏感","过去50 年珠峰周边冰川覆盖面积减少33.3%","珠峰海拔7000 米以上的冰川没有快速融化的迹象"],"a":1,"e":"【答案】B\n【解析】削弱论证。论点：根据未来的气候变化趋势，喜马拉雅地区的冰川减少的速\n度还有可能加快，如果本世纪内气温如预测的一样继续升高，该地区的冰川最终将消失殆\n尽。\nA 项，喜马拉雅冰川面积每年缩小0.1%到0.6%，表示冰川在持续消失，可以加强，\n排除；\nB 项，喜马拉雅其他地方的冰川对气温变化不敏感，说明气温不一定会影响冰川的消\n失，可以削弱，保留；\nC 项，过去冰川面积减少33.3%，但未说明本世纪内冰川是否会消失殆尽，论据不可\n预见，排除；\nD 项，说珠峰海拔7000 米以上的冰川没有出现快速融化的迹象，举例削弱，保留。\nB、D 对比，B 项范围更广，削弱力度更强，优选B 项。\n故正确答案为B。\n第六组："},{"q":"研究人员设计了这样一个实验。他们从实验鼠体内收集了神经细胞并且将它们植入到家鼠大脑内。实验鼠的寿命大约只有18 个月。而家鼠的寿命是它们的两倍。研究人员发现，当家鼠死亡的时候，从实验鼠植入的神经细胞依然存活。以下哪项可以作为上述实验的结论（  ）","options":["实验鼠的神经细胞比它们所属的生物体的寿命更长","家鼠的神经细胞寿命长于实验鼠的神经细胞寿命","实验鼠的神经细胞寿命长于家鼠的神经细胞寿命","神经细胞可以通过移植而得到无限期的存活"],"a":0,"e":"【答案】A\n【解析】加强论证。论据：实验鼠的神经细胞植入家鼠大脑内，家鼠的寿命是实验鼠\n的两倍。论点：家鼠死亡时，植入的神经细胞依然存活。\nA 项，由实验家鼠死亡而神经细胞依然存活可知，神经细胞比生物体的寿命更长，可\n以得出，当选；\nB 项，家鼠的神经细胞在题干中没有提及，不能进行比较，排除；\nC 项，家鼠的神经细胞寿命在题干中没有提及，不能进行比较，排除；\nD 项，无限期的存活，太过于绝对，由实验无法得出存活时间有多长，论据不可预\n见，排除。\n故正确答案为A。"},{"q":"感冒是自限性疾病，一到两周之后会自愈。如果忍受得了，完全没有必要吃那些缓解症状的感冒药，注意多喝水和休息即可。忍受不了，可吃点缓解症状的感冒药也行，但普通感冒药并不真正治疗感冒。以下哪项如果为真，能够削弱上述观点（  ）","options":["吃药缓解症状可加速感冒的治愈","感冒会自愈，吃药的作用在于缓解症状","多喝水多休息有利于感冒的自愈","感冒药可缓解咳嗽、鼻涕等症状"],"a":0,"e":"【答案】A\n【解析】削弱论证。论点：感冒可以自愈，普通感冒药并不真正治疗感冒。\nA 项，说明吃药可以加速感冒的治愈，说明吃药是有用的，可以削弱，当选；\nB 项，强调感冒能自愈，吃药只是缓解症状，肯定题干论据，加强，排除；\nC 项，强调多喝水有利于感冒自愈，吃药能否治愈感冒并没有说明，论题不一致，排\n除；\nD 项，说明感冒药可缓解症状，而吃药能否治愈感冒没有说明，论题不一致，排除。\n故正确答案为A。"},{"q":"考古学家对安第斯地区出土的900 年到2800 年前的人类骨骼进行了研究。从中提取出的某些化学同位素成分，反映出那里的人当时多以玉米为食。“玉米文化”带动了安第斯地区的人口增长，当时爆发的几次大规模战争也与争夺稀缺的适种玉米的土壤有关，战争导致了社会体系不断变革和发展。因此他们得出结论“农业推动了古代安第斯社会的发展”。以下哪项如果为真，最能质疑上述结论（  ）","options":["安第斯地区的印加文明早在2800 年前就经历了几次较大的社会变革","安第斯地区3600 年前的人类以沿海打鱼为主，直到2800 年左右才逐渐向内陆迁徙","从人类骨骼中提取的另一些化学同位素反映了人们当时也食用马铃薯和豆类","安第斯地区的社会体系拥有中央政府和地方政府，后又衍生出多种社会形态"],"a":1,"e":"【答案】B\n【解析】削弱论证。论点：农业推动了古代安第斯社会的发展。论据：对安第斯地区\n的人类骨骼进行研究，发现以玉米为食，玉米带动人口增长，并且战争也与玉米有关。\nA 项，强调安第斯地区的印加文明发生过变革，论点讨论农业是否推动该地发展，论\n题不一致，排除；\nB 项，说明安第斯地区在2800 年以前以渔业为主，而不是种植作物的农业为主，所\n以并不是农业推动了古代安第斯社会的发展，可以削弱，当选；\nC 项，说明提取到了马铃薯和豆类的化学同位素，而马铃薯和豆类也是农作物，说明\n还是农业推动了发展，可以加强，排除；\nD 项，强调安第斯地区有多种社会形态，论题不一致，排除。\n故正确答案为B。"},{"q":"谷子大约在5000 万年前开始从水稻中分化出来，分化之后的基因组结构仍存在明显的共线性。研究人员发现谷子的2 号和9 号染色体分别由水稻的7 号和9 号，3 号和10号染色体融合而成。同时，他们发现这两次融合事件也发生在高粱的染色体中，由此，研究人员推测这两次染色体融合事件应该发生在高粱从谷子中分化出来之前。上述推理需要以下哪项作为前提（  ）","options":["高粱从谷子中分化出来发生在谷子从水稻中分化出来之后","高粱与谷子之间的共线性小于高粱和水稻之间的共线性","3 号和10 号染色体融使之后不大可能再分离开来","谷子由水稻分化出来之后又发生一次染色体融合事件"],"a":0,"e":"【答案】A\n【解析】加强论证。论点：两次染色体融合事件应该发生在高粱从谷子中分化出来之\n前。论据：谷子的染色体由水稻的染色体融合而成，这两次融合事件也发生在高粱的染色\n体中。\nA 项，如果高粱从谷子中分化出来发生在谷子从水稻分化出来之前，就不可能出现谷\n子还未从水稻分化出来，高粱就从谷子中分化，所以该项是论点成立的前提，可以加强，\n当选；\nB 项，说明的是二者共线性的比较，论点讨论两次染色体融合的时间，论题不一致，\n排除；\nC 项，说明染色体融合后能否分离，论题不一致，排除；\nD 项，说明谷子从水稻分化后又发生染色体融合，论点讨论两次染色体融合的时间，\n论题不一致，排除。\n故正确答案为A。"},{"q":"很多医学者专家提出过量饮用咖啡对健康有害。为验证过量饮用咖啡对心脏的影响，研究人员选取了两组被试者。第一组被试者每天饮用5 杯或5 杯以上咖啡，第二组被试者从不饮用咖啡。一段时间后发现，第一组被试者中患心脏病的比例明显高于第二组被试者。因此，研究人员得出结论，过量饮用咖啡会增加患心脏病的风险。以下哪项如果为真，最能质疑上述论证（  ）","options":["研究发现，每日饮用2 杯咖啡的人心脏功能未受影响","在研究期间，第一组被试者每日的运动量大大小于第二组被试者","除影响心脏功能外，咖啡中所含的咖啡因还易引发焦虑症","第一组被试者中部分人每日饮用10 杯咖啡"],"a":1,"e":"【答案】B\n【解析】削弱论证。论点：过量饮用咖啡会增加患心脏病的风险。论据：第一组被试\n者每天饮用5 杯或5 杯以上咖啡，第二组被试者从不饮用咖啡。发现第一组被试者中患心\n脏病的比例明显高于第二组被试者。\nA 项，饮用2 杯咖啡是否为过量不清楚，论据不可预见，排除；\nB 项，说明第一组患心脏病比例高有可能是缺乏运动导致的，另有他因削弱，当选；\nC 项，说明咖啡还会引发焦虑症，与过量饮用咖啡是否会增加心脏病风险无关，论题\n不一致，排除；\nD 项，10 杯咖啡仍然是5 杯或5 杯以上，这些人的情况没有说明，论据不可预见，排\n除。\n故正确答案为B。"},{"q":"随着气候变化，肥料和供水导致了极大的能源和环境成本，如何让作物更好地吸收营养和水就显得极其重要。因此不少人认为只要增加植物根毛的长度，就可以更有效地吸收水和养分，从而提高作物产量。下列哪项如果为真，最能削弱上述结论（  ）","options":["实践证明，合理控制光照时间，并保证同一块田地间隔播种作物能极大地提高产量","根毛的寿命很短，仅能存活2—3 周便自行脱落，由于更新很快，植物的根部总能保持一个数量相对稳定的根毛区","如果植株过于密集而养料不足，即使增加了根毛长度，也无法保证植物的营养供应","根毛的长度与植物生长激素密切相关，当植物生长激素分泌旺盛时，根毛也变长；而生长激素分泌减少时，根毛也逐渐萎缩"],"a":2,"e":"【答案】C\n【解析】削弱论证。论点：只要增加植物根毛的长度，就可以更有效地吸收水和养\n分，从而提高作物产量。\nA 项，说的是光照可以提高产量，论点说的是增加植物根毛的长度提高作物产量，论\n题不一致，排除；\nB 项，讨论的是根毛的数量稳定，论题不一致，排除；\nC 项，说明增加根毛长度也无法为植物提供营养，不能提高产量，可以削弱，当选；\nD 项，讨论的是根毛的长度和植物生长激素密切相关，论题不一致，排除。\n故正确答案为C。"},{"q":"大脑受到有毒化学物质伤害会产生功能受损，进而导致帕金森症。研究显示，体内细胞色素P450 水平低的人患帕金森症的可能性是体内P450 水平正常的人的三倍。因而可以认为，P450 可以保护大脑免受有毒化学物质的损伤，进而预防帕金森症。以下陈述如果为真，哪项最能质疑上述结论（  ）","options":["有毒化学物质损伤大脑功能的同时也抑制人体产生P450","帕金森症患者除P450 外的其他细胞色素水平也显著低于常人","人工合成P450 可以用于治疗帕金森症患者","某些非细胞色素物质可有效对抗有害化学物质来预防帕金森症"],"a":1,"e":"【答案】B\n【解析】削弱论证。论点：P450 可以保护大脑免受有毒化学物质的损伤，进而预防\n帕金森症。论据：体内细胞色素P450 水平低的人患帕金森症的可能性是体内P450 水平正\n常的人的三倍。\nA 项，讨论的是有毒物质会抑制P450 的产生，论点讨论P450 是否会预防帕金森，论\n题不一致，排除；\nB 项，指出论据中涉及的帕金森症患者与常人除了P450 水平不同，其他细胞色素水\n平也不相同，有可能是其他细胞色素是影响帕金森症的因素，所以P450 可能不能预防帕\n金森，可以削弱，当选；\nC 项，强调用P450 治疗帕金森，论点强调用P450 预防帕金森，论题不一致，排除；\nD 项，强调用某些非细胞色素物质预防帕金森，论题不一致，排除。\n故正确答案为B。"},{"q":"众所周知，每个人的指纹都是不同的，指纹才是每个人独一无二的身份证，因此指纹常常用在案件侦破中。然而科学家的最新研究发现，随着机体老化，指纹纹路排列会发生不可逆转的变化，因此科学家得出结论：指纹不应该再用于案件侦破中。以下哪项如果为真，最能质疑上述结论（  ）","options":["指纹是目前案件侦破的最关键证据，许多重案犯是依靠指纹才被抓捕归案的","除了指纹，每个人的DNA 也是独一无二的且不会随着时间变化而发生改变","除了纹路排列，指纹的其他几项指标也是指纹识别技术的重要依据","指纹纹路排列发生变化有规律可循，这一规律是普遍适用的"],"a":3,"e":"【答案】D\n【解析】削弱论证。论点：指纹不应该再用于案件侦破中。论据：指纹纹路排列会发\n生不可逆转的变化。\nA 项，讨论的是目前指纹用于破案，那之后到底是否应该用于案件中无从得知，论题\n不一致，排除；\nB 项，讨论的是DNA 也会变化，论题不一致，排除；\nC 项，强调除了纹路排列，指纹的其他几项指标也是指纹识别技术的重要依据，说明\n破案可以使用指纹的其他指标，可以削弱，保留；\nD 项，说明指纹纹路排列变化的规律普遍适用，因此不用担心纹路发生变化，指纹破\n案依旧适用，可以削弱，保留；\n比较C、D 项，C 项说明可以用指纹其他指标，D 项说明指纹纹路依然可以使用，直\n接否定论据，因此D 项更强。\n故正确答案为D。"},{"q":"骨质疏松是一种骨钙质减少，骨脆性增加，易发骨折的疾病。现有的治疗手段比如使用雌激素或者降钙素有助于阻止进一步的骨质减少但不能增加骨头质量。氟化物被认为能增加骨质，给骨质疏松症患者注入氟化物会帮助他们的骨骼不容易折断。以下哪项如果为真，能够削弱文中观点（  ）","options":["大多数患骨质疏松症的人没有意识到注入氟化物可以增加骨质","牙膏中常加入氟化物来起到坚固牙齿的作用","氟化物注入健康人的体内会导致较强的副作用","通过注入氟化物增加的骨质比正常的骨骼组织更加脆弱而缺少弹性"],"a":3,"e":"【答案】D\n【解析】削弱论证。论点：给骨质疏松症患者注入氟化物会帮助他们的骨骼不容易折\n断。\nA 项，说明大多数人没有注入氟化物的意识，论点讨论注入氟化物能否增加骨质，论\n题不一致，排除；\nB 项，说明氟化物可以坚固牙齿，能否增加人类骨骼的骨质没有提及，论题不一致，\n排除；\nC 项，强调氟化物对人体有副作用，能否增强骨质没有说明，论题不一致，排除；\nD 项，说明注入氟化物增加的骨质更加脆弱而缺少弹性，说明注入氟化物更容易骨\n折，可以削弱，当选。\n故正确答案为D。"},{"q":"澳大利亚研究人员称，桉树在吸收水分的同时，会将水中微量的金元素吸收进树体。通过分析桉树落叶中金的含量，可指示金矿的位置，不用钻探就能了解地表以下是否有矿藏。因此桉树探矿法对矿产勘探具有重要意义。以下哪项如果为真，最能削弱上述结论（  ）","options":["金矿一般都埋藏于砂石层之下，普通土壤层在砂石层上面，植物的根生长在土壤层","澳洲西南部的新南威尔士州富含金矿，当地的桉树叶中含金量与其它地区并无显著差异","桉树探矿法的实施周期较长，需要等待桉树成材之后才能有效","澳州西南部有大片的桉树林，澳洲最早发现的金矿也在那里"],"a":0,"e":"【答案】A\n【解析】削弱论证。论点：桉树探矿法对矿产勘探具有重要意义。论据：桉树在吸收\n水分的同时，会将水中微量的金元素吸收进树体，通过分析桉树落叶中金的含量，可指示\n金矿的位置。\nA 项，说明桉树的根和金矿在不同的位置，树根吸收水分不会吸收金元素，因此不能\n用桉树探矿，可以削弱，保留；\nB 项，举新南威尔士州的例子说明当地桉树叶含金量与其他地区没有差异，但是当地\n富含金矿，说明用桉树探矿不准确，可以削弱，保留；\nC 项，强调桉树探矿实施周期长，论点讨论桉树探矿法有没有作用，论题不一致，排\n除；\nD 项，说明澳洲西南部有桉树也有金矿，但是并没有说明桉树含金量的情况，论题不\n一致，排除；\n比较A、B 项，A 项解释说明为什么桉树探矿发不可取，B 项举反例说明桉树探矿法\n不可取，A 项解释说明的力度强于B 项举反例。\n故正确答案为A。\n第七组："},{"q":"人们已经知道：如果果蝇体内的w 基因发挥作用，雄性果蝇就不会向雌性果蝇求爱，转而追求同性。因此果蝇的同性恋行为被认为是由遗传因素决定的。最近，研究人员培养出w 基因发挥作用的雄性果蝇，然后利用这种果蝇进行了实验。他们发现，果蝇的同性恋行为不仅受遗传因素影响，社会因素也发挥了很大的促进作用。以下哪项如果为真，最能支持研究人员的发现（  ）","options":["如果这种雄性果蝇羽化为成虫后，只要进行一天以上的集体饲养，雄性果蝇就开始追逐其他雌性果蝇，显示出求爱行为；但如果这种果蝇羽化后是一只只隔离饲养的，则不会出现此种行为","如果这种雄性果蝇羽化后是一只只隔离饲养的，若干天后，果蝇就开始表现出对其他雄性果蝇的求爱行为；如果这种雄性果蝇羽化为成虫后是集体饲养的，则不会出现此种行为","如果这种雄性果蝇羽化为成虫后，只要进行一天以上的集体饲养，雄性果蝇就开始追逐其他雄性果蝇，显示出同性恋的求爱行为；但如果这种果蝇羽化后是一只只隔离饲养的，则不会出现此种行为","如果这种雄性果蝇羽化后是一只只隔离饲养的，若干天后，果蝇就开始表现出对其他雌性果蝇的求爱行为；如果这种雄性果蝇羽化为成虫后是集体饲养的，则不会出现此种行为"],"a":2,"e":"【答案】C\n【解析】加强论证。论点：果蝇的同性恋行为不仅受遗传因素影响，社会因素也发挥\n了很大的促进作用。\nA 项，讨论的是果蝇的异性恋，论点讨论果蝇的同性恋，论题不一致，排除；\nB 项，说明集体饲养的雄性果蝇没有出现同性恋行为，说明社会因素会抑制果蝇的同\n性恋行为，可以削弱，排除；\nC 项，说明集体饲养的雄性果蝇出现同性恋行为，而隔离饲养的没有出现，说明社会\n因素促进了果蝇的同性恋行为，可以加强，当选；\nD 项，讨论的是果蝇的异性恋，论题不一致，排除。\n故正确答案为C。"},{"q":"奇虾是一类已经灭绝的大型无脊椎海洋动物，是目前已知最庞大的寒武纪动物。化石表明这种动物口器有十几排牙齿，直径有25 厘米，粪便化石长10 厘米，粗5 厘米。由此推测，奇虾体长可能超过2 米。以下哪项如果为真，最能支持上述推测（  ）","options":["寒武纪时期，海洋虾类食物充足","25 厘米直径的巨口奇虾可掠食当时的任何大型生物","对于大型无脊椎动物而言，牙齿越多身体越长","寒武纪时期的海洋虾类，其牙齿和体长有比较固定的构成比例"],"a":2,"e":"【答案】C\n【解析】加强论证。论点：奇虾体长可能超过2 米。\nA 项，讨论的是海洋虾类食物充足，论点讨论奇虾的体长，论题不一致，排除；\nB 项，讨论的是巨口奇虾可以吃大型生物，论题不一致，排除；\nC 项，指出牙齿越多身体越长，题干说奇虾牙齿有十几排，所以可能体长超过2 米，\n可以加强，当选；\nD 项，指出牙齿和体长有一个固定比例，但是比例是正比还是反比不清楚，论据不可\n预见，排除。\n故正确答案为C。"},{"q":"某项研究中，研究者追踪了该国19 万名在1974 年至1994 年期间出生的人的医疗数据，他们在2006 年至2012 年期间做过智力测试。在做智力测试时，大约有35%的调查对象正因感染而住院。研究人员发现，那些因感染而住院者的智商分数平均比一般人低1.76分。而那些因感染住了5 次及以上医院的人，智商分数平均比一般人低9.44 分。研究人员指出，人体感染会造成个体智商下降。以下哪项如果为真，最能削弱以上结论（  ）","options":["大脑周围组织感染会影响大脑的智力水平","有证据表明，感染会影响痴呆病人的认知能力","智商是对心智能力的评价方式，存在着测量误差","患病使得患者情绪紧张，测试时注意力不集中"],"a":3,"e":"【答案】D\n【解析】削弱论证。论点：人体感染会造成个体智商下降。论据：因感染而住院者的\n智商分数平均比一般人低。\nA 项，指出大脑周围组织感染会影响大脑的智力，也就是说人体感染会造成智商下\n降，可以加强，排除；\nB 项，指出感染会影响痴呆病人认知能力，举例说明人体感染会造成智商下降，可以\n加强，排除；\nC 项，强调测量智商会存在误差，但无法确定误差对这次研究结果的影响，论据不可\n预见，排除；\nD 项，说明患病使得患者情绪紧张，测试时注意力不集中，因此测量智力时分数低是\n因为注意力不集中，可以削弱，当选。\n故正确答案为D。"},{"q":"研究人员用X 射线拍摄猕猴进食、打哈欠以及相互嘶吼时发出各种各样声音的影像。结果显示，猕猴很容易就能发出许多不同的声音，包括英语字母中最基本的5 个元音。研究人员据此推测，猕猴不能说出数千个单词和完整的句子，是因为它们的大脑和人类存在差异。以下哪项如果为真，最能支持上述研究人员的推测（  ）","options":["猕猴和类人猿的声带特征是它们无法重现人类语音的原因","非洲灰鹦鹉经过人类训练之后，可以说800 多个单词","人类丰富的语言表达能力主要源于大脑中特有的高度发达的语言功能区","利用电脑模拟猕猴讲完整的句子，每个词都比较清晰，并不难听懂"],"a":2,"e":"【答案】C\n【解析】加强论证。论点：猕猴不能说出数千个单词和完整的句子，是因为它们的大\n脑和人类存在差异。论据：猕猴很容易就能发出许多不同的声音，包括英语字母中最基本\n的5 个元音。\nA 项，说明猕猴不能说人类语音是由于声带特征，跟人类大脑的差异无关，可以削\n弱，排除；\nB 项，研究的是非洲灰鹦鹉，与论点研究的猕猴不同，论题不一致，排除；\nC 项，说明语言的表达能力是人类大脑特有的语言功能区，补充了论据说明猕猴无法\n说很多话的原因确实是和人脑存在差异，可以加强，当选；\nD 项，利用电脑模拟能听懂猕猴的声音，和猕猴不能说数千个单词和句子的原因无\n关，论题不一致，排除。\n故正确答案为C。"},{"q":"在国家发展新兴产业的大背景下，某公司虽然在某产业长期处于领先地位，但上半年的生产数据显示，领先优势越来越小，在邀请专家进行企业诊断后，专家认为该公司领先优势缩小的原因在于公司虽然管理制度健全，但由于企业文化缺乏进取心，导致在好的政策环境下公司发展趋缓。以下哪项如果为真，不能反驳专家的观点（  ）","options":["相较沿海地区同类公司受益于健全的产业链，公司处于内地，其发展有所受限","发展趋缓的原因在于长期以来公司下半年的生产数据一般高于上半年","公司一直注重加强企业文化建设，形成了和谐的企业氛围","企业文化并不是一个公司的核心竞争力，关键问题在于新产品研发力度不够"],"a":2,"e":"【答案】C\n【解析】削弱论证，选非题。论点：由于企业文化缺乏进取心，导致在好的政策环境\n下公司发展趋缓。\nA 项，说明公司的地理环境导致发展趋缓，另有他因削弱，排除；\nB 项，说明发展趋缓的原因在于下半年的生产数据一般高于上半年，另有他因削弱，\n排除；\nC 项，讨论的是公司有和谐氛围，论题不一致，当选；\nD 项，说明新产品研发力度不够导致发展趋缓，另有他因削弱，排除。\n故正确答案为C。"},{"q":"自闭症患者往往认知水平低下，一些自闭症患者会表现出述情障碍，即无法理解情感，缺乏对自身或他人情感的认知能力，由于缺乏情感认知能力，人们通常认为自闭症患者比较冷漠。以下哪项如果为真，最能支持上述结论（  ）","options":["在道德两难的困境中，自闭症患者会为了避免作出伤害性举动而承受强烈的情绪压力","述情障碍的发生率在自闭症患者中高达50%左右，远远高于普通人","自闭症患者也会对他人产生正常的共情反应，甚至会比普通人更加关注别人的情绪","述情障碍虽会伴随自闭症出现，但二者并无必然联系，因为很多普通人也会出现"],"a":1,"e":"【答案】B\n【解析】加强论证。论点：自闭症患者比较冷漠。论据：自闭症患者会表现出述情障\n碍，缺乏情感认知能力。\nA 项，指出自闭症患者会考虑他人的情感，说明自闭症患者不冷漠，可以削弱，排\n除；\nB 项，说明自闭症患者更容易发生述情障碍，因此自闭症患者比其他人冷漠，可以加\n强，当选；\nC 项，说明自闭症患者会产生共情反应，说明自闭症患者不冷漠，可以削弱，排除；\nD 项，指出述情障碍与自闭症无必然联系，因此不能得出自闭症患者冷漠，可以削\n弱，排除。\n故正确答案为B。"},{"q":"当人们在海洋游泳时，身体会释放一种看不见的电信号，科研人员根据这一种情况研制了海洋隐形衣，该隐形衣通过屏蔽掉身体释放的电信号，使得鲨鱼等海洋生物无法发现人们的踪迹。这样，人们就可以近距离接触并观察鲨鱼等海洋生物。以下哪项是科研人员假设的前提（  ）","options":["有些海洋生物利用超声波进行信息交流、觅食、发现并躲避天敌","部分鱼类其视网膜中含有很多视锥细胞，能够敏锐地感受水中细微的光线变化","鲨鱼等海洋生物是凭借人体释放的电信号来发现人们踪迹的","该隐形衣非常轻薄，对人们在水下的活动不会形成阻碍"],"a":2,"e":"【答案】C\n【解析】加强论证。论点：人们就可以近距离接触并观察鲨鱼等海洋生物。论据：科\n研人员制作了屏蔽掉人类身体释放的电信号的隐形衣，鲨鱼等海洋生物无法发现人类踪\n迹。\nA 项，讨论的有些海洋生物，是否包括鲨鱼等海洋生物不清楚，论题不一致，排除；\nB 项，说的是部分鱼类，是否包括鲨鱼等海洋生物不清楚，论题不一致，排除；\nC 项，说明屏蔽掉身体释放的电信号的隐形衣可以起作用，是论点成立的前提，可以\n加强，当选；\nD 项，说的是隐形衣的轻重问题，论题不一致，排除。\n故正确答案为C。"},{"q":"为什么一些灵长类动物的大脑尺寸比其它动物要大？原因通常被认为是社会行为，即灵长类动物生活于更大更复杂的社会群体中，为了更好地处理各种社会关系，它们需要更大的大脑。以下哪项如果为真，不能质疑上述观点（  ）","options":["通过灵长类动物的饮食特点而非社群复杂性，能够更容易预测大脑的大小","猩猩等一些灵长类动物通常是独居生活，但它们的大脑也很大","大脑皮层的大小与大脑尺寸没有直接关联，但对于灵长类动物的认知、空间推理能力等非常重要","灵长类动物中，食果类的大脑比食叶类大，这是因为果实在时间和空间上更分散，找到果实是一项更为复杂的任务"],"a":2,"e":"【答案】C\n【解析】削弱论证。选非题。论点：灵长类动物为了更好地处理各种社会关系，需要\n更大的大脑。\nA 项，说明饮食特点决定了大脑的大小而不是处理好各种社会关系，可以削弱，排\n除；\nB 项，说明独居的灵长类动物大脑也大，因此大脑大小和社会关系无关，可以削弱，\n排除；\nC 项，讨论的是灵长类动物的认知推理能力，论题不一致，当选；\nD 项，说明灵长类动物中食果类比食叶类的大脑更大，说明食物类型决定了大脑的大\n小，而不是处理好各种社会关系，可以削弱，排除。\n故正确答案为C。"},{"q":"目前，人们通过在河流上筑坝建造水电站获得电能，但是地球上适合筑坝的地方为数不多，筑坝也会破坏生态环境。相比之下，海洋覆盖70%的地球表面。海面上波涛滚滚，昼夜不息，蕴藏着巨大的能量，收集波浪能适合的海域广，生态环境破坏小。因此，收集波浪能用于发电将比在河流上筑坝发电更有优势。以下哪项如果为真，不能质疑上述结论（  ）","options":["据估计，全世界可开发利用的波浪能达2.5TW，目前一些小功率的波浪能设备已经推广应用于导航浮标、灯塔等","河流的流向较为稳定，而波浪是海水的缓慢运动，方向并不固定，在此条件下设立的发电机效率非常低","不管是在海床上建塔来支撑发电，还是把发电机固定在海床上都要耗费巨资，成本比河流电站要昂贵得多","河水的水能易于收集，而深海地区及开阔洋面中的波浪能难以提取，可供利用的波浪能仅局限于靠近海岸的地方"],"a":0,"e":"【答案】A\n【解析】削弱论证，选非题。论点：收集波浪能用于发电将比在河流上筑坝发电更有\n优势。\nA 项，说明现在已经出了波浪能设备，说明利用波浪发电是可行的，而且全世界可开\n发利用的波浪能达2.5TW，说明收集波浪发电有优势，可以加强，当选；\nB 项，指出了收集波浪发电的弊端，效率低，因此收集波浪发电不可取，可以削弱，\n排除；\nC 项，说明收集波浪发电的成本巨大，比河流发电贵得多，因此不可取，可以削弱，\n排除；\nD 项，说明波浪不易收集，因此收集波浪发电不可取，可以削弱，排除。\n故正确答案为A。"},{"q":"近年来科技的迅猛发展为科幻小说创作提供了启发，也为科幻小说创作提供了丰富的素材。科幻小说的主题即是围绕着科技幻想、揭示科技发展带来的社会问题及其给人类带来的启示而展开的。因此科幻小说的蓬勃发展是科技发展的结果。以下哪项如果为真，最能削弱上述结论（  ）","options":["伴随着西方工业革命产生的科幻小说经历了初创、成熟和鼎盛三个历史时期","科技发展拓展了科幻小说的想象空间，科幻小说为科技发展提供了人文视角","科技只是科幻小说中的背景元素，科幻小说本质上还是要讲述一个完整的故事","科幻小说展现了人类的愿望，最终推动科技发展将那些梦想变为现实"],"a":3,"e":"【答案】D\n【解析】削弱论证。论点：科幻小说的蓬勃发展是科技发展的结果。\nA 项，讨论的是科幻小说的发展阶段，论点讨论的是科幻小说蓬勃发展的原因，论题\n不一致，排除；\nB 项，讨论的是科幻小说带来的好处，论题不一致，排除；\nC 项，讨论的是科幻小说的本质，论题不一致，排除；\nD 项，说明科幻小说的发展导致科技发展，并非科技发展导致科幻小说的发展，因果\n倒置削弱，当选。\n故正确答案为D。\n第八组："},{"q":"美国鸟类学基金会在不久前公布了《美国鸟类状况》的报告。他们认为，全球变暖正促使鸟类调整生物钟，提前产蛋期，而上述变化会使这些鸟无法为其刚破壳而出的后代提供足够的食物，比如蓝冠山雀主要以蛾和蝴蝶的幼虫为食，而蛾和蝴蝶的产卵时间没有相应提前，“早产”的小蓝冠山雀会在破壳后数天内持续挨饿。下列哪项如果为真，最能支持上述论证（  ）","options":["最近40 年的英国的平均气温不断上升","很多鸟类的产蛋期确实提前了","除了蛾和蝴蝶的幼虫外，蓝冠山雀很少吃其他食物","蛾和蝴蝶的产卵期不同"],"a":2,"e":"【答案】C\n【解析】加强论证。论点：全球变暖使鸟类提前产蛋，导致后代挨饿。论据：小蓝冠\n山雀。\nA 项，“英国的平均气温上升”，并没有说明对鸟类产蛋期的影响，无法论证幼鸟是\n否会挨饿，论题不一致，排除；\nB 项，“很多鸟类的产蛋期确实提前”，并不能说明是否因为鸟类产蛋期提前，也无\n法说明幼鸟是否会挨饿，论题不一致，排除；\nC 项，“除了蛾和蝴蝶的幼虫外，蓝冠山雀很少吃其他食物”，说明小蓝冠山雀确实\n在破壳后数天内吃不到足够的食物，会持续挨饿，属于解释，可以加强，当选；\nD 项，“蛾和蝴蝶的产卵期不同”，与论点“全球变暖使鸟类提前产蛋，导致后代挨\n饿”，没有关系，论题不一致，排除。\n故正确答案为C。"},{"q":"一种针对某种疾病的新疗法在12 个月的临床试验中使68%的患者病情有了明显改善，其中43%的患者痊愈。然而，通常采用的治疗方法也可在12 个月内将38%的患者完全治愈。由于新疗法主要选择了那些症状比较严重的患者，因此有人认为这种新疗法在疗效方面比常用的疗法更显著。以下各项如果为真，能够对上述观点提出最有力质疑的是（  ）","options":["新疗法出现后，这种疾病的患者仍然倾向于使用原有疗法","这种疾病发病初期往往很严重，但相对容易治疗","通过改变生活方式，很多人即使不用药也可使病情改善，甚至痊愈","常用疗法使用四种药物搭配治疗，但新疗法只使用两种药物"],"a":1,"e":"【答案】B\n【解析】削弱论证。题干论点：新疗法比常用疗法疗效更显著。论据：新疗法使43%\n的患者痊愈，常用疗法将38%的患者完全治愈，但新疗法主要选择较严重的患者。\nA 项，“倾向于”只是患者的主观意愿，没有提及在实际疗效，论题不一致，排除；\nB 项，“这种疾病发病初期往往很严重，但相对容易治疗”，而新疗法选择的主要选\n择较严重的患者，所以治愈更高，所以新疗法是否比常用疗法疗效更显著，是不确定的，\n可以削弱，当选；\nC 项，“很多人不用药也可使病情改善”，并没有涉及新、旧疗法哪一个疗效更显\n著，论题不一致，排除；\nD 项，讨论的是药物搭配的问题，没有提到药效的问题，论题不一致，排除。\n故正确答案为B。"},{"q":"合成氨基酸特征与20 种标准氨基酸不同，将这些合成氨基酸整合进入蛋白质中，可以系统地改变蛋白质的结构和生物学特征。然而，到目前为止研究人员只能做到一次将一个合成氨基酸整合进一个蛋白质中，因此一次只能改变蛋白质的一种特征。下列哪项是以上论述所需要的前提（  ）","options":["改变蛋白质的结构，就可以改变蛋白质的生物学特征","研究人员一次只能改变一个蛋白质的结构","一个合成氨基酸只能改变蛋白质的一种结构","一个合成氨基酸只能改变蛋白质的一种特性"],"a":3,"e":"【答案】D\n【解析】加强论点。论点：一次只能改变蛋白质的一种特征。论据：到目前为止研究\n人员只能做到一次将一个合成氨基酸整合进一个蛋白质中。\nA 项，“生物学特征”是题干第一句背景出现的内容，并不是论点讨论的内容，论题\n不一致，排除；\nB 项，讨论的是“结构”，论点讨论的是“特征”，二者不是一回事，论题不一致，\n排除；\nC 项，与B 项犯的错误一样，讨论的“结构”，与论点“特征”不是一回事，论题不\n一致，排除；\nD 项，“氨基酸”是论据的内容，“蛋白质的特征”是论点中的内容，D 项同时出现\n论点和论据的关键词，在论据和论点间建立联系，为搭桥项，可以加强，当选。\n故正确答案为D。"},{"q":"某国一足球杂志报道说，30 年来该国足球甲级联赛的冠军都是通过假球决出来的。该杂志还给出证据说，有一位不愿透露姓名的参赛队员告诉记者，他和他的队友曾收取了20 万美元的贿赂，于是他们在一场关键性的比赛中踢假球，最终让另一支球队获胜。但是，该国足球联赛主席则对这则报道进行了反驳。以下各项如果为真，最能对该主席予以支持的是（  ）","options":["该足球杂志曾数次刊发不实报道","该国足联赛对踢假球行为处罚极重，所以一般不会出现踢假球事件","即使那场比赛中踢假球事件是真的，也不能断定甲级联赛的冠军是通过假球决出来的，否则联赛也不会举办30 年","通过近期一次全国性的调查，并没有发现足够影响冠军归属的假球案件"],"a":2,"e":"【答案】C\n【解析】加强论证。设问中选最能支持主席，而题干中主席对报道进行了反驳，也就\n将提问方式转化为：最能反驳报道。报道认为：30 年来该国足球甲级联赛的冠军都是通\n过假球决出来的。论据：曾有参赛队员收取贿赂而在一场关键性的比赛中踢假球。\nA 项，“该足球杂志曾数次刊发不实报道”，但这一次是不是发表的不实报道，论据\n不可预见，排除；\nB 项，“一般不会出现踢假球事件”，但这次报道出来的是不是真的踢了假球，论据\n不可预见，排除；\nC 项，“踢假球事件”是论据中内容，“断定甲级联赛的冠军”属于论点中的内容，\nC 项是在论点和论据中断开联系，为拆桥项。告诉我们即使论据成立，也不能推出论点，\n可以削弱报道，当选；\nD 项，“没有发现”并不代表实际不存在，论据不可预见，排除。\n故正确答案为C。"},{"q":"“闪婚”是指男女双方恋爱不到半年就结婚。某研究所对某市法院审理的所有离婚案件了调查。结果显示，闪婚夫妻三年内起诉离婚的比例远远高于非闪婚夫妻。由此，该研究机构认为闪婚是目前夫妻离婚的一个重要原因。下列哪项如果为真，最能削弱以上论证（  ）","options":["调查发现，离婚最快的夫妻往往不是闪婚夫妻","到该市民政部门办理的协议离婚案件占该市离婚案件总量的70%","调查显示，闪婚夫妻婚后感情更加融洽","调查显示，恋爱时间过长的夫妻离婚率高于闪婚夫妻"],"a":1,"e":"【答案】B\n【解析】削弱论证。论点：闪婚是夫妻离婚的一个重要原因。论据：闪婚夫妻三年内\n起诉离婚的比例远远高于非闪婚夫妻\nA 项，“离婚最快”并不在论点讨论的范围内，论点讨论的是离婚的原因，论题不一\n致，排除；\nB 项，“协议离婚案件占该市离婚案件总量的70%”，说明起诉离婚只占30％，也就\n是论据中的研究只调查了30％而得出了结论，属于样本不典型，有削弱作用，当选；\nC 项，“婚后感情如何”与论点“闪婚是不是离婚的一个重要原因”无关系，论题不\n一致，排除；\nD 项，比较的是“恋爱时间过长”与“闪婚”，哪一个导致夫妻离婚率更高，与论点\n“闪婚是不是夫妻离婚的一个重要原因”没有关系，论题不一致，排除。\n故正确答案为B。"},{"q":"在选购地板时，消费都很关心地板散发的气味，因为地板的刺激性气味强，往往是有毒有害物质超标的一种表现，最近有一种据称是香味环保地板赢得了不少消费者的青睐。销售人员声称地板散发的香味可以消毒杀菌，去除空气中的异味。当销售人员在推销这种产品时，往往会拿来几种不同的地板，让有购买意向的消费者闻一闻，并指出散发着清香气味的地板，即是香味环保地板。以下哪项如果为真，最能削弱销售人员的观点（  ）","options":["气味并不是判别地板是否环保的唯一标准，除气味外，消费者更关心地板中有机挥发物的含量","事实上，由于木材本身的气味以及受制造工艺所限，地板或多或少都带有一定的刺激性气味","到目前为止，国家有关部门还没有出台香味环保地板的专门标准，所谓的“香味”不过是厂家炒作的概念","检验证明，不少厂商是通过在地板中添加大量香精等化学助剂来达到掩盖或者中和刺激性气味的目的"],"a":3,"e":"【答案】D\n【解析】削弱论证。论点：销售人员声称地板散发的香味可以消毒杀菌，去除空气中\n的异味。\nA 项，讨论的是判别地板是否有害的标准，而论点说的是地板散发的香味可以消毒杀\n菌，论题不一致，排除；\nB 项，承认地板都有点气味，但是环保地板散发的香味可以消毒杀菌未知，论据不可\n预见，排除；\nC 项，“香味”不过是厂家炒作的概念，但是香味地板是否能消毒未知，论据不可预\n见，排除；\nD 项，通过在地板中添加大量香精等化学助剂来达到掩盖或者中和刺激性气味，说明\n环保香味地板不能去除异味，可以削弱，当选。\n故正确答案为D。"},{"q":"生理学家发现，人类掌管记忆和思维等高级认知功能的大脑皮质在正常情况下有6层，如果胎儿缺乏一种名为“Cdk5”的酶，大脑皮质的发育就会变得极为缓慢，无法最终形成正常大脑皮质的层结构，从而严重影响儿童认知发展，一些医药界人士推测，利用这一发现，将有望研发出药物，普遍提高学生的学习能力。如果以下为真，哪项不能质疑上述推测（  ）","options":["人体不能吸收外部补充的“Cdk5”酶","学生的学习能力主要是通过后天学习获得的","青少年过了脑发育关键期后，补充“Cdk5”酶不起作用","一些“Cdk5”酶含量高的人学习能力并不突出"],"a":3,"e":"【答案】D\n【解析】削弱论证。选非题，论点：利用这一发现，将有望研发出药物，普遍提高学\n生的学习能力。论据：如果胎儿缺乏一种名为“Cdk5”的酶，大脑皮质的发育就会变得极\n为缓慢，无法最终形成正常大脑皮质的层结构，从而严重影响儿童认知发展。\nA 项，人体不能吸收外部补充的“Cdk5”酶，所以外部补充对提高学生的学习能力无\n作用，可以削弱，排除；\nB 项，学生的学习能力主要是通过后天学习获得的，所以先天补充没有作用，可以削\n弱，排除；\nC 项，青少年过了脑发育关键期后，补充“Cdk5”酶不起作用，所以研制出药物，也\n无法提高学生的学习能力，可以削弱，排除；\nD 项，一些“Cdk5”酶含量高的人学习能力并不突出，并不代表缺“Cdk5”酶的人补\n充之后学习能力不会提高，不可预见，不能削弱，当选。\n故正确答案为D。"},{"q":"虎山长城遗址除一号台址发现很少的残砖之外，其他地方均没有发现城砖。虎山村及附近村庄也没有从长城上拆下城砖用于民房建筑的情况。由此可以推测，虎山长城用砖是极少的。上述推测还需要隐含哪一项假设（  ）","options":["虎山长城遗址附近没有发现古砖窑","当地县志记载虎山长城是夯土筑成","此地山高坡陡，城砖难以运进运出","此地土质极差，不适宜烧制长城用砖"],"a":2,"e":"【答案】C\n【解析】加强论证。论点：虎山长城用砖是极少的。论据：虎山长城遗址除一号台址\n发现很少的残砖之外，其他地方均没有发现城砖。虎山村及附近村庄也没有从长城上拆下\n城砖用于民房建筑的情况。\nA 项，虎山长城遗址附近没有发现古砖窑，不能说明虎山长城用砖是极少的，论题不\n一致，排除；\nB 项，当地县志记载虎山长城是夯土筑成，记载是真假无法确定，也无法说明虎山长\n城用砖是极少的，论题不一致，排除；\nC 项，此地山高坡陡，城砖难以运进运出，否定代入，如果城砖可以运进运出，那么\n有可能虎山村的砖被运出，论点不成立，所以此项为前提，当选；\nD 项，此地土质极差，不适宜烧制长城用砖，但是不能代表长城用砖是极少的，论题\n不一致，排除。\n故正确答案为C。"},{"q":"伏案工作者长时间低头阅读，书写很容易患腰颈椎疾病，为帮助这部分人预防和缓解腰颈椎疾病，某单位工会为职工印发了宣传册，教大家一些预防和治疗腰颈椎疾病的一些方法。以下哪项如果为真，最能对上述宣传效果提出质疑（  ）","options":["预防和缓解腰颈椎疾病的方法因人而异","腰颈椎疾病很难进行自我预防和治疗","预防和治疗腰颈椎疾病需要专业人士指导","不经常伏案工作的人也可能患腰颈椎疾病"],"a":1,"e":"【答案】B\n【解析】削弱论证。论点：伏案工作者长时间低头阅读，书写很容易患腰颈椎疾病，\n为帮助这部分人预防和缓解腰颈椎疾病，某单位工会为职工印发了宣传册，教大家一些预\n防和治疗腰颈椎疾病的一些方法。\nA 项，预防和缓解腰颈椎疾病的方法因人而异，不能削弱印发了宣传册能预防，不能\n削弱，排除；\nB 项，腰颈椎疾病很难进行自我预防和治疗，所以印发宣传册预防没有作用，可以削\n弱，当选；\nC 项，预防和治疗腰颈椎疾病需要专业人士指导，但是不能削弱印发了宣传册不能预\n防，也许宣传册就是专业人士写的，不能削弱，排除；\nD 项，讨论的是患腰颈椎疾病可能性，而论点讨论的是如何预防和缓解，论题不一\n致，排除。\n故正确答案为B。"}]},{"id":"fanyi","name":"翻译推理","items":[{"q":"克山病是一种原因未明的地方性心肌病，山东省两次克山病流行均发生在病区居民生活困难时期，此时居民饮食结构单一，营养缺乏。1978 年以后，由于农村经济体制的改革，病区居民生活逐渐好转，营养结构趋向合理，克山病新发病人越来越少，达到基本控制标准。一些研究者据此推测，营养缺乏可能是克山病发病的重要因素。如果以下各项为真，哪项不能质疑上述推论（  ）","options":["原来克山病病区的土壤、水质在几十年中发生了较大变化","1978 前农村生活水平普遍较低，但克山病仅在个别地方出现","一些生活水平高的地区，也出现过克山病病例","通过调整饮食结构，无法治愈克山病"],"a":3,"e":"【答案】D\n【解析】削弱论证。选非题，论点：营养缺乏可能是克山病发病的重要因素。论据：\n山东省两次克山病流行均发生在病区居民生活困难时期，此时居民饮食结构单一，营养缺\n乏。1978 年以后，由于农村经济体制的改革，病区居民生活逐渐好转，营养结构趋向合\n理，克山病新发病人越来越少，达到基本控制标准。\nA 项，论点说营养缺乏可能是克山病发病的重要因素，选项说土壤、水质在几十年中\n发生了较大变化，有可能导致克山病，另有他因，可以削弱，排除；\nB 项，1978 前农村生活水平普遍较低，但克山病仅在个别地方出现，说明并非是生活\n水平低，营养缺乏导致的克山病，另有他因，可以削弱，排除；\nC 项，一些生活水平高的地区，也出现过克山病病例，说明并非是生活水平低，营养\n缺乏导致的克山病，另有他因，可以削弱，排除；\nD 项，通过调整饮食结构，无法治愈克山病，而论点讨论的是克山病发病的原因，论\n题不一致，无法削弱，当选。\n故正确答案为D。\n第二节翻译推理\n第一组："},{"q":"某公司所有的销售人员都是男性，所有的文秘都是女性，所有的已婚者都是文秘，公司的总经理尚未结婚。据此，我们可以知道（  ）","options":["总经理是男性","已婚者中有男性","女员工中可能有未婚者","销售人员中有的已经结婚"],"a":2,"e":"【答案】C\n【解析】翻译推理。题干翻译为：所有销售人员→男性，所有已婚→所有文秘→女\n性，总经理→未婚。\nA 项，总经理是对第三个逻辑表达式的肯前，肯前必肯后，能得到总经理是未婚。未\n婚是第二个逻辑表达式的否前，否前无必然结论，故无法推出总经理是男性，排除；\nB 项，男性是对第二个逻辑表达式的否后，否后必否前，可以得到男性不是文秘，没\n有结婚。即男性都没结婚，所以该选项错误，排除；\nC 项，女员工是对第二个逻辑表达式的肯后，肯后无必然结论，但是有可能性的结\n论，即可能结婚也可能没结婚，该选项说可能有未婚者，当选；\nD 项，销售人员是对第一个逻辑表达式的肯前，能得到销售人员都是男性，男性是对\n第二个逻辑表达式的否后，否后必否前，可以得到男性不是文秘，没有结婚。即销售人员\n都没结婚，所以该选项错误，排除。\n故正确答案为C。"},{"q":"在城镇化过程当中，当城镇化率超过50%以后，城镇化减速的现象将逐渐出现。阻止城镇化减速的一个必备的战略思路是加快农民工市民化进程，加快这一进程的一个必要举措是建设农民工信息系统和信用体系。由此可以推出（  ）","options":["如果没能阻止城镇化减速，也就没有加快农民工市民化","如果加快农民工市民化进程，就可以阻止城镇化减速","如果不建设农民工信息系统和信用体系，就不能阻止城镇化减速","如果建设农民工信息系统和信用体系，就可以推进农民工市民化进程"],"a":2,"e":"【答案】C\n【解析】翻译推理。题干翻译为：①阻止城镇化减速→加快农民工市民化进程；②加\n快农民工市民化进程→建设农民工信息系统和信用体系。连推为：③阻止城镇化减速→加\n快农民工市民化进程→建设农民工信息系统和信用体系。\nA 项，不能阻止城镇化减速是否定①中的前件，否前无必然结论，排除；\nB 项，加快农民工市民化进程是肯定①中的后件，肯后无必然结论，排除；\nC 项，不建设农民工信息系统和信用体系是③的否后，否后必否前，可以推出不能阻\n止城镇化减速，可以推出，当选；\nD 项，建设农民工信息系统和信用体系肯定②中的后件，肯后无必然结论，排除。\n故正确答案为C。"},{"q":"无论是从全球范围，还是从我国的实际情况来看，人类文明都发展到了这样一个阶段，即保护生态环境，确保人与自然的和谐，是经济能够得到可持续发展的必要前提，也是人类文明得以延续的保证。由此可以推出（  ）","options":["如果经济不可持续发展，就是没有搞好环境保护","只有搞好环境保护，才能实现经济的可持续发展","即使没有搞好环境保护，也能实现经济的可持续发展","只有实现了经济的可持续发展，环境保护才能搞得好"],"a":1,"e":"【答案】B\n【解析】翻译推理。题干翻译为：经济得到可持续发展→保护环境。\nA 项，经济不持续否定了翻译的前件无法得到必然性结论，排除；\nB 项，经济可持续保护生态环境肯定了翻译前件，肯前必肯后，可以推出搞好环境保\n护，当选；\nC 项，没有保护环境否定了翻译的后件，否后必否前，应该推出的是无法实现经济可\n持续发展，排除；\nD 项，保护生态环境肯定了翻译的后件，肯后无必然结论，无法推出，排除。\n故正确答案为B。"},{"q":"某水果店只有进货价低于正常价格时，才能以低于市场的价格卖水果而获利。除非该水果店的销售量很大，否则，不能从果农那里购得低于正常价格的水果。要想有大的销售量，该水果店就要拥有特定品种水果的独家销售权。因为种种原因，该水果店没有得到特定品种水果的独家销售权。由此可以推出（  ）","options":["该水果店的销售量很大","该水果店的进货价低于正常价格","该水果店不能以低于市场的价格卖水果而获利","该水果店获利很少"],"a":2,"e":"【答案】C\n【解析】翻译推理。题干翻译为：①低于市场的价格卖水果而获利→进货价低于正常\n价格→销售量很大→拥有特定品种水果的独家销售权。已知该水果店没有得到特定品种水\n果的独家销售权，对于表达式是否后，否后必否前，推出销量不大、进货价没有低于正常\n价格、不能以低于市场的价格卖水果而获利，因此AB 项推不出，排除，C 项可推出，当\n选，D 项，水果店获利多少题干未提及，排除。\n故正确答案为C。"},{"q":"已知下列三个判断为真：（1）要么甲出差，要么乙出差，要么丙出差；（2）如果甲出差，那么丙就出差；（3）丙因工作忙走不开。由此推出的是（  ）","options":["甲出差而乙不出差","乙出差而甲不出差","甲出差乙也出差","甲不出差乙也不出差"],"a":1,"e":"【答案】B\n【解析】翻译推理。题干翻译为：①甲乙丙之一；②甲→丙；③-丙；\n已知“三个判断为真”，将③代入②中，根据“否后必否前”可知-甲，结合①得出\n乙出差，甲、丙不出差，B 项当选。\n故正确答案为B。"},{"q":"对于权力，有人这样主张：有实权干大事，有虚权干实事，没权了干好事。以下哪项最不可能从上述主张中推出（  ）","options":["没有权，不干好事","没有虚权，不干实事","有权了，干好事","没有实权，不干大事"],"a":0,"e":"【答案】A\n【解析】翻译推理，选非题。题干翻译为：①实权→干大事；②虚权→干实事；③没\n权→干好事\nA 项，没有权对于表达式③为肯前，肯前必肯后，一定干好事，选项说不干好事，错\n误，当选；\nB 项，没有虚权对于表达式②为否前，否前无必然，可能会不干实事，有可能推出，\n排除；\nC 项，有权对于表达式③为否前，否前无必然，可能会干好事，有可能推出，排除；\nD 项，没有实权对于表达式①为否前，否前无必然，可能会干大事，有可能推出，排\n除。\n故正确答案为A。"},{"q":"所有来自中国的留学生，都住在校园内；所有住在校园内的学生，都必须参加运动会；有些中国留学生加入了学生会；有些心理专业的学生也加入了学生会；所有心理学专业的学生都没有参加运动会。由此不能推出以下哪项结论（  ）","options":["所有中国留学生都参加了运动会","没有一个心理学专业的学生住在校园内","有些中国留学生是学心理学专业的","有些学生会成员没有参加运动会"],"a":2,"e":"【答案】C\n【解析】翻译推理，选非题。题干翻译为：①中国留学生→住校→参加运动会；②有\n些中国留学生加入学生会；③有些心理专业学生加入学生会；④心理专业学生→—参加运\n动会\nA 项，所有中国留学生对于表达式①为肯前，肯前必肯后，一定参加运动会，选项正\n确，排除；\nB 项，心理学专业的学生对于表达式④为肯前，肯前必肯后，一定没参加运动会，没\n参加运动会对于表达式①为否后，否后必否前，一定不住校内，因此没有一个心理专业留\n学生住校，正确，排除；\nC 项，有些中国留学生对于表达式①为肯前，肯前必肯后，一定参加运动会，参加运\n动会对于表达式④为否后，否后必否前，一定不是心理学生，选项说有些中国留学生是心\n理学专业，错误，当选；\nD 项，对于③根据换位可得：有些学生会成员是心理学专业，根据④肯前必肯后可\n得，心理学专业都没有参加运动会，因此有些学生会成员没有参加运动会，正确，排除。\n故正确答案为C。"},{"q":"某研究所人员结构状况如下：所有女性都拥有博士学位，有的男博士有高级职称，但所里也存在既没有博士学位也没有高级职称的人员。由此可以推出（  ）","options":["有的男性没有高级职称","有的女性有高级职称","所有男性都拥有高级职称","有的女性没有高级职称"],"a":0,"e":"【答案】A\n【解析】翻译推理。题干翻译为：①女性→博士；②有的男博士有高级职称；③有的\n人不是博士且没有高级职称\nA 项，根据表达式①否后必否前可知，不是博士的均不是女性，也就是男性，结合③\n可知有的人不是博士也没有高级职称，因此有的男性没有高级职称，可以推出，当选；\nB 项，根据表达式①可知女性均为博士，但是博士和高级职称没有必然联系，排除；\nC 项，题干无法推出“所有男性”的结论，排除；\nD 项，根据表达式①可知女性均为博士，但是博士和高级职称没有必然联系，排除。\n故正确答案为A。"},{"q":"在摩天大楼里工作的人大多数都是白领阶层，英语水平四级以上是成为外企白领的必要条件，外企中只有白领阶层的办公地点设在摩天大楼里。根据以上描述，以下哪项是不正确的（  ）","options":["在摩天大楼里的白领不一定是在外企工作","外企中英语水平四级以上的未必是白领","英语水平四级以上的白领可能不在摩天大楼里工作","外企中英语水平四级以下者可能在摩天大楼里工作"],"a":3,"e":"【答案】D\n【解析】翻译推理，选非题。题干翻译为：①外企白领→英语四级；②外企且摩天大\n楼工作→白领\nA 项，由题干可知摩天大楼里工作的人大多数都是白领阶层，但没有说白领都是外企\n的，所以在摩天大楼里的白领可能在外企工作，也可能不在外企工作，可以推出，排除；\nB 项，英语水平四级以上对于表达式①为肯后，肯后无必然，可能是外企白领，也可\n能不是白领，可以推出，排除；\nC 项，英语水平四级以上对于表达式①为肯后，肯后无必然，可能是外企白领，也可\n能不是外企白领，所以也有可能在摩天大楼工作，也可能不在摩天大楼工作，可以推出，\n排除；\nD 项，英语水平四级以下者对于表达式①为否后，否后必否前，一定不是外企白领，\n不是白领对于表达式②为否后，否后必否前，得到—外企或—摩天大楼工作，但是选项已\n说明在外企工作，所以一定不在摩天大楼工作，选项说可能在摩天大楼工作，错误，当\n选。\n故正确答案为D。"},{"q":"学校工会举办“教工好声音”歌唱比赛，赛后参赛者们预测比赛结果。张老师说：“如果我能获奖，那么李老师也能获奖。”李老师说：“如果我能获奖，那么刘老师也能获奖。”刘老师说：“如果田老师没获奖，那么我也不能获奖。”比赛结果公布后发现，上述3 位老师说的都对，并且上述四位老师中有三位获奖。由此可以推出没有获奖的是（  ）","options":["张老师","李老师","刘老师","田老师"],"a":0,"e":"【答案】A\n【解析】翻译推理。题干翻译为：①张→李；②李→刘；③—田→—刘；表达式③根\n据否后必否前可得：④刘→田；如果张老师获奖，那么根据肯前必肯后可知李、刘、田三\n位老师也会获奖，而题干说只有三位获奖，因此，张老师不能获奖。\n故正确答案为A。\n第二组："},{"q":"只有确立竞争政策的基础性地位，才能推动供给侧结构性改革。在这种新形势下，必须加强顶层设计，才能确立竞争政策的基础性地位，加强顶层设计必须围绕创造公平竞争的制度环境展开，确立竞争政策的基础性地位也是实现创新驱动的必然要求。由此可以推出（  ）","options":["不加强顶层设计就不能推动供给侧结构性改革","推动供给侧结构性改革才能实现创新驱动","围绕创造公平竞争的制度环境展开是加强顶层设计的充分条件","只有推动供给侧结构性改革才能加强顶层设计"],"a":0,"e":"【答案】A\n【解析】翻译推理。翻译题干：\n①推动供给侧结构性改革→确立竞争政策的基础性地位→加强顶层设计→围绕创造公\n平竞争的制度环境展开；②实现创新驱动→确立竞争政策的基础性地位。\nA 项，不加强顶层设计对于表达式“推动供给侧结构性改革→确立竞争政策的基础性\n地位→加强顶层设计”为否后，否后必否前，一定不能推动供给侧结构性改革，选项正\n确，当选；\nB 项，实现创新驱动对于表达式②为肯前，肯前必肯后，一定确立竞争政策的基础性\n地位，确立地位对于表达式“推动供给侧结构性改革→确立竞争政策的基础性地位”为肯\n后，肯后无必然结论，选项为必然性结论，排除；\nC 项，由表达式①可知围绕创造公平竞争的制度环境展开是加强顶层设计的必要条\n件，排除；\nD 项，说加强顶层设计对于表达式“推动供给侧结构性改革→确立竞争政策的基础性\n地位→加强顶层设计”为肯后，肯后无必然结论，选项为必然性结论，排除。\n故正确答案为A。"},{"q":"某城市选拔志愿者，已知情况如下：（1）只有小红报名，小白、小黑和小花才会都跟着报名；（2）如果小白不报名，则小黑也不报名；（3）如果小黑不报名，则小灰也不报名；（4）小红没报名；（5）小灰报名了。由此可以推出（  ）","options":["小白、小黑和小花都报名了","小白和小黑都报名了","小黑和小花都报名了","小白和小花都报名了"],"a":1,"e":"【答案】B\n【解析】翻译推理。翻译题干：①小白且小黑且小花→小红；②小黑→小白；③-小\n黑→-小灰；④-小红；⑤小灰。把⑤代入③，可推出小黑报名了；将小黑报名，带入②中\n可推出小白也报名了；把④带入①中，可推出-小白或-小黑或-小花；已推出小黑和小白都\n报名了，或关系为真否一推一，推出小花没报名。\n故正确答案为B。"},{"q":"某校规定，对于学校的任一实验室，除非有教师在国际期刊上发表论文，否则没资格申报国家重点实验室。该校甲实验室有教师在国际期刊上发表论文。该校乙实验室有资格申报国家重点实验室。若上述陈述为真，则以下哪项也一定为真（  ）","options":["该校甲实验室有资格申报国家重点实验室","该校甲实验室有教师没有在国际期刊上发表过论文","该校乙实验室有教师在国际期刊上发表论文","该校乙实验室有教师没有在国际期刊上发表过论文"],"a":2,"e":"【答案】C\n【解析】翻译推理。翻译题干：①没有教师发表论文→没资格申报实验室；②甲实验\n室有教师发表论文；③乙实验室有资格申报国家重点实验室。\nA 项，甲实验室有教师发表论文是对逻辑表达式①否前，否前无必然结论，无法推出\n甲实验室是否有资格申报国家重点实验室，排除；\nB 项，②说的是甲实验室有教师发表论文，但无法推出有老师没发表过论文，排除；\nC 项，乙实验室有资格申报国家重点实验室是对①的否后，否后必否前，可以推出乙\n实验室有教师发表论文，当选；\nD 项，②乙实验室有资格申报国家重点实验室是对①的否后，否后必否前，得到的是\n乙实验室有教师发表论文，无法推出有教师没有发表过论文，排除。\n故正确答案为C。"},{"q":"在由发展中国家向经济发达国家前进的过程中，大量资本支持是必不可少的条件，而高储蓄率是获得大量资本的必要条件。就目前来说，中国正处于经济起飞时期，因此储蓄率高是当前经济发展中一种正常而合理的现象。由此可以推出（  ）","options":["有了大量的资本支持，就可以实现由发展中国向发达国家的跨越","有了高储蓄率，就可以获得大量的资本支持","如果没有获得大量的资本支持，说明储蓄率不高","如果没有高储蓄率，就不能实现向发达国家的转变"],"a":3,"e":"【答案】D\n【解析】翻译推理。翻译题干：由发展中国家向经济发达国家前进的过程中→大量资\n本→高储蓄率。\nA 项，“有了大量的资本支持”属于肯后，根据推理规则肯后无必然，因此推不出必\n然结论，排除；\nB 项，“有了高储蓄率”是肯后无必然结论，排除；\nC 项，“没有获得大量的资本支持”属于否前，否前无必然结论，排除；\nD 项，“没有高储蓄率”属于否后，“不能实现向发达国家的转变”是否前，否后必\n否前，当选。\n故正确答案为D。"},{"q":"知己知彼，才能百战不殆。这句话同样适用于人际交往之中，一个人只有先了解自己，才能了解别人；任何人也只信赖充分了解他的人，包括他自己。试想，如果一个人根本不了解你，他如何值得你信赖呢？由此可以推出（  ）","options":["只有信赖自己，才能信赖别人","不了解自己，就不会被任何人信赖","他充分了解你，所以他值得你信赖","充分了解自己，就可以获得许多人的信赖"],"a":1,"e":"【答案】B\n【解析】翻译推理。翻译题干：①了解别人→了解自己；②被别人信赖→了解别人。\nA 项，信赖别人→信赖自己，由题干条件无法推出，排除；B 项，不了解自己→不被别人\n信赖，是题干推导关系的逆否命题，当选；C 项，别人了解你→信赖别人，“别人了解\n你”对于②是肯后，无法推出绝对表达的结论，排除；D 项，了解自己→被别人信赖，\n“了解自己”对于①是肯后，无法推出绝对表达的结论，排除。\n故正确答案为B。"},{"q":"从世界经济的发展历程来看，如果一国或者地区的经济保持着稳定的增长速度，大多数商品和服务的价格必然会随之上涨，只要这种涨幅始终在一个较小的区间内就不会对经济造成负面影响。由此可以推出，在一定时期内（  ）","options":["如果大多数商品价格上涨，说明该国经济在稳定增长","如果大多数商品价格涨幅过大，对该国经济必然有负面影响","如果大多数商品价格不上涨，说明该国经济没有保持稳定增长","如果经济发展水平下降，该国的大多数商品价格也会下降"],"a":2,"e":"【答案】C\n【解析】翻译推理。翻译题干：①经济稳定增长→大多数商品、服务价格上涨；②价\n格涨幅较小→不会对经济造成负面影响。\nA 项，大多数商品价格上涨→经济稳定增长，“大多数商品价格上涨”对于①是肯\n后，无法推出绝对表达的结论，排除；\nB 项，价格涨幅过大→对经济造成负面影响，“价格涨幅过大”对于②是否前，无法\n推出绝对表达的结论，排除；\nC 项，大多数商品价格不上涨→经济没有稳定增长，对于①是否后必否前，当选；\nD 项，经济发展水平下降→大多数商品价格下降，“经济发展水平下降”对于①是否\n前，无法推出绝对表达的结论，排除。\n故正确答案为C。"},{"q":"某高校外语教研室新招进五位外语老师，每位老师只教授一门外语。并且满足以下条件：（1）如果小钱教德语，那么小孙不教俄语（2）或者小李教德语，或者小钱教德语（3）如果小孙不教俄语，那么小赵不教法语（4）或者小赵教法语，或者小周不教英语。以下选项如果为真，可以得出“小李教德语”的结论（  ）","options":["小孙不教俄语","小钱教德语","小周教英语","小赵不教法语"],"a":2,"e":"【答案】C\n【解析】翻译推理。翻译题干：①小钱教德语→﹣小孙教俄语；②小李教德语或者小\n钱教德语；③﹣小孙教俄语→﹣小赵教法语；④小赵教法语或者小周不教英语。若想让\n“小李教德语”根据②或关系否一推一，必须要让小钱不教德语，而小钱不教德语在①中\n为前件，否后才能否前，要让小孙教俄语。在③中小孙教俄语，又要使小赵教法语，根据\n④中否一推一，小周教英语小赵才能教法语。最终需要条件为小周教英语。\n故正确答案为C。"},{"q":"一个人生活虽然很难，但也必须学会一个人，不要轻易依赖别人。这样以后身边的人都离开你的时候，你还可以好好活下去。如果以上为真，则以下哪项为真（  ）","options":["身边人都离开时还可以好好活，未必是因你以前学会如何一个人生活","不能独自生活的人，在身边的人都离开他的时候，就无法好好活下去","一个人生活虽然很难，但也比身边的人都离开他的时候要来得容易些","不要轻易依赖别人，因为一个人生活的时候会很艰难无法好好活下去"],"a":0,"e":"【答案】A\n【解析】翻译推理。翻译题干：一个人，不依赖他人→离开，好好活。\nA 项，“身边人都离开时还可以好好活”为肯后，肯后无必然有可能，“未必”表可\n能，当选；\nB 项，“不能独自生活的人”为否前，否前无必然有可能，之后为肯定性表述，排\n除；\nC 项，与翻译式无关，排除；\nD 项，“因为”为因果关系，排除。\n故正确答案为A。"},{"q":"记者采访时的提问要具体、简洁明了，切忌空泛、笼统、不着边际。《采访技巧》一书中尖锐地剖析了“您感觉如何”等问题的弊端，认为这些提问实际上在信息获取上等于原地踏步，它使采访对象没法回答，除非用含混不清或枯燥无味的话来应付。由此可以推出（  ）","options":["记者采访时的提问如果具体、简洁明了，就不会给采访对象带来答的困难","采访对象如果没法回答提问，说明他没有用含混不清或枯燥无味的话来应付","采访对象只有用含混不清或枯燥无味的话来应付，才能回答“您感觉如何”等问题的提问","诸如“您感觉如何”这样的问题，只能使采访对象抓不住问题的要点而作泛泛的或言不由衷的回答"],"a":2,"e":"【答案】C\n【解析】翻译推理。翻译题干：回答了→含混不清或枯燥无味。\nA 项，“就不会给采访对象带来回答的困难”，题干并没有提到，排除；\nB 项，“采访对象如果没法回答提问”否定了翻译表达式的前件，否前推不出必然结\n论，选项中无“可能”的描述，排除；\nC 项，“回答‘您感觉如何’等问题的提问”肯定了前件，推出肯定后件“用含混不\n清或枯燥无味的话来应付”，当选；\nD 项，“泛泛的或言不由衷”题干没有出现，无法推理，排除。\n故正确答案为C。"},{"q":"某大型晚会的导演组在对节目进行终审时，有六个节目尚未确定是否通过，这六个节目分别是歌曲A、歌曲B、相声C、相声D、舞蹈E 和魔术F。综合考虑各种因素，导演组确定了如下方案：（1）歌曲A 和歌曲B 至少要上一个；（2）如果相声C 不能通过或相声D 不能通过，则歌曲A 也不能通过；（3）如果相声C 不能通过，那么魔术F 也不能通过；（4）只有舞蹈E 通过，歌曲B 才能通过。导演组最终确定舞蹈E 不能通过。由此可以推出（  ）","options":["无法确定魔术F 是否能通过","歌曲A 不能通过","无法确定两个相声节目是否能通过","歌曲B 能通过"],"a":0,"e":"【答案】A\n【解析】翻译推理。翻译题干：①A 或B；②—C 或—D→—A；③—C→—F；④B→\nE。根据已知条件，E 不能通过，则根据④否后必否前可得：—E→—B，即歌曲B 不能通\n过，排除D 项；根据①可得：—B→A，可知歌曲A 可以通过，排除B 项；根据②否后必\n否前得：A→C 且D，可知相声CD 都可通过，排除C 项。\n故正确答案为A。\n第三组："},{"q":"某公司30 岁以下的年轻员工中有一部分报名参加了公司在周末举办的外语培训班。该公司的部门经理一致同意在本周末开展野外拓展训练。所有报名参加外语培训班的员工都反对在本周末开展拓展训练。由此可以推出（  ）","options":["所有部门经理年龄都在30 岁以上","该公司部门经理中有人报名参加了周末的外语培训班","报名参加周末外语培训班的员工都是30 岁以下的年轻人","有些30 岁以下的年轻员工不是部门经理"],"a":3,"e":"【答案】D\n【解析】翻译推理。翻译题干：①有的30 岁以下年轻员工→参加外语培训班②部门\n经理→同意拓展训练③参加外语培训班→反对拓展训练。\nA 项，根据已知条件②③，部门经理→同意拓展训练→—参加外语培训班，但“—参\n加外语培训班”这个条件无法对于①进行否后推否前的推理，所以得不出“都在30 岁以\n上”的结果，排除；\nB 项，根据已知条件②③，部门经理→同意拓展训练→—参加外语培训班，故所有部\n门经理都没参加外语培训班，B 选项错误，排除；\nC 项，条件①表达有的30 岁以下的人参加了外语培训班，而对于整个外语培训班而\n言，班内同学是否均为30 岁以下是无法推断的，所以C 项错误，排除；\nD 项，根据条件①③可得出;有的30 岁以下年轻员工→参加外语培训班→反对拓展训\n练，又根据条件②和“否后必否前”的推理规则可得出：30 岁以下年轻员工→反对拓展\n训练→—部门经理，当选。\n故正确答案为D。"},{"q":"一切生命有机体都需要新陈代谢，否则生命就会停止。文明也是一样，如果长期自我封闭，必将走向衰落。交流互鉴是文明发展的本质要求。只有同其他文明交流互鉴、取长补短，才能保持旺盛生命活力。由此可以推出（  ）","options":["一种文明如果没有同其他文明交流互鉴，就不能保持旺盛生命活力","一种文明如果没有长期自我封闭，就不会走向衰落","一种文明如果同其他文明交流互鉴、取长补短，就能保持旺盛生命活力","一种文明如果没有保持旺盛生命活力，它就没有同其他文明取长补短"],"a":0,"e":"【答案】A\n【解析】翻译推理。翻译题干：①-生命停止→新陈代谢；②自我封闭→衰落；③旺\n盛生命活力→交流互鉴且取长补短。\nA 项，翻译为“-交流互鉴→-旺盛生命活力”，③后件是且关系，否定其中一项则否\n定全部，该选项是否后推否前，可以推出，当选；\nB 项，翻译为“-自我封闭→-衰落”，是对②的否前，否前推不出确定性结论，排\n除；\nC 项，翻译为“交流互鉴且取长补短→旺盛生命活力”，是对③的肯后，肯后推不出\n确定性结论，排除；\nD 项，翻译为“-旺盛生命活力→-取长补短”，是对③的否前，否前推不出确定性结\n论，排除。\n故正确答案为A。"},{"q":"一则广告，“衣服不搭无所谓，基金不买你心碎。”小方看后说：“我不同意。”下列最符合小方的意思的是（  ）","options":["衣服不搭有所谓，基金不买你不心碎","或者衣服不搭有所谓，或者基金不买你不心碎","如果衣服不搭有所谓，那么基金不买你心碎","如果衣服不搭无所谓，那么基金不买你心碎"],"a":1,"e":"【答案】B\n【解析】翻译推理。翻译题干：衣服不搭无所谓且基金不买你心碎。小芳说“不同\n意”即为否定广告中的“且”关系，即：（衣服不搭有所谓且基金不买你不心碎），可得\n出：-衣服不搭有所谓或基金不买你不心碎，只有B 项符合小方的意思，当选。\n故正确答案为B。"},{"q":"巫马子对墨子说：我不能兼爱。我爱我的家人比爱我家乡的人深，爱我的双亲比爱我的家人深，爱我自己胜过爱我双亲，这是因为切近我的缘故。打我，我会痛，打别人，不会痛在我身上，所以我只会杀他人以利于我。墨子问道：你的这种义会告诉别人吗？巫马子答道：我为什么要隐藏，我会告诉别人。墨子说：既然你这样，如果有人喜欢你的主张，那么这个人就要杀你以利于自己。如果有人不喜欢你的主张，那他也要杀你，因为他认为你是散布不祥之言的人。由上文可推知（  ）","options":["巫马子只能远走他乡","巫马子必须承认自己的观点是错的","巫马子一定要改变自己原来的观点","巫马子一定会被人杀死"],"a":3,"e":"【答案】D\n【解析】翻译推理。题干可翻译为：①支持巫马子→杀巫马子。②-支持巫马子→杀\n巫马子。根据归谬法可知无论支不支持巫马子，巫马子都一定会被人杀死。\n故正确答案为D。"},{"q":"某市要建花园或修池塘，有下列4 种假设，修了池塘就要架桥；架了桥就不能建花园；建花园必须植树；植树必须架桥。据此不可能推出的是（  ）","options":["最后有池塘","最后一定有桥","最后可能有花园","池塘和花园不能同时存在"],"a":2,"e":"【答案】C\n【解析】翻译推理。翻译题干：①花园或池塘；②池塘→架桥；③架桥→-花园；④\n花园→植树；⑤植树→架桥。由③④⑤递推可得：花园→植树→架桥→-花园，即花园→-\n花园；根据“归谬推理”可得：“一定不建花园”，故不可能推出C 项，当选。\n故正确答案为C。"},{"q":"中央作出新一轮支援新疆的战略部署后，某单位很快组成由党办、人事处、业务处室参加的推荐小组，确定了援疆干部人选。这三部门的推荐意见分别是：党办：从甲、乙、丙三人中选派出一至两人；人事处：如果不选派甲，就不选派乙和丙；业务处：如果不选派乙和丙，才选派甲；在下列选项中，能够同时满足党办、人事处和业务处室的意见的方案是（  ）","options":["选派乙和丙，不选派甲","不选派乙和丙，选派甲","选派乙，不选派甲和丙","选派丙，不选派甲和乙"],"a":1,"e":"【答案】B\n【解析】翻译推理。翻译题干：①-甲→-乙且-丙；②-乙且-丙→甲。①逆否命题可\n得：③-（-乙且-丙）→甲；②和③根据“归谬推理”可得：不论“-乙且-丙”成立与否，\n都能推出甲，则一定选派甲。\n故正确答案为B。"},{"q":"今天的中国，改革依然是人心所向、大势所趋。在新的历史时期，在现有成就基础上，经济社会要持续保持又好又快发展，就需要以更大的勇气、魄力和力度来推进改革、深化改革，只有这样，才能在用好机遇、化解风险中奋力闯出深水区，开创中国现代化的新境界。由此可以推出（  ）","options":["不深化改革，就无法闯出改革的深水区","深化改革，可以闯出改革的深水区","无法闯出改革的深水区，是因为没有深化改革","闯出改革的深水区，就能深化改革"],"a":0,"e":"【答案】A\n【解析】翻译推理。翻译题干：①经济社会持续保持又好又快发展→推进改革、深化\n改革；②闯出改革的深水区→推进改革、深化改革。\nA 项，闯出改革对逻辑表达式②肯前，肯前必肯后，可推出推进改革、深化改革，当\n选；\nB 项，深化改革→闯出改革的深水区，是对②肯后，否前肯后无必然结论，排除；\nC 项，-闯出改革的深水区→-深化改革，是对②的否前，否前肯后无必然结论，排\n除；\nD 项，闯出改革的深水区→深化改革，改变原意，排除。\n故正确答案为A。"},{"q":"应该看到，“少数人靠觉悟，多数人靠政策”。将各种社会问题归结为良知不守，则有逻辑倒置和认知错位之嫌。很多问题，是缺“法”导致缺“德”，而不是相反。如果监管和惩罚机制能够得到严格执行，食品生产者的“投毒冲动”就能得到有效抑制：如果制度健全，使好人流血不再流泪，藏于人心的本然良知就能够转化为见义勇为的实际行为。由此可以推出（  ）","options":["如果良知不能化为行动，说明制度仍有待完善","只有制度健全，才不会良知不守","只要守住良知，就不会有各种社会问题","只有制度健全，才不会有各种社会问题"],"a":0,"e":"【答案】A\n【解析】翻译推理。翻译题干：制度健全→藏于人心的本然良知就能够转化为见义勇\n为的实际行为。\nA 项，良知不能化为行动为逻辑表达式的“否后”，否后必否前，推出“制度不健\n全”，即制度仍有待完善，当选。\nB 项，良知不守与制度健全之间无明确逻辑关系，排除；\nC 项，守住良知和社会问题之间无明确条件关系，排除；\nD 项，制度健全和社会问题之间无明确逻辑关系，排除。\n故正确答案为A。"}]},{"id":"fenxi","name":"分析推理","items":[{"q":"T 国几大电力企业近日联合宣布，除非国产煤炭价格下调，否则将放弃国产煤炭。发言人表示，目前进口煤炭的价格已经降至每吨100 美元以内，而国产煤炭价格仍然居高不下。但是，煤炭行业业内人士表示，一旦煤炭价格持续走低，中小型煤矿将生存艰难，大型煤矿企业生产的动力也会严重不足，整个国内煤炭生产行业将面临严峻的形势。一段时间后，该业内人士判断，目前国内煤炭生产企业已经形势严峻。该业内人士的判断必须基于以下哪项事实（  ）","options":["国内煤炭企业在这段时间内减少了煤炭产量","该国国产煤炭价格始终居高不下","国产煤炭在与进口煤炭的价格竞争中没有优势","该国几大电力企业没有放弃购买国产煤炭"],"a":3,"e":"【答案】D\n【解析】翻译推理。翻译题干：①不放弃国产煤炭→价格下调；②价格下调→煤炭生\n产行业面临严峻形势；①②根据递推可得③不放弃国产煤炭→价格下调→煤炭生产行业面\n临严峻形势，需要得到国内煤炭生产企业已经形势严峻的结论。\nA 项，减少煤炭产量和逻辑表达式无关，无法推导，排除；\nB 项，价格居高不下是对②的否前，无法得到确定的结论，排除；\nC 项，国产煤炭无价格优势与逻辑表达式无关，无法推导，排除；\nD 项，电力企业没有放弃购买国产煤炭是对③的肯前，可以得到国内煤炭生产企业已\n经形势严峻的结论，当选。\n故正确答案为D。\n第三节分析推理\n第一组："},{"q":"某宿舍住着小华、小峰、小明、小刚和小强五名本科生，在确定学年论文指导老师时，他们将分别被分给张老师、王老师和李老师当中的一人。张老师只研究古代文学，王老师只研究词汇学和古文字学，李老师只研究句法学和词汇学。每位指导老师最多可指导两人，每位同学仅对所分配指导老师的一个研究方向感兴趣。已知：（1）小峰和小刚被分给了王老师；（2）小华被分给了李老师。若每位同学都按照自己的兴趣被分配给了指导老师，则以下各项都是符合题干的陈述，除了哪项（  ）","options":["小明对词汇学感兴趣，小强对古代文学感兴趣","小明对句法学感兴趣，小强对古代文学感兴趣","小明对古代文学感兴趣，小强对句法学感兴趣","小明对古代文学感兴趣，小强对古文字学感兴趣"],"a":3,"e":"【答案】D\n【解析】分析推理，选非题。分析题干条件可知：王老师研究词汇学和古文字学且已\n有小峰和小刚两个学生，由于每位导师最多可指导两人，故剩余的两位学生小明和小强，\n应分配给张老师和李老师。\nA 项，如果小明对词汇学感兴趣可分配给李老师，则小强对古代文学感兴趣可分配给\n张老师，满足题干条件，排除；\nB 项，如果小明对句法学感兴趣只能分配给李老师，则小强对古代文学感兴趣可分配\n给张老师，满足题干条件，排除；\nC 项，如果小明对古代文学感兴趣可分配给张老师，则小强对句法学感兴趣可分配给\n李老师，此时满足题干条件，排除；\nD 项，如果小明对古代文学感兴趣可分配给张老师，则小强对古文字学感兴趣只能分\n配给王老师，此时与我们推理相矛盾，当选。\n故正确答案为D。"},{"q":"几位同事在小王家喝茶聊天。他们讨论正在喝的这种茶是什么茶。小刘说：“不是龙井，不是碧螺春”，小赵说：“不是龙井，是乌龙茶”，小李说：“不是乌龙茶，是龙井。”最后，经小王确认，三人中有一人的判断完全正确，一个人只说对了一半，另外一个人则完全说错。据此，可以推出（  ）","options":["小刘的判断完全正确，他们喝的是乌龙茶","小赵的判断完全正确，他们喝的不是龙井","小李的判断完全正确，他们喝的是龙井","小李只说对了一半，他们喝的是碧螺春"],"a":2,"e":"【答案】C\n【解析】分析推理。\nA 项，代入题干，小刘正确，喝的是乌龙茶，那么小赵也完全正确，与题干不符，排\n除；B 项，代入题干，小赵完全正确，喝的不是龙井，是乌龙茶，那么小刘也完全正确，\n与题干不符，排除；C 项，代入题干，小李的判断完全正确，喝的是龙井，小刘对一半，\n小赵全错，与题干相符，当选；D 项，代入题干，小李只说对了一半，喝的是碧螺春，小\n刘对一半，小赵也对一半，与题干不符，排除。\n故正确答案为C。"},{"q":"某国针对本国本科毕业生的调查数据显示，该国的大多数本科毕业生为工学类，也有一部分本科毕业生为人文社科类，在这些毕业生中，大多数在毕业时就已经就业，只有少部分未就业。由此一定可以推出的是（  ）","options":["大多数工学类本科毕业生在毕业时已就业","有些人文社科类本科毕业生在毕业时未就业","有些工学类本科毕业生在毕业时已就业","有些人文社科类毕业生在毕业时已就业"],"a":2,"e":"【答案】C\n【解析】分析推理。\n①大多数本科毕业生为工学类\n②有一部分本科毕业生为人文社科类\n③大多数在毕业时就已经就业\n根据题干所给信息，①③，都为大多数，即都超过二分之一，必然会有一部分的重\n叠，故有些工学类本科毕业生在毕业时已就业。\n故正确答案为C。"},{"q":"F、G、H、J 四个人是大学同学，他们都参加了研究生考试，但最后只有一个人考上了研究生。而其余三人分别成为了作曲家、高中老师和公务员。在研究生考试复习期间，有一天他们坐在一起预测大家将来的生活，F 说：G 肯定不会成为作曲家；G 说：H 肯定可以考上研究生；H 说：J 不会成为公务员；J 预测他自己将来会娶一名外国妻子。可是他们的预测中只有一个是正确的，且预测正确的那个人考上了研究生。据此可以推断出以下哪项是错误的（  ）","options":["J 并未娶外国人为妻","F 考上了研究生","G 成为了高中老师","H 成为了公务员"],"a":3,"e":"【答案】D\n【解析】分析推理，选非题。根据题干最后一句：他们的预测中只有一个是正确的，\n且预测正确的那个人考上了研究生。由于题干条件不充分，故可运用假设法。从研究生入\n手进行推理，G 说的内容提到了研究生，故先假设G 说的为真，根据条件，即得出G 为研\n究生；又因他说的话为真，则H 也为研究生，但题干要求“只有一个人考上了研究生”，\n故假设不成立，G 的预测错误，即G 和H 没有考上研究生，那么H 预测的也是错误的，\n可得：J 成为了公务员。因此，D 项错误，当选。\n故正确答案为D。"},{"q":"在下列4×4 的正方形矩阵中，每个小方格可填入一个汉字，要求每行每列以及粗线框成的4 个小正方形中均含有天、地、日、月4 个汉字。根据上述条件，方格①中应填入的汉字是（  ）","options":["地","天","月","日"],"a":1,"e":"【答案】B\n【解析】分析推理。根据最大信息法，横纵信息最多交叉的位置为最大信息处，如图\n所示，首先看a 处，a 不能填入月、日、地、因此a 填入天，红色粗线框内b 只能填入\n地，而c 处不能填天、地、日，只能填入月，因此①处应该填入天。\n故正确答案为B。"},{"q":"甲、乙、丙、丁、戊、己、庚七人表演配乐诗朗诵，为确保表演效果，需要安排朗诵顺序。已知：（1）甲要么第一个朗诵，要么最后一个朗诵；（2）乙和丙之间有三人；（3）丁和戊之间有三人，且丁先朗诵；（4）丁在乙之前朗诵。根据上述条件，以下哪项可能为真（  ）","options":["丙第二个朗诵","乙第四个朗诵","庚第二个朗诵","丁第四个朗诵"],"a":0,"e":"【答案】A\n【解析】分析推理。代入选项。\nA 项，丙第二个，根据条件2 可知，乙在第六个，根据条件3、4 可知，表演顺序为\n甲、丙、丁、X、X、乙、戊，丙第二个可以为真，当选；\nB 项，乙第四个，根据条件2 可知，丙没有合适位置，因此乙第四个不能为真，排\n除；\nC 项，庚第二个，假设甲在第一个，根据条件2、4 可知丙在第三个，乙在最后一\n个，丁和戊之间最多有一人，不符合条件3，错误；假设甲在最后一个，根据条件2、4\n可知丙在第一个，乙在第五个，丁和戊之间最多有两人，不符合条件3，错误，因此庚在\n第二个不能为真，排除；\nD 项，丁第四个，根据条件3 可知戊没有合适的位置，因此丁第四个不能为真，排\n除。\n故正确答案为A。"},{"q":"有教师、公务员、银行职员三人，其中甲不是银行职员，乙不是教师，丙不是公务员。教师比乙年龄大，丙在三人中年龄最小。根据上述条件，下列说法错误的是（  ）","options":["甲是教师","乙是公务员","甲不是公务员","丙不是银行职员"],"a":3,"e":"【答案】D\n【解析】分析推理。选非题。因为教师比乙年龄大，丙在三人中年龄最小，所以丙不\n是教师，又因为丙不是公务员，所以丙只能是银行职员，D 项错误。\n故正确答案为D。"},{"q":"在人事科科长人选问题上，某局决定由单位全体工作人员投票产生，得票前三名作为候选人，每人只需在本局职工名单上打勾即可。计票组发现，刚毕业的张浩没有打任何人的勾；凡是对赵杰打勾的人，王明对这些人都打了勾；没有得全票的人李紫露都打了勾。由此可以推出（  ）","options":["王明和李紫露相互没打勾","王明和李紫露相互打了勾","王明选了李紫露，但是李紫露没有选王明","王明没选李紫露，但是李紫露选了王明"],"a":1,"e":"【答案】B\n【解析】分析推理。①刚毕业的张浩没有打任何人的勾；②凡是对赵杰打勾的人，王\n明对这些人都打了勾；③没有得全票的人李紫露都打了勾。从“张浩没有打任何人的勾”\n可知，没有人得全票。而李紫露给没得全票的人都打了勾，因此李紫露给所有人都打勾\n了，包括赵杰、王明。而所有给赵杰打勾的人，王明都给打勾了，因此王明给李紫露打勾\n了。\n故正确答案为B。"},{"q":"吴旭、郑洁和沈瑶三人打算到南京故地重游，三人选择飞机、火车、汽车和轮船之一出行，但各人出行方式均不相同。如果郑洁选择汽车出行，则吴旭不选择轮船；如果吴旭选择火车出行，则沈瑶不选择飞机；沈瑶选择飞机、火车之一出行。根据以上陈述可知，下列哪项，必定是错误的（  ）","options":["沈瑶选择飞机，而郑洁选择汽车","沈瑶选择飞机，而郑洁选择轮船","沈瑶选择火车，而郑洁选择汽车","沈瑶选择火车，而郑洁选择飞机"],"a":0,"e":"【答案】A\n【解析】分析推理。翻译题干：①郑洁汽车→吴旭不轮船，②吴旭火车→沈瑶不飞\n机，③沈瑶要么飞机要么火车。将A 选项代入题干，沈瑶选择飞机，根据翻译②，否后必\n否前，可知吴旭不坐火车，郑洁选择汽车，根据翻译①，肯前必肯后，可知吴旭不坐轮\n船，则吴旭没有能坐的交通工具，因此A 项必定是错误的。\n故正确答案为A。"},{"q":"几位同学对物理竞赛的名次进行猜测。小钟说：“小华第三，小任第五。”小华说：“小闽第五，小宫第四。”小任说：“小钟第一，小闽第四”。小闽说：“小任第一，小华第二。”小宫说：“小钟第三，小闽第四。”已知本次竞赛没有并列名次，并且每个名次都有人猜对。那么，具体名次应该是（  ）","options":["小华第一、小钟第二、小任第三、小闽第四、小官第五","小闽第一、小任第二、小华第三、小宫第四、小钟第五","小任第一、小华第二、小钟第三、小宫第四、小闽第五","小任第一、小闽第二、小钟第三、小宫第四、小华第五"],"a":2,"e":"【答案】C\n【解析】分析推理。已知本次竞赛没有并列名次，并且每个名次都有人猜对，可知题\n干名次只出现一次必然猜对了，题干第二只出现1 次，因此小华第二必然正确，只有C 项\n小华第二。\n故正确答案为C。\n第二组："},{"q":"某次会议讨论期间，甲、乙、丙、丁、戊被安排在一张圆桌前进行讨论，圆桌边放着标有1～5 号的五张座椅（未必按序排列）。实际讨论时，甲、乙、丙、丁、戊5 人均未按顺序坐在1～5 号的座椅上，已知：（1）甲坐在1 号座椅右边第二张座椅上；（2）乙坐在5 号座椅左边第二张座椅上；（3）丙坐在3 号座椅左边第一张座椅上；（4）丁坐在2 号座椅左边第一张座椅上。如果丙坐在1 号座椅上，则可知甲坐的是哪个座椅（  ）","options":["2 号","3 号","4 号","5 号"],"a":2,"e":"【答案】C\n【解析】已知1 号是丙，条件（1）甲坐在1 号座椅右边第二张座椅上，所以甲在图\n1 所示位置；条件（3）丙坐在3 号座椅左边第一张座椅上，所以找到3 号座椅，如图2\n所示位置；条件（2）乙坐在5 号座椅左边第二张座椅上，有a、b、c（如图3 所示）3 种\n可能性，若a 为5 号，则乙坐在丙的位置上，排除；若b 为5 号，则乙坐在3 号位置上，\n可取；若c 为5 号，则乙坐在甲的位置上，排除；所以b 位置为5 号（如图4 所示）。条\n件（4）丁坐在2 号座椅左边第一张座椅上，2 号有a、c 位置2 种可能，如果a 为2 号，\n丁坐在乙的位置上，排除；若c 为2 号，则丁坐在5 号位置。所以甲的位置只能是4 号。\n故正确答案为C。"},{"q":"小溪根据学习计划制定了阅读书单，准备阅读《红楼梦》《水浒传》《三国演义》《西游记》《论语》《道德经》《诗经》七部名著，每部均要阅读，但是她的阅读顺序必须符合如下要求：（1）阅读《道德经》之前要先阅读《三国演义》，阅读这两部著作之间还要阅读另外两部著作（《诗经》除外）；（2）第一部或者最后一部阅读《西游记》；（3）第三部阅读《论语》；（4）阅读《诗经》要在阅读《道德经》之前或者刚刚阅读完《道德经》之后。如果小溪首先要阅读《三国演义》，则可以确定她的阅读顺序是（  ）","options":["第二部阅读《水浒传》","第五部阅读《道德经》","第二部阅读《红楼梦》","第五部阅读《诗经》"],"a":3,"e":"【答案】D\n【解析】分析推理，根据提问和题干条件（2）（3）可知：\n根据题干条件（1）可知，《道德经》排在第四\n根据题干条件（1）（4）可知，《诗经》不能在一、四之间，只能在刚刚阅读完《道\n德经》之后，所以在第五\n根据题干条件，无法确定《红楼梦》和《水浒转》的顺序谁第二，谁第六。\n故正确答案为D"},{"q":"小若为了参加一项法律考试，准备在一周之内复习14 门课程，其中民法课程5 门、经济法课程3 门、行政法课程3 门、商法课程2 门、国际私法课程1 门。但是因为精力有限，小若每天只能复习2 门课程，并且需要满足以下条件：（1）星期四只能复习2 门民法课程，其余每天必须复习两类不同的课程；（2）国际私法必须在星期天复习；（3）民法和行政法不能在同一天复习；（4）经济法和商法不能在同一天复习。由此可以推出，以下哪两类课程不可能在同一天复习（  ）","options":["经济法和国际私法","行政法和经济法","行政法和商法","民法和经济法"],"a":0,"e":"【答案】A\n【解析】由题干知，每天复习2 门，周四已经排满，因此剩余13 门课程只能排在除\n周四以外的6 天内。\n民法和行政法不能在同一天，所以剩余6 天排3 门民法和3 门行政法。由于周日复习\n国际私法，因此另1 门要么是民法，要么是行政法。不可能是经济法或商法。\n故正确答案为A。"},{"q":"某部门新录用甲、乙、丙三名工作人员，他们各自的籍贯为江苏、安徽、浙江中的某个省。张红、李梅和王芹对他们的籍贯有如下猜测：张红：甲是浙江人，乙是安徽人，丙也是浙江人；李梅：甲是浙江人，乙是江苏人，丙不是江苏人；王芹：甲是江苏人，乙是浙江人，丙也是江苏人。已知，对甲、乙、丙的籍贯，上述三人均猜对1 个，猜错2 个。根据以上信息，以下哪项是可能的（  ）","options":["甲是江苏人，乙是安徽人，丙是浙江人","甲是浙江人，乙是江苏人，丙是江苏人","甲是安徽人，乙是浙江人，丙是江苏人","甲是江苏人，乙是安徽人，丙是安徽人"],"a":3,"e":"【答案】D\n【解析】分析推理。将选项代入题干分析，只有D 项满足三人均猜对1 个，猜错2\n个。\n故正确答案为D。"},{"q":"单位安排甲、乙、丙、丁、戊、己、庚、辛8 人出差，他们恰好被安排在宾馆同一排左右相邻的8 个房间。已知：①甲和丙中间隔着3 人；②乙和已中间隔着2 人；③丁在庚的左边，他们中间隔着2 人；④辛和戊中间隔着1 人。根据以上信息，按照从左到右的顺序，下列哪项是不可能的（  ）","options":["丁在第一个房间","丁在第二个房间","丁在第三个房间","丁在第四个房间根据所给材料，回答6—10 题。某办公室有王莉、李明和丁勇3 名工作人员，本周有分别涉及网络、财务、管理、人事和教育的5 项工作需要他们完成。关于任务安排，需要满足下列条件：①每人均需至少完成其中的一项工作，一项工作只能由一人完成；②人事和管理工作都不是由王莉完成的；③如果人事工作由丁勇完成，那么财务工作由李明完成；④完成教育工作的人至少还需完成一项其他工作。到了周末，3 人顺利地完成了上述5 项工作。"],"a":2,"e":"【答案】C\n【解析】分析推理。代入选项分析。\nA 项，存在下图这种可能性，排除；\nB 项，存在下图这种可能性，排除；\nC 项，丁在三，那么庚在六，此时甲和丙只能是一和五或者四和八。当甲和丙在一和\n五时，那么乙和己只能是四和七，剩下二和八只能是戊和辛，与④矛盾；当甲和丙是四和\n八时，那么乙和己只能是二和五，剩下一和七只能是戊和辛，与④矛盾，因此C 项不可\n能，当选；D 项，存在这种可能性，排除。\n故正确答案为C。"},{"q":"以下哪项的工作安排符合上述条件（  ）","options":["王莉：管理、网络；李明：教育、人事；丁勇：财务","王莉：教育、财务；李明：人事、管理；丁勇：网络","王莉：网络；李明：人事、管理、财务；丁勇：教育","王莉：网络；李明：教育、管理；丁勇：人事、财务"],"a":1,"e":"【答案】B\n【解析】分析推理。翻译题干:丁勇完成人事→李明完成财务，题干信息确定，优先\n采用排除法。\n由②可知王莉不能完成管理，排除A 项；\n由③可知丁勇完成人事，则李明必须完成财务，因此排除D 项；\n由④可知完成教育的必须完成其他工作，所以丁勇不能只完成教育，排除C 项。\n故正确答案为B。"},{"q":"如果李明只完成5 项工作中的一项，那么包括该工作的所有可能性是以下哪项（  ）","options":["人事、财务","人事、管理、财务","人事、网络","财务"],"a":0,"e":"【答案】A\n【解析】如果李明只完成人事，剩余工作为：财务、教育、网络、管理。其中王莉不\n能做管理，则管理只能由丁勇完成。王莉做剩余其他三项工作，假设成立。所以李明可以\n只做人事。排除D；如果李明只完成财务，剩余工作为：人事、教育、网络、管理。其中\n王莉不能做人事、管理，则人事、管理由丁勇完成。那么王莉可完成教育和网络工作，假\n设成立。所以李明可以只做财务。排除C；如果李明只完成管理，剩余工作为：财务、教\n育、网络、人事。其中王莉不能做人事，则人事由丁勇完成。与题干“丁勇若做人事，则\n李明做财务”矛盾；所以李明不能只完成管理。排除B。\n故正确答案为A。"},{"q":"以下哪项中的任务不可能均由李明完成（  ）","options":["教育、人事、财务","教育、人事、网络","教育、管理、财务","教育、管理、网络"],"a":3,"e":"【答案】D\n【解析】A 项，若李明完成教育、人事、财务，则剩余工作为：网络、管理。其中王\n莉不能做管理，则管理由丁勇完成。王莉做网络，假设成立。排除；\nB 项，若李明完成教育、人事、网络，则剩余工作为：管理、财务。其中王莉不能做\n管理，则管理由丁勇完成。王莉做财务，假设成立。排除；\nC 项，若李明完成教育、管理、财务，则剩余工作为：人事、网络。其中王莉不能做\n人事，则人事由丁勇完成。王莉完成网络，假设成立。排除；\nD 项，若李明完成教育、管理、网络，则剩余工作为：人事、财务。其中王莉不能做\n人事，则人事由丁勇完成，财务由王莉完成，与题干“丁勇若做人事，则李明做财务”矛\n盾，假设不成立。当选。\n故正确答案为D。"},{"q":"以下哪项中的任务不可能均由丁勇完成（  ）","options":["财务、管理","网络、人事","管理、人事","教育、管理"],"a":1,"e":"【答案】B\n【解析】A 项，若丁勇完成财务、管理，则剩余工作为：人事、网络、教育。其中王\n莉不能做人事，则人事由李明完成。王莉做网络、教育，假设成立。排除；\nB 项，若丁勇完成网络、人事，则剩余工作为:管理、财务、教育。其中王莉不能做管\n理，则管理由李明完成。由题干“丁勇若做人事，则李明做财务”可知，李明完成：管\n理、财务。王莉做教育，与题干“完成教育工作的人至少还需完成一项其他工作”矛盾，\n假设不成立。当选。\n故正确答案为B。"},{"q":"如果管理工作和网络工作是由同一个人完成的，则以下哪项是可能的（  ）","options":["教育工作是由李明完成的","财务工作是由丁勇完成的","管理工作是由李明完成的","人事工作是由丁勇完成的"],"a":0,"e":"【答案】A\n【解析】A 选项，教育工作是由李明完成的。管理和网络由同一人完成，由于王莉不\n能完成管理，因此做管理和网络的只能为丁勇或李明。假设①李明完成：管理、网络、教\n育。剩余工作为：人事、财务。由于王莉不做人事，则人事由丁勇完成。财务由王莉完\n成，与题干“丁勇若做人事，则李明做财务”矛盾，第一种假设不成立。②丁勇完成：管\n理、网络，李明：教育，剩余工作为：人事、财务。由于王莉不能做人事，则人事由李明\n完成。李明：教育、人事。王莉做财务，假设成立，当选。\n故正确答案为A。\n第三组："},{"q":"关于分管情况，下列哪项是可能的（  ）","options":["王：人事、工会卫：宣传、后勤丁：科研、教育、财务","王：工会、科研卫：人事、教育、财务丁：宣传、后勤","王：教育、财务卫：人事、后勤丁：科研、宣传、工会","王：宣传、后勤卫：人事、工会丁：科研、教育、财务"],"a":0,"e":"【答案】A\n【解析】分析推理。\n由条件（2）可知，宣传和后勤由同一人负责，排除C 项；由条件（3）可知，丁>\n卫，\n排除B 项；由条件（4）可知，王负责教育工会中的一个，排除D 项。\n故正确答案为A。"},{"q":"如果王分管的部门多于丁，下列哪项可能为真（  ）","options":["人事由卫分管","科研由卫分管","后勤由丁分管","教育由丁分管"],"a":2,"e":"【答案】C\n【解析】分析推理。\n已知王分管的部门多于丁，根据（3），可知王>丁>卫。结合（5）可知，卫至少分管\n1 个。一共7 个部门，王、丁、卫分管的部门数只有一种情况，即王分管4 个，丁分管2\n个，卫分管1 个。\nA 项，人事由卫分管，那么根据（5），卫需要负责分管2 个部门，与上述结论冲\n突，排除；\nB 项，科研由卫分管，那么根据（5），卫需要负责分管2 个部门，与上述结论冲\n突，排除；\nC 项，后勤由丁分管，根据（5），卫负责工会。根据（4），王负责教育。结合\n（1）（2）可知，王负责教育和财务，丁负责后勤和宣传。剩余人事和宣传可一并由王负\n责。故该项可能为真，当选；\nD 项，教育由丁分管，根据（1），丁同时负责教育和财务，根据（4）王负责工会，\n根据（5），卫负责后勤，结合（2），卫还需要负责宣传，与上述结论冲突，排除。\n故正确答案为C。"},{"q":"下列哪项是不可能的（  ）","options":["科研和宣传由丁分管","教育和宣传由王分管","人事和宣传由王分管","人事和宣传由丁分管"],"a":2,"e":"【答案】C\n【解析】分析推理。\nA 项，科研和宣传由丁分管，根据条件（2）可知：丁分管宣传、后勤、科研；根据\n条件（5）可知：卫负责工会；根据（4）（1）可知：王分管教育、财务；那么剩下的人\n事，可由三人中任何一人分管，故A 项是可能的，排除；\nB 项，教育和宣传由王分管，根据条件（1）（2）可知：王分管的为教育、财务、宣\n传、后勤；根据条件（5）可知：卫分管工会；根据条件（3）剩下的两个部门需由丁分\n管，故\nB 项也是可能的，排除；\nC 项，人事和宣传由王分管，根据条件（2）可知：王分管人事、宣传、后勤；根据\n条件（5）可知：工会就由卫分管；那么根据条件（4）（1）可知：王同时要分管教育、\n财务、人事、宣传、后勤；此时丁只负责科研，不符合条件（3），故C 项是不可能的，\n当选；\nD 项，人事和宣传由丁分管，根据条件（2）可知：丁分管人事、宣传、后勤；根据\n条件（5）工会由卫负责；根据条件（4）（1），教育和财务由王分管，那么剩下的科\n研，可由三人中任何一人分管，故D 项是可能的，排除；\n故正确答案为C。"},{"q":"财务和以下哪个部门不可能由同一人分管（  ）","options":["工会","科研","宣传","人事"],"a":0,"e":"【答案】A\n【解析】分析推理。\nA 项，财务和工会由同一个人分管，根据条件（1），此人同时分管教育、财务和工\n会。与条件（4）王分管教育和工会中的一个矛盾，所以财务和工会不能由同一人负责。\n故正确答案为A。"},{"q":"如果科研和宣传由同一人分管，那么下列哪项是可能的（  ）","options":["人事由卫分管","科研由王分管","教育由丁分管","宣传由卫分管"],"a":0,"e":"【答案】A\n【解析】分析推理。\n已知：科研和宣传由同一个人负责。结合（2），此人需同时负责后勤。根据（4）可\n知，王至少需要分管其中一个部门，那么一共7 个部门，结合（3），此人只能是丁或\n王。\nA 项，人事由卫分管，根据（5），卫还需分管工会，结合（4）可知，教育由王分\n管，根据（1）王还需要负责财务。剩余一个部门：人事。可以由任意一个人负责，满足\n题干条件，当选；\nB 项，科研由王分管，根据已知条件，王同时负责科研、宣传和后勤。根据（5），\n工会由卫分管，结合（4）可知，教育由王分管，根据（1）王还需要负责财务。王同时负\n责科研、宣传、后勤、教育和财务。即使人事由丁分管，也不满足（3），排除；\nC 项，教育由丁分管，根据（1），丁需要负责教育和财务。根据（4），工会由王负\n责。根据（5），后勤由卫负责。结合已知条件，可知卫同时分管科研、宣传和后勤。与\n已知信息冲突，排除；\nD 项，宣传由卫分管，根据（2）卫还需分管后勤，结合已知条件，可知卫需要同时\n分管科研、宣传和后勤。与已知信息冲突，排除。\n故正确答案为A。"},{"q":"已知一次英语考试甲、乙、丙、丁的成绩如下：甲、乙的成绩之和等于丁、丙的成绩之和，如果把乙和丁的成绩互换，甲和丁的成绩之和大于乙和丙的成绩之和，乙的成绩比甲、丙的成绩都高。根据以上所知，下列哪项为真（  ）","options":["甲的成绩最高","乙的成绩最高","丙的成绩最高","丁的成绩最高"],"a":3,"e":"【答案】D\n【解析】分析推理。根据已知条件可得：①甲＋乙=丙+丁，②甲＋丁>乙+丙，③乙>\n甲、丙；根据条件③，甲、丙的成绩不能是最高的，排除A、C。再由条件①②可知丁>\n乙，排除B 项。\n故正确答案为D。"},{"q":"甜品店有四种甜品：双皮奶、布丁、蛋糕和冰淇淋。B 比A 贵，C 最便宜，双皮奶比布丁贵，蛋糕最贵，冰淇淋比D 贵。关于这四种甜点，下列说法正确的事（  ）","options":["A 是双皮奶，B 是蛋糕，C 是冰淇淋，D 是布丁","A 是布丁，B 是冰淇淋，C 是蛋糕，D 是双皮奶","A 是冰淇淋，B 是蛋糕，C 是布丁，D 是双皮奶","A 是冰淇淋，B 是蛋糕，C 是双皮奶，D 是布丁"],"a":2,"e":"【答案】C\n【解析】分析推理。由题干信息可确定C 最便宜，双皮奶比布丁贵，说明双皮奶不是\nC，排除D 项；蛋糕最贵说明蛋糕也不是C，排除B 项；冰淇淋比D 贵说明冰淇淋不是\nC，排除A 项。\n故正确答案为C。"},{"q":"三人在一起猜测晚会节目的顺序。甲说：“一班第一个出场，二班第三个出场。”乙说：“三班第一个出场，四班第四个出场。”丙说：“四班第二个出场，一班第三个出场。”结果公布后，发现他们的预测都只对了一半。由以上可以推出，节目的正确出场顺序是（  ）","options":["四班第一，三班第二，一班第三，二班第四","二班第一，一班第二，三班第三，四班第四","三班第一，四班第二，二班第三，一班第四","一班第一，二班第二，四班第三，三班第四"],"a":2,"e":"【答案】C\n【解析】分析推理。题干已知发现他们的预测都只对了一半，所以选项代入题干验证\n即可。\nA 项，甲说一班第一个出场错误，二班第三个出场错误，甲全错，与题干条件每人的\n预测都只对了一半不符，排除；\nB 项，甲说一班第一个出场错误，二班第三个出场错误，甲全错，与题干条件每人的\n预测都只对了一半不符，排除；\nC 项，甲说一班第一个出场错误，二班第三个出场正确，甲符合；乙说三班第一个出\n场正确，四班第四个出场错误，乙符合；丙说四班第二个出场正确，一班第三个出场错\n误，丙符合，三人预测都只对了一班，满足题干条件，当选；\nD 项，甲说一班第一个出场正确，二班第三个出场正错误，甲符合；乙说三班第一个\n出场错误，四班第四个出场错误，乙全错，与题干条件每人的预测都只对了一半不符，排\n除。\n故正确答案为C。"},{"q":"把红、黄、蓝、绿、紫五个小球放在五个排成一列的抽屉里，序号为A、B、C、D、E。要求：黄球放在绿球和紫球前面，蓝球不能放在B 抽屉里，红球和绿球之间隔着一个抽屉。问黄球放在哪个抽屉时，五个球的排放顺序是唯一的（  ）","options":["B 抽屉","C 抽屉","D 抽屉","E 抽屉"],"a":1,"e":"【答案】B\n【解析】分析推理。黄球放在绿球和紫球前面，所以黄球不可能在DE 位置，排除CD\n两项。剩下两个选项继续推理的情况太多，我们来使用假设法。假设黄球在C 抽屉，绿球\n和紫球只能放在DE 中，蓝球不能放在B 抽屉里，那只能放在A 中。红球只能放在B 中。\n红球和绿球之间隔着一个抽屉。那么绿球只能放在D 中，紫球放在E 中。排序是唯一的。\n故正确答案为B。"},{"q":"甲乙丙丁四个人高考前对英语成绩进行预测。当时，甲说：“我再怎么努力也考不了90 分。”乙说：“不知道自己能考多少分，但是我知道丙能考90 分。”丙说：“不会考到80 分。”丁说：“乙不会考的比60 分还低”。事实上只有一个人猜对了。以下哪个结论不支持乙猜对了（  ）","options":["丁考得比甲好","乙考得不是最差的","甲和丙考得一样高","丙和丁考得一样高"],"a":1,"e":"【答案】B\n【解析】分析推理，选非题。假设乙说的话对，其他人说的都是错的，那么由此得出\n甲≥90 分，丙≥90 分，丁≥80。乙＜60 分。必须满足以上条件才可以支持乙猜对了，不\n满足的就是不支持乙猜对。B 选项为乙考的不是最差的，矛盾，不能支持。\n故正确答案为B。\n第四组："},{"q":"甲乙丙丁同住一寝室，有人问他们：“你们当中谁会的语言最多？”甲说：“我不会说英语，当乙和丙交谈时，我能用外语给他们翻译。”乙说：“我是英国人，丁不会说英语，但我俩可以毫无困难地交流。”丙说：“我和丁交流时，需要乙来帮忙翻译”。丁说：“我们四个人不能同时用一种语言交流。”据此可以推断出四个人中谁会的语言最多（  ）","options":["甲","乙","丙","丁"],"a":1,"e":"【答案】B\n【解析】分析推理。整理题干条件可知：甲不会英语，丁不会英语，丙和丁交流需要\n乙翻译，说明丙不会丁的语言，我们就知道甲、丙、丁都至少不懂一种语言，即最多懂三\n种语言，乙是英国人会英语，丙丁交流需要乙翻译，所以乙至少懂三种语言，所以只可能\n是乙会的语言最多。\n故正确答案为B。"},{"q":"某书店有10 个书架按序号1、2、3……、10 依次摆放，其中只放置儿童书籍的书架有1 个；只放置科技书籍的书架有2 个，并且连号排列；只放置历史书籍的书架有3 个，并且不与放置儿童书籍的书架连号排列；只放置文学书籍的书架有4 个，并且不与放置科技书籍的书架连号排列。如果第1、3、10 号书架放置历史书籍，4 号书架放置科技书籍，那么儿童书籍一定放置在几号书架上（  ）","options":["2 号书架","5 号书架","6 号书架","7 号书架"],"a":2,"e":"【答案】C\n【解析】分析推理。题干信息太多，我们利用表格法来梳理题干信息。\n已知信息第1、3、10 号书架放置历史书籍，4 号书架放置科技书籍。\n根据题干“只放置科技书籍的书架有2 个，并且连号排列”可知5 号为科技书架，\n根据题干条件“只放置文学书籍的书架有4 个，并且不与放置科技书籍的书架连号排\n列”可知文学书架不能放在6 号，那么2、7、8、9 四个位置为文学书架，最后剩下6 号\n位置就是儿童书架。\n故正确答案为C。"},{"q":"一群网友在现实中举办化装舞会，每个人必须按照网名所代表的人物或者事物来装扮自己。白雪公主、巫婆、佐罗、石头、哈利波特、仙人掌是甲、乙、丙、丁、戊、己六个网友的网名。甲、乙、戊是女性，其他三位是男性。乙、丙、戊的年龄超过了30 周岁。在化妆舞会上扮演上述六种角色的六个人分别说了一句话表明现实身份，白雪公主：我比你们都小，请多多关照。巫婆：巫婆只能是女的，男的应当叫巫师，所以我是女的。佐罗：六个人的年龄从大到小排列，我是倒数第2 的，我不是丁。石头：我的网名是我妻子取的，因为她说我不浪漫，连木头都不如。哈利波特：虽然我年纪最大，但我还是有童心的。仙人掌：多刺的我终于能够在30 岁以前把自己嫁出去了，明天举行婚礼，欢迎大家来参加。如果他们说的都是真话，则不能推出的是（  ）","options":["白雪公主是丁","哈利波特是乙","佐罗是己","石头是丙"],"a":1,"e":"【答案】B\n【解析】分析推理。整理题干关系：①女性：甲、乙、戊，②男性：丙、丁、己，③\n超过30 周岁：乙、丙、戊，④未超过30 周岁：甲、丁、己；\n分析题干信息：由“仙人掌：我在30 岁以前把自己嫁出去了”，可知仙人掌是小于\n30 岁的女性，由①④可得：⑤仙人掌是甲；由“佐罗：我的年龄是倒数第2 的，且不是\n丁”和“白雪公主：我比你们都小，请多多关照。”及⑤、④可知：佐罗是己，白雪公主\n是丁。A、C 选项能推出；由“石头：我的网名是我妻子取的”可知：石头是男性，是②\n丙、丁、己三人之一，前面推知丁是白雪公主，己是佐罗可得：⑧石头是丙，D 选项能推\n出；巫婆和哈利波特在乙和戊之间，无法确定。\n故正确答案为B。"},{"q":"夏燕，贾枢和郑薇三个同学一起去旅游，为了照相方便，每个人拿的是同学的相机，背的是另一个同学的包。如果背着郑薇的包的人拿的是贾枢的相机，那么以下哪项为真（  ）","options":["贾枢拿的是郑薇的相机","郑薇拿的是贾枢的相机","郑薇背的是夏燕的包","贾枢背着郑薇的包"],"a":0,"e":"【答案】A\n【解析】分析推理。已知每个人拿的是同学的相机，背的是另一个同学的包。所以根\n据已知条件，背着郑薇的包的人拿的是贾枢的相机，可知这个人既不是贾枢也不是郑薇，\n那么只能是夏燕。那么贾枢背着夏燕的包，拿的是郑薇的相机，郑薇背着贾枢的包，拿着\n夏燕的相机。\n故正确答案为A。"},{"q":"某开发区发展委员会召开环境工作专题圆桌会议，参加会议的有委员会主任和副主任，以及委员会所属的开发区环保局、工业局和农业局的局长和副局长。他们八个人均匀地坐在一张会议圆桌旁，只有一个同部门的正职和副职的座位被分隔开了。并且：①委员会副主任对面的人是坐在环保局局长左边的一位局长；②工业局副局长左边的人是坐在农业局局长对面的一位副局长；③农业局局长右边的人是一位副局长，这位副局长坐在委员会主任左边第二个位置上的副局长的对面。则座位一定被隔开的是（  ）","options":["环保局的局长和副局长","工业局的局长和副局长","农业局的局长和副局长","委员会的主任和副主任"],"a":1,"e":"【答案】B\n【解析】分析推理。根据最大信息法，题干条件②③均提到了农业局局长，所以此题\n应该先排放农业局局长的位置，如下图a 所示，可以首先把农业局局长排在1 号座位，题\n干条件②提到了农业局局长，已知工业局副局长左边的人是坐在农业局局长对面的一位副\n局长，因此农业局局长对面的5 号位是一位副局长，且这位副局长在工业局副局长的左\n边，故工业局副局长在4 号位；\n题干条件③又提到了农业局局长，已知农业局局长右边的人是一位副局长，因此8 号\n位是一位副局长，又已知这位副局长坐在委员会主任左边第二个位置上的副局长的对面，\n如下图a 所示，8 号位副局长坐在4 号位的工业局副局长的对面，而4 号位工业局副局长\n坐在委员会主任左边第二个位置上，所以委员会主任坐在2 号位；\n根据条件①可知委员会副主任对面的人是坐在环保局局长左边的一位局长，如下图a\n所示，现在只剩下3、6、7 这三个空位，既然环保局局长左边要坐一位局长，所以环保局\n局长只能坐在6 号位，另一位局长坐在7 号位，即委员会副主任坐在3 号位；由下图b 可\n知，最后座位被隔开的是工业局的局长和副局长。\n故正确答案为B。"},{"q":"某单位要选拔人才下乡挂职。符合条件的人有甲、乙、丙、丁、戊、己，人事部门、组织部门和办公室分别提出了自己的要求：人事部门：丙、丁两人中只能去一人组织部门：若丁不去，则戊也不能去办公室：甲、丙和己三人必须留下一个由此可以推出，能够同时满足三个部门要求的派出方案是（  ）","options":["乙、丙、丁、戊","乙、丙、戊","甲、乙、丙、己","甲、乙、丙"],"a":3,"e":"【答案】D\n【解析】分析推理。根据第一句话丙、丁两人中只能去一人，A 项中，丙和丁都去\n了，排除A 项；根据第二句话，丁不去，则戊也不能去可以写成-丁→-戊，B 项中丁没去\n戊去了，排除B 项；根据第三句话甲、丙和己三人必须留下一个，C 项中甲、丙、己都去\n了，排除\nC 项；D 项符合题意，当选。\n故正确答案为D。"},{"q":"兄弟姐妹四人，甲，乙，丙，丁。甲说：丁是最小的妹妹。乙说：兄弟姐妹中只有哥哥一个是男孩。丙说：我是甲的姐姐。（  ）","options":["甲排行第二，是男孩；乙排行第三，是女孩","乙排行第二，是女孩；丙排行第一，是女孩","丙排行第二，是女孩；丁排行最小，是女孩","甲排行第二，是女孩；丙排行第一，是女孩"],"a":0,"e":"【答案】A\n【解析】分析推理。乙说：兄弟姐妹中只有哥哥一个男孩，说明丁是最小的。而丙是\n甲的姐姐，乙有一个哥哥说明，四个人的顺序从大到小依次为：丙（女）甲（男）乙\n（女）丁（女）。\n故正确答案为A。"},{"q":"某单位有南、北两个绿化区，拟在其中种植一些果树。员工们推荐了4 种果树备选：杏树、桃树、苹果、柿子。根据实际情况，还需满足以下3 项种植要求：（1）每区种植3种果树：（2）至少要在一个绿化区同时种植杏树和苹果；（3）种植桃树的绿化区也要种植柿子。下列选项中，一定错误的是（  ）","options":["两个区都种有桃树","两个区都种有苹果","只有一个区种有杏树","只有一个区种有苹果"],"a":0,"e":"【答案】A\n【解析】分析推理。采用排除法。题干要求每区种3 种果树，至少有一个区要同时种\n植杏和苹果，桃树和柿子树也要同时种植。将选项带入到题干之后发现，只有A 是错误\n的。A 选项两个区都种桃树，因此也要种柿子树。题干要求每区种植3 种果树，现在已经\n种植了桃树和柿子树，因此只能选杏树和苹果树的一种进行种植。如果满足题干第二个条\n件要求，则这个区就种植了4 种果树，与题干第一个条件矛盾。\n故正确答案为A。"}]},{"id":"zhenjia","name":"真假推理","items":[{"q":"某国承办了一次国际大赛，决定将赛事分配给该国的3 个城市具体筹办。现有甲、乙、丙、丁、戊、己、庚7 个候选城市通过了初选。根据要求，最终负责筹办的城市还需符合以下条件：（1）甲和乙要么都入选，要么都不入选；（2）丙与丁至多只能有一个入选；（3）丙和甲至少要有一个入选。如果戊入选，那么下列哪两个城市也可能同时入选（  ）","options":["甲和丙","甲和己","乙和丙","丙和己"],"a":3,"e":"【答案】D\n【解析】分析推理。已知戊入选，且只有3 个城市入选。由条件（1）可知，选项要\n么为甲和乙，要么为-甲和-乙，二者不能单独出现，只有D 项符合。\n故正确答案为D。\n第四节真假推理\n第一组："},{"q":"在索莱岛上，有四个草屋，每个草屋的门上挂着一块牌子。第一块牌子上写着：“有些草屋中没有食物。”第二块牌子上写着：“该草屋中没有猎枪。”第三块牌子上写着：“所有的草屋中都有食物。”第四块牌子上写着：“该草屋中有草药。”索莱岛上的游客发现，四块牌子中只有一块牌子上写着真话。由此可以推出（  ）","options":["四个草屋中都有草药","四个草屋中都有食物","第三个草屋中有猎枪","第四个草屋中没有草药"],"a":3,"e":"【答案】D\n【解析】真假推理。矛盾关系：有些草屋中没有食物与所有草屋中都有食物。题干中\n只有一块牌子上写着真话，矛盾关系必有一真一假，唯一的真话在矛盾关系中；看其余的\n论断可推出第二块牌子和第四块牌子上所写均为假话，所以，第四个草屋中没有草药。\n故正确答案为D。"},{"q":"小王、小张、小赵、小刘四人讨论比赛四强的甲、乙、丙、丁四个队伍哪个将获得冠军。小王：“乙是冠军。”小张：“冠军是丁或丙。”小赵：“冠军是甲或丁。”小刘：“甲和丙不是冠军。”结果出来后，只有两个人的推断是正确的，冠军是（  ）","options":["甲","乙","丙","丁"],"a":1,"e":"【答案】B\n【解析】真假推理。题干没有矛盾关系，代入选项。\nA 项，甲是冠军为真，可知小王、小张、小刘说错了，小赵说对了，只有一个猜对与\n题干条件矛盾，排除；\nB 项，乙是冠军为真，可知小王、小刘说对，两人猜对，符合题干要求，当选；\nC 项，丙是冠军为真，可知小王、小赵、小刘说错了，小张说对了，只有一个猜对与\n题干条件矛盾，排除；\nD 项，丁是冠军为真，可知小王说错，小张、小赵、小刘都说对了，三个人对与题干\n条件矛盾，排除。\n故正确答案为B。"},{"q":"甲说：如果考试不合格，就不能被录取。乙说：不对。李明考试合格了，但没有被录取。乙的回答说明他将甲的话错误地理解为（  ）","options":["有些被录取的人考试合格了","李明应该被录取","只要考试合格，就要被录取","并非所有考试合格的都要被录取"],"a":2,"e":"【答案】C\n【解析】真假推理。乙的回答是对甲的否定，否定乙的话就可以知道乙将甲的话理解\n成什么意思。乙：李明考试合格了，但没有被录取，可以翻译为：①合格且—录取，否定\n①，也就是与①矛盾，A 且—B 的矛盾是A→B，因此，乙将甲的话理解成：合格→录取。\n故正确答案为C。"},{"q":"甲、乙、丙、丁四人讨论本班同学完成作业的情况。甲说：班里所有同学都写完了作业。乙说：如果小李写完了作业，那么小赵就没有写完作业。丙说：小李写完了作业。丁说：班里有人没有写完作业。已知四人中只有一人说的不对，那么可推出下列哪项（  ）","options":["甲说的不对，小赵没有写完作业","乙说的不对，小李写完了作业","丙说的不对，小赵没有写完作业","丁说的不对，小赵写完了作业"],"a":0,"e":"【答案】A\n【解析】真假推理。矛盾关系：甲和丁为矛盾关系，必有一真一假，已知只有一个人\n说错了，乙和丙说的就是正确的，丙说小李写完了作业为真，乙说小李写完了小赵就没写\n完，肯前必肯后因此小赵没写完，因此甲说的是假话。\n故正确答案为A。"},{"q":"某慈善组织号召企业向受暴雨袭击的某地区捐赠帐篷。某地区为表谢意向该组织询问是哪些企业进行了捐赠。经调查，了解到以下情况：（1）四家企业都没有捐赠；（2）丁企业没有捐赠；（3）乙企业和丁企业至少有一家企业没有捐赠；（4）四家企业中确有企业捐赠。后来得知上述四种情况两种为真，两种为假。由此可以推出（  ）","options":["甲企业没有进行捐赠","乙企业进行了捐赠","丙企业没有进行捐赠","丁企业进行了捐赠"],"a":3,"e":"【答案】D\n【解析】真假推理。（1）和（4）互为矛盾关系，必有一真必有一假，已知四种情况\n有两真两假，故（2）和（3）也必有一真必有一假；当（2）丁企业没有捐赠为真时，可\n知（3）乙企业和丁企业至少有一家企业没有捐赠一定为真，（2）和（3）必须一真一\n假，不符合条件，因此条件（2）为假，它的矛盾为真，可推知丁企业捐赠了，D 项当\n选。\n故正确答案为D。"},{"q":"运动会长跑成绩公布后，小张说：“我的排名在前五名，小夏的名次不好，小王是最后过终点的。”小夏说：“我的长跑成绩一直都在这个水平，我紧跟着小王的后面跑过终点。”小王说：“小张和小夏的成绩都比我好。”三个人中最多一个人说假话。据此，可以推出（  ）","options":["小张说了假话","小夏说了假话","小王说了假话","三人都没说假话"],"a":1,"e":"【答案】B\n【解析】真假推理。题干中小张和小夏都说了小王的名次，小张：小王最后过终点\n（小王是倒数第一）；小夏：我紧跟着小王的后面跑过终点（小王不是倒数第一）；为矛\n盾关系，必有一真一假，题干给出信息，三个人最多一个人说假话。则剩余一个人，小王\n的话为真话：小张和小夏的成绩比我好；故小夏说的话为假话。\n故正确答案为B。"},{"q":"某机关拟在全民国防教育日举办专项国防教育活动。至于采用何种活动形式，组织者甲、乙、丙三人意见如下：甲：如果搞读书演讲、知识竞赛，那就不搞文艺演出和专题展览。乙：如果不搞文艺演出和专题展览，那就搞读书演讲、知识竞赛。丙：不搞读书演讲、知识竞赛。上述三人的意见只有一个人的意见与最后结果相符合，最后结果是（  ）","options":["搞读书演讲、知识竞赛，也搞文艺演出和专题展览","搞读书演讲、知识竞赛，不搞文艺演出和专题展览","搞文艺演出和专题展览，不搞读书演讲、知识竞赛","不搞读书演讲、知识竞赛，也不搞文艺演出和专题展览"],"a":0,"e":"【答案】A\n【解析】真假推理。翻译题干：甲：读书演讲和知识竞赛→－文艺演出和－专题展\n览；乙：－文艺演出和－专题展览→读书演讲和知识竞赛；丙：－读书演讲和－知识竞\n赛。甲、乙、丙只有一个为真。A 项只有乙为真；B 项甲、乙都为真；C 项甲、乙、丙都\n为真；D 项甲、丙都为真。\n故正确答案为A。"},{"q":"四个好朋友相约在孤岛进行野外生活体验一个月，随后他们对这次活动有如下对话：甲：我们四个都没有坚持一个月；乙：我们四个中有人坚持了一个月；丙：乙和丁至少有一人没有坚持一个月；丁：我没有坚持一个月。如果四个人中有两人说的是真话，两人说的是假话，则下列说法正确的是（  ）","options":["说真话的是甲和丁","说真话的是乙和丙","说真话的是甲和丙","说真话的是乙和丁"],"a":1,"e":"【答案】B\n【解析】真假推理。甲乙为矛盾关系，存在一真一假，题干规定有两真两假，所以丙\n丁也为一真一假。假设丁说的是真话，则丙的话也为真话（或关系一真即真），这与题干\n不符，所以丁说的一定为假话，丁坚持了一个月。说明有的人坚持了，那乙说的也是真\n话，所以，说真话的是乙和丙。\n故正确答案为B。"},{"q":"四位球迷在某球赛的晋级赛开始之前对几个队伍的赛况进行预测，他们比较关注其中的两支球队，分别作了如下预测：方某说：如果甲队不能晋级，那么乙队也不能晋级。白某说：不管甲队能不能晋级，乙队都不能晋级。夏某说：乙队能晋级，但甲队不能晋级。邓某说：我看这几支球队都不能晋级。比赛结果证明，四位球迷中只有一位的预测是正确的。根据上述情况，以下哪项一定为真（  ）","options":["白某预测是正确的","邓某预测是正确的","如果甲队能够晋级，那么方某的预测是正确的","如果甲队不能晋级，那么方某的预测是正确的"],"a":2,"e":"【答案】C\n【解析】翻译式：\n（1）方：—甲→—乙；白：—乙；夏：—甲且乙；邓：所有人不能晋级。\n（2）“—甲→—乙”与“—甲且乙”为矛盾关系，必然一句为真，一句为假；所以\n白某和邓某所说必然为假；得到“乙晋级”和“有的人晋级了”；排除A 项和B 项；\n（3）代入C 项，如果甲某晋级，夏某所说必然为假，只能方某为真；正确\n（4）代入D 项如果甲某不晋级，夏某所说为真，方某所说为假，D 项错误，排除。\n故正确答案为C。"}]},{"id":"jiegou","name":"结构评价","items":[{"q":"甲、乙、丙、丁四人驾车外出，遇到交警排查酒驾，四人因司机酒后驾车害怕受到惩罚而弃车逃跑，很快被交警擒获。当询问谁是驾驶员时，甲说：“不是我。”乙说：“是甲。”丙说：“不是我。”丁说：“是乙。”若四人中有且仅有两人说了假话，那么谁一定说了假话（  ）","options":["甲","乙","丙","丁"],"a":3,"e":"【答案】D\n【解析】真假推理。题干关系：①甲：－甲；②乙：甲；③丙：－丙；④丁：乙。\n①和②构成矛盾关系，根据矛盾关系的特性“必有一真，必有一假”及题干的真假限\n定“四人中有且仅有两人说了假话”，可知丙和丁中必有一真，必有一假。假设丙说假\n话，丁说真话，可得：丙是驾驶员，乙也是驾驶员，因驾驶员只能有一人，所以此种情况\n不成立。所以丙说真话，丁说假话，可得：丙不是驾驶员，乙不是驾驶员，则驾驶员要么\n是甲，要么是丁，符合题干。因为提问方式中问的是“一定”说假话的人，综上所述，丁\n一定说假话。\n故正确答案为D。\n第五节结构评价\n第一组："},{"q":"只有巧干加实干，才能创造出惊人的业绩。某公司的业务经理取得了非凡的业绩，可见该业务经理实践了巧干加实干。下列哪个推理结构与上述推理在形式上是相同的（  ）","options":["如果一个人犯了罪，那么他就会受到刑事处罚。张某受到了刑事处罚，可见张某犯了罪","这种植物只有开花，才能结出果实。今年这种植物没有开花，所以不会结出果实","只有通过全国统一司法考试的人，才能从事律师职业。小李从事律师职业，所以小李已通过全国统一司法考试","只有在特定的土质和气候条件下，这种葡萄才能获得好收成。现在这种葡萄没有获得好收成，说明这里没有这种特质的土质和气候条件"],"a":2,"e":"【答案】C\n【解析】结构评价，分别设“巧干加实干”为a，“惊人的业绩”为b，“某公司业\n务经理”为c，其推理形式为：b→a，c→b，可见c→a。\nA 项，“一个人犯了罪”为a，“受到刑事处罚”为b，“张某”为c，其推理形式\n为：a→b，c→b，可见c→a，与题干推理形式不同，排除；\nB 项，“开花”为a，“结果”为b，“没有开花”为-a，“不会结果”为-b，其推理\n形式为：b→a，-a→-b，与题干推理形式不同，排除；\nC 项，“通过司法考试”为a，“从事律师职业”为b，“小李”为c，其推理形式\n为：b→a，c→b，所以c→a，与题干推理形式相同，当选；\nD 项，“土质和气候条件”为a，“好收成”为b，“没有好收成”为-b，“没有土\n质和气候”为-a，其推理形式为：b→a，-b→-a，与题干推理形式不同，排除。\n故正确答案为C。"},{"q":"所有聪明人都是近视眼，我近视得很厉害，所以，我很聪明。以下哪项最能揭示上述推理的错误（  ）","options":["我是个笨人，因为所有的聪明人都是近视眼，而我的视力很好","所有的羊都有四条腿，但这种动物有八条腿，所以它不是羊","马是四蹄食草动物，牛是四蹄食草动物，所以，牛是马","所有的天才都高度近视，我一定是高度近视，因为我是天才"],"a":2,"e":"【答案】C\n【解析】结构评价。分别设“所有聪明人”为a，“近视眼”为b，“我”为c，则\n其推理形式为：a→b，c→b，所以c→a。\nA 项，分别设“所有聪明人”为a，“近视眼”为b，“我”为c，则其推理形式为：\na→b，c→-b，所以c→-a。与题干推理形式不同，排除；\nB 项，分别设“羊”为a，“四条腿”为b，“这种动物”为c，则其推理形式为：a\n→b，c→-b，所以c→-a。与题干推理形式不同，排除；\nC 项，分别设“马”为a，“四蹄食草动物”为b，“牛”为c，则其推理形式为：a\n→b，c→b，所以c→a。与题干推理形式相同，当选；\nD 项，分别设“天才”为a，“高度近视”为b，“我”为c，则其推理形式为：a→\nb，c→a，所以c→b。与题干推理形式不同，排除。\n故正确答案为C。"},{"q":"人的认识能力是无限的，张某是人，因此，张某的认识能力是无限的。以下哪项的逻辑错误与上述推理的错误最为相似（  ）","options":["人是宇宙间最宝贵的，我是人，因此，我是宇宙间最宝贵的","人贵有自知之明，你没有自知之明，因此你不是人","干部应起带头作用，我不是干部，所以我不应起带头作用","干部应为人民服务，我是干部，所以，我应为人民服务"],"a":0,"e":"【答案】A\n【解析】结构评价。分别设“人”为a，“认识能力是无限的”为b，“张某”为\nc，则其推理形式为：a 是b，c 是a，因此，c 是b。且“人的认识能力是无限的”中的\n“人”指的是集合意义上的“人”，如“人类”，而“张某是人”中的“人”指的是个体\n意义上的“人”，二者不同。\nA 项，分别设“人”为a，“宇宙间最宝贵的”为b，“我”为c，则其推理形式为：\na 是b，c 是a，因此，c 是b，与题干推理形式相同，且“人是宇宙间最宝贵的”中的\n“人”是集合概念，“我是人”中的“人”为个体意义上的概念，与题干推理形式相同，\n当选；\nB 项，分别设“人”为a，“有自知之明”为b，“你”为c，则其推理形式为：a 是\nb，c 是-b，因此c 是-a，与题干推理形式不同，排除；\nC 项，分别设“干部”为a，“起带头作用”为b，“我”为c，则其推理形式为：a\n是b，c 是-a，所以c 是-b，与题干推理形式不同，排除；\nD 项，分别设“干部”为a，“为人民服务”为b，“我”为c，则其推理形式为：a\n是b，c 是a，所以，c 是b，与题干推理形式相同，但两个干部均指个体意义概念，排\n除。\n故正确答案为A。"},{"q":"如果电用完了，电动自行车就无法继续前行。我的电动自行车不能继续前行，因此，电一定用完了。以下哪项推理与题干的最为类似（  ）","options":["如果姚明上场，中国队就一定能赢。中国队输了，所以，姚明肯定没上场","所有的条件我都可以接受，除非它明显不公平。这个条件我不能接受，因此，它明显不公平","如果晓莉努力学习，考试成绩就会很好。晓莉考试成绩不好，所以，晓莉没有努力学习","如果小美去过香港，她一定会购买高档化妆品。小美购买了高档化妆品，所以，小美去过香港"],"a":3,"e":"【答案】D\n【解析】结构评价。A（电用完）→B（不能前行），B（不能前行）→A（电用\n完），\n肯后推肯前的推理形式。\nA 项，A（姚上场）→B（赢），-B（-赢）→-A（-姚上场），否后推否前，与题干推\n理形式不同，排除；\nB 项，A（-接受）→B（-公平），A（-接受）→B（-公平），肯前推肯后，与题干推\n理形式不同，排除；\nC 项，A（努力学习）→B（成绩好），-B（-成绩好）→-A（-努力学习），否后推否\n前，与题干推理形式不同，排除；\nD 项，A（去过香港）→B（买化妆品），B（买化妆品）→A（去过香港），肯后推肯\n前，与题干推理形式相同，符合，当选。\n故正确答案为D。"},{"q":"大学生在大学里要学习很多知识，小王是一名大学生，所以他学习了很多的知识。以下哪项论证展示的推理错误与上述论证中的最相似（  ）","options":["水果中含有各种丰富的维生素，苹果是一种水果，所以苹果中含有丰富的维生素","所有的老员工都是优秀的，李刚是新来的员工，所以李刚不是优秀员工","某高校学报的编辑不但要组织和编辑稿件，自己也写了许多学术方面的文章，老郑是该学报的一名编辑，所以他也写过许多学术方面的文章","这所大学的有些学生学习成绩很好，小赵是这所大学的一名学生，所以她的学习成绩很好"],"a":0,"e":"【答案】A\n【解析】结构评价。A（大学生）→B（学习很多知识），C（小王）→A（大学\n生），\n所以C（小王）→B（学习了很多知识）。\nA 项，A→B，C→A，所以C→B，与题干推理形式相同，当选；\nB 项，A→B，C→-A，所以C→-B，与题干推理形式不同，排除；\nC 项，A→B 且D，C→A，所以C→D。与题干推理形式不同，排除；\nD 项，有的A 是B，C→A，所以C→B。与题干推理形式不同，排除。\n故正确答案为A。"},{"q":"狗不嫌家贫，子不嫌母丑。爱自己家乡的人不会说家乡的坏话，张三就从不说家乡的坏话。可见，他是一个多么爱自己家乡的人啊！以下哪项的推理方式与上述最为相似（  ）","options":["灯不挑不亮，话不挑不明。如果没有听到张处长这番话，我还在纠结要不要报名参加行业大赛，现在一切都清楚了。看来，张处长的话太重要了","不入虎穴，焉得虎子？巨大的成功往往伴随着巨大的风险，李四投资股票获得高额回报。可见他承担了多大的风险啊","玉不琢不成器，人不学要落后。追求进步的人不会不爱学习的，王教授退休后一直无所事事，不爱学习。可见，王教授已不是一个追求进步的人了","人不可貌相，海水不可斗量。一个有才能的人不会将他的才能显示出来，李先生就从来没有显示过他的才能。可见，他是一个多么有才能的人啊"],"a":3,"e":"【答案】D\n【解析】结构评价。题干可以翻译为：爱自己家乡→不说家乡的坏话。题干推理为：\n“张三不说家乡的坏话”属于“肯后”，“他是热爱家乡的人”属于“肯前”，即推理过\n程为“肯后推肯前”。\nA 项，翻译为：没有听到张处长的话→还在纠结，“现在一切都清楚了”即“不纠\n结”，属于“否后”，与题干推理形式不同，排除；\nB 项，翻译为：巨大的成功→巨大的风险，“李四投资股票获得成功”属于“肯\n前”，“承担多大风险”属于“肯后”，与题干推理形式不同，排除；\nC 项，翻译为：追求进步的人→爱学习，“王教授退休后不爱学习”属于“否后”，\n“他不是追求进步的人”属于“否前”，与题干推理形式不同，排除；\nD 项，翻译为：有才能的人→不会将才能显示出来，“李先生没有显示过才能”属于\n“肯后”，“他是一个多么有才能的人”属于“肯前”，即推理过程为“肯后推肯前”，\n与题干推理形式相同，当选。\n故正确答案为D。"},{"q":"在全球范围内，所有的大城市的生活成本都比较高，上海是一座大城市，因此上海的生活成本比较高。以下哪项与上述论证方式不一样（  ）","options":["要进入法院工作必须要通过国家司法考试，小王在法院工作，因此小王已经通过了国家司法考试","某高校的硕士研究生只要通过毕业论文答辩就能获得硕士学位，小张今年获得了硕士学位，因此他通过了毕业论文答辩","纵观世界历史，每一位杰出的国家领导人无不有着坚强的意志，华盛顿是一位杰出的国家领导人，因此他拥有着坚强的意志","城镇职工养老保险只要按规定缴费满15 年就能在退休后按月领取养老金，李先生已按规定缴满20 年的养老保险，因此他在退休后能按月领取养老金"],"a":1,"e":"【答案】B\n【解析】结构评价。题干结构为：所有A 都是B，C 是A，所以C 是B。\nA 项，结构为所有A 都是B，C 是A，所以C 是B，与题干结构一致，排除；\nB 项，结构为所有A 都是B，C 是B，所以C 是A，与题干结构不一致，当选；\nC 项，结构为所有A 都是B，C 是A，所以C 是B，与题干结构一致，排除；\nD 项，结构为所有A 都是B，C 是A，所以C 是B，与题干结构一致，排除。\n故正确答案为B。"},{"q":"历史上的诗人都能喝酒，李白能喝酒，所以李白是诗人。以下选项所犯逻辑错误与题干最为类似的是（  ）","options":["所有信仰上帝的人都会被拯救，马三不信任上帝，因此，马三不会被拯救","有些素食主义者活得比平均年龄长，王五是素食主义者，因此，王五将活得比平均年龄长","英雄都难过美人关，李四难过美人关，因此，李四是英雄","有些男人比大多数女人都聪明，安德鲁是男人，因此，安德鲁比大多数女人都聪明"],"a":2,"e":"【答案】C\n【解析】结构评价。题干结构为：所有A 都是B，C 是B，所以C 是A。\nA 项，结构为所有A 都是B，C 是-A，所以C 是-B，与题干结构不一致，排除；\nB 项，题干为所有，选项为有的，结构与题干不相符，排除；\nC 项，结构为所有A 都是B，C 是B，所以C 是A，与题干结构一致，当选；\nD 项，题干为所有，选项为有的，结构与题干不相符，排除。\n故正确答案为C。"},{"q":"某刑事人类学家在对260 名杀人犯的外貌进行了考察后，发现他们具有一些共同的生理特征，于是得出“杀人犯具有广颚、颧骨突出、头发黑而短的特征”的结论。以下哪项与上述推理方式相同（  ）","options":["24—28 之间没有质数","八月十五云遮月，正月十五雪打灯","植物种子经超声波处理后可增产，所以玉米种子经超声波处理后也可增产","某高校在对全校学生进行调查后，得出“我校同学学习态度普遍较好”的结论"],"a":1,"e":"【答案】B\n【解析】结构评价题。题干中根据260 名杀人犯的外貌得出了所有杀人犯具有的特\n征，是根据部分推导出整体的结论。\nA 项，24~28 一共五个数字，其中没有质数，是我们可以直接数出来的，是整体推出\n整体；\nB 项，“八月十五”会阴天“正月十五”会下雪，这里的八月十五与正月十五肯定不\n是全部，属于部分推出了整体，当选；\nC 项，植物种子对于玉米种子是整体推出部分，不符合题干，排除；\nD 项，对全校学生进行调查得出的结论，是整体推出整体，排除。\n故正确答案为B。"}]},{"id":"yuanyin","name":"原因解释","items":[{"q":"所有狗是动物，所有猪是动物，因此所有狗是猪。以下与题干所犯的逻辑错误相同的是（  ）","options":["所有猪都是象，有些猫是鸟，所以有些猫是象","所有树都是动物，所有熊都是动物，所以所有熊都是树","所有鲨鱼都是鸟，所有鸟是政治家，所有鲨鱼是政治家","所有叔叔是男性，克里斯是叔叔，所以克里斯是男性"],"a":1,"e":"【答案】B\n【解析】结构评价。题干结构为：A 是B，C 是B，所以A 是C。\nA 项，结构为：A 是B，有些C 是D，所以有些C 是A，与题干结构不同，排除；\nB 项，结构为：A 是B，C 是B，所以C 是A，与题干结构相同，当选；\nC 项，结构为：A 是B，B 是C，所以A 是C，与题干结构不同，排除；\nD 项，结构为：A 是B，C 是A，所以C 是B，与题干结构不同，排除。\n故正确答案为B。\n第六节原因解释\n第一组："},{"q":"近年来，国家从药品生产、流通和销售各环节发力，频频出台降低药价的相关政策。但是，让不少患者感到疑惑的是，一方面是国家降低药价的政策不断出台，另一方面却是诸多常用药价格不断上涨。以下哪项如果为真，最能解释上述现象（  ）","options":["价格下降的药品占大多数，价格上涨的药品占少数，因此从整体上来说，药品价格仍然是下降了","常用进口药的需求增多，相关政策无法控制此类药品的价格上涨","国家虽然出台了降低药价的政策，但是其影响要经过一段时间才能显现出来","降低药价的政策可以有效控制药品市场中因制药原料涨价而导致的药价上涨"],"a":1,"e":"【答案】B\n【解析】原因解释。题干矛盾为：国家降低药价的政策不断出台和诸多常用药价格不\n断上涨。\nA 项，“价格上涨的药品占少数”说明还是有药品价格上涨了，但是没有解释这一部\n分药品价格上涨的原因，不能解释，排除；\nB 项，说明上涨的药品是进口药品，国家出台的政策无法控制这一类药物的价格，可\n以解释，当选；\nC 项，“影响要过一段时间才能显现出来”，只能说明现在价格可能不会下降，但无\n法解释现在药品价格上涨的原因，不能解释，排除；\nD 项，国家出台的政策可以控制市场中因制药原料涨价而导致的药价上涨，说明药价\n总体还是要下降的，不能解释药价上涨的原因，不能解释，排除。\n故正确答案为B。"},{"q":"有一段时间，电视机生产行业竞争激烈。由于电视机品牌众多，产品质量成为消费者考虑的首要因素。某电视机生产厂家为了扩大市场份额，一方面加大研发力度，进一步提高了电视机产品的质量；另一方面在价格上作调整，适当降低了产品的价格。然而，调整之后的头三个月，其电视机产品的市场份额不但没有提高反而有所下降。以下哪项如果为真，最能解释上述现象（  ）","options":["消费者通常会考虑不同产品的价格差异，而非同一产品在不同时期的价格差异","一个家庭再次购买电视机产品时会首先考虑原来的品牌","消费者通常是通过价格来衡量电视机产品质量的","其他电视机生产厂家也调整了产品价格"],"a":2,"e":"【答案】C\n【解析】原因解释。题干矛盾为：提高了电视机产品的质量；降低了产品的价格，市\n场份额反而下降。优选体现矛盾双方的选项。\nA 项，消费者通常会考虑不同产品的价格差异，厂商降低了产品的价格，市场份额应\n该相应增多，与题干现象相反，不能解释，排除；\nB 项，消费者会再次购买原先的品牌，和质量、价格无关，可造成的现象仅为市场份\n额不变，无法解释份额减少，排除；\nC 项，厂商降低产品价格会使消费者认为产品质量下降，而不购买产品，导致市场份\n额下降，可以解释现象，当选；\nD 项，其他厂商也调整了产品价格，造成影响不可知，无法解释，排除。\n故正确答案为C。"},{"q":"所有的幼儿园都面临同一个问题：就是对于那些在幼儿园放学之后不能及时来接孩子的家长，幼儿园老师除了等待别无他法，因此许多幼儿园都向晚接孩子的家长收取费用。然而，有调查显示，收取费用后晚接孩子的家长数量并未因此减少，反而增加了。以下哪项如果为真，最能解释上述调查结果（  ）","options":["收费标准太低，对原本经常晚来接孩子的家长没有太大的约束力","有个别家长对收费行为不满，有时会故意以晚接孩子的行为来抗议","有些家长因工作忙碌，常常不能及时来接孩子","收费后，更多的家长认为即使晚来接孩子也不必愧疚，只要付费即可"],"a":3,"e":"【答案】D\n【解析】原因解释。题干矛盾为：通过收取费用的方式让家长早接孩子，但是收费后\n晚接孩子的家长数量不减反增。\nA 项，收费低对原本晚接孩子的家长无影响，可以解释为什么人数没有减少，但是无\n法解释为什么人数增加，不能解释题干矛盾，排除；\nB 项，该项说的是个别家长抗议收费而晚来接孩子，“个别”无法解释清楚为什么晚\n接孩子的家长数增加了，不能解释题干矛盾，排除；\nC 项，该项解释了家长晚来接孩子的原因，与题干幼儿园收费后晚接孩子的家长数量\n不减反增无关，不能解释题干矛盾，排除；\nD 项，该项说明幼儿园对晚接孩子进行收费后，将这种行为合理化，更多的家长心安\n理得的晚来接孩子，可以解释为什么晚接孩子的人不减反增，当选。\n故正确答案为D。"},{"q":"S 市规定，适龄儿童须接种麻疹疫苗，适龄儿童必须接受义务教育，下图表示：1990 年到2010 年间S 市儿童数量的一些统计，其中M 表示接受义务教育的儿童总数，N 表示新生儿总数，P 表示接种麻疹疫苗的儿童总数。下面哪一项最能解释2000 年到2010 年间S 市接受义务教育的儿童总数与接种麻疹疫苗的儿童总数下降程度的不同（  ）","options":["2000 年至2010 年间，有部分在S 市接种麻疹疫苗的儿童没有在S 市入学","2000 年至2010 年间，约有20%的父母没有按照S 市的规定让他们的孩子接种麻疹疫苗","2000 年至2010 年间，每年都有不在S 市出生但已接种了麻疹疫苗的儿童在S 市入学","2000 年至2010 年间，S 市新生儿总数下降，因此入学儿童总数和接种麻疹疫苗的儿童总数也随之下降"],"a":2,"e":"【答案】C\n【解析】原因解释。题干矛盾为：就人数下降的数量而言，M 是下降幅度最小的，N\n是\n下降幅度最大的，P 介于两者中间。\nA 项，如果在S 市接种麻疹疫苗的儿童没有在S 市入学，那么M 的下降幅度应该大于\nP 才对，这与图不符，排除；\nB 项，接受义务教育的儿童中有些不在S 市出生，跟S 市的父母有没有按规定给自己\n的孩子接种麻疹疫苗没有关系，不能通过20%的父母没有让孩子接种疫苗来解释，排除；\nC 项，接受义务教育的儿童中，有些没有在S 市接种疫苗，因此接受义务教育的儿童\n数量要多于接种麻疹疫苗的儿童数量，使M 曲线的下降程度小于P 曲线，可以解释，当\n选；\nD 项，无法解释P 和M 下降幅度不同的原因，排除。\n故正确答案为C。"},{"q":"研究发现，如果开饭时间晚了几分钟，人类的婴儿就会大声哭叫，而对于3、4 个月大的企鹅幼崽来说，它们却异常平静。在小企鹅的父母外出觅食时，它们甚至要适应长达几天没有食物的困境。以下哪项如果为真，能够解释这一现象（  ）","options":["3、4 个月大的企鹅消化系统并未发育健全，因此它们的食量相对较小","当雌企鹅去觅食时，雄性企鹅会用胃内的分泌物喂食幼崽","大企鹅外出时，小企鹅常会在夜间聚在一起互相取暖","当大企鹅不在时，小企鹅的叫声会引来天敌"],"a":3,"e":"【答案】D\n【解析】原因解释。矛盾在于：开饭时间晚了几分钟，人类的婴儿就会大声哭叫，对\n于三四个月大的企鹅幼崽来说，它们却异常平静。\nA 项，3、4 个月大的企鹅消化系统发育健全与否并不能解释小企鹅异常平静这一现\n象，排除；\nB 项，题干中提到在小企鹅的父母外出觅食时，它们甚至要适应长达几天没有食物的\n困境，雄性企鹅喂食幼崽与题干矛盾，排除；\nC 项，小企鹅常会在夜间聚在一起互相取暖没有涉及小企鹅异常平静，同样不能解释\n这一现象，排除；\nD 项，小企鹅的叫声会引来天敌，因此不敢叫，异常平静，可以解释这一现象，当\n选。\n故正确答案为D。"},{"q":"某国政府在半年内两次宣布降低购房按揭贷款的利率，因此很多潜在的购房者都处于持币待购的状态，进一步观望利率能否再探新低，所以六月份新建房屋的销售量大幅下降。但是，一个值得关注的现象是，在新建房屋销售量大幅下降的同时，新建房屋销售的平均价格却在快速上涨。以下哪项如果为真，能解释这一矛盾现象（  ）","options":["新建高价房处于热销中，价格一路上涨，因为高价房的购买者基本不受利率波动的影响","受利率波动的影响，已购房者惜售手中的房屋，造成二手房的供应量不足","过去三年中，由于住房供应短缺的问题越来越严重，使得新建房屋的销售量一直在缓慢上涨","受国际市场的影响，一年来该国建筑材料价格不断波动"],"a":0,"e":"【答案】A\n【解析】原因解释。题干矛盾：新建房屋销售量大幅下降的同时，新建房屋销售的平\n均价格却在快速上涨。\nA 项，因为高价房的购买者基本不受利率波动的影响，所以新建高价房处于热销中，\n价格一路上涨，相应的低价房销售量下降，导致总体平均价格快速上涨，可以解释题干矛\n盾，当选；\nB 项，二手房供应量是否充足都与新建房屋的平均价格无关，不能解释题干矛盾，排\n除；\nC 项，题干没有提到总体销售量与平均价格的关系，所以通过新建房屋销售量的变化\n不能确定平均价格的变化趋势，不能解释题干矛盾，排除；\nD 项，建筑材料价格波动即价格有升有降，对新建房屋的价格造成什么影响不明确，\n不能解释题干矛盾，排除。\n故正确答案为A。"},{"q":"一般来说，幼儿的体温因阳光照射而上升的幅度比成人小。可是人们发现，在汽车车厢内，如果温度较高，幼儿很容易发生中暑，而成人几乎很少出现这一现象。甚至在45℃的高温环境下待在车厢里一小时，也不会中暑。以下哪项如果为真，最能解释上述发现（  ）","options":["在0—3 岁的幼儿中，年龄越小的孩子，抵抗能力越弱","随着年龄的增长，人体内的水分占体液总量的比例变小，体温的变化也不再明显","车内属于密闭空间，当室外气温达到25~29℃时，车内温度就能达到45℃，而成人在车内感到不适时很可能会打开车窗","中暑多在丧失了相当于体重3%的水分时发生，幼儿体重相对应的体表面积更大，能更快地吸收热量，由于汗腺数目与大人相同，水分流失速度更快"],"a":3,"e":"【答案】D\n【解析】原因解释。题干矛盾为：幼儿的体温因阳光照射而上升的幅度比成人小，但\n是在汽车车厢内，如果温度较高，幼儿很容易发生中暑，成人不会。\nA 项，说的是幼儿抵抗力弱，但是幼儿的体温上升的幅度比成人小，还是无法解释为\n什么幼儿比成人更容易中暑，排除；\nB 项，说的是随着年龄的增长而体温变化不明显，但还是无法解释在密闭的车厢内幼\n儿会中暑，排除；\nC 项，讨论的是成人感到不适会开窗，但是题干在45℃的高温环境下待在车厢里一小\n时，还是无法解释，排除；\nD 项，指出幼儿体重相对应的体表面积更大，能更快地吸收热量，水分流失速度更\n快，解释了幼儿的体温上升幅度比成人小，也更容易中暑的现象，当选。\n故正确答案为D。"},{"q":"研究表明，适当休息可以提高工作效率。当完成一项复杂艰巨的任务时，人们可以适当休息一下，做点简单的其他事情，之后继续工作，这可以让工作业绩提高40%。一家公司老总将这一理论应用于公司，增加了员工休息时间，但生产业绩却没有上升，反而明显下降。以下哪项如果为真，最能解释上述矛盾现象（  ）","options":["公司的有些部门并没有严格执行老总的休息计划","一些员工在休息的时候想工作，工作的时候想休息","近段时间公司的销售业绩不佳，没有出现明显的增长","公司生产都是流水线作业，员工做的都是单一机械动作"],"a":3,"e":"【答案】D\n【解析】原因解释。题干分析：一家公司老总将这一理论应用于公司，增加了员工休\n息时间，但生产业绩却没有上升，反而明显下降。\nA 项，公司的有些部门并没有严格执行老总的休息计划不能够解释生产业绩却没有上\n升，反而明显下降，排除；\nB 项，一些员工在休息的时候想工作，工作的时候想休息不能够解释生产业绩却没有\n上升，反而明显下降，排除；\nC 项，公司的销售业绩不佳并没有说明休息时间与业绩之间的关系，排除；\nD 项，公司生产都是流水线作业，员工做的都是单一机械动作，题干中所说完成复杂\n的任务与简单的任务休息时间不同，不符合题干的前提，故能够解释题干矛盾的原因，当\n选。\n故正确答案为D。"},{"q":"睡眠监测软件靠谱吗？一款监测睡眠的手机APP，下载后将手机塞在枕头下，早晨醒来，软件就会自动统计数据，全面反馈使用者一夜的睡眠情况。但结果显示，这款睡眠监测软件是没法实现睡眠的准确监测和判断的。以下哪项如果为真，最不能解释上述矛盾现象（  ）","options":["对于90％以上的原发性失眠患者而言，调整睡眠的核心应在于心理","使用睡眠软件时会不自觉地用手机上网聊天，导致过度兴奋睡不着","使用睡眠软件会把正常睡眠中的定时翻身计入浅睡眠或者觉醒时间","手机的光亮会刺激眼睛，影响软件使用者大脑内褪黑素的分泌情况"],"a":0,"e":"【答案】A\n【解析】原因解释，选非题。\n题干矛盾：一款监测睡眠的手机APP 能全面反馈使用者一夜的睡眠情况，但是这款睡\n眠监测软件是没法实现睡眠的准确监测和判断的。\nA 项，说的是调整睡眠的核心在于心理，不涉及软件为何不能准确监测睡眠，与题干\n矛盾无关，无法解释，当选；\nB 项，使用睡眠软件时会不自觉用手机上网聊天导致过度兴奋睡不着，而此时软件已\n经开始进行监测，那么软件就不能对睡眠进行准确检测和判断，可以解释，排除；\nC 项，睡眠软件会把正常睡眠中的翻身计入浅睡眠或者觉醒时间，说明软件虽然可以\n记录数据，但是不能对睡眠进行准确检测和判断，可以解释，排除；\nD 项，手机的光亮会刺激眼睛，并且会影响使用者大脑褪黑素的分泌情况，而褪黑素\n是影响睡眠的一种物质，从而使得软件不能对睡眠进行准确检测和判断，可以解释，排\n除。\n故正确答案为A。"}]},{"id":"guina","name":"归纳推理","items":[{"q":"美国研究人员分析了南极半岛和邻近的斯科舍海地区的实地数据后发现，20 世纪70 年代以来，当地气温上升了5 至6 摄氏度，并且来自其他海域的哺乳动物增多导致南极哺乳动物捕食竞争加剧。因此，在上述地区作为哺乳动物主要食物来源的磷虾的密度降低了80%。而同一时期，生活在该地区以磷虾为主食的阿德利企鹅和帽带企鹅的数量也急剧减少。由此可以推出（  ）","options":["气温上升造成了南极海洋哺乳动物捕食的竞争加剧","如果磷虾的密度继续减少，阿德利企鹅和帽带企鹅都会灭绝","气候变暖和哺乳动物的捕食竞争加剧威胁了帽带企鹅的生存","气温上升对南极地区生态环境的破坏极大"],"a":2,"e":"【答案】C\n【解析】归纳推理题。\nA 项，气温上升只是造成南极动物捕食竞争加剧的原因之一，排除；\nB 项，文段只说企鹅的数量急剧减少，“灭绝”夸大事实，排除；\nC 项，与文段第一句表述一致，当选；\nD 项，对于南极地区生态环境破坏文段中没有涉及，无中生有，排除。\n故正确答案为C。"},{"q":"调查显示，中国消费者对奢侈品品牌的忠诚度远远低于西方消费者，对许多中国消费者而言，高价格仍然很重要，物有所值仍然比品牌重要，而且现阶段甚至比质量还重要。由此可以推出（  ）","options":["中国消费者购买奢侈品时往往不会考虑价格因素","中国消费者喜欢购买价格高且物有所值的奢侈品","比起知名度来，奢侈品的价格更吸引中国消费者","中国消费者不甚关注知名奢侈品的价格及其质量"],"a":1,"e":"【答案】B\n【解析】归纳推理。\nA 项，由文段“高价格仍然很重要”可知，消费者考虑价格因素，排除；\nB 项，由文段“高价格仍然很重要，物有所值仍然比品牌重要”可知，消费者喜欢购\n买价格高且物有所值的奢侈品，当选；\nC 项，文段并没有将“知名度”与“奢侈品价格”放一起比较，无中生有，排除；\nD 项，由文段“高价格仍然很重要”可知，消费者关注价格，排除。\n故正确答案为B。"},{"q":"研究小组利用超级计算机模拟宇宙，并结合多种其他计算，证明了在我们这个加速膨胀的宇宙中，描述大尺度时空结构的因果关系网络曲线图，是一个具有显著聚类特征的幂函数曲线，和许多复杂网络如互联网、社交网、生物网络等惊人的相似。由此可以推出（  ）","options":["人脑研究有助于了解宇宙的结构","宇宙就是一个大脑或一台计算机","宇宙万物的演化遵循同样的规律","复杂系统演化存在某种相似法则"],"a":3,"e":"【答案】D\n【解析】归纳推理。\nA 项，“人脑研究”文段并没有提到，无中生有，排除；\nB 项，“就是”过于绝对，文段没提到，排除；\nC 项，“遵循同样的规律”文段没提到，无中生有，排除；\nD 项，由文段“和许多复杂网络如互联网、社交网、生物网络等惊人的相似”可知，\n“复杂系统演化存在某种相似法则”正确，当选。\n故正确答案为D。"},{"q":"在防治癌症方面，橙汁有多种潜在的积极作用，尤其由于它富含橙皮素和柚苷素等类黄酮抗氧化剂。研究证据已经表明，橙汁可以减少儿童患白血病的风险，并有助于预防乳腺癌、肝癌和结肠癌。根据研究结果，橙汁的生物效应在很大程度上受到其成分的影响，而其成分的变化又依赖于气候、土壤、水果成熟度以及采摘后的存储方法等条件。由此可以推出（  ）","options":["并非所有的橙汁都有相同的防癌功效","过度饮用橙汁会给身体健康造成不良影响","相对于健康儿童而言，白血病患儿的橙汁饮用量较小","生长于良好的气候土壤条件下，成熟并避光保存的橙子最有功效"],"a":0,"e":"【答案】A\n【解析】归纳推理。\nA 项，由“橙汁的生物效应在很大程度上受到其成分的影响，而其成分的变化又依赖\n于气候、土壤、水果成熟度以及采摘后的存储方法等条件。”可知橙汁的生物效应不同，\n可推出防癌效果也不同，当选；\nB 项，文段没有提到“过度饮用橙汁”的影响，排除；\nC 项，原文提到“橙汁可以减少儿童患白血病的风险”但对于健康儿童与白血病患儿\n橙汁的饮用量没有进行对比，排除；\nD 项，原文只说橙汁的生物效应受气候、土壤、水果成熟度以及采摘后的存储方法等\n条件的影响，但没有体现什么条件下橙子最有功效，排除。\n故正确答案为A。"},{"q":"研究显示，睡眠超过八小时的人的皮肤比通宵熬夜的人更加健康。一些金融工作者是通宵熬夜的人，部分体育工作者一直保持着超过八小时的睡眠。张玉是一名体育工作者。由此可以推出（  ）","options":["多数体育工作者比某些金融工作者的皮肤更健康","某些体育工作者比某些金融工作者的皮肤更健康","某些金融工作者的皮肤比张玉的皮肤更健康","张玉的皮肤比某些金融工作者的皮肤更健康"],"a":1,"e":"【答案】B\n【解析】归纳推理\nA 项，题干只强调了部分，无法根据部分体育工作者的情况推出多数体育工作者的情\n况，无法进行两个群体多少之间的比较，所以不能推出，排除；\nB 项，存在有的体育工作者睡眠超过八小时，也存在有的金融工作者通宵熬夜，这两\n个群体比较，可以推出某些体育工作者比某些金融工作者的皮肤更健康，当选；\nC、D 项，张玉虽然属于体育工作者，但是他的睡眠时间无法确定，无法由部分的情\n况推出群体中个人的情况如何，所以无法与其他人比较，排除。\n故正确答案为B。"},{"q":"一项研究中，在其他条件均相同的情况下，研究人员每天用含有0.002 克13-oxODA的高热量食物喂食一组肥胖小鼠，另一组肥胖小鼠则单纯喂食高热量食物。4 周后测量它们体内中性脂肪含量和血糖值，发现前者血液和肝脏中的中性脂肪比后者少30%左右，血糖值也比后者低20%左右。13-oxo-ODA 是一种亚油酸，在西红柿特别是在经过加热处理的西红柿汁中含量较高。由此可以推出（  ）","options":["13-oxo-ODA 有助于降低脂肪含量和血糖值","13-oxo-ODA 对小鼠的身体健康有益","食用经过加热处理的西红柿更有利于健康","亚油酸是一种对身体健康有益的物质"],"a":0,"e":"【答案】A\n【解析】归纳推理。\nA 项，13-oxo-ODA 降低了小鼠的中性脂肪含量和血糖值，可以推出，当选；\nB 项，降低脂肪、血糖是否就代表健康从题干中无法得知，排除；\nC 项，同理，可以得知加热的西红柿13-oxo-ODA 含量高，但无法得知是否利于健\n康，排除；\nD 项，可以得知加热的西红柿13-oxo-ODA 含量高，但无法得知是否利于健康，排\n除。\n故正确答案为A。"},{"q":"某单位员工除了基本工资之外，其收入很大一部分来源于绩效工资。在今年4 月份，该单位第一项目组所有员工的绩效工资高于第二组员工的最高绩效工资，但是该单位本月绩效工资最高的员工并不在第一项目组。由此可以推出（  ）","options":["该单位领导的绩效工资最高","该单位其他项目组有些员工的绩效工资没有第一、第二项目组平均的高","该单位有些员工既不属于第一项目组也不属于第二项目组","第二项目组的平均绩效工资低于单位的平均绩效工资"],"a":2,"e":"【答案】C\n【解析】归纳推理。\nA 项，单位领导的工资在题干中没有提及，话题不一致，排除；\nB 项，其他组员工的绩效工资在题干中没有提及，话题不一致，排除；\nC 项，由题干可知，一组员工绩效工资都比二组高，但是该单位最高的并不在一二\n组，所以一定有人不在一二组，可以推出，当选；\nD 项，单位的平均绩效工资在题干中没有提及，话题不一致，排除。\n故正确答案为C。"},{"q":"通常情况下，人体内的瘦素和胰岛素能帮人管住嘴巴，一旦吃饱就会发出信号传至大脑告知人们停止进食。而垃圾食品中含有过量的饱和脂肪，饱和脂肪分子会屏蔽这些停止进食的信号。由此可以得出（  ）","options":["整体均衡饮食，保持营养全面是维护健康的最关键因素","垃圾食品不仅会导致肥胖，还会诱发其他疾病","垃圾食品中含有的饱和脂肪大大超过其他食品","吃饱的信号传至大脑可避免饮食过度"],"a":3,"e":"【答案】D\n【解析】归纳推理。\nA 项，整体均衡饮食和维护健康均未在题干中提及，话题不一致，排除；\nB 项，垃圾食品诱发其他疾病未在题干中提及，话题不一致，排除；\nC 项，由题干可知垃圾食品有过量饱和脂肪，但并没有说大大超过其他食品，不能进\n行比较，排除；\nD 项，由题干“一旦吃饱就会发出信号传至大脑，告知人们停止进食”可知，可以推\n出，当选。\n故正确答案为D。"},{"q":"有研究发现，那些每天坐着看电视和工作总计达10 小时的女性，与每天通常坐8小时的女性相比，患结肠癌的风险增加8%，患子宫癌的风险增加10%，而且无论研究对象在不坐时有多活跃，都不会影响这个结果。由此可以推出（  ）","options":["缺乏运动可能是某些癌症的首要病因","久坐可能对女性健康造成不良的影响","工作之余的体育锻炼可以强身健体","上班族职业女性的身体健康状况堪忧"],"a":1,"e":"【答案】B\n【解析】归纳推理。\nA 项，的缺乏运动是患癌因素在题干中没有提及，话题不一致，排除；\nB 项，由题干可知，女性坐的时间越长患癌风险增加，因此久坐可能对女性健康造成\n不良影响，当选；\nC 项，体育锻炼可强身健体在题干中没有提及，话题不一致，排除；\nD 项，由题干可知讨论的是久坐的女性，并不是单指上班族职业女性，话题不一致，\n排除。\n故正确答案为B。"},{"q":"过去人们基于对月岩原子放射性衰变的测量认为，月球诞生在太阳系形成之后约3000 万到4000 万年之间。一项新的研究基于259 台电脑对围绕太阳旋转的原行星盘演化过程的模拟，再现了小型天体在最终形成现有岩态行星之前不断撞击和聚合的过程。该研究人员认为，大约在太阳系诞生之后约9500 万年，一颗巨大的小行星撞击地球，形成的碎片最后变成了月球。以下哪项最能指出前后两种观点的分歧（  ）","options":["关于月球形成时间，有两种不同的估算方法，一种基于放射性衰变测量，一种是基于计算机模拟","关于月球形成过程，有两种不同的理论假说，一种基于月岩自然衰变，一种是原行星盘自然演化","关于月球形成方式，有两种不同的模型解释，一种基于月球组成成分的测量，一种是小行星撞击","关于月球与地球的演化，有两种不同的还原方法，一种基于月球现有成分的测量，一种是计算机模拟"],"a":0,"e":"【答案】A\n【解析】归纳推理。观点1：月球诞生在太阳系形成之后约3000 万到4000 万年之\n间。观点2：大约在太阳系诞生之后约9500 万年，一颗巨大的小行星撞击地球，形成的\n碎片最后变成了月球。\nA 项，由题干可知第一种观点是基于对月岩原子放射性衰变的测量得出结论，第二种\n观点是基于259 台电脑的模拟，得到了不同的月亮形成时间，是两种不同的估算方法，当\n选；\nB 项，讨论的是月球的形成过程，题干讨论月球的形成时间，排除；\nC 项，讨论的是月球形成方式，题干讨论月球的形成时间，排除；\nD 项，讨论的是月球与地球的演化，题干讨论月球的形成时间，排除。\n故正确答案为A。\n第二组："},{"q":"车主信息会影响汽车保费，比如年龄较大、女性、高学历的车主，保费相对较低，25 岁以下的年轻人保费较高，出过交通事故的车主保费高；另外，汽车价格、车型、车龄甚至颜色都会影响保险费用。高价新车不一定比低价旧车保费贵，因为新车、好车的防盗装置、安全装置多；特定车型颜色鲜艳的车保费贵，比如爱开红色跑车的人，性格比较奔放，开车时相对不太谨慎。根据上文，最有可能推出的是（  ）","options":["有过交通事故的红色跑车的18 岁男性车主所交的保费高","开豪华跑车的女性要比开平价汽车的男性所交的保费高","大龄、有研究生学历并购买新车的女性车主所交的保费低","谨慎细致的车主要比奔放活泼的车主所交的保费低"],"a":0,"e":"【答案】A\n【解析】归纳推理。\nA 项，由题干可知出过交通事故、红色跑车、年轻、男性均会导致车主所交保费高，\n所以有过交通事故的红色跑车的18 岁男性车主所交的保费高，可以推出，当选；\nB 项，豪华跑车和平价跑车的保费在题干中并没有比较，排除；\nC 项，由题干可知高价新车不一定比低价旧车保费贵，不能比较两者的保费，排除；\nD 项，细致谨慎和奔放活泼的保费在题干并未提及，排除。\n故正确答案为A。"},{"q":"研究显示，黑、灰色汽车是盗贼的最爱，亮色汽车很少被问津，白色汽车失窃率最低。心理学家分析认为，偷车贼往往有“黑暗型人格”，选择和自己性格颜色相反的汽车倒卖，让他们感觉不踏实。相比新款或豪车而言，盗车贼偏好有着三年车龄左右的大众车型，这种车保值且好转手。根据上文，最有可能推出的是（  ）","options":["三年车龄的红色大众车型最易被盗","暗色系汽车在二手车市场最为畅销","崭新的白色豪华汽车不容易被盗","最畅销的车型也是最易被盗的车型"],"a":2,"e":"【答案】C\n【解析】归纳推理。\nA 项，由题干可知亮色汽车很少被问津，因此红色汽车不一定最容易被盗，排除；\nB 项，由题干可知，暗色汽车容易被盗，但是二手市场卖的不一定是被盗的汽车，所\n以不能说暗色汽车就畅销，排除；\nC 项，由题干可知白色汽车失窃率最低，并且新款不容易被盗，因此新款的白色汽车\n不容易被盗，当选；\nD 项，最畅销的车型题干没有提及，不能进行比较，排除。\n故正确答案为C。"},{"q":"快乐是非常个人的，也是非常主观的，它与物质、环境相关，但是更主要的是取决于一个人的心态。他人的快乐，未必是自己的快乐；自己的快乐，也未必是他人的快乐；将自己的快乐告诉别人，未必能给他人带来快乐；别人将快乐告诉自己，也未必会给自己带来快乐。根据以上陈述，能够得出以下哪项（  ）","options":["他人的快乐可能给自己带来快乐","自己的快乐可能是他人的快乐","他人的快乐可能不是自己的快乐","自己的快乐可能给他人带来快乐"],"a":2,"e":"【答案】C\n【解析】归纳推理。\nA 项，由题干可知他人的快乐未必给自己带来快乐，未必代表可能不，所以可能不会\n带来快乐，可能不会不能推出可能会，排除；\nB 项，由题干可知自己的快乐，也未必是他人的快乐，所以可能不会是别人的快乐，\n排除；\nC 项，由题干可知他人的快乐未必给自己带来快乐，所以可能不会带来快乐，当选；\nD 项，由题干可知自己的快乐，未必能给他人带来快乐，所以可能不会给他人带来快\n乐，排除。\n故正确答案为C。"},{"q":"美国幼儿教育注重培养孩子的“批判式思维”，其中重要一点就是区分事实陈述与观点陈述，事实陈述是可被验证的，有“真假”，无“好坏”；观点陈述则多为主观体验，受价值观等影响。以下广告语中，兼顾事实与观点的是（  ）","options":["金牌巧克力，唤醒你的甜蜜回忆","量牌65 英寸无边框全玻璃超薄电视，给您海一般视野","喜酒沁人心脾，滴滴难舍，回味无穷","水平对置发动机，左右对称全时四驱，成就捷牌汽车"],"a":1,"e":"【答案】B\n【解析】归纳推理。事实陈述是可被验证的，有“真假”，无“好坏”；观点陈述则\n多为主观体验，受价值观等影响。\nA 项，唤醒你的甜蜜回忆是主观感情，观点陈述，没有事实，排除；\nB 项，65 英寸无边框全玻璃超薄电视是事实的陈述，可以被验证，给您海一般视野是\n主观的体验，观点陈述，事实和观点均有体现，当选；\nC 项，沁人心脾、回味无穷是主观感情，观点陈述，没有事实，排除；\nD 项，水平对置发动机，左右对称全时四驱是事实的陈述，可以被验证，没有观点，\n排除。\n故正确答案为B。"},{"q":"在人际交往的过程中，容貌是最容易观察到的属性特征。和容貌普通的人相比，容貌有吸引力的个体，往往被认为具有较高的能力、较为积极的人格特征和较好的人际关系，甚至收入水平和个人幸福指数也会比较高。在工作中，相同的任务被不同人完成时，通常顾客会对容貌姣好员工的服务质量给予相对较高的评价。由此可以推出（  ）","options":["随着容貌吸引力越来越大，人们对其个性特征的评价越来越好","企业应选择容貌姣好的人为员工，以提高顾客的服务满意度","简历不应附带照片，因为照片会影响招聘者决策的公平性","发表文章时提供作者的照片，可以提高读者对文章质量的评价"],"a":1,"e":"【答案】B\n【解析】归纳推理。\nA 项，越来越大、越来越好在题干中没有提及，题干只说明和容貌普通的人相比，容\n貌有吸引力的个体，往往被认为具有较高的能力、较为积极的人格特征和较好的人际关\n系，并没有程度趋势上的变化，排除；\nB 项，由题干可知通常顾客会对容貌姣好员工的服务质量给予相对较高的评价，因此\n选择容貌姣好的员工提高服务满意度，当选；\nC 项，简历附带照片在题干中并没有提及，话题不一致，排除；\nD 项，发表文章提供作者的照片与读者对文章质量的评价，在题干中并没有提及，话\n题不一致，排除。\n故正确答案为B。"},{"q":"某位记者说道：“金钱和幸福是人们苦苦追求的。但是，一个人有钱并不意味着他一定幸福。而一个人幸福也不意味着他一定有钱。我采访过的人中：有的人有钱，有的人幸福，多数人并不同时具备这两者。”若该记者所述为真，关于他所采访的人中，哪项陈述一定为真（  ）","options":["只有少数人既有钱又幸福","有钱人比幸福的人要多","幸福的人比有钱的人更多些","有的人既没钱，又不幸福"],"a":0,"e":"【答案】A\n【解析】归纳推理。\nA 项，题干中记者表述为“多数人并不同时具备这两者”，也就是说只有少数人同时\n具备两者，可以推出，当选；\nB 项，题干并没有比较有钱人和幸福的人这二者的人数，无中生有，排除；\nC 项，题干并没有比较有钱人和幸福的人这二者的人数，无中生有，排除；\nD 项，题干中记者表述为“多数人并不同时具备这两者”，也就是说有的人有钱，有\n的人幸福，但并没有说有人同时不具备，无法推出，排除。\n故正确答案为A。"},{"q":"某国研究人员招募大学生被试进行情绪与大脑活动的研究，先让大学生读一些能够激发嫉妒和幸灾乐祸的情绪的故事，然后用功能磁共振成像仪对被试脑部血流变化进行测定，发现，嫉妒情绪与大脑前扣带回皮层的活跃度有关，幸灾乐祸与大脑纹状体的活跃度有关，而且，在产生嫉妒情绪时前扣带回皮层的活动越活跃的人，其纹状体的活跃程度就越高。根据上述研究，最有可能得出以下哪项结论（  ）","options":["大脑的功能变化可以证明，嫉妒和幸灾乐祸都是人之常情","喜欢嫉妒别人的人，大脑前扣带回皮层的功能要比其他人更强","那些爱嫉妒别人的人，更有可能在别人不顺利时幸灾乐祸","喜欢幸灾乐祸的人，大脑的纹状体活跃程度要比喜欢嫉妒的人更高"],"a":2,"e":"【答案】C\n【解析】归纳推理。\nA 项，题中研究的是情绪与大脑活动的关系，是嫉妒和幸灾乐祸的情绪与大脑的关\n系，无法推出嫉妒和幸灾乐祸都是人之常情，排除；\nB 项，题干只是嫉妒情绪与大脑前扣带回皮层的活跃度有关，并没有将喜欢嫉妒别人\n的人的大脑前扣带回皮层的功能与其他人进行对比，排除；\nC 项，在产生嫉妒情绪时前扣带回皮层的活动越活跃的人，其纹状体的活跃程度就越\n高。说明嫉妒程序所影响的前扣带回皮层能影响与幸灾乐祸相关的纹状体，可以推出，当\n选；\nD 项，题干中没有涉及幸灾乐祸的人大脑的纹状体活跃程度如何，无法推出，排除。\n故正确答案为C。"},{"q":"癌症的发病与基因相关，如基因发生突变，变得过于活跃，会驱动癌症的发生，同理，如果抑癌基因发生突变，失去功能，也会促发癌症。PTEN 是一种容易发生突变的抑癌基因，目前发现人体内有一种叫WWP1 的E3 泛素连接酶会与PTEN 结合，影响其抑癌功能。抑制WWP1 的功能，就能解放PTEN，恢复PTEN 对癌症的抑制，从而起到抗癌作用。有研究证实，一种叫做“吲哚-3-甲醇”（I3C）的天然化合物能有效抑制WWP1 的功能，而I3C在西兰花等十字花科植物中非常普遍。根据上述论述，以下哪项判断正确（  ）","options":["常吃西兰花等十字花科蔬菜有助于治疗癌症","WWP1 含量越高，PTEN 的含量越低","E3 泛素连接酶通过对致癌基因的作用而影响癌症的发生","I3C 有助于恢复PTEN 的抑癌功能"],"a":3,"e":"【答案】D\n【解析】归纳推理。\nA 项，题干说的是抑制预防，不等于治疗，偷换概念，排除；\nB 项，题干中并未进行比较，无法推出，排除；\nC 项，原文“E3 泛素连接酶会与PTEN 结合，影响其抑癌功能”，而选项中PTEN 是\n抑癌基因，排除；\nD 项，题干中提到“吲哚-3-甲醇”（I3C）的天然化合物能有效抑制WWP1 的功\n能”、“抑制WWP1 的功能，就能解放PTEN，恢复PTEN 对癌症的抑制，从而起到抗癌\n作用”，可以推出I3C 有助于恢复PTEN 的抑癌功能，当选。\n故正确答案为D。"},{"q":"用水超标家庭指的是日均用水量超过所在地区70%家庭的水平的家庭。近五年来，甲地区的用水超标家庭数量明显逐年增加。由此可以推知以下哪项陈述也必定属实（  ）①今年甲地区任何一个用水超标家庭的日均用水量都高于该地区的日均耗水量。②近五年来，甲地区的日用水总量逐年明显增加。③近五年来，甲地区用水不超标的家庭数量明显逐年增加。","options":["只有①","只有②","只有③","只有①和②"],"a":2,"e":"【答案】C\n【解析】归纳推理。\n①中，题干中没有提到其他家庭的具体用水量，也就无法确定甲地区的日均耗水量，\n无法进行比较，无法推出；\n②中，由题干不能得出该地区的日均用水量，所以无法确定甲地区的日用水总量，无\n法推出；\n③中，由题干可知，用水超标家庭占所在地区家庭数量的30%，是一个固定的比例，\n用水超标家庭数量增加，所以不超标家庭的数量也逐年增加，可以推出。\n故正确答案为C。"}]},{"id":"leibi","name":"类比推理","items":[{"q":"科学界最近发现了一种α拟菌病毒，这种病毒会寄生于β变形虫体内。被这种病毒寄生的ß 变形虫会在哺乳类动物体内释放某种γ刺激物，这种刺激物会导致该动物的呼吸系统产生剧烈反应，严重时会造成呼吸困难。目前在临床中发现有呼吸困难症状物体内都能找到α拟菌病毒。由此可以推出（  ）","options":["在呼吸正常的哺乳类动物体内不可能发现γ刺激物","ß 变形虫会在哺乳类动物体内会使哺乳类动物的呼吸系统产生剧烈反应","ß 变形虫在没有α拟菌病毒寄生的情况下，不会产生导致哺乳类动物呼吸困难的刺激物","如果某个哺乳类动物感染了α拟菌病毒，该动物肯定会有呼吸困难的症状"],"a":2,"e":"【答案】C\n【解析】归纳推理。\nA 项，题干中未提到呼吸正常的情况，不可能三个字太绝对，无法推出，排除；\nB 项，被α拟菌病毒寄生的β变形虫体，会导致剧烈反映，B 项没有说明是否寄生，\n无法推出，排除；\nC 项，被这种病毒寄生的ß 变形虫会刺激动物，没有被寄生的，即不会产生导致哺乳\n类动物呼吸困难的刺激物，可以推出，当选；\nD 项，内有说明是否寄生在ß 变形虫内，寄生的会呼吸困难，没寄生不明确，无法推\n出，排除。\n故正确答案为C。\n第三章类比推理\n第一组："},{"q":"指甲：指甲钳（  ）","options":["头发：发卡","铅笔：铅笔盒","手：手套","胡子：剃须刀"],"a":3,"e":"【答案】D\n【解析】对应关系。指甲钳是剪指甲的工具。\nA 项，发卡的作用是装饰与固定头发的工具，不是剪头发的工具，与题干逻辑关系不\n符，排除；\nB 项，铅笔盒是装铅笔的工具，不是削铅笔的工具，与题干逻辑关系不符，排除；\nC 项，手套是保护手的物品，不是修剪手的，与题干逻辑关系不符，排除；\nD 项，剃须刀是剃胡子的工具，与题干逻辑关系一致，当选。\n故正确答案为D。"},{"q":"哺乳动物：陆生动物（  ）","options":["航天器：交通工具","有花植物：无花植物","星际物质：天狼星","北极熊：极地企鹅"],"a":0,"e":"【答案】A\n【解析】交叉关系。有的哺乳动物是陆生动物，有的陆生动物是哺乳动物，二者是交\n叉关系。\nA 项，有的航天器是交通工具，有的交通工具是航天器，二者是交叉关系，与题干逻\n辑关系一致，当选；\nB 项，有花植物和无花植物是植物的两种分类，为矛盾关系，与题干逻辑关系不符，\n排除；\nC 项，天狼星是星体，星际物质是星体与星体之间的物质，二者没有必然联系，排\n除；\nD 项，北极熊和极地企鹅是两种动物，二者为并列关系，与题干逻辑关系不符，排\n除。\n故正确答案为A。"},{"q":"天下雨：地上湿（  ）","options":["满18 岁：有选举权","开花：结果","地上不湿：天没下雨","摩擦：生热"],"a":2,"e":"【答案】C\n【解析】条件关系。如果天下雨，那么地上湿，天下雨是地上湿的充分条件。\nA 项，18 岁是选举权的必要条件，与题干逻辑关系不符，排除；\nB 项，开花不一定会结果，不是充分条件，与题干逻辑关系不符，排除；\nC 项，地上不湿是天没下雨的充分条件，与题干逻辑关系一致，当选；\nD 项，摩擦不一定会生热，与题干逻辑关系不符，排除。\n故正确答案为C。"},{"q":"研究生：硕士：博士（  ）","options":["青少年：少年：青年","妇孺：儿童：妇女","建筑：平房：高楼","图形：直线：三角形"],"a":0,"e":"【答案】A\n【解析】时间顺序。研究生可以分为硕士研究生和博士研究生两个阶段，先读硕士，\n后读博士，存在时间先后顺序。\nA 项，青少年可以分为少年和青年两个阶段，先是少年，后是青年，存在时间先后顺\n序，与题干逻辑关系一致，当选；\nB 项，妇孺指妇女和儿童，但是儿童分为男孩女孩，和妇女没有时间先后顺序，与题\n干逻辑关系不符，排除；\nC 项，平房和高楼都是建筑的一种，但二者没有时间先后顺序，与题干逻辑关系不\n符，排除；\nD 项，图形有直线和三角形，但二者不具有时间先后顺序，与题干逻辑关系不符，排\n除。\n故正确答案为A。"},{"q":"行驶：违章：罚款（  ）","options":["学习：成绩：奖励","栽培：减产：施肥","竞争：优势：成功","锻炼：受伤：医治"],"a":3,"e":"【答案】D\n【解析】对应关系。行驶过程中，违章可能会被罚款，且违章是动词。\nA 项，学习过程中成绩好可能会得到奖励，但选项只是成绩，与题干逻辑关系不符，\n排除；\nB 项，栽培的结果可能是减产，减产不是栽培过程中产生的，与题干逻辑关系不符，\n排除；\nC 项，竞争过程中有优势可能会带来成功，但优势是名词，与题干逻辑关系不符，排\n除；\nD 项，锻炼中受伤会得到医治，且受伤是动词，与题干逻辑关系一致，当选。\n故正确答案为D。"},{"q":"监督：人大：媒体（  ）","options":["教育：小学：中学","融资：借贷：赞助","增收：加薪：优惠","惩罚：死刑：徒刑"],"a":0,"e":"【答案】A\n【解析】功能关系。人大与媒体都有监督的功能，且人大与媒体都是监督的主体。\nA 项，小学和中学都有教育的功能，且小学和中学都是教育的主体，与题干逻辑关系\n一致，当选；\nB 项，借贷与赞助都是融资的方式，并不是功能，与题干逻辑关系不符，排除；\nC 项，加薪是增收的一种方式，与优惠无必然联系，排除；\nD 项，死刑和徒刑有惩罚的功能，但不是惩罚的主体，与题干逻辑关系不符，排除。\n故正确答案为A。"},{"q":"春雨：杏花：江南（  ）","options":["夏荷：烈日：江北","秋风：腊梅：华北","秋霜：枯草：塞外","冬雪：牡丹：边疆"],"a":2,"e":"【答案】C\n【解析】对应关系。春雨是天气现象，杏花是植物，二者都是春天的景象，江南为地\n点对应。\nA 项，夏荷是植物，烈日是天气现象，二者词语顺序反了，排除；\nB 项，秋风是秋天的天气，腊梅是冬天的景色，二者季节不同，与题干逻辑关系不\n符，排除；\nC 项，秋霜是天气现象，枯草是植物，二者都是秋天的景象，塞外为地点对应，与题\n干逻辑关系一致，当选；\nD 项，冬雪是冬天的天气现象，牡丹是春天的景色，二者季节不同，与题干逻辑关系\n不符，排除。\n故正确答案为C。"},{"q":"航空母舰对于（  ）相当于雷达对于（  ）","options":["驱逐舰；天线","海洋；天空","舰载机；显示屏","舰艇；电子设备"],"a":3,"e":"【答案】D\n【解析】种属关系。代入选项逐一分析。\nA 项，航空母舰和驱逐舰都属于舰艇，二者是并列关系，天线是雷达的组成部分，二\n者是组成关系，前后逻辑关系不一致，排除；\nB 项，航空母舰在海洋上行驶，而雷达和天空无必然关系，排除；\nC 项，舰载机停靠在航空母舰上，二者是地点对应关系，显示屏和雷达是组成关系，\n前后逻辑关系不一致，排除；\nD 项，航空母舰是舰艇的一种，雷达是电子设备的一种，前后均为种属关系，当选。\n故正确答案为D。"},{"q":"理想对于（  ）相当于（  ）对于涂鸦","options":["现实；作品","梦想；画家","白日梦；画作","志愿；涂"],"a":2,"e":"【答案】C\n【解析】交叉关系。代入选项逐一分析。\nA 项，理想与现实是反义词，有的作品是涂鸦，有的涂鸦是作品，二者为交叉关系，\n前后逻辑关系不一致，排除；\nB 项，理想和梦想是近义词，画家涂鸦是主谓关系，前后逻辑关系不一致，排除；\nC 项，有的理想是白日梦，有的白日梦是理想，有的画作是涂鸦，有的涂鸦是画作，\n前后均为交叉关系，当选；\nD 项，理想和志愿是近义词，涂鸦和涂改没有必然联系，排除。\n故正确答案为C。"},{"q":"烟灰：烟灰缸（  ）","options":["黑板：黑板擦","鼠标：鼠标垫","首饰：首饰盒","领带：领带夹"],"a":2,"e":"【答案】C\n【解析】功能关系。烟灰缸的功能是盛放烟灰。\nA 项，黑板擦的功能是擦除黑板，与题干逻辑关系不符，排除；\nB 项，鼠标垫的作用是放置鼠标，与题干逻辑关系不符，排除；\nC 项，首饰盒的作用是盛放首饰，与题干逻辑关系一致，当选；\nD 项，领带夹的作用是夹领带，与题干逻辑关系不符，排除。\n故正确答案为C。\n第二组"},{"q":"上衣：领袖（  ）","options":["兄弟：手足","时间：岁月","身体：耳目","动物：鹰犬"],"a":2,"e":"【答案】C\n【解析】组成关系。领和袖是上衣的组成部分，二者是组成关系。\nA 项，手足代表兄弟，二者是同一关系，与题干逻辑关系不符，排除；\nB 项，岁月和时间是近义词，与题干逻辑关系不符，排除；\nC 项，耳和目是身体的组成部分，与题干逻辑关系一致，当选；\nD 项，鹰犬属于动物，二者是种属关系，与题干逻辑关系不符，排除。\n故正确答案为C。"},{"q":"进展：变化（  ）","options":["妥协：退让","口角：冲突","开花：结果","喜欢：信任"],"a":1,"e":"【答案】B\n【解析】种属关系。进展属于变化的一种，二者是种属关系。\nA 项，妥协和退让是近义词，与题干逻辑关系不符，排除；\nB 项，口角是冲突的一种，与题干逻辑关系一致，当选；\nC 项，开花和结果是植物生长的两个阶段，二者是并列关系，与题干逻辑关系不符，\n排除；\nD 项，喜欢和信任没有必然联系，与题干逻辑关系不符，排除。\n故正确答案为B。"},{"q":"作茧自缚：化蛹成蝶（  ）","options":["灯蛾扑火：化羽归尘","雨润花开：春华秋实","鱼翔浅底：鹰击长空","凤凰浴火：涅槃重生"],"a":3,"e":"【答案】D\n【解析】时间顺承关系。作茧自缚指蚕吐丝作茧子，把自己包裹起来，化蛹成蝶指蝴\n蝶幼虫由蛹，经过蜕皮，变化为成虫的过程，先作茧自缚，后化蛹成蝶，二者为时间先后\n顺序。\nA 项，灯蛾扑火比喻自己找死，化羽归尘指化作羽毛，归入尘土，二者没有必然联\n系，排除；\nB 项，雨润花开指雨水滋润，花朵开放，春华秋实指春天开花，秋天结果，二者没有\n必然联系，排除；\nC 项，鱼翔浅底和鹰击长空都比喻有雄心壮志的人在广阔的领域中施展自己的才能，\n二者是近义词，与题干逻辑关系不符，排除；\nD 项，凤凰浴火指凤凰投身于熊熊烈火中，经受煎熬，涅槃重生指凤凰经历烈火的煎\n熬和痛苦的考验，获得重生，先凤凰浴火，后涅槃重生，二者为时间先后顺序，与题干逻\n辑关系一致，当选。\n故正确答案为D。"},{"q":"风：风车：旋转（  ）","options":["水：金鱼：游动","雷：闪电：暴雨","电：电车：行驶","火：木柴：燃烧"],"a":2,"e":"【答案】C\n【解析】对应关系。风车利用风进行旋转，风是风车旋转的动力来源。\nA 项，金鱼在水中游动，水是游动的地点，不是动力来源，与题干逻辑关系不符，排\n除；\nB 项，雷、闪电、暴雨都是自然现象，三者为并列关系，与题干逻辑关系不符，排\n除；\nC 项，电车利用电进行行驶，电是电车的动力来源，与题干逻辑关系一致，当选；\nD 项，木柴燃烧时产生火，火不是木柴燃烧的动力来源，与题干逻辑关系不符，排\n除。\n故正确答案为C。"},{"q":"玫瑰：植物：动物（  ）","options":["童话：书籍：影像","画眉：鸟：鱼","镜片：太阳镜：墨镜","雾：雨：风"],"a":1,"e":"【答案】B\n【解析】种属关系+并列关系。玫瑰是一种植物，二者为种属关系，植物和动物是并\n列关系。\nA 项，书籍是童话的载体，与题干逻辑关系不符，排除；\nB 项，画眉是一种鸟，二者为种属关系，鸟和鱼为并列关系，与题干逻辑关系一致，\n当选；\nC 项，镜片是太阳镜的组成部分，二者为组成关系，与题干逻辑关系不符，排除；\nD 项，雾、雨、风均为自然现象，三者为并列关系，与题干逻辑关系不符，排除。\n故正确答案为B。"},{"q":"口试：笔试：招聘（  ）","options":["摄影：购物：旅游","招标：中标：建设","批发：零售：销售","出口：内销：商品"],"a":2,"e":"【答案】C\n【解析】对应关系。口试和笔试为招聘的方式。\nA 项，摄影和购物是旅游中进行的活动，与题干逻辑关系不符，排除；\nB 项，先招标，再中标，最后建设，三者为时间先后顺序，与题干逻辑关系不符，排\n除；\nC 项，批发和零售是销售的方式，与题干逻辑关系一致，当选；\nD 项，出口和内销的对象是商品，与题干逻辑关系不符，排除。\n故正确答案为C。"},{"q":"年号：历法：计时（  ）","options":["股票：基金：投资","水坝：城墙：防洪","火把：流星：照明","手机：信函：洽谈"],"a":0,"e":"【答案】A\n【解析】并列关系+功能关系。年号和历法二者是并列关系，二者均有计时的功能。\nA 项，股票和基金都有投资的功能，与题干逻辑关系一致，当选；\nB 项，水坝有防洪的功能，但是城墙的功能不是防洪，与题干逻辑关系不符，排除；\nC 项，火把的功能是照明，但是流星的功能不是照明，与题干逻辑关系不符，排除；\nD 项，手机和信函的功能是通信，不是洽谈，与题干逻辑关系不符，排除。\n故正确答案为A。"},{"q":"家庭对于（  ）相当于细胞对于（  ）","options":["社会；生物","住房；细胞核","规范；秩序","和谐；营养"],"a":0,"e":"【答案】A\n【解析】组成关系。代入选项。\nA 项，家庭是社会的组成部分，细胞是生物的组成部分，前后均为组成关系，当选；\nB 项，家庭需要住房，细胞核是细胞的组成部分，二者为组成关系，前后逻辑关系不\n一致，排除；\nC 项，家庭和规范没有必然联系，细胞和秩序也无必然联系，排除；\nD 项，和谐的家庭，二者为偏正关系，细胞和营养没有必然联系，排除。\n故正确答案为A。"},{"q":"插图对于（  ）相当于（  ）对于小说","options":["漫画；散文","图画；语言","正文；文学","读物；序言"],"a":3,"e":"【答案】D\n【解析】组成关系。代入选项。\nA 项，有的插图是漫画，有的漫画是插图，二者为交叉关系，散文和小说都是一种文\n体，二者为并列关系，前后逻辑关系不一致，排除；\nB 项，插图是图画的一种，二者为种属关系，小说和语言没有必然联系，排除；\nC 项，插图和正文组成文章，二者为并列关系，小说是文学的载体，前后逻辑关系不\n一致，排除；\nD 项，插图是读物的组成部分，序言是小说的组成部分，前后均为组成关系，当选。\n故正确答案为D。"},{"q":"宇航员：探月（  ）","options":["航空公司：飞行","清洁工：保洁","志愿者：组织","药厂：制药"],"a":1,"e":"【答案】B\n【解析】对应关系。宇航员是一种职业，工作是探月。\nA 项，航空公司不是一种职业，与题干逻辑关系不符，排除；\nB 项，清洁工是一种职业，工作是保洁，与题干逻辑关系一致，当选；\nC 项，志愿者不是一种职业，与题干逻辑关系不符，排除；\nD 项，药厂不是一种职业，与题干逻辑关系不符，排除。\n故正确答案为B。\n第三组："},{"q":"语言：德语（  ）","options":["图书馆：书本","命题：概念","有理数：正分数","地球：卫星"],"a":2,"e":"【答案】C\n【解析】种属关系。德语是一种语言，二者是种属关系。\nA 项，书本放在图书馆中，二者是地点对应，与题干逻辑关系不符，排除；\nB 项，命题是概念的一种，二者属于种属关系，二者属于种属关系，但是词语顺序反\n了，排除；\nC 项，正分数是有理数，二者是种属关系，与题干逻辑关系一致，当选；\nD 项，地球是行星，不是卫星，与题干逻辑关系不符，排除。\n故正确答案为C。"},{"q":"有形损耗：无形损耗（  ）","options":["中国哲学：西方哲学","蒸馏酒：葡萄酒","急性中毒：慢性中毒","有色金属：稀有金属"],"a":2,"e":"【答案】C\n【解析】矛盾关系。有形损耗和无形损耗，是损耗的两种形式，并且有形无形为矛盾\n关系。\nA 项，哲学除了中国哲学和西方哲学还有别的分支，二者是反对关系，与题干逻辑关\n系不符，排除；\nB 项，有的蒸馏酒是葡萄酒，有的葡萄酒是蒸馏酒，二者为交叉关系，与题干逻辑关\n系不符，\n排除；\nC 项，急性中毒和慢性是中毒的两种形式，并且急性和慢性是矛盾关系，与题干逻辑\n关系一致，当选；\nD 项，稀有金属是有色金属的一种，二者是种属关系，与题干逻辑关系不符，排除。\n故正确答案为C。"},{"q":"循规蹈矩：规矩（  ）","options":["年富力强：富强","功成名就：成就","待人接物：人物","伶牙俐齿：牙齿"],"a":1,"e":"【答案】B\n【解析】对应关系。循规蹈矩指按照规矩做事，二者为对应关系。\nA 项，年富力强指年纪轻精力旺盛，富强指富足强盛，二者无必然联系，排除；\nB 项，功成名就指取得了成就，与题干逻辑关系一致，当选；\nC 项，待人接物指跟人相处，人物经常指代表作品中描写的人，二者无必然联系，排\n除；\nD 项，伶牙俐齿指能说会道，和牙齿没有关系，排除。\n故正确答案为B。"},{"q":"大豆：酱油（  ）","options":["柠檬：白醋","淀粉：年糕","花生：香油","甘蔗：红糖"],"a":3,"e":"【答案】D\n【解析】原材料对应。大豆是制作酱油的原材料，二者为原材料对应。\nA 项，白醋的原材料是大米，不是柠檬，与题干逻辑关系不符，排除；\nB 项，年糕的原材料是糯米，不是淀粉，与题干逻辑关系不符，排除；\nC 项，香油的原材料是芝麻，不是花生，与题干逻辑关系不符，排除；\nD 项，红糖的原材料是甘蔗，与题干逻辑关系一致，当选。\n故正确答案为D。"},{"q":"亭台：楼宇：砖瓦（  ）","options":["彩虹：阳光：蜃景","电闪：雷鸣：电荷","蛋糕：面包：面粉","核聚变：核裂变：核能"],"a":2,"e":"【答案】C\n【解析】并列关系+原材料关系。亭台和楼宇都是建筑物，二者为并列关系，砖瓦是\n建造亭台楼宇的原材料。\nA 项，阳光照射形成彩虹，二者为必要条件，与题干逻辑关系不符，排除；\nB 项，电闪和雷鸣是自然现象，二者为并列关系，电荷不是产生电闪雷鸣的原材料，\n与题干逻辑关系不符，排除；\nC 项，蛋糕和面包为并列关系，面粉是制作蛋糕面包的原材料，与题干逻辑关系一\n致，当选；\nD 项，核聚变和核裂变都是核反应形式，二者为并列关系，它们释放核能，与题干逻\n辑关系不符，排除。\n故正确答案为C。"},{"q":"小斑虎猫：虎猫属：猫科（  ）","options":["庄稼：粮食：谷物","卷尺：尺子：工具","小学：初中：高中","少尉：少校：少将"],"a":1,"e":"【答案】B\n【解析】种属关系。小斑虎猫是虎猫属动物的一种，二者为种属关系，虎猫属是猫科\n的一种，二者为种属关系。\nA 项，庄稼指地里的农作物，粮食指谷物、豆类和薯类，粮食是庄稼的一种，谷类是\n粮食的一种，均为种属关系，但词语顺序和题干不一致，排除；\nB 项，卷尺是尺子的一种，二者为种属关系，尺子是工具的一种，二者为种属关系，\n与题干逻辑关系一致，当选；\nC 项，小学、初中、高中是并列关系，与题干逻辑关系不符，排除；\nD 项，少尉、少校、少将是不同的军衔名称，三者是并列关系，与题干逻辑关系不\n符，排除。\n故正确答案为B。"},{"q":"批准：审查：申报（  ）","options":["烹饪：切菜：洗菜","跑步：走路：爬行","早退：迟到：报到","痊愈：治疗：受伤"],"a":3,"e":"【答案】D\n【解析】时间关系。先申报，再审查，最后批准，三者为时间先后顺序。\nA 项，洗菜和切菜没有必然的时间先后顺序，与题干逻辑关系不符，排除；\nB 项，爬行、走路和跑步，为三种运动方式，三者为并列关系，与题干逻辑关系不\n符，排除；\nC 项，早退和迟到并没有先后顺序，与题干逻辑关系不符，排除；\nD 项，先受伤，再治疗，最后痊愈，三者为时间先后顺序，与题干逻辑关系一致，当\n选。\n故正确答案为D。"},{"q":"扇子对于（  ）相当于（  ）对于钢笔","options":["折扇；笔帽","团扇；墨水","空调；毛笔","扇面；圆珠笔"],"a":2,"e":"【答案】C\n【解析】并列关系。代入选项。\nA 项，折扇是扇子的一种，二者为种属关系，笔帽是钢笔的组成部分，二者为组成关\n系，前后逻辑关系不一致，排除；\nB 项，团扇是扇子的一种，钢笔和墨水是配套使用关系，前后逻辑关系不一致，排\n除；\nC 项，扇子和空调都有降温的功能，二者是功能对应关系，毛笔和钢笔都具有书写功\n能，二者是功能对应关系，前后逻辑关系一致，当选；\nD 项，扇面是扇子的组成部分，二者是组成关系，圆珠笔和钢笔都是笔的一种，二者\n为并列关系，前后逻辑关系不一致，排除。\n故正确答案为C。"},{"q":"（  ）对于污染相当于起诉对于（  ）","options":["防治；驳回","排放；判决","农药；原告","工厂；法院"],"a":1,"e":"【答案】B\n【解析】时间顺序。代入选项。\nA 项，防治污染是动宾关系，驳回起诉是动宾关系，但是词语顺序反了，排除；\nB 项，先排放后污染，先起诉后判决，前后均为时间先后顺序，当选；\nC 项，使用农药会造成污染，二者为因果关系，原告起诉，是主谓关系，前后逻辑关\n系不一致，排除；\nD 项，工厂是产生污染的地点，法院是起诉的地点，但是词语顺序反了，排除。\n故正确答案为B。"},{"q":"感冒药：中药：西药（  ）","options":["果汁：冷饮：热饮","标枪：田赛：径赛","城墙：古建筑：西方建筑","学士：硕士：博士"],"a":0,"e":"【答案】A\n【解析】并列关系+交叉关系。感冒药有中药，也有西药，中药和西药为并列关系，\n二者与感冒药为交叉关系。\nA 项，果汁有冷饮和热饮，冷饮和热饮为并列关系，二者与果汁为交叉关系，与题干\n逻辑关系一致，当选；\nB 项，标枪属于田赛的一种，二者为种属关系，与题干逻辑关系不符，排除；\nC 项，有的古建筑是西方建筑，有的西方建筑是古建筑，二者属于交叉关系，与题干\n逻辑关系不符，排除；\nD 项，学士、硕士、博士三者为并列关系，与题干逻辑关系不符，排除。\n故正确答案为A。\n第四组："},{"q":"动脉血管：静脉血管：毛细血管（  ）","options":["散文：诗歌：小说","历史片：战争片：科幻片","休眠火山：死火山：活火山","晴天：雨天：雪天"],"a":2,"e":"【答案】C\n【解析】并列关系。动脉血管、静脉血管、毛细血管均是血管的一种，三者为并列关\n系，且三者构成了全部的血管种类。\nA 项，散文、诗歌、小说均是文体的一种，三者为并列关系，但是文体还包括戏剧\n等，三者并不是全部，与题干逻辑关系不符，排除；\nB 项，历史片、战争片、科幻片均是影片题材的一种，三者为并列关系，但是影片题\n材还包括动作片等，三者并不是全部，与题干逻辑关系不符，排除；\nC 项，休眠火山、死火山、活火山均是火山的一种，三者为并列关系，且三者构成了\n全部\n的火山种类，与题干逻辑关系一致，当选；\nD 项，晴天、雨天、雪天均是天气现象的一种，三者为并列关系，但是天气现象还包\n括阴天等，三者并不是全部，与题干逻辑关系不符，排除。\n故正确答案为C。"},{"q":"国有企业：化工企业：大型企业（  ）","options":["草本植物：观叶植物：室内植物","钝角三角形：等边三角形：等腰三角形","内脏：肝脏：消化系统","音乐：舞蹈：戏剧"],"a":0,"e":"【答案】A\n【解析】交叉关系。国有企业、化工企业、大型企业三者之间两两为交叉关系。\nA 项，草本植物、观叶植物、室内植物三者之间两两为交叉关系，与题干逻辑关系一\n致，当选；\nB 项，等边三角形是特殊的等腰三角形，二者为种属关系，与题干逻辑关系不符，排\n除；\nC 项，肝脏属于内脏，二者为种属关系，与题干逻辑关系不符，排除；\nD 项，音乐、舞蹈、戏剧均为艺术的表现形式，三者为并列关系，与题干逻辑关系不\n符，排除。\n故正确答案为A。"},{"q":"高兴对于（  ）相当于（  ）对于巧夺天工","options":["得意：匠心独运","谈笑风生：鬼斧神工","悲哀：照猫画虎","心花怒放：精巧"],"a":3,"e":"【答案】D\n【解析】近义关系。代入选项。\nA 项，高兴和得意是近义词，匠心独运指在文学、艺术等方面独创性地运用巧妙的心\n思，巧夺天工形容技巧的高超，二者没有必然联系，排除；\nB 项，谈笑风生形容交谈的挺高兴，鬼斧神工和巧夺天工均形容技艺非常精细巧妙，\n二者是近义词，前后逻辑关系不一致，排除；\nC 项，高兴和悲哀是反义词，照猫画虎比喻照着样子模仿，和巧夺天工没有必然联\n系，排除；\nD 项，高兴和心花怒放是近义词，精巧和巧夺天工是近义词，前后逻辑关系一致，当\n选。\n故正确答案为D。"},{"q":"开机：关机（  ）","options":["上车：下车","发烧：吃药","地震：逃生","入学：考试"],"a":0,"e":"【答案】A\n【解析】并列关系。开机和关机为并列关系，且开和关是反义词。\nA 项，上车和下车是并列关系，且上和下是反义词，与题干逻辑关系一致，当选；\nB 项，因为发烧，所以吃药，二者为因果关系，与题干逻辑关系不符，排除；\nC 项，因为地震所以需要逃生，二者为因果关系，与题干逻辑关系不符，排除；\nD 项，入学和考试没有必然联系，排除。\n故正确答案为A。"},{"q":"（  ）对于花蕊相当于叶脉对于（  ）","options":["蜂蜜；二氧化碳","花瓣；叶肉","花朵；叶片","花蜜；水分"],"a":1,"e":"【答案】B\n【解析】并列关系。代入选项。\nA 项，蜂蜜和花蕊没有必然联系，叶脉和二氧化碳没有必然联系，排除；\nB 项，花瓣和花蕊都是花的组成部分，二者为并列关系，叶脉和叶肉是叶的组成部\n分，二者为并列关系，前后逻辑关系一致，当选；\nC 项，花蕊是花朵的组成部分，二者为组成关系，叶脉是叶片的组成部分，但是词语\n顺序反了，排除；\nD 项，花蜜是花的分泌物，花蕊是花的组成部分，二者没有必然联系，叶脉为叶提供\n水分，前后逻辑关系不一致，排除。\n故正确答案为B。"},{"q":"如芒在背：不安（  ）","options":["目无全牛：自大","前车之鉴：教训","墨守成规：守法","萍水相逢：巧合"],"a":1,"e":"【答案】B\n【解析】对应关系。如芒在背形容极度的不安，二者为对应关系。\nA 项，目无全牛指技艺高超，和自大没有必然联系，排除；\nB 项，前车之鉴比喻先前的失败，可以作为以后的教训，二者为对应关系，与题干逻\n辑关系一致，当选；\nC 项，墨守成规指守着老规矩不变，和守法没有必然联系，排除；\nD 项，萍水相逢指和不认识的人相遇，和巧合没有必然联系，排除。\n故正确答案为B。"},{"q":"商场：小卖部（  ）","options":["县城：农村","拖拉机：农用车","水稻：莲藕","工厂：作坊"],"a":3,"e":"【答案】D\n【解析】并列关系。商场与小卖部是并列关系，二者功能相同，都可以销售尚品，商\n场比小卖部规模更大。\nA 项，县城与农村是并列关系，但没有相同的功能，排除；\nB 项，拖拉机是农用车的一种，二者是种属关系，排除；\nC 项，水稻和莲藕都为农作物，二者为并列关系，也不存在规模大小的比较，排除；\nD 项，工厂和作坊是并列关系，功能相同，都可以生产产品，工厂比作坊规模更大，\n与题干逻辑关系一致，当选。\n故正确答案为D。"},{"q":"天真：幼稚（  ）","options":["小偷：强盗","懵懂：糊涂","公正：公平","懦弱：忍让"],"a":1,"e":"【答案】B\n【解析】近义关系。天真与幼稚都指思想简单、不复杂，二者是近义关系。\nA 项，小偷指偷东西的人，强盗指用暴力抢夺别人财物的人，二者不是近义关系，与\n题干逻辑关系不一致，排除；\nB 项，懵懂和糊涂都是指头脑不清楚，对事物的认识模糊，二者是近义关系，与题干\n逻辑关系一致，当选；\nC 项，公正指符合法律道德标准，公平主要指人与人之间平等，二者不是近义关系，\n与题干逻辑关系不一致，排除；\nD 项，懦弱指的是软弱无能；忍让指忍耐退让，二者不是近义关系，与题干逻辑关系\n不一致，排除。\n故正确答案为B。"},{"q":"高大：渺小（  ）","options":["无穷：无尽","春种：秋收","赞誉：诋毁","牛奶：面包"],"a":2,"e":"【答案】C\n【解析】反义关系。高大和渺小是反义关系。\nA 项，无穷和无尽都指没有尽头，二者为近义关系，与题干逻辑关系不一致，排除；\nB 项，春种和秋收都指耕作的不同阶段，二者不构成反义关系，排除；\nC 项，赞誉和诋毁二者构成反义关系，当选；\nD 项，牛奶和面包都是食品，二者为并列关系，排除。\n故正确答案为C。"},{"q":"计算：电脑（  ）","options":["可乐：饮料","热水：茶壶","载货：货车","火焰：灶台"],"a":2,"e":"【答案】C\n【解析】功能关系。计算是电脑的功能之一，而且从词性上看，计算是动词，电脑是\n名词。\nA 项，可乐是饮料的一种，二者为种属关系，与题干逻辑关系不一致，排除；\nB 项，热水和茶壶是对应关系，但不是功能对应，与题干逻辑关系不一致，排除；\nC 项，载货是货车的功能之一，而且从词性上看，载货是动词，货车是名词，与题干\n逻辑关系一致，当选；\nD 项，火焰与灶台是对应关系，但不是功能对应，与题干逻辑关系不一致，排除。\n故正确答案为C。\n第五组："},{"q":"和平：战争（  ）","options":["小生：老生","油画：素描","遗传：变异","整齐：凌乱"],"a":3,"e":"【答案】D\n【解析】反义关系。和平说的是没有战争的状态，二者为反义关系。\nA 项，小生和老生都是戏曲表演中的角色，二者是并列关系，与题干逻辑关系不一\n致，排除；\nB 项，油画和素描是两种不同方式的绘画，二者为并列关系，与题干逻辑关系不一\n致，排除；\nC 项，遗传和变异生物演化过程中的两种形式，二者为并列关系，与题干逻辑关系不\n一致，排除；\nD 项，整齐和凌乱二者为反义关系，与题干逻辑关系一致，当选。\n故正确答案为D。"},{"q":"艳羡：嫉妒（  ）","options":["崇拜：迷信","增长：衰退","淡漠：热心","排放：污染"],"a":0,"e":"【答案】A\n【解析】近义关系。二者说的都是羡慕的意思，二者是近义关系，而且艳羡是中性\n词，嫉妒是贬义词。\nA 项，崇拜和迷信是近义关系，而且崇拜是中性词，迷信是贬义词，与题干逻辑关系\n一致，当选；\nB 项，增长和衰退是反义关系，与题干逻辑关系不一致，排除；\nC 项，淡漠和热心是反义关系，与题干逻辑关系不一致，排除；\nD 项，排放可能导致污染，二者是或然因果关系，与题干逻辑关系不一致，排除。\n故正确答案为A。"},{"q":"花木：盆景（  ）","options":["布料：窗帘","轮胎：汽车","墨水：书画","石头：假山"],"a":3,"e":"【答案】D\n【解析】对应关系。盆景由花木等原材料制作而成，二者为原材料对应关系，且盆景\n为观赏类艺术品。\nA 项，窗帘由布料制作而成，二者为原材料对应关系，但窗帘不是观赏类艺术品，与\n题干逻辑关系不一致，排除；\nB 项，轮胎是汽车组成部分，二者为组成关系，与题干逻辑关系不符，排除；\nC 项，书画会用到墨水，但书画不是由墨水制作而成，与题干逻辑关系不符，排除；\nD 项，假山由石头制作而成，二者为原材料对应关系，且假山是观赏类艺术品，与题\n干逻辑关系一致，当选。\n故正确答案为D。"},{"q":"近视：远视（  ）","options":["雨水：冰雹","瘦弱：肥胖","前进：后退","收缩：松弛"],"a":1,"e":"【答案】B\n【解析】对应关系。近视和远视为相反的两种状态，并且是人体非健康的两种状态，\n二者是对应关系。\nA 项，雨水与冰雹是并列关系，与题干逻辑关系不一致，排除；\nB 项，瘦弱和肥胖是相反的状态，并且是人体非健康的两种状态，二者是对应关系，\n与题干逻辑关系一致，当选；\nC 项，前进与后退并不是人体两种非健康的状态，与题干逻辑关系不一致，排除；\nD 项，收缩和松弛并不是两种相反的状态，收缩相反的词应该是扩大，与题干逻辑关\n系不一致。\n故正确答案为B。"},{"q":"散步：走路：赶路（  ）","options":["战斗：战役：战争","想象：理想：幻想","休闲：无聊：空虚","好感：喜欢：热爱"],"a":3,"e":"【答案】D\n【解析】并列关系。散步、走路和赶路属于并列关系，都是指走路，而且三个词所形\n容的速度越来越快。\nA 项，战役是战争的一部分，二者属于组成关系，战斗是战役的组成部分，二者为组\n成关系，与题干逻辑关系不一致，排除；\nB 项，理想与幻想均与想象构成种属关系，排除；\nC 项，休闲与无聊、空虚不构成关系，排除；\nD 项，好感、喜欢与热爱属于并列关系，都表示喜爱，而且三个词所形容的喜爱的程\n度越来越深，与题干逻辑关系一致，当选。\n故正确答案为D。"},{"q":"空气：空调：冷气（  ）","options":["信号：电视：图像","食材：烹饪：美食","面粉：烤箱：面包","石油：提炼：汽油"],"a":0,"e":"【答案】A\n【解析】种属关系。空调将空气制成冷气，三者是对应关系，而且冷气是空气的一\n种。\nA 项，电视将信号转为图像，三者是对应关系，而且图像是信号的一种，与题干逻辑\n关系一致，当选；\nB 项，烹饪食材属于动宾关系，与题干逻辑关系不一致，排除；\nC 项，烤箱不能直接烤面粉，而是要烤面团，与题干逻辑关系不一致，排除；\nD 项，石油经过提炼后得到汽油，但汽油与石油并不属于种属关系，与题干逻辑关系\n不一致，排除。\n故正确答案为A。"},{"q":"天空：蔚蓝（  ）","options":["气氛：融洽","土地：耕种","茶叶：保健","河流：灌溉"],"a":0,"e":"【答案】A\n【解析】偏正关系。题干逻辑关系：蔚蓝的天空，偏正关系。\nA 项，融洽的气氛，偏正关系，与题干逻辑关系一致，当选；\nB 项，耕种土地为动宾关系，与题干逻辑关系不一致，排除；\nC 项，保健不能形容茶叶，与题干逻辑关系不一致，排除；\nD 项，灌溉河流为动宾关系，与题干逻辑关系不一致，排除。\n故正确答案为A。"},{"q":"蜡烛：电灯（  ）","options":["椅子：写字台","茶杯：饮水机","拖把：吸尘器","电视：计算机"],"a":2,"e":"【答案】C\n【解析】功能对应。题干逻辑关系：蜡烛和电灯两者功能相同，都是照明，且蜡烛是\n非电力驱动，电灯是电力驱动。\nA 项，椅子的功能是供人坐着，而写字台的功能是供人伏案写作，两者功能不同，与\n题干逻辑关系不一致，排除；\nB 项，茶杯是盛茶水的用具，饮水机是方便人们饮用的装置，两者功能不同，与题干\n逻辑关系不一致，排除；\nC 项，拖把的功能是擦除地面灰尘，吸尘器的功能也是清除地面灰尘，且拖把是非电\n力驱动，吸尘器是电力驱动，与题干逻辑关系一致，当选；\nD 项，电视机都可以计算机播放节目，但两者都是电力驱动，与题干逻辑关系不一\n致，排除。\n故正确答案为C。"},{"q":"富裕：扶贫（  ）","options":["干燥：抽湿","蒙昧：教育","落后：推进","健康：保卫"],"a":0,"e":"【答案】A\n【解析】目的对应。题干逻辑关系：通过扶贫达到富裕的目的，二者属于目的对应关\n系。\nA 项，通过抽湿达到干燥的目的，二者属于目的对应关系，与题干逻辑关系一致，当\n选；\nB 项，通过教育避免蒙昧，但蒙昧并非教育的目的，与题干逻辑关系不一致，排除；\nC 项，落后与推进无明显逻辑关系，排除；\nD 项，保卫与健康属于动宾关系，与题干逻辑关系不一致，排除。\n故正确答案为A。"},{"q":"干旱：沙漠（  ）","options":["笔直：树干","坚硬：水泥","寒冷：南极","多雨：赤道"],"a":2,"e":"【答案】C\n【解析】属性关系。题干逻辑关系；干旱是沙漠的必然属性。\nA 项，树干不必然是笔直的，与题干逻辑关系不一致，排除；\nB 项，水泥不必然是坚硬的（例如还没凝固的状态），与题干逻辑关系不一致，排\n除；\nC 项，南极一定是寒冷的，与题干逻辑关系一致，当选；\nD 项，赤道不一定是多雨的，赤道穿过不同气候类型的地区，不是所有地区都多雨，\n与题干逻辑关系不一致，排除。\n故正确答案为C。\n第六组："},{"q":"菜刀：食物（  ）","options":["子弹：枪支","毛巾：身体","铅笔：书籍","窗帘：窗户"],"a":1,"e":"【答案】B\n【解析】功能对应。菜刀的主要功能是用来切食物。\nA 项，子弹和枪支是配套使用的，与题干逻辑关系不一致，排除；\nB 项，毛巾的主要功能是擦身体，与题干逻辑关系一致，当选；\nC 项，铅笔的主要功能是写字，与题干逻辑关系不一致，排除；\nD 项，窗帘的主要功能是遮挡光线，与题干逻辑关系不一致，排除。\n故正确答案为B。"},{"q":"玉石：雕琢：玉器（  ）","options":["蚕丝：织造：丝绸","粮食：酿造：美酒","生铁：冶炼：钢材","蚊香：点燃：烟雾"],"a":0,"e":"【答案】A\n【解析】对应关系。题干逻辑关系：玉石经过雕琢制成玉器，且发生的是物理变化，\n三者为原材料、工艺和成品之间的对应关系。\nA 项，蚕丝经过织造制成丝绸，且发生的是物理变化，三者为原材料、工艺和成品之\n间的对应，而且织造发生的是物理变化，与题干逻辑关系一致，当选；\nB 项，粮食经过酿造制成美酒，为原材料、工艺和成品之间的对应，但酿造的过程存\n在化学变化，与题干逻辑关系不一致，排除；\nC 项，生铁通过冶炼制成钢材，为原材料、工艺和成品之间的对应，但冶炼的过程中\n存在化学变化，与题干逻辑关系不一致，排除；\nD 项，点燃蚊香产生烟雾，烟雾不是成品，与题干逻辑关系不一致，排除。\n故正确答案为A。"},{"q":"站台：码头：停机坪（  ）","options":["现金：支票：银行卡","软件：硬件：互联网","外套：婚纱：羽绒服","演员：群众：主持人"],"a":0,"e":"【答案】A\n【解析】反对关系。题干逻辑关系：站台，码头和停机坪，分别是火车、轮船和飞机\n的停靠场所，三者功能相似，属于反对关系。\nA 项，现金，支票和银行卡都有支付功能，三者功能相似，属于反对关系，与题干逻\n辑关系一致，当选；\nB 项，硬件和软件属于矛盾关系，与题干逻辑关系不一致，排除；\nC 项，外套和羽绒服属于交叉关系，与题干逻辑关系不一致，排除；\nD 项，演员，群众和主持人，三者职业身份不同，没有功能上的相似性，与题干逻辑\n关系不一致，排除。\n故正确答案为A。"},{"q":"沙龙：志趣相投（  ）","options":["论坛：千言万语","擂台：针锋相对","网站：集思广益","枢纽：承上启下"],"a":1,"e":"【答案】B\n【解析】对应关系。沙龙是为志趣相投的人提供的交流平台，志趣相投是参与人员的\n特点，二者属于对应关系。\nA 项，论坛是人们发表想法的平台，但千言万语并非参与人员的特点，与题干逻辑关\n系不一致，排除；\nB 项，擂台是为参与人员提供的比试平台，针锋相对是参与人员的特点，与题干逻辑\n关系一致，当选；\nC 项，网站可以起到集思广益的作用，但集思广益并不是参与人员的特点，与题干逻\n辑关系不一致，排除；\nD 项，枢纽具有承上启下的功能，但并非一个平台，与题干逻辑关系不一致，排除。\n故正确答案为B。"},{"q":"陈词滥调：老生常谈（  ）","options":["按部就班：循序渐进","博闻强识：见多识广","见义勇为：助人为乐","八面玲珑：面面俱到"],"a":3,"e":"【答案】D\n【解析】近义关系。陈词滥调指没有新意，陈腐、空泛的论调。老生常谈比喻人们听\n惯了的没有新意的话，二者为近义词，而且陈词滥调为贬义词，老生常谈为中性词。\nA 项，按部就班指按照一定的条理、步骤做事，循序渐进是指依照次序或步骤逐步深\n入或提高，为中性词。二者为近义关系，但二者都为中性词，与题干逻辑关系不一致，排\n除；\nB 项，博闻强识指知识丰富，记忆力强。见多识广指见得多，知道的广。二者为近义\n关系，但是二者都是褒义词，与题干逻辑关系不一致，排除；\nC 项，见义勇为与助人为乐都是人的两种优秀品质，二者为并列关系，与题干逻辑关\n系不一致，排除；\nD 项，八面玲珑形容为人处世圆滑，待人接物各方面都能巧妙应对。面面俱到指各方\n面都照顾得很周到，与八面玲珑为近义关系，而且八面玲珑是贬义词，面面俱到是中性\n词，与题干逻辑关系一致，当选。\n故正确答案为D。"},{"q":"吹毛求疵：鸡蛋里面挑骨头（  ）","options":["赶鸭子上架：牛不喝水强按头","敬酒不吃吃罚酒：不识抬举","舍本逐末：捡了芝麻丢了西瓜","福无双至：屋漏偏逢连夜雨"],"a":2,"e":"【答案】C\n【解析】近义关系。吹毛求疵是成语比喻故意挑剔别人的缺点。鸡蛋里挑骨头是俗语\n比喻故意挑剔，二者为近义关系。\nA 项，赶鸭子上架是俗语，比喻强迫去做能力所达不到的事情，牛不喝水强按头是成\n语比喻用强迫手段使就范，二者为近义关系，但两个词语位置颠倒，与题干逻辑关系不一\n致，排除；\nB 项，敬酒不吃吃罚酒是俗语，指被迫去做事情，不识抬举是成语，比喻不懂得别人\n对自己的好意，二者词语顺序颠倒，与题干逻辑关系不一致，排除；\nC 项，舍本逐末是成语，比喻不注意根本，追求细枝末节，捡了芝麻，丢了西瓜是俗\n语比喻做事因小失大，得不偿失。二者为近义关系。前者是成语，后者俗语，与题干逻辑\n关系一致，当选；\nD 项，福无双至是成语指幸运事不会接连到来，屋漏偏逢连夜雨是俗语，比喻不幸的\n事接二连三地发生，二者不属于近义。题干逻辑关系不一致，排除。\n故正确答案为C。"},{"q":"U 盘：光盘（  ）","options":["楼梯：电梯","插头：插座","国画：毛笔","水杯：杯盖"],"a":0,"e":"【答案】A\n【解析】并列关系。题干逻辑关系：U 盘和光盘都是存储工具，具有存储功能，二者\n是并列关系。\nA 项，楼梯和电梯都是到达不同楼层的工具，二者是并列关系，与题干逻辑关系一\n致，当选；\nB 项，插头和插座需要配套使用，二者是配套使用关系，与题干逻辑关系不一致，排\n除；\nC 项，毛笔是画国画的工具，二者是工具对应关系，与题干逻辑关系不一致，排除；\nD 项，杯盖是水杯的一部分，是组成关系，与题干逻辑关系不一致，排除。\n故正确答案为A。"},{"q":"春暖：花开（  ）","options":["和风：细雨","雨后：天晴","天寒：地冻","云开：雾散"],"a":2,"e":"【答案】C\n【解析】因果关系。题干逻辑关系：春暖是花开的原因，二者是因果关系。\nA 项，和风和细雨都是天气状态，二者属于并列关系，与题干逻辑关系不一致，排\n除；\nB 项，雨后不是天晴的原因，与题干逻辑关系不一致，排除；\nC 项，天寒是地冻的原因，二者是因果关系对应，与题干逻辑关系一致，当选；\nD 项，云开和雾散都是天气状态，二者属于并列关系，与题干逻辑关系不一致，排\n除。\n故正确答案为C。"},{"q":"投票：抽签（  ）","options":["联系：沟通","管理：服务","劝说：争辩","推荐：号召"],"a":2,"e":"【答案】C\n【解析】并列关系。题干逻辑关系：投票和抽签都是决定结果的方式之一，二者属于\n并列关系。\nA 项，联系和沟通是近义关系，与题干逻辑关系不一致，排除；\nB 项，管理在一定程度上是为了更好地服务，二者为目的对应关系，排除；\nC 项，劝说和争辩都是说服别人的方式之一，二者属于并列关系，与题干逻辑关系一\n致，当选；\nD 项，推荐是推举，介绍的意思；号召是向人发出通知，让大家响应所发出的号召，\n二者无明显逻辑关系，排除。\n故正确答案为C。"},{"q":"调研：座谈（  ）","options":["转型：创新","垄断：专营","发明：试验","秩序：通畅"],"a":0,"e":"【答案】A\n【解析】对应关系。题干逻辑关系：座谈是调研方式之一，二者是对应关系。\nA 项，创新是转型的方式之一，与题干逻辑关系一致，当选；\nB 项，垄断指把持和独占；专营指专门经营某种商品，二者无明显逻辑关系，与题干\n逻辑关系不一致，排除；\nC 项，发明是创造新事物的一个过程；试验指已知某种事物的时候，为了解它的性能\n或者结果而进行的试用操作，二者无明显逻辑关系，与题干逻辑关系不一致，排除；\nD 项，通畅是指通行无阻，秩序是有条理的，有组织的安排各个构成部分以求达到正\n常的状态，两者无明显逻辑关系，与题干逻辑关系不一致，排除。\n故正确答案为A。\n第七组："},{"q":"言论：自由（  ）","options":["版权：保护","危机：调控","生产：安全","设计：创新"],"a":2,"e":"【答案】C\n【解析】偏正关系。题干逻辑关系：自由的言论，偏正关系。\nA 项，保护版权，是动宾结构，与题干逻辑关系不一致，排除；\nB 项，调控，指的是调节、控制，与危机无必然逻辑关系，与题干逻辑关系不一致，\n排除；\nC 项，安全的生产，偏正结构，与题干逻辑关系一致，当选；\nD 项，可以说设计的创新，但词语顺序颠倒，排除。\n故正确答案为C。"},{"q":"清风：朗月（  ）","options":["钢墙：铁壁","斗转：星移","惊涛：骇浪","高山：流水"],"a":3,"e":"【答案】D\n【解析】并列关系。二者都是自然现象为并列关系，清风和朗月这两个词都是偏正结\n构。\nA 项，钢墙和铁壁为并列关系，但是钢墙和铁壁不是自然现象，与题干逻辑关系不一\n致，排除；\nB 项，斗转和星移都是自然现象为并列关系，但二者并不是偏正结构，与题干逻辑关\n系不一致，排除；\nC 项，惊涛和骇浪都是指浪很大，二者为同一关系，与题干逻辑关系不一致，排除；\nD 项，高山流水都是自然现象二者为并列关系，高山和流水这两个词都是偏正结构，\n与题干逻辑关系一致，当选。\n故正确答案为D。"},{"q":"水：火（  ）","options":["美：丑","有：无","左：右","红：绿"],"a":3,"e":"【答案】D\n【解析】并列关系。题干逻辑关系：金木水火土，水与火属于并列关系。\nA 项：美与丑属于并列关系，保留；\nB 项：有与无属于矛盾关系，与题干逻辑关系不一致，排除；\nC 项：左与右属于并列关系，保留；\nD 项：红与绿属于并列关系，保留。\n比较A、C、D 三项，题干中水、火是反对关系，但不是反义关系。而A 项中的美、\n丑，C 项中的左、右都是反义关系。\n故正确答案为D。"},{"q":"净水：过滤（  ）","options":["名次：竞赛","房屋：装修","苗条：节食","环境：绿化"],"a":2,"e":"【答案】C\n【解析】对应关系。题干逻辑关系：过滤是获得净水的方式之一，过滤是通过减少杂\n质达到净水的效果，有减少的一个过程。\nA 项，竞赛是获得名次的方式之一，但并没有减少的过程，与题干逻辑关系不一致，\n排除；\nB 项，装修不是获得房屋的方式之一，与题干逻辑关系不一致，排除；\nC 项，节食是获得苗条的方式之一，节食是通过减少食物摄入达到苗条，又减少的一\n个过程，与题干逻辑关系一致，当选；\nD 项，绿化不是获得环境的方式之一，与题干逻辑关系不一致，排除。\n故正确答案为C。"},{"q":"雾霾：污染：治理（  ）","options":["风扇：电器：使用","粳米：粮食：调查","信息：报纸：阅读","报告：文件：审批"],"a":0,"e":"【答案】A\n【解析】种属+动宾。题干逻辑关系：雾霾是污染的一种，二者为种属关系，治理与\n雾霾和污染都属于动宾关系。\nA 项，风扇是电器的一种，二者是种属关系，使用与风扇和电器都属于动宾结构，与\n题干逻辑关系一致，当选；\nB 项，粳米是粮食的一种，二者是种属关系，但调查与粳米和粮食之间无明显逻辑关\n系，与题干逻辑关系不一致，排除；\nC 项，报纸是信息的载体，与题干逻辑关系不一致，排除；\nD 项，有的报告是文件，有的文件是报告，二者为交叉关系，与题干逻辑关系不一\n致，排除。\n故正确答案为A。"},{"q":"好感：喜欢：热爱（  ）","options":["伤心：悲伤：悲哀","不安：紧张：焦躁","不悦：反感：厌恶","高兴：愉快：喜悦"],"a":1,"e":"【答案】B\n【解析】近义关系。题干逻辑关系：三者是近义关系，并且程度逐渐加深。\nA 项，三者是近义关系，但悲伤和悲哀没有程度加深，与题干逻辑关系不一致，排\n除；\nB 项，三者是近义关系，并且程度逐渐加深，与题干逻辑关系一致，当选；\nC 项，不悦指不高兴；反感是不满的情绪；厌恶是反感的情绪；反感与厌恶表示不\n满。三者不是近义关系，与题干逻辑关系不一致，排除；\nD 项，高兴通常指愉快；愉快指欢欣快乐；喜悦指欢乐快活。三者为近义关系，但程\n度无明显变化，与题干逻辑关系不一致，排除。\n故正确答案为B。"},{"q":"自行车：出行：环保（  ）","options":["蔬菜：食品：健康","台灯：灯泡：节能","手表：时间：指针","货车：运输：载体"],"a":0,"e":"【答案】A\n【解析】对应关系。题干逻辑关系：自行车是一种环保的出行方式，三者为对应关\n系。\nA 项，蔬菜是一种健康的食品，与题干逻辑关系一致，当选；\nB 项，灯泡是台灯的组成部分，二者为组成关系，与题干逻辑关系不一致，排除；\nC 项，手表是显示时间的工具，指针是手表的组成部分，题干逻辑关系不一致，排\n除；\nD 项，货车是运输工具，货车是运输的载体，与题干逻辑关系不一致，排除。\n故正确答案为A。"},{"q":"畅通：拥堵（  ）","options":["结实：松散","详尽：简略","踏实：忧虑","男性：女性"],"a":1,"e":"【答案】B\n【解析】反义关系。题干逻辑关系：畅通是指毫无障碍，顺利通过；拥堵指拥挤堵\n塞，二者为反义关系，同时也为反对关系。\nA 项，结实的反义词是虚弱；松散的反义词是紧密，二者不构成反义关系，与题干逻\n辑关系不一致，排除；\nB 项，详尽和简略，二者为反义关系，同时也为反对关系，与题干逻辑关系一致，当\n选；\nC 项，踏实的反义词是浮躁；忧虑的反义词是安心，二者不属于反义关系，与题干逻\n辑关系不一致，排除；\nD 项，男性和女性属于反义关系，但也是矛盾关系，与题干逻辑关系不一致，排除。\n故正确答案为B。"},{"q":"法律：遵守（  ）","options":["政策：推动","资源：利用","经济：发达","环境：整洁"],"a":1,"e":"【答案】B\n【解析】动宾关系。题干逻辑关系：遵守法律，动宾关系。\nA 项，推动政策的落实，而不能是推动政策，二者不属于动宾关系，排除；\nB 项，利用与资源属于动宾关系，与题干逻辑关系一致，当选；\nC 项，发达与经济属于偏正关系，与题干逻辑关系不一致，排除；\nD 项，整洁与环境属于偏正关系，与题干逻辑关系不一致，排除。\n故正确答案为B。"},{"q":"创新：发展（  ）","options":["批评：进步","辞旧：迎新","竞赛：夺冠","学习：提高"],"a":3,"e":"【答案】D\n【解析】对应关系。题干逻辑关系：创新是为了发展，目的对应，并且二者主体相\n同。\nA 项，批评是为了获得进步，但二者的主体不一致，排除；\nB 项，辞旧是指告别旧年，迎新是指迎接新的一年，二者为并列关系，与题干逻辑关\n系不一致，排除；\nC 项，参加竞赛的主要目的是为了比较技术的优劣，所以二者不属于目的对应，排\n除；\nD 项，学习是为了获得提高，二者为目的对应，并且二者主体相同，与题干逻辑关系\n一致，当选。\n故正确答案为D。\n第八组："},{"q":"钢笔：墨水（  ）","options":["牙刷：牙膏","手机：电脑","词典：报纸","壁画：台灯"],"a":0,"e":"【答案】A\n【解析】配套关系。题干逻辑关系；钢笔需要和墨水搭配使用，二者为配套使用关\n系。\nA 项，牙刷和牙膏搭配使用，二者为配套使用的关系，与题干逻辑关系一致，当选；\nB 项，手机和电脑均为电子产品，二者为并列关系，与题干逻辑关系不一致，排除；\nC 项，词典是工具书，报纸是印刷刊物，二者不属于配套使用关系，与题干逻辑关系\n不一致，排除；\nD 项，壁画和台灯没有必然的逻辑关系，与题干逻辑关系不一致，排除。\n故正确答案为A。"},{"q":"降价：促销（  ）","options":["编程：语言","复习：考试","实验：研究","实践：真理"],"a":2,"e":"【答案】C\n【解析】对应关系。降价是促销方式之一，二者为方式对应关系\nA 项，编程语言是一种计算机语言，二者并不是方式对应，排除；\nB 项，复习是为考试做准备，不是考试方式，与题干逻辑关系不一致，排除；\nC 项，实验是研究方式之一，二者为方式对应关系，与题干逻辑关系一致，当选；\nD 项，实践是检验真理的标准，二者不是方式对应关系，与题干逻辑关系不一致，排\n除。\n故正确答案为C。"},{"q":"有备：无患（  ）","options":["有口：无心","前赴：后继","苦尽：甘来","有眼：无珠"],"a":2,"e":"【答案】C\n【解析】因果关系。“有备”指事先有准备，“无患”指避免祸患，“无患”是“有\n备”的果，且“无患”是好的结果。\nA 项，“有口”、“无心”意思是嘴上说了，心里可没那样想，二者为并列关系，与\n题干逻辑关系不一致，排除；\nB 项，“前赴”、“后继”意思是前面的上去了，后面的紧跟上来，二者为时间关\n系，与题干逻辑关系不一致，排除；\nC 项，“苦尽”、“甘来”意思是艰苦的日子过完，美好的日子来到了，“甘来”是\n“苦尽”的果且“甘来”是好的结果，与题干逻辑关系一致，当选；\nD 项，“有眼”“无珠”用来责骂人瞎了眼，二者为并列关系，与题干逻辑关系不一\n致，排除。\n故正确答案为C。"},{"q":"摇曳：晃动（  ）","options":["自满：自谦","翻天覆地：一成不变","悲痛：欲绝","顺风转舵：见机行事"],"a":3,"e":"【答案】D\n【解析】近义关系。摇曳指摇荡、晃动指摇晃、摆动，二者为近义关系。\nA 项，自满，多指满足于自己已有的成绩而沾沾自喜的心理状态；自谦，指的是自己\n谦逊的态度，二者为反义关系，与题干逻辑关系不一致，排除；\nB 项，翻天覆地形容变化大；一成不变指的是一经形成，不再改变，二者为反义关\n系，与题干逻辑关系不一致，排除；\nC 项，悲痛指悲伤哀痛；欲绝指感情极其强烈的，非常激动的，用来形容悲痛的程\n度，二者为对应关系，与题干逻辑关系不一致，排除；\nD 项，顺风转舵比喻顺着情势改变态度；见机行事指看具体情况灵活办事，二者为近\n义关系，与题干逻辑关系一致，当选。\n故正确答案为D。"},{"q":"蛛丝马迹：鸟迹虫丝（  ）","options":["寒酸落魄：寒心酸鼻","堆玉积金：屯粮积草","冰肌玉骨：劲骨丰肌","挨冻受饿：担饿受冻"],"a":2,"e":"【答案】C\n【解析】偏正关系。蛛丝马迹可拆分为“蛛丝（蜘蛛的丝）”、“马迹（灶马留下的\n痕迹）”，鸟迹虫丝可拆分为“鸟迹（鸟的爪印）”、“虫丝（虫吐的丝）”，均为偏正\n结构。\nA 项，寒酸落魄指穷困、狼狈的样子，“寒酸”和“落魄”都是形容词，与题干逻辑\n关系不一致，排除；\nB 项，堆玉积金指金玉多得可以堆积起来，“堆玉”和“积金”是动宾结构；屯粮积\n草指储存粮食和草料，“屯粮”和“积草”是动宾结构，与题干逻辑关系不一致，排除；\nC 项，冰肌玉骨指肌骨如同冰玉一般，“冰肌（像冰一样的肌肤）”和“玉骨（像玉\n一样的肌骨）”是偏正结构；劲骨丰肌指书法有力而丰润，“劲骨（有力的骨架）”和\n“丰肌（丰满的肌肉）”也是偏正结构，与题干逻辑关系一致，当选；\nD 项，挨饿受冻指遭受饥饿与寒冷侵袭，“挨饿”和“受冻”是动宾结构，“担饿”\n和“受冻”也是动宾结构，与题干逻辑关系不一致，排除。\n故正确答案为C。"},{"q":"栉风：沐雨（  ）","options":["门当：户对","东山：再起","万里：长城","助人：为乐"],"a":0,"e":"【答案】A\n【解析】反对关系。栉风指的是以风梳头，沐雨指的是以雨洗发，二者为并列关系。\nA 项，门当与户对是古民居建筑中大门的组成部分，二者为并列关系，与题干逻辑关\n系一致，当选；\nB 项，东山是地点，再起是一个动作，二者是地点对应，与题干逻辑关系不一致，排\n除；\nC 项，万里是修饰长城的，二者为偏正关系，与题干逻辑关系不一致，排除；\nD 项，助人指的是帮助他人，为乐指当作快乐，二者为对应关系，与题干逻辑关系不\n一致，排除。\n故正确答案为A。"},{"q":"和衷共济：和合共生（  ）","options":["如临深渊：如履薄冰","或为玉碎：或为瓦全","不入虎穴：焉得虎子","锲而不舍：金石可镂"],"a":0,"e":"【答案】A\n【解析】近义关系。和衷共济，指团结互助，战胜困难；和合共生，指相互协助，共\n同发展，二者为近义关系。\nA 项，如临深渊，指如同处于深渊边缘一般，比喻存有戒心，行事极为谨慎；如履薄\n冰，指像走在薄冰上一样，比喻行事极为谨慎，存有戒心，二者为近义关系，与题干逻辑\n关系一致，当选；\nB 项，或为玉碎，指或者玉器被打碎；或为瓦全指或者瓦器被保全，二者无近义关\n系，与题干逻辑关系不一致，排除；\nC 项，不入虎穴，指不进入老虎的巢穴；焉得虎子，指怎么能捉到小老虎，二者无近\n义关系，与题干逻辑关系不一致，排除；\nD 项，锲而不舍，指不停地雕刻；金石可镂，指金属、玉石也可以雕出花饰，二者无\n近义关系，与题干逻辑关系不一致，排除。\n故正确答案为A。"},{"q":"固根基：扬优势：补短板（  ）","options":["清谈客：奋斗者：泥菩萨","勤思考：爱劳动：学习好","涉险滩：破坚冰：攻堡垒","有政治：有形象：有人格"],"a":2,"e":"【答案】C\n【解析】动宾关系。固根基、扬优势和补短板三者均为动宾关系的结构。\nA 项，清谈客，奋斗者，泥菩萨，三者均不是动宾关系的结构，与题干逻辑关系不一\n致，排除；\nB 项，勤思考，为偏正结构，与题干逻辑关系不一致，排除；\nC 项，涉险滩、破坚冰和攻堡垒三者均为动宾关系的结构，与题干逻辑关系一致，当\n选；\nD 项，有政治、有形象、有人格，这里的“有”没有实际意义，故三者均不是动宾关\n系，与题干逻辑关系不一致，排除。\n故正确答案为C。"},{"q":"青年人：公务员：服务人民（  ）","options":["当代史：革命史：史海耕耘","下农村：进工厂：劳动锻炼","创业者：劳动者：市场打拼","大学生：志愿者：奉献社会"],"a":3,"e":"【答案】D\n【解析】交叉关系。有的青年人是公务员，有的公务员是青年人，二者是交叉关系，\n公务员的宗旨是服务人民，二者是对应关系。\nA 项，世界当代史为1945 年-至今，中国当代史为1949 年-至今，而革命史指二战结\n束前（1945 年）一些具有历史意义革命的历史，当代史与革命史时间范围上没有交叉，\n与题干逻辑关系不一致，排除；\nB 项，下农村和进工厂是两种不同的劳动锻炼方式，二者是并列关系，与题干逻辑关\n系不一致，排除；\nC 项，创业者是主导劳动方式的领导人，劳动者是对从事劳作活动的一类人的统称，\n创业者是劳动者，二者是种属关系，与题干逻辑关系不一致，排除；\nD 项，有的大学生是志愿者，有的志愿者是大学生，二者是交叉关系，志愿者的宗旨\n是奉献社会，二者为对应关系，与题干逻辑关系一致，当选。\n故正确答案为D。"},{"q":"大豆：豆油：压榨（  ）","options":["茶叶：茶水：冲泡","水泥：房屋：建造","布料：成衣：缝制","太阳：阳光：辐射"],"a":2,"e":"【答案】C\n【解析】原材料+工艺对应关系。大豆是豆油的原材料，压榨是制作豆油的工艺，三\n者为原材料、工艺和成品的对应关系，且大豆是豆油的主要原材料。\nA 项，茶叶是茶水的组成部分，二者为组成关系，与题干逻辑关系不一致，排除；\nB 项，水泥是房屋的原材料，建造是房屋的工艺，三者为原材料、工艺和成品的对应\n关系，与题干逻辑关系一致，但水泥不是房屋的主要原材料，排除；\nC 项，布料是成衣的原材料，缝制是成衣的工艺，三者为原材料、工艺和成品的对应\n关系，与题干逻辑关系一致，且布料是成衣的主要原材料，当选；\nD 项，太阳辐射出阳光，三者不是原材料、工艺和成品的对应关系，与题干逻辑关系\n不一致，排除。\n故正确答案为C。\n第九组："},{"q":"和谐对于（  ）相当于谦虚对于（  ）","options":["强硬蛮横；安分守己","融洽无间；夜郎自大","波澜不惊；虚怀若谷","动荡不安；趾高气扬"],"a":3,"e":"【答案】D\n【解析】反义关系。选项代入题干。\nA 项，强硬蛮横是形容一个人态度粗暴而不讲理，与和谐没有明显逻辑关系；安分守\n己是指规矩、本分，不做违规、违纪、违法之事，与谦虚没有明显逻辑关系，排除；\nB 项，融洽无间是指融合而没有隔阂抵触，与和谐是近义关系；夜郎自大比喻妄自尊\n大，与谦虚是反义关系，前后逻辑关系不一致，排除；\nC 项，波澜不惊比喻局面平静、形势平稳，没有什么变化或曲折，与和谐没有明显逻\n辑关系，排除；\nD 项，动荡不安形容局势不稳定，不平静，与和谐是反义词；趾高气扬形容骄傲自\n满，得意忘形的样子，与谦虚是反义词，前后逻辑关系一致，当选。\n故正确答案为D。"},{"q":"（  ）对于探月相当于北斗三号对于（  ）","options":["玉兔二号；通信","嫦娥四号；导航","长征五号；短信","绕月卫星；授时"],"a":1,"e":"【答案】B\n【解析】功能对应关系。将选项代入题干。\nA 项，玉兔二号是嫦娥四号任务月球车，有探月的功能，但不是探月任务的主体；北\n斗三号是全球卫星导航系统，有通信的功能，且是通信功能的主体，前后逻辑关系不一\n致，排除；\nB 项，嫦娥四号是是中国探月工程二期发射的月球探测器，有探月的功能，北斗三号\n有导航的功能，二者为功能对应关系，前后逻辑关系一致，当选；\nC 项，长征五号是一种大型低温液体捆绑式运载火箭，它的功能是运载，与探月没有\n明显逻辑关系，排除；\nD 项，绕月卫星是绕着月球运转的人造卫星总称，包含多个卫星，是一类概念，而北\n斗三号具体的概念，前后逻辑关系不一致，排除。\n故正确答案为B。"},{"q":"嘈杂：环境安静（  ）","options":["疲劳：驾驶安全","粗心：头脑清醒","迟缓：工作效率","温暖：抵御寒冬"],"a":0,"e":"【答案】A\n【解析】因果关系。嘈杂导致环境不安静。\nA 项，疲劳导致驾驶不安全，二者属于因果关系，与题干逻辑关系一致，当选；\nB 项，粗心是头脑不清醒的一种状态，二者属于对应关系，与题干逻辑关系不一致，\n排除；\nC 项，工作效率分为高效或低效，迟缓和工作效率，二者无明显逻辑关系，排除；\nD 项，温暖与抵御寒冬无关，与题干逻辑关系不一致，排除。\n故正确答案为A。"},{"q":"助听器：眼镜（  ）","options":["钢笔：日记","轮船：邮轮","房屋：别墅","冰箱：烤箱"],"a":3,"e":"【答案】D\n【解析】并列关系。助听器与眼镜都是辅助工具，二者为并列关系。\nA 项，钢笔可以用来写日记，与题干逻辑关系不一致，排除；\nB 项，邮轮是一种轮船，二者为种属关系，与题干逻辑关系不一致，排除；\nC 项，别墅是房屋的一种，二者为种属关系，与题干逻辑关系不一致，排除；\nD 项，冰箱和烤箱都是家用电器，二者为并列关系，与题干逻辑关系一致，当选。\n故正确答案为D。"},{"q":"臭豆腐：香菇（  ）","options":["热干面：凉水","黑芝麻：白菜","小麦：大米","甜菜：苦瓜"],"a":0,"e":"【答案】A\n【解析】人工与自然。臭豆腐是人工制作而成，是人工产物，香菇是自然产物。\nA 项，热干面是人工产物，凉水是自然产物。与题干逻辑关系一致，当选；\nB 项，黑芝麻和白菜，二者均为自然产物，与题干逻辑关系不一致，排除；\nC 项，小麦和大米，二者均为自然产物，与题干逻辑关系不一致，排除；\nD 项，甜菜和苦瓜，二者均为自然产物，与题干逻辑关系不一致，排除。\n故正确答案为A。"},{"q":"冰：水（  ）","options":["木：炭","桑田：沧海","犬：獒","火：灰"],"a":0,"e":"【答案】A\n【解析】对应关系。冰融化后变成水，二者为对应关系。\nA 项，木经过燃烧变为炭，二者为对应关系，与题干逻辑关系一致，当选；\nB 项，沧海即大海，桑田即为农田，二者都是景观的一种，是并列关系，排除；\nC 项，獒是犬的一种，二者属于种属关系，与题干逻辑关系不一致，排除；\nD 项，灰是某些物质经火烧后的产物，二者无明显逻辑关系，排除。\n故正确答案为A。"},{"q":"轮椅：汽车（  ）","options":["公路：马路","火车：水车","缆车：索道","飞机：坦克"],"a":3,"e":"【答案】D\n【解析】反对关系。轮椅和汽车都属于交通工具，二者为反对关系。\nA 项，公路属于马路，二者为种属关系，与题干逻辑关系不一致，排除；\nB 项，火车是交通工具，水车是灌溉工具，二者无明显逻辑关系，排除；\nC 项，索道与缆车是配套使用，二者为对应关系，与题干逻辑关系不一致，排除；\nD 项，飞机和坦克都是作战工具，二者为反对关系，与题干逻辑关系一致，当选。\n故正确答案为D。"},{"q":"黄桃：水蜜桃：桃（  ）","options":["红缨枪：冲锋枪：枪","地中海：大海：海","煎饼：烧饼：饼","雏菊：杭菊：菊"],"a":3,"e":"【答案】D\n【解析】并列关系。黄桃和水蜜桃都属于桃的一种，二者为并列关系，且都是自然产\n物。\nA 项，红缨枪是刺击用的长矛，冲锋枪是现代发射子弹的热武器，二者不属于并列关\n系，排除；\nB 项，大海和海是同一关系，与题干逻辑关系不一致，排除；\nC 项，煎饼和烧饼都是饼的一种，但两者都是人工制成品，与题干逻辑关系不一致，\n排除；\nD 项，雏菊和杭菊都属于菊的一种，二者为并列关系，且都是自然产物，当选。\n故正确答案为D。"},{"q":"激发：激荡：激切（  ）","options":["激化：激愤：激扬","激剧：激情：激增","激怒：激将：激昂","激活：激流：激奋"],"a":2,"e":"【答案】C\n【解析】词性关系。激发是动词，激荡是动词，激切是形容词。\nA 项，激愤是形容词，与题干逻辑关系不一致，排除；\nB 项，激剧是形容词，与题干逻辑关系不一致，排除；\nC 项，激怒是动词，激将是动词，激昂是形容词，与题干逻辑关系一致，当选；\nD 项，激流是名词，与题干逻辑关系不一致，排除。\n故正确答案为C。"},{"q":"电影院：观众：观影（  ）","options":["广播：听众：主播","医生：病人：问诊","演唱会：歌手：演唱","发布会：记者：提问"],"a":3,"e":"【答案】D\n【解析】对应关系。观众在电影院观影，并且观众是客体，电影院是个场所。\nA 项，广播不是一个场所，与题干逻辑关系不一致，排除；\nB 项，医生不是一个场所，与题干逻辑关系不一致，排除；\nC 项，歌手在演唱会演唱，但是歌手是主体，与题干逻辑关系不一致，排除；\nD 项，记者在发布会提问，记者是客体，发布会是个场所，与题干逻辑关系一致，当\n选。\n故正确答案为D。\n第十组："},{"q":"头发：颜色：长度（  ）","options":["狗：品种：性格","蔬菜：价格：营养","衣服：款式：尺码","人：长相：气质"],"a":2,"e":"【答案】C\n【解析】对应关系。颜色和长度是头发的不同外在表现形式。\nA 项，品种和性格是狗的不同表现形式，但性格是内在的，与题干逻辑关系不一致，\n排除；\nB 项，价格和营养是蔬菜的不同表现形式，但营养是内在的，与题干逻辑关系不一\n致，排除；\nC 项，款式和尺码是衣服的不同外在表现形式，与题干逻辑关系一致，当选；\nD 项，长相和气质是人的不同表现形式，但气质是内在的，与题干逻辑关系不一致，\n排除。\n故正确答案为C。"},{"q":"设计：修建：高楼（  ）","options":["痛恨：打击：仇敌","热爱：学习：书本","体检：判断：病人","勘探：开采：石油"],"a":3,"e":"【答案】D\n【解析】时间关系。高楼需要先设计再修建，设计和修建，二者为时间关系。\nA 项，痛恨与打击不存在明显的时间先后顺序，排除；\nB 项，热爱与学习属于动宾关系，不存在时间先后顺序，排除；\nC 项，先体检再判断，但体检病人和判断病人搭配不当，排除；\nD 项，石油先勘探再开采，二者为时间顺承关系，与题干逻辑关系一致，当选。\n故正确答案为D。"},{"q":"正方形：立方体（  ）","options":["三角形：棱形","直线：平面","圆：球","四边形：八面体"],"a":2,"e":"【答案】C\n【解析】对应关系。立方体就是正方体，它的三视图均为正方形，且内部无线条，二\n者为对应关系。A 项，棱形是只具有棱的立体图形，棱形的三视图并非都是三角形，排\n除；B 项，平面不是立体图形，没有三视图，排除；C 项，球的三视图都是圆，且内部无\n线条，二者为对应关系，与题干逻辑关系一致，当选；D 项，八面体是由八个正三角形构\n成的棱锥体，八面体的三视图外轮廓是四边形，但里面有线条，排除。故正确答案为C。"},{"q":"无机物：化合物（  ）","options":["中草药：野菜","二氧化碳：有机盐","空间：时间","原子：电子"],"a":0,"e":"【答案】A\n【解析】交叉关系。无机物包括单质和无机化合物。化合物包括有机化合物和无机化\n合物。\nA 项，有些中草药是野菜，有些野菜是中草药，二者之间为交叉关系，与题干逻辑关\n系一致，当选；\nB 项，二氧化碳属于无机物，所以与有机盐没有必然联系，与题干逻辑关系不一致，\n排除；\nC 项，空间和时间都是一种物质客观存在的形式，二者为并列关系，与题干逻辑关系\n不一致，排除；\nD 项，原子由原子核和绕核运动的电子组成，所以电子是原子的组成部分，二者为组\n成关系，与题干逻辑关系不一致，排除。\n故正确答案为A。"},{"q":"报销：凭据：发票（  ）","options":["平衡：支出：消费","乘车：凭证：车票","辩护：律师：法律","观赏：电影：门票"],"a":1,"e":"【答案】B\n【解析】种属关系+功能对应。发票是报销的凭据，发票是一种凭据，二者为种属关\n系，发票与报销属于功能对应关系。\nA 项，平衡和支出之间没有明显的逻辑关系，与题干逻辑关系不一致，排除；\nB 项，车票是乘车的凭证，车票是一种凭证，二者为种属关系，车票与乘车是功能对\n应关系，与题干逻辑关系一致，当选；\nC 项，辩护需要律师，法律是律师的工具，与题干逻辑关系不一致，排除；\nD 项，观赏电影是动宾结构，与题干逻辑关系不一致，排除。\n故正确答案为B。"},{"q":"青岛：城市：沿海地区（  ）","options":["苹果：水果：果树","矿泉水：饮料：茶杯","足球：运动：草坪","公交车：公路：市区"],"a":0,"e":"【答案】A\n【解析】种属关系+组成关系。青岛是沿海地区的一座城市，青岛与城市是种属关\n系，青岛是沿海地区的一部分，二者为组成关系。\nA 项，苹果是一种生长在果树上的水果，苹果与水果是种属关系，苹果是果树的一部\n分，二者为组成关系，与题干逻辑关系一致，当选；\nB 项，矿泉水不是一种饮料，与题干逻辑关系不一致，排除；\nC 项，足球是一种球类，而非一种运动，与题干逻辑关系不一致，排除；\nD 项，公交车在公路上行驶，二者之间是地点对应关系，与题干逻辑关系不一致，排\n除。\n故正确答案为A。"},{"q":"民歌对于（  ）相当于（  ）对于航天器","options":["民谣；飞机","民间；太空","舞曲；宇航员","歌曲；飞船"],"a":3,"e":"【答案】D\n【解析】种属关系+地点对应。代入选项。\nA 项，民歌与民谣是同一关系，飞机与航天器是种属关系，前后逻辑关系不一致，排\n除；\nB 项，民歌是民间传唱的歌曲，航天器是在太空飞行的仪器，但是前后顺序相反，排\n除；\nC 项，民歌和舞曲是两种艺术形式，二者为并列关系。宇航员在航天器内工作，二者\n为地点对应关系，前后逻辑关系不一致，排除；\nD 项，民歌是一种歌曲，二者是种属关系，飞船是一种航天器，二者也是种属关系，\n前后逻辑关系一致，当选。\n故正确答案为D。"},{"q":"鸭子：河（  ）","options":["摩天轮：过山车","喜剧：话剧","飞机：飞机场","火车：轨道"],"a":2,"e":"【答案】C\n【解析】地点对应。河是鸭子活动的场所，但是也可以在陆地上活动，河不是鸭子的\n唯一活动场所。\nA 项，摩天轮与过山车都是游乐场的娱乐设施，属于并列关系，与题干逻辑关系不一\n致，排除；\nB 项，有的喜剧是话剧，有的话剧是喜剧，属于交叉关系，与题干逻辑关系不一致，\n排除；\nC 项，飞机场是飞机的停放场所，且飞机可以在空中飞行，飞机场也不是飞机的唯一\n活动场所，与题干逻辑关系一致，当选；\nD 项，火车在轨道上行驶，但是不能在其他道路上行驶，轨道是火车的唯一活动场\n所，与题干逻辑关系不一致，排除。\n故正确答案为C。"},{"q":"水泥：建房（  ）","options":["水杯：解渴","船桨：船帆","瓢：舀水","血：循环"],"a":2,"e":"【答案】C\n【解析】功能对应。水泥是用来建造房屋的。\nA 项，水杯是用来盛水的工具，并不具备解渴功能，与题干逻辑关系不一致，排除；\nB 项，船桨和船帆都是船的组成部分，属于并列关系，与题干逻辑关系不一致，排\n除；\nC 项，瓢有舀水功能，也是功能对应，与题干逻辑关系一致，当选；\nD 项，血是在人体内循环，血的功能并非循环，与题干逻辑关系不一致，排除。\n故正确答案为C。"},{"q":"书籍：人类进步的阶梯：《进化论》（  ）","options":["跑步：使人健康的方式：强壮","语言：心灵的桥梁：汉语","月亮：天空中的小船：天体","舞蹈：流动的符号：表演"],"a":1,"e":"【答案】B\n【解析】比喻义。把书籍比喻为人类进步的阶梯，为比喻义；《进化论》是一种书\n籍，为种属关系。\nA 项，跑步是使人健康的方式之一，为种属关系，并非比喻义，排除；\nB 项，把语言比喻心灵的桥梁，是比喻义，且汉语是语言的一种，为种属关系，与题\n干逻辑关系一致，当选；\nC 项，月亮是天空中的小船，运用的是比喻义，月亮是天体的一种，但是顺序相反，\n排除；\nD 项，把舞蹈比喻成流动的符号，运用的是比喻义，舞蹈是表演的一种，为种属关\n系，但是顺序相反，排除。\n故正确答案为B。\n第十一组："},{"q":"歌唱家：歌唱：歌曲（  ）","options":["厨师：烹饪：食物","学生：学习：考试","律师：法院：案件","清洁工：施肥：垃圾"],"a":0,"e":"【答案】A\n【解析】词语语法。歌唱家歌唱歌曲，三者为主谓宾的关系。\nA 项，厨师烹饪食物，三者为主谓宾的关系，与题干逻辑关系一致，当选；\nB 项，学习考试，搭配不当，与题干逻辑关系不一致，排除；\nC 项，法院是律师的工作地点，与题干逻辑关系不一致，排除；\nD 项，清洁工清扫垃圾，与施肥无明显关系，排除。\n故正确答案为A。"},{"q":"报名：培训：结业（  ）","options":["高考：招生：毕业","设计：产品：使用","驾驶：公路：旅行","挂号：看病：痊愈"],"a":3,"e":"【答案】D\n【解析】时间顺承。先报名，再进行培训，最后的结果之一是结业，属于时间关系。\nA 项，高考后招生，但是招生的结果不是毕业，与题干逻辑关系不一致，排除；\nB 项，设计产品是动宾关系，使用产品也是动宾关系，与题干逻辑关系不一致，排\n除；\nC 项，在公路上驾驶，二者属于地点对应关系，与题干逻辑关系不一致，排除；\nD 项，先挂号，再看病，最后的结果之一是痊愈，属于时间关系，与题干逻辑关系一\n致，当选。\n故正确答案为D。"},{"q":"资料：文件（  ）","options":["质量：砝码","飞艇：航空器","护卫舰：补给舰","自然现象：极光"],"a":3,"e":"【答案】D\n【解析】种属关系。文件属于资料的一种。\nA 项，砝码是衡量质量的工具，二者为功能对应关系，与题干逻辑关系不一致，排\n除；\nB 项，飞艇是航空器的一种，二者为种属关系，但两词位置与题干相反，排除；\nC 项，护卫舰与补给舰都属于舰艇，二者为并列关系，与题干逻辑关系不一致，排\n除；\nD 项，极光属于自然现象，二者为种属关系，与题干逻辑关系一致，当选。\n故正确答案为D。"},{"q":"开：关（  ）","options":["小麦：水稻","痛苦：快乐","盈利：非盈利","工作：休息"],"a":2,"e":"【答案】C\n【解析】矛盾关系。开、关是一个事物的两种状态，二者为矛盾关系。\nA 项，小麦与水稻都是农作物，除此之外还有其他农作物，二者为反对关系，排除；\nB 项，痛苦与快乐都是感受，除此之外还有其他感受，二者为反对关系，排除；\nC 项，盈利与非盈利是非此即彼的关系，二者为矛盾关系，与题干逻辑关系一致，当\n选；\nD 项，工作与休息都是生活状态，除此之外还有其他生活状态，二者为反对关系，排\n除。\n故正确答案为C。"},{"q":"拍卖公告：拍卖：交付（  ）","options":["起诉：应诉：庭审","感冒：服药：发热","泡茶：加水：饮用","开机：关机：重启"],"a":0,"e":"【答案】A\n【解析】时间顺承。先发布拍卖公告，然后进行拍卖，最后确认交付。\nA 项，先进行起诉，然后对方应诉，最后进行庭审，三个事件的发生符合时间先后顺\n序，与题干逻辑关系一致，当选；\nB 项，发热是伴随感冒一同出现的，与题干逻辑关系不一致，排除；\nC 项，加水是泡茶的一个过程，目的是为了饮用，与题干逻辑关系不一致，排除；\nD 项，先开机才能关机，关机就不能重启，与题干逻辑关系不一致，排除。\n故正确答案为A。"},{"q":"药物：手术：治疗（  ）","options":["火车：公路：运输","现金：信用卡：金融","物质：精神：文明","电子邮件：短信：通讯"],"a":3,"e":"【答案】D\n【解析】并列关系。药物和手术为并列关系，二者都是治疗手段，且治疗是一个动\n词。\nA 项，火车和公路不是并列关系，铁路和公路才为并列关系，排除；\nB 项，现金和信用卡是并列关系，二者都是金融工具，但金融是名词，排除；\nC 项，物质和精神是并列关系，二者都属于文明，但文明是名词，排除；\nD 项，电子邮件和短信为并列关系，二者都属于通讯方式，且通讯是动词，与题干逻\n辑关系一致，当选。\n故正确答案为D。"},{"q":"航空母舰 对于（  ）相当于 潜艇 对于（  ）","options":["巡洋舰；导弹","舰载机；鱼雷","常规动力；核动力","远程偷袭；协同攻击"],"a":1,"e":"【答案】B\n【解析】对应关系。逐一代入选项。\nA 项，航空母舰和巡洋舰是并列关系，但是潜艇上可以搭载导弹两者不是并列关系，\n前后逻辑关系不一致，排除；\nB 项，舰载机是航空母舰上的一种作战工具，鱼雷是潜艇上的一种作战工具，前后逻\n辑关系一致，当选；\nC 项，航空母舰不一定是常规动力驱动，潜艇也不一定为核动力驱动，前后逻辑关系\n不一致，排除；\nD 项，航空母舰的作用不一定为远程偷袭，潜艇的作用也不一定为协同攻击，前后逻\n辑关系不一致，排除。\n故正确答案为B。"},{"q":"空运：海运：运输（  ）","options":["平装：精装：装帧","货轮：客轮：邮轮","晚会：聚会：集会","试飞：试航：航天"],"a":0,"e":"【答案】A\n【解析】并列关系。空运与“海运”是两种不同的“运输”方式，“空运”与“海\n运”属于并列关系，二者与“运输”属于方式对应关系。\nA 项，平装与精装是两种不同的装帧方式，平装与精装属于并列关系，二者与装帧属\n于方式对应关系，与题干逻辑关系一致，当选；\nB 项，货轮与客轮属于并列关系，邮轮指海洋上的定线、定期航行的大型客运轮船，\n是客轮的一种，二者属于包含关系中的种属关系，排除；\nC 项，晚会指晚上的集会，二者属于包含关系中的种属关系，排除；\nD 项，试飞指在飞机交付使用之前，对飞机进行飞行测试，试航指对飞机或舰船等进\n行试验性航行，“试航”包括“试飞”，二者属于包含关系，排除。\n故正确答案为A。"},{"q":"指鹿为马：颠倒黑白（  ）","options":["师心自用：固执己见","目无全牛：鼠目寸光","不以为然：不屑一顾","不孚众望：众望所归"],"a":0,"e":"【答案】A\n【解析】近义关系。题干逻辑关系：“指鹿为马”是指着鹿，说是马，比喻故意颠倒\n黑白，混淆是非。“颠倒黑白”意思是把黑的说成白的，白的说成黑的，比喻歪曲事实，\n混淆是非，指鹿为马。二者为近义词关系。\nA 项，师心自用意思是只相信自己，固执己见意思是不肯接受别人的正确意见，而坚\n持自己的意见。二者为近义词，与题干逻辑关系一致，当选；\nB 项，目无全牛形容技艺已经到达非常纯熟的地步，鼠目寸光比喻目光短浅，缺乏远\n见，二者不是近义词，与题干逻辑关系不一致，排除；\nC 项，不以为然意思是不认为是对的，表示不同意或否定。不屑一顾意思是认为不值\n得一看，形容极端轻视，二者不是近义词，与题干逻辑关系不一致，排除；\nD 项，不孚众望意思是不能使大家信服。众望所归是指某人得到大家的信赖，希望他\n担任某项工作或完成事情，二者不是近义词，与题干逻辑关系不一致，排除。\n故正确答案为A。"},{"q":"（  ）对于美丽相当于春风满面对于（  ）","options":["楚楚动人；愉快","笑靥如花；兴奋","眉开眼笑；高兴","心地善良；滋润"],"a":0,"e":"【答案】A\n【解析】近义关系。分别代入题干分析。\nA 项，楚楚动人对于美丽，楚楚动人形容姿容美好，动人心神，形容人很美丽，二者\n构成近义关系；春风满面形容人愉快，前后逻辑关系一致，当选；\nB 项，笑靥如花形容女子的笑脸像花儿一样美丽，但春风满面不形容兴奋，前后逻辑\n关系不一致，排除；\nC 项，眉开眼笑形容人高兴愉快的样子，不形容人美丽，前后逻辑关系不一致，排\n除。\nD 项，心地善良指有道德、德行好，不形容美丽，前后逻辑关系不一致，排除；\n故正确答案为A。\n第十二组："},{"q":"鱼饵：鱼竿（  ）","options":["笔：书籍","写诗：笔","锅铲：炒锅","电脑：无线路由器"],"a":2,"e":"【答案】C\n【解析】对应关系。题干逻辑关系：鱼饵和鱼竿为必然的配套关系。\nA 项，笔可以用来写书籍，但是写书籍还可以用电脑打印等方式，二者不是必然的配\n套关系，与题干逻辑关系不一致，排除；\nB 项，笔可以用来写诗，但是写诗可以用电脑等方式，二者也不是必然的配套关系，\n与题干逻辑关系不一致，排除；\nC 项，锅铲和炒锅为必然的配套关系，与题干逻辑关系一致，当选；\nD 项，电脑和无线路由器可以分开使用，二者不是必然的配套关系，与题干逻辑关系\n不一致，排除。\n故正确答案为C。"},{"q":"沟通：手机：金属（  ）","options":["招聘：面试：简介","物流：运输：公路","卫星：科技：科学家","露营：帐篷：帆布"],"a":3,"e":"【答案】D\n【解析】功能关系。题干逻辑关系；手机功能是用于沟通，二者构成功能关系，制成\n手机的材料是金属，二者属于原材料对应关系。\nA 项，简介不是面试的材料，与题干逻辑关系不一致，排除；\nB 项，可以通过公路运输，公路不是运输的材料，与题干逻辑关系不一致，排除；\nC 项，科学家是研发卫星的人，可以发展科技，与题干逻辑关系不一致，排除；\nD 项，帐篷用于露营，帐篷的材料就是帆布，与题干逻辑关系一致，当选。\n故正确答案为D。"},{"q":"麻雀：动物：生物链（  ）","options":["豆浆：早餐：豆制品","开水：纸杯：便利品","发卡：首饰：妆扮品","钢笔：电脑：办公品"],"a":2,"e":"【答案】C\n【解析】种属关系。题干逻辑关系：麻雀是一种动物，二者为种属关系，而麻雀和动\n物都是生物链上的一环。\nA 项，豆浆是一种早餐，二者为种属关系，早餐不是豆制品的组成部分，与题干逻辑\n关系不一致，排除；\nB 项，开水不是纸杯的一种，二者不是种属关系，与题干逻辑关系不一致，排除；\nC 项，发卡是首饰的一种，二者是种属关系，发卡和首饰都是妆扮品，与题干逻辑关\n系一致，当选；\nD 项，钢笔不是电脑的一种，二者不属于种属关系，与题干逻辑关系不一致，排除。\n故正确答案为C。"},{"q":"报刊：新闻（  ）","options":["土地：玉米","法院：法律","出版社：书籍","唱片：歌曲"],"a":3,"e":"【答案】D\n【解析】对应关系。题干逻辑关系：报刊是新闻的载体，二者构成载体对应关系。\nA 项，玉米在土地上种植，二者为农作物和种植地的关系，与题干逻辑关系不一致，\n排除；\nB 项，法院是司法机关，法律是律法，法院并不是法律的载体，与题干逻辑关系不一\n致，排除；\nC 项，书籍在出版社出版，出版社并不是书籍的载体，与题干逻辑关系不一致，排\n除；\nD 项，唱片是歌曲的载体，二者构成载体对应关系，与题干逻辑关系一致，当选。\n故正确答案为D。"},{"q":"港湾：停泊（  ）","options":["基因：遗传","法庭：诉讼","电缆：发电","公路：运输"],"a":3,"e":"【答案】D\n【解析】地点对应。题干逻辑关系：港湾是停泊的一个地点，二者为地点对应关系，\n并且港湾为具体地点。\nA 项，基因是遗传物质的基本单位，与题干逻辑关系不一致，排除；\nB 项，法庭是诉讼的一个地点，与题干逻辑关系一致，但是法庭不是一个具体的地\n点，排除；\nC 项，电缆不是一个地点，与题干逻辑关系不一致，排除；\nD 项，公路是运输的一个地点，与题干逻辑关系一致，并且公路为一个具体的地点，\n当选。\n故正确答案为D。"},{"q":"谎言：欺骗（  ）","options":["谣言：抱怨","谗言：无知","佯言：委婉","诤言：劝诫"],"a":3,"e":"【答案】D\n【解析】目的对应+词性。题干逻辑关系：谎言的目的是欺骗，其中前者为名词，后\n者为动词。\nA 项，谣言的目的并非抱怨，与题干逻辑关系不一致，排除；\nB 项，谗言的目的不是无知，与题干逻辑关系不一致，排除；\nC 项，佯言的目的不是委婉，与题干逻辑关系不一致，排除；\nD 项，诤言意为直率地规劝人改正过错的话，名词词性。诤言的目的为劝诫，与题干\n逻辑关系一致，当选。\n故正确答案为D。"},{"q":"初伏：中伏：末伏（  ）","options":["火星：木星：土星","大雨：小雨：谷雨","上旬：中旬：下旬","大暑：小暑：处暑"],"a":2,"e":"【答案】C\n【解析】时间顺承+并列关系。初伏、中伏与末伏统称为三伏，三者属于并列关系，\n且时间上的先后顺序为初伏、中伏、末伏。\nA 项，火星、木星与土星是八大行星中的三颗行星，三者属于并列关系，但不存在时\n间上的先后顺序，排除；\nB 项，大雨与小雨是两种天气气象，二者属于并列关系，谷雨是一个节气，排除；\nC 项，上旬、中旬与下旬分别指一个月中的上段、中段、下段时间，三者属于并列关\n系，且存在时间先后顺序，与题干逻辑关系一致，当选；\nD 项，大暑、小暑与处暑是三个节气，但时间的先后顺序应该为小暑、大暑、处暑，\n排除。\n故正确答案为C。"},{"q":"水：森林：煤炭（  ）","options":["氮：蛋白质：智力","闪电：雨：打伞","雪：丰年：喜悦","表扬：自信：乐观"],"a":0,"e":"【答案】A\n【解析】必要条件关系。题干逻辑关系：水是森林生长的必要条件，森林又是煤炭形\n成的必要条件。\nA 项，氮是蛋白质组成的必要条件，蛋白质又是智力发育的必要条件，与题干逻辑关\n系一致，当选；\nB 项，闪电不是下雨的必要条件，而是打雷的必要条件，雨也不是打伞的必要条件，\n不下雨也可以打伞，与题干逻辑关系不一致，排除；\nC 项，雪不是丰年的必要条件，丰年也不是喜悦的必要条件，与题干逻辑关系不一\n致，排除；\nD 项，表扬不是自信的必要条件，自信与乐观为并列关系，与题干逻辑关系不一致，\n排除；\n故正确答案为A。"},{"q":"骆驼祥子：四世同堂（  ）","options":["呐喊：雷雨","土门：秦腔","红与黑：老人与海","国富论：资本论"],"a":1,"e":"【答案】B\n【解析】并列关系。题干逻辑关系：骆驼祥子与四世同堂都是老舍的著作，二者是并\n列关系。\nA 项，呐喊作者是鲁迅，雷雨作者是曹禺，与题干逻辑关系不一致，排除；\nB 项，土门与秦腔都是贾平凹的著作，二者是并列关系，与题干逻辑关系一致，当\n选；\nC 项，红与黑作者是司汤达，老人与海作者是海明威，与题干逻辑关系不一致，排\n除；\nD 项，国富论作者是亚当•斯密，资本论作者是马克思，与题干逻辑关系不一致，排\n除。\n故正确答案为B。"},{"q":"猪：猪肝（  ）","options":["鱼：鱼鳔","马：马蹄","虫：虫草","虾：虾须"],"a":0,"e":"【答案】A\n【解析】组成关系。猪肝是猪的组成部分，也是猪的器官，二者属于组成关系。\nA 项，鱼鳔是鱼的组成部分，也是鱼的器官，与题干逻辑关系一致，当选；\nB 项，马蹄是马的组成部分，但不是其器官，与题干逻辑关系不一致，排除；\nC 项，虫是虫草的组成部分，但不是其器官，与题干逻辑关系不一致，排除；\nD 项，虾须是虾的组成部分，但不是器官，与题干逻辑关系不一致，排除。\n故正确答案为A。\n第十三组："},{"q":"救援：围魏救赵（  ）","options":["进攻：风声鹤唳","防守：草木皆兵","追击：穷寇勿追","转移：斗折蛇行"],"a":2,"e":"【答案】C\n【解析】对应关系。题干逻辑关系：围魏救赵是救援的一种策略，二者是对应关系。\nA 项，风声鹤唳形容惊慌失措。与进攻没有明显的逻辑关系，排除；\nB 项，草木皆兵形容人在惊慌时疑神疑鬼，与防守没有明显的逻辑关系，排除；\nC 项，穷寇勿追是指不追无路可走的敌人，以免敌人情急反扑，造成自己的损失。穷\n寇勿追也是追击的一种策略，与题干逻辑关系一致，当选；\nD 项，斗折蛇行形容道路曲折蜿蜒。与转移没有明显的逻辑关系，排除。\n故正确答案为C。"},{"q":"讨论：会议：方案（  ）","options":["合作：课题：计划","研究：手机：销量","分析：汽车：技术","调研：基层：实情"],"a":3,"e":"【答案】D\n【解析】地点对应关系。题干逻辑关系：在会议上讨论方案，会议是对应地点，讨论\n方案构成动宾关系。\nA 项，合作计划不构成动宾关系，排除；\nB 项，研究销量，但手机不是地点，排除；\nC 项，分析技术，但汽车不是地点，排除；\nD 项，在基层调研实情，基层属于地点对应，调研实情属于动宾关系，当选。\n故正确答案为D。"},{"q":"中子：辐射：军事（  ）","options":["货车：交通：运输","电解质：物理：化学","薄膜：隔热：大棚","干冰：吸热：消防"],"a":3,"e":"【答案】D\n【解析】对应关系。题干逻辑关系：中子可以发生辐射反应，中子辐射运用在军事领\n域，为对应关系。\nA 项，货车是一种交通工具，货车的作用是运输。与题干逻辑关系不一致，排除；\nB 项，电解质有导电的物理性质，电解质本身是一种化学物质，与题干逻辑关系不一\n致，排除；\nC 项，薄膜有隔热的作用，薄膜是制作大棚的一种材料，与题干逻辑关系不一致，排\n除；\nD 项，干冰能够发生吸热反应，干冰吸热能够应用于消防领域，与题干逻辑关系一\n致，当选。\n故正确答案为D。"},{"q":"农家乐：农家：乐（  ）","options":["一日游：一日：游","广场舞：广场：舞","袋鼠跳：袋鼠：跳","颅内伤：颅内：伤"],"a":1,"e":"【答案】B\n【解析】对应关系。题干逻辑关系：农家乐是一项娱乐活动，农家是农家乐的活动地\n点，乐是农家乐的活动主题。\nA 项，一日游是一项娱乐活动，一日是一日游活动时间阶段而非地点，与题干逻辑关\n系不一致，排除；\nB 项，广场舞是一项娱乐活动，广场是广场舞的活动地点，舞是广场舞的活动主题，\n与题干逻辑关系一致，当选；\nC 项，袋鼠跳是一项娱乐活动，袋鼠是袋鼠跳的原型而非地点，与题干逻辑关系不一\n致，排除；\nD 项，颅内伤是一种伤而非娱乐活动，与题干逻辑关系不一致，排除。\n故正确答案为B。"},{"q":"盲动：一败涂地：重起炉灶（  ）","options":["超速：风驰电掣：按部就班","跟风：鹦鹉学舌：真知灼见","熬夜：萎靡不振：养精蓄锐","传神：生动逼真：洛阳纸贵"],"a":2,"e":"【答案】C\n【解析】因果关系。题干逻辑关系：盲动可能导致一败涂地，一败涂地之后需要重起\n炉灶。\nA 项，超速指速度超过了规定速度，违反交通法则；风驰电掣形容非常迅速，与题干\n逻辑关系不一致，排除；\nB 项，鹦鹉学舌比喻人家怎么说，他也跟着怎么说，与跟风意思相近，与题干逻辑关\n系不一致，排除；\nC 项，熬夜可能导致萎靡不振，萎靡不振之后需要养精蓄锐，与题干逻辑关系一致，\n当选；\nD 项，生动逼真与传神意思相近，与题干逻辑关系不一致，排除。\n故正确答案为C。"},{"q":"（  ）对于宋朝相对于（  ）对于汉朝","options":["岳飞；陈胜","金人；匈奴人","词；《汉书》","印刷术；万里长城"],"a":1,"e":"【答案】B\n【解析】对应关系。分别代入题干分析。\nA 项，“岳飞”是“宋朝”人，二者为朝代对应关系，“陈胜”是秦朝人，前后逻辑\n关系不一致，排除；\nB 项，“金人”是“宋朝”的少数民族，二者为对应关系，“匈奴”是“汉朝”的少\n数名族，前后逻辑关系一致，当选；\nC 项，“词”是“宋朝”文学的主流文体，“《汉书》”是具体的书名，并非文体，\n前后逻辑关系不一致，排除；\nD 项，“印刷术”发明于唐朝而不是“宋朝”，二者无明显逻辑关系，排除。\n故正确答案为B。"},{"q":"违约之于（  ）相当于（  ）之于承诺","options":["法律；民俗","处罚；兑现","合同；食言","赔偿；责任"],"a":2,"e":"【答案】C\n【解析】对应关系。分别代入题干分析。\nA 项，违约可能会违反法律，民宿和承诺没有直接联系，前后逻辑关系不一致，排\n除；\nB 项，违约可能会受到处罚，兑现承诺属于动宾关系，前后逻辑关系不一致，排除；\nC 项，违约是指违背了合同，食言就是违背了承诺，都属于对应关系，当选；\nD 项，违约后可能要赔偿，责任和承诺没有明显的联系，前后逻辑关系不一致，排\n除。\n故正确答案为C。"},{"q":"（  ）之于精当相当于固若金汤之于（  ）","options":["瑕瑜互见；牢靠","字字珠玑；防御","无懈可击；城池","不刊之论；坚实"],"a":3,"e":"【答案】D\n【解析】近义关系。分别代入题干中。\nA 项，瑕瑜互见，比喻有缺点也有优点，精当是指精确恰当，二者没有明显的逻辑关\n系；固若金汤，形容城池或阵地坚固，与牢靠为近义词，但前后逻辑关系不一致，排除；\nB 项，字字珠玑，可以指每个字都经过斟酌，推敲，与精当为近义词；固若金汤可以\n用来形容防御坚固，二者为对应关系，前后逻辑关系不一致，排除；\nC 项，无懈可击，形容十分严密，找不到一点漏洞，精当指的是精确恰当，两者逻辑\n关系不明显；固若金汤，可以形容城池坚固，二者为对应关系，前后逻辑关系不一致，排\n除；\nD 项，不刊之论，指准确的、不可修改的言论，与精当为近义词；固若金汤与坚实为\n近义词，前后逻辑关系一致，当选。\n故正确答案为D。"},{"q":"番茄之于（  ）相当于（  ）之于蹴鞠","options":["美洲；中国","炒饭；健身","植物；人类","白菜；篮球"],"a":3,"e":"【答案】D\n【解析】并列关系。分别代入题干分析。\nA 项，番茄的起源是美洲，蹴鞠的起源是中国，但是前后位置点到，排除；\nB 项，番茄可能是炒饭时候的一种食材，蹴鞠有健身的作用，前后逻辑关系不一致，\n排除；\nC 项，番茄和植物是种属关系，但蹴鞠是人类发明的一种运动，前后逻辑关系不一\n致，排除；\nD 项，番茄和白菜是并列关系；篮球和蹴鞠也是并列关系，前后逻辑关系一致，当\n选。\n故正确答案为D。"},{"q":"风霜雨雪：雾里看花（  ）","options":["春夏秋冬：踏雪寻梅","金木火土：水中望月","桃李杏橘：青梅煮酒","梅兰竹菊：茜窗画眉"],"a":1,"e":"【答案】B\n【解析】并列关系。“风”“霜”“雨”“雪”都属于自然现象，属于并列关系，\n“雾里看花”中“雾”也属于自然现象，与“风”“霜”“雨”“雪”构成并列关系。\nA 项，“春”“夏”“秋”“冬”都属于季节，属于并列关系，“踏雪寻梅”中\n“踏”是一种动作，而不是季节，与题干逻辑关系不一致，排除；\nB 项，“金”“木”“火”“土”都属于五行，属于并列关系，“水中望月”中\n“水”也属于五行之一，与“金”“木”“火”“土”属于并列关系，与题干逻辑关系一\n致，当选；\nC 项，“桃”“李”“杏”“橘”都属于水果，属于并列关系，“青梅煮酒”中\n“青”不是一种水果，与题干逻辑关系不一致，排除；\nD 项，“梅”“兰”“竹”“菊”被称为“四君子”，属于并列关系，“茜窗画眉”\n中“茜”指茜草，不是四君子之一，与题干逻辑关系不一致，排除。\n故正确答案为B。\n第十四组："},{"q":"西子湖：曹娥江（  ）","options":["美人蕉：老婆饼","东坡肉：五柳鱼","女儿红：祖母绿","狮子头：凤凰胆"],"a":1,"e":"【答案】B\n【解析】并列关系。西子湖与曹娥江分别是以西施和曹娥命名的水域名称，二者是并\n列关系。\nA 项，美人蕉是一种植物，老婆饼则是一种食物，二者不能构成并列关系，与题干逻\n辑关系不一致，排除；\nB 项，东坡肉和五柳鱼分别是以苏东坡（苏轼）和五柳先生（陶渊明）命名的菜品名\n称，二者是并列关系，与题干逻辑关系一致，当选；\nC 项，女儿红是一种酒，祖母绿则是一种宝石，二者不能构成并列关系，与题干逻辑\n关系不一致，排除；\nD 项，狮子头是一种菜品，凤凰胆是天然的玉石珠，二者不能构成并列关系，与题干\n逻辑关系不一致，排除。\n故正确答案为B。"},{"q":"仪态万方：美丽多姿（  ）","options":["风度翩翩：富富有余","腰缠万贯：富甲一方","其貌不扬：荣华富贵","仪表堂堂：身无长物"],"a":1,"e":"【答案】B\n【解析】近义关系。仪态万方形容女子容貌、姿态各方面都很美，与美丽多姿构成近\n义关系。\nA 项，风度翩翩形容气质不凡，富富有余表示东西量多，满足需要外还有富余，二者\n不构成近义关系，与题干逻辑关系不一致，排除；\nB 项，腰缠万贯和富甲一方都形容十分富有，二者构成近义关系，与题干逻辑关系一\n致，当选；\nC 项，其貌不扬指人的外貌不漂亮，荣华富贵形容有钱有势，二者不构成近义关系，\n与题干逻辑关系不一致，排除；\nD 项，仪表堂堂形容人外表端正，姿态威严，身无长物形容贫穷，二者不构成近义关\n系，与题干逻辑关系不一致，排除。\n故正确答案为B。"},{"q":"井底蛙：三脚猫：智慧（  ）","options":["笑面虎：变色龙：真诚","千里马：孺子牛：可靠","替罪羊：铁公鸡：坚强","地头蛇：纸老虎：勇敢"],"a":0,"e":"【答案】A\n【解析】并列关系+反义关系。井底蛙比喻目光短浅，见识狭隘的人，三脚猫比喻对\n技艺略知皮毛的人，二者为并列关系，井底蛙象征缺乏智慧，与智慧是反义关系。\nA 项，“笑面虎”比喻的是表面上一团和气，背地里总想着怎么排挤别人。“变色\n龙”\n比喻在生活中善于变化和伪装的人，二者是并列关系。笑面虎象征缺乏真诚，与真诚\n是反义关系，与题干逻辑关系一致，当选；\nB 项，“千里马”比喻人才，“孺子牛”比喻无私奉献的人，前两者为并列关系，但\n是“千里马”与可靠无明显逻辑关系，与题干逻辑关系不一致，排除；\nC 项，“替罪羊”比喻代人受过的人，“铁公鸡”比喻生活中小气、吝啬、一毛不拔\n的人，“替罪羊”与坚强没有明显逻辑关系，与题干逻辑关系不一致，排除；\nD 项，“地头蛇”指在当地有势力的欺压人民的恶霸，“纸老虎”比喻外强中干的\n人，“地头蛇”与勇敢没有明显逻辑关系，与题干逻辑关系不一致，排除。\n故正确答案为A。"},{"q":"演员：公园：演出（  ）","options":["谣言：微信：查处","股民：股市：投资","士兵：战争：升迁","信息：卫星：定位"],"a":1,"e":"【答案】B\n【解析】语法关系+对应关系。演员在公园演出，演员和演出构成主谓关系，公园是\n对应的场所。\nA 项，微信不是查处的地点，与题干逻辑关系不一致，排除；\nB 项，股民在股市投资，股民和投资构成主谓关系，股市是对应的场所，与题干逻辑\n关系一致，当选；\nC 项，士兵升迁构成主谓关系，战争不是场所，与题干逻辑关系不一致，排除；\nD 项，信息和定位不构成主谓关系，与题干逻辑关系不一致，排除。\n故正确答案为B。"},{"q":"骡子：耕畜：犁地（  ）","options":["基因：生命：遗传","衙役：衙门：当差","鸬鹚：水鸟：捕鱼","恒星：宇宙：发光"],"a":2,"e":"【答案】C\n【解析】种属关系+功能对应。骡子是一种耕畜，二者构成种属关系，骡子可以用来\n犁地，功能对应。\nA 项，基因和生命不构成种属关系，与题干逻辑关系不一致，排除；\nB 项，衙役在衙门当差，衙役和衙门为地点对应，与题干逻辑关系不一致，排除；\nC 项，鸬鹚是一种水鸟，二者构成种属关系，鸬鹚可以捕鱼，功能对应，与题干逻辑\n关系一致，当选；\nD 项，恒星和宇宙是组成关系，与题干逻辑关系不一致，排除。\n故正确答案为C。"},{"q":"团扇：羽毛扇：舞蹈扇（  ）","options":["宣纸：餐巾纸：铜版纸","圈椅：实木椅：办公椅","排球：羽毛球：乒乓球","墨镜：老花镜：显微镜"],"a":1,"e":"【答案】B\n【解析】交叉关系。团扇为近似圆形的一种扇子，以其形状命名，羽毛扇是以其材质\n命名，舞蹈扇是以其功能命名，三者互为交叉关系。\nA 项，宣纸产自古代宣州，以其产地命名，餐巾纸以其功能命名，铜版纸以其硬度命\n名，与题干逻辑关系不一致，排除；\nB 项，圈椅以其形状命名，实木椅以其材质命名，办公椅以其功能命名，且三者为交\n叉关系，与题干逻辑关系一致，当选；\nC 项，排球、羽毛球、乒乓球为并列关系，与题干逻辑关系不一致，排除；\nD 项，墨镜以其颜色命名，老花镜和显微镜都以其功能命名，与题干逻辑关系不一\n致，排除。\n故正确答案为B。"},{"q":"火药：鞭炮：二踢脚（  ）","options":["乌铁：刀具：三棱刀","红砖：建筑：四合院","清水：白酒：五粮液","杉木：乐器：六弦琴"],"a":2,"e":"【答案】C\n【解析】原材料关系+种属关系。火药是鞭炮的必然原材料；二踢脚是鞭炮的一种，\n为种属关系。\nA 项，乌铁是刀具的或然原材料，与题干逻辑关系不一致，排除；\nB 项，红砖是建筑的或然原材料，与题干逻辑关系不一致，排除；\nC 项，清水是白酒的必然原材料，五粮液是一种白酒，为种属关系，与题干逻辑关系\n一致，当选；\nD 项，杉木是乐器的或然原材料，与题干逻辑关系不一致，排除。\n故正确答案为C。"},{"q":"（  ）之于风油精相当于碳酸之于（  ）","options":["薄荷脑；可乐","清凉；陈醋","叶绿素；花露水","液体；二氧化碳"],"a":0,"e":"【答案】A\n【解析】原料对应。将选项带入分析。\nA 项，“薄荷脑”是“风油精”的主要成分，“碳酸”是“可乐”的主要成分，都属\n于组成关系，前后逻辑关系一致，当选；\nB 项，“风油精”有“清凉”的作用，二者属于功能对应关系，“碳酸”与“陈醋”\n没有明显逻辑关系，前后逻辑关系不一致，排除；\nC 项，“叶绿素”与“风油精”无明显逻辑关系，“碳酸”与“花露水”无明显逻辑\n关系，排除；\nD 项，“风油精”是一种“液体”，二者属于种属关系，“二氧化碳”可以溶于水生\n成“碳酸”，二者属于对应关系，前后逻辑关系不一致，排除。\n故正确答案为A。"},{"q":"钟表之于（  ）相当于（  ）之于排字工","options":["时间；印刷工","刻度；线装书","更夫；打印机","油纸；修理工"],"a":2,"e":"【答案】C\n【解析】功能对应。分别带入题干分析。\nA 项，钟表是看时间的工具，属于对应关系；印刷工和排字工为并列关系，前后逻辑\n关系不一致，排除；\nB 项，钟表通过刻度记录时间，属于对应关系；线装书和排字工没有必然逻辑关系，\n前后逻辑关系不一致，排除；\nC 项，钟表和更夫的功能相同，打印机和排字工的功能相同，均为功能对应，且前后\n两个词均构成现代机器和古代职业的对应关系，前后逻辑关系一致，当选；\nD 项，钟表和油纸无必然逻辑关系，修理工和排字工是并列关系，前后逻辑关系不一\n致，排除。\n故正确答案为C。"},{"q":"海马对于（  ）相当于（  ）对于珊瑚","options":["海龙：海葵","河马：礁石","木马：海螺","贝壳：海带"],"a":0,"e":"【答案】A\n【解析】并列关系。代入选项分析。\nA 项，海马与海龙均为动物的一种，属于海龙科，二者属于并列关系，海葵与珊瑚均\n为动物，属于珊瑚纲，属于并列关系，前后逻辑一致，当选；\nB 项，海马与河马均为动物，而珊瑚生长在礁石中，场所对应，前后逻辑不一致，排\n除；\nC 项，木马与海马之间并无直接联系，海螺和珊瑚都是海洋动物，并列关系，前后逻\n辑不一致，排除；\nD 项，海马和贝壳无明显逻辑关系，海带是植物，珊瑚是动物，二者无明显逻辑关\n系，排除。\n故正确答案为A。\n第十五组："},{"q":"若明若暗：雾里看花（  ）","options":["如醉如梦：一清二楚","如日中天：日薄西山","如火如荼：无声无息","如履薄冰：如临深渊"],"a":3,"e":"【答案】D\n【解析】近义关系。题干逻辑关系：若明若暗比喻对情况的了解或对问题的认识不清\n楚；雾里看花比喻看事情不真切，二者为近义词。\nA 项，如醉如梦形容处于不清醒、迷糊状态中；一清二楚形容清楚明白，二者为反义\n词，与题干逻辑关系不一致，排除；\nB 项，如日中天比喻事物正发展到十分兴盛的阶段；日薄西山比喻事物衰败接近灭\n亡，二者为反义词，与题干逻辑关系不一致，排除；\nC 项，如火如荼形容旺盛、热烈；无声无息没有名声，不被人知道，二者为反义词，\n与题干逻辑关系不一致，排除；\nD 项，如履薄冰与如临深渊都比喻行事极为谨慎，存有戒心，二者为近义词，与题干\n逻辑关系一致，当选。\n故正确答案为D。"},{"q":"单价：数量：总价（  ）","options":["现状：问题：方案","被除数：除数：商","本金：利息：利率","速度：时间：路程"],"a":3,"e":"【答案】D\n【解析】对应关系。题干逻辑关系：单价乘以数量等于总价，三者为对应关系。\nA 项，方案解决现状中的问题，与题干逻辑关系不一致，排除；\nB 项，被除数除以除数等于商，与题干逻辑关系不一致，排除；\nC 项，本金乘以利率等于利息，但1、3 两个词语顺序颠倒，与题干逻辑关系不一\n致，排除；\nD 项，速度乘以时间等于路程，与题干逻辑关系一致，当选。\n故正确答案为D。"},{"q":"漫画：推理漫画：连环漫画（  ）","options":["大气：对流层：中间层","离子：阳离子：阴离子","可见光：红光：紫光","文物：馆藏文物：史前文物"],"a":3,"e":"【答案】D\n【解析】种属关系。题干逻辑关系：推理漫画和连环漫画均是漫画的一种，第一个词\n与后两个词为种属关系；有的推理漫画是连环漫画，后两个词又可以构成交叉关系。\nA 项，对流层和中间层是大气的组成部分，第一个词与后两个词为组成关系；对流层\n和中间层为并列关系，不是交叉关系，与题干逻辑关系不一致，排除；\nB 项，阳离子与阴离子都是离子的一种，第一个词与后两个词为种属关系；但阳离子\n与阴离子为并列关系，不是交叉关系，与题干逻辑关系不一致，排除；\nC 项，红光与紫光都是可见光的一种，第一个词与后两个词为种属关系；但红光与紫\n光是并列关系，不是交叉关系，与题干逻辑关系不一致，排除；\nD 项，馆藏文物与史前文物都是文物的一种，第一个词与后两个词为种属关系；馆藏\n文物与史前文物为交叉关系，与题干逻辑关系一致，当选。\n故正确答案为D。"},{"q":"我：认识：你（  ）","options":["尔：就是：你","他：喜欢：她","八：大于：六","你：矮于：她"],"a":1,"e":"【答案】B\n【解析】语法关系。题干逻辑关系：我、你均是人称代词，认识是一个动词，三者构\n成主谓宾结构。\nA 项，尔、你是人称代词，但就是为副词，无法构成主谓宾，与题干逻辑关系不一\n致，排除；\nB 项，他、她是人称代词，喜欢为动词，三者构成主谓宾结构，与题干逻辑关系一\n致，当选；\nC 项，八、六不是人称代词，大于不是动词，与题干逻辑关系不一致，排除；\nD 项，你、她是人称代词，但矮于不是动词，与题干逻辑关系不一致，排除。\n故正确答案为B。"},{"q":"经理：法官：公务员（  ）","options":["农具：沙发：家具","原告：被告：当事人","总统：明星：演员","蛋白质：花岗岩：无机物"],"a":0,"e":"【答案】A\n【解析】并列关系。题干逻辑关系：经理和公务员是两种职业，为并列关系，法官属\n于公务员的一种，后两个词为种属关系。\nA 项，农具与家具为并列关系，沙发属于家具的一种，后两个词为种属关系，与题干\n逻辑关系一致，当选；\nB 项，原告与被告是并列关系，二者均是当事人，与题干逻辑关系不一致，排除；\nC 项，总统与演员是并列关系，但明星和演员是交叉关系，与题干逻辑关系不一致，\n排除；\nD 项，蛋白质与无机物不在一个层级，二者不是并列关系，与题干逻辑关系不一致，\n排除。\n故正确答案为A。"},{"q":"声母：韵母：声调（  ）","options":["满族：汉族：白族","比拟：拟人：拟物","本体：喻体：喻词","车轮：车胎：车门"],"a":2,"e":"【答案】C\n【解析】并列关系。题干逻辑关系：声母、韵母、声调三者为并列关系，且共同组成\n一个完整的汉字。\nA 项，满族、汉族、白族三者为并列关系，但不能组成完整的事物，与题干逻辑关系\n不一致，排除；\nB 项，比拟可以分为拟人与拟物，后两个词与第一个词为种属关系，与题干逻辑关系\n不一致，\n排除；\nC 项，喻词是本体与喻体之间的连接词，所以本体、喻体、喻词三者为并列关系，共\n同组成比喻，与题干逻辑关系一致，当选；\nD 项，车轮、车胎、车门三者为并列关系，但不能组成完整的车，与题干逻辑关系不\n一致，排除。\n故正确答案为C。"},{"q":"（  ）对于冶炼相当于创作对于（  ）","options":["工人；作品","提纯；表演","矿物；作者","选矿；发表"],"a":3,"e":"【答案】D\n【解析】条件关系。选项逐个带入。\nA 项，工人冶炼是主谓关系；而创作对象是动宾关系，前后逻辑关系不一致，排除；\nB 项，提纯与冶炼为并列关系；先创作再表演，两者是时间先后关系，前后逻辑关系\n不一致，排除；\nC 项，冶炼矿物是动宾关系；作者创作是主谓关系，前后逻辑关系不一致，排除；\nD 项，选矿是冶炼的必要条件；创作是发表的必要条件，前后逻辑关系一致，当选。\n故正确答案为D。"},{"q":"（  ）对于社会科学相当于蝗虫对于（  ）","options":["物理学；蜻蜓","经济学；昆虫","自然科学；害虫","超声波；大雁"],"a":1,"e":"【答案】B\n【解析】种属关系。选项逐个带入。\nA 项，物理学与社会科学为全反关系；蝗虫与蜻蜓为并列关系，前后逻辑关系不一\n致，排除；\nB 项，经济学是社会科学的一种，二者为种属关系；蝗虫属于昆虫的一种，二者为种\n属关系，前后逻辑关系一致，当选；\nC 项，自然科学与社会科学为并列关系；蝗虫是害虫的一种，二者为种属关系，前后\n逻辑关系不一致，排除；\nD 项，超声波与社会科学没有关系；蝗虫与大雁都是动物，二者为并列关系，前后逻\n辑关系不一致，排除。\n故正确答案为B。"},{"q":"人体：肝脏：解毒（  ）","options":["动物：麋鹿：四不像","广告：商业广告：宣传","树木：叶子：光合作用","微量元素：锌：记忆力"],"a":2,"e":"【答案】C\n【解析】组成关系。题干逻辑：“肝脏”是“人体”的组成部分，二者属于组成关\n系；“肝脏”具有“解毒”功能，二者属于功能对应关系。\nA 项，“麋鹿”是“动物”的一种，二者属于种属关系，与题干逻辑关系不一致，排\n除；\nB 项，“商业广告”是“广告”的一种，二者属于种属关系，与题干逻辑关系不一\n致，排除；\nC 项，“叶子”是“树木”的组成部分，二者属于组成关系；“叶子”具有“光合作\n用”的功能，二者属于功能对应关系，与题干逻辑关系一致，当选；\nD 项，“锌”是“微量元素”的一种，二者属于种属关系，与题干逻辑关系不一致，\n排除；\n故正确答案为C。"},{"q":"《国富论》：亚当•斯密（  ）","options":["中山装：孙中山","《西厢记》：红娘","加拿大：白求恩","《史记》：司马迁"],"a":3,"e":"【答案】D\n【解析】对应关系。题干逻辑：“《国富论》”的作者是“亚当•斯密”，二者属于\n著作与作者对应关系。\nA 项，“中山装”是“孙中山”设计制作的，但“中山装”不是著作，与题干逻辑关\n系不一致，排除；\nB 项，“《西厢记》”的作者是“王实甫”，而“红娘”是“《西厢记》”中的人\n物，与题干逻辑关系不一致，排除；\nC 项，“白求恩”是“加拿大”人，二者属于人物与国籍对应关系，与题干逻辑关系\n不一致，\n排除；\nD 项，“《史记》”的作者是“司马迁”二者属于著作与作者对应关系，与题干逻辑\n关系一致，当选。\n故正确答案为D。\n第十六组："},{"q":"沧桑：白发（  ）","options":["清纯：酒窝","稚嫩：乳牙","鲁莽：健壮","博学：眼镜"],"a":1,"e":"【答案】B\n【解析】象征关系。白发象征着沧桑，二者是象征的关系。\nA 项，酒窝只是面部特征，并不象征着清纯，排除；\nB 项，乳牙是人类的第一套牙齿，所以乳牙象征着稚嫩，当选；\nC 项，鲁莽是用来修饰性格，而健壮是用来修饰身材，二者不是象征的关系，排除；\nD 项，人们近视才戴眼镜，所以眼镜不能象征着博学，排除。\n故正确答案是B。"},{"q":"家属：亲属：家族（  ）","options":["事故：事变：事情","助教：讲师：教授","蓝领：粉领：白领","而立：不惑：古稀"],"a":0,"e":"【答案】A\n【解析】包含关系。家属、亲属、家族之间概念范围逐步扩大，三者之间为逐一包含\n关系。\nA 项，事故、事变、事情概念范围逐步扩大，三者之间依次为包含关系，事情包含事\n变，事变包含事故，与题干逻辑关系一致，当选；\nB 项，三者均为职业，构成并列关系，与题干逻辑关系不一致，排除；\nC 项，三者均为职业类型，构成并列关系，与题干逻辑关系不一致，排除；\nD 项，三者均指代年龄，构成并列关系，与题干逻辑关系不一致，排除。\n故正确答案选A。"},{"q":"赛事对于（  ）相当于（  ）对于编辑","options":["哨子；文字","运动；校对","裁判；书稿","进取；精确"],"a":2,"e":"【答案】C\n【解析】主宾关系。A 项，哨子是赛事的辅助工具，对应关系；编辑文字是动宾关\n系，前后逻辑关系不一致，排除；\nB 项，赛事的内容可以是运动，对应关系，校对是编辑的工作，前后对应方式不一\n致，排除；\nC 项，裁判判决赛事，主宾关系，编辑编订书稿，主宾关系。前后逻辑关系一致，当\n选；\nD 项，赛事与进取无明显的逻辑关系，精确与编辑无明显的逻辑关系，排除。\n故正确答案选C。"},{"q":"三顾茅庐：刘备（  ）","options":["负荆请罪：蔺相如","请君入瓮：周兴","雪中送炭：宋太宗","程门立雪：程颐"],"a":2,"e":"【答案】C\n【解析】对应关系。在三顾茅庐的典故中，刘备为典故的主体，诸葛亮为典故的客\n体。\nA 项，蔺相如为负荆请罪的客体，主体为廉颇，与题干逻辑关系不一致,排除；\nB 项，周兴为请君入瓮的客体，主体为来俊臣，与题干逻辑关系不一致，排除；\nC 项，雪中送炭的主体为宋太宗，与题干逻辑关系一致，当选；\nD 项，程颐为程门立雪的客体，主体为杨时，与题干逻辑关系不一致，排除。\n故正确答案选C。"},{"q":"黄连：苦涩（  ）","options":["花朵：鲜红","钻石：坚硬","城市：繁华","班级：团结"],"a":1,"e":"【答案】B\n【解析】必然属性。分析题干逻辑关系，黄连是苦涩的，苦涩是黄连的必然属性。\nA 项，中鲜红不是花朵的必然属性，花朵有很多种颜色，不符合题干逻辑关系，排\n除；\nB 项，中钻石是坚硬的，坚硬是钻石的必然属性，符合题干逻辑关系，当选；\nC 项，中繁华不是城市的必然属性，城市并不一定是繁华的，不符合题干逻辑关系，\n排除；\nD 项，中团结不是班级的必然属性，不符合题干逻辑关系，排除。\n故正确答案为B。"},{"q":"（  ）对于熟练相当于敏捷对于（  ）","options":["熟悉；迅速","操作；迅捷","谙熟；灵动","娴熟；灵敏"],"a":3,"e":"【答案】D\n【解析】近义关系。将选项带入题干。\nA 项，熟悉是指对事物了解得清楚，熟练是指对技术精通而有经验，二者无关。敏捷\n和灵敏都指反应迅速，二者构成近义关系。前后逻辑关系不一致，排除；\nB 项，熟练的操作，构成偏正关系；敏捷和迅捷，二者构成近义关系。前后逻辑关系\n不一致，排除；\nC 项，谙熟和熟练都指对技术精通而有经验，二者构成近义关系；敏捷和灵动，敏捷\n指反应迅速，灵动指有灵气，二者无关，前后逻辑关系不一致，排除；\nD 项，娴熟和熟练都为对技术精通而有经验的意思；敏捷和灵敏都指反应迅速，前后\n二者构成近义关系。逻辑关系一致，当选。\n故正确答案选D。"},{"q":"树根：根雕：工艺品（  ）","options":["纸张：风筝：春天","粘土：唐三彩：古董","消费：借贷：信用","泥沙：混凝土：建筑"],"a":1,"e":"【答案】B\n【解析】原材料+种属。根雕是一种工艺品，二者为种属关系，根雕由树根制作而\n成，二者为原材料关系。\nA 项，风筝与春天无明显逻辑关系，与题干逻辑关系不符，排除；\nB 项，唐三彩是一种古董，是由粘土制作而成，与题干的逻辑关系一致，当选；C\n项，借贷与信用之间并非种属关系，与题干逻辑关系不符，排除；\nD 项，混凝土可以是建筑的原材料，与题干逻辑关系不符，排除。\n故正确答案为B。"},{"q":"竞争：淘汰（  ）","options":["惊吓：失色","疏忽：失算","亏损：失信","判断：失误"],"a":3,"e":"【答案】D\n【解析】因果关系。题干逻辑关系：参与竞争（中性词）会产生入围（积极性）或淘\n汰（消极性）两种结果，前者与后者为或然性因果关系，其中后者为前者的消极性结果。\nA 项，惊吓（贬义词）不会产生积极性结果，失色为惊吓的必然性结果，与题干逻辑\n关系不一致，排除；\nB 项，疏忽（贬义词）不会产生积极性结果，疏忽为贬义词，与题干词语感情色彩不\n对应，排除；\nC 项，亏损与失信之间非因果关系，亏损不会产生失信，与题干逻辑关系不一致，排\n除；\nD 项，做出判断（中性词）可能会产生正确（积极性）与失误（消极性）两种结果，\n为或然性因果关系，且后者为前者的消极性结果，与题干逻辑关系一致，当选。\n故正确答案为D。"},{"q":"沟通：手机：金属（  ）","options":["招聘：面试：简介","卫星：科技：科学家","物流：运输：公路","露营：帐篷：帆布"],"a":3,"e":"【答案】D\n【解析】功能+原材料。手机可以用于沟通，二者属于功能对应关系，金属是制作手\n机的原材料，二者属于原材料对应关系。\nA 项，面试可以用于招聘，二者属于功能对应关系，但简介不是面试的原材料，与题\n干逻辑关系不一致，排除；\nB 项，卫星是科技的产物，二者属于对应关系，科学家研究科技，二者属于主宾关\n系，与题干逻辑关系不一致，排除；\nC 项，运输是物流的必要环节，二者属于必要条件关系，公路可以用于运输二者属于\n功能对应关系，与题干逻辑关系不一致，排除；\nD 项，帐篷可以用于露营，二者属于功能对应关系，帆布是制作帐篷的原材料，二者\n属于原材料对应关系，与题干逻辑关系一致，当选。\n故正确答案为D。"},{"q":"（  ）对于美丽相当于春风满面对于（  ）","options":["笑靥如花；兴奋","楚楚动人；愉快","心地善良；滋润","眉开眼笑；高兴"],"a":1,"e":"【答案】B\n【解析】将选项逐一带入。\nA 项，笑靥如花形容女子的笑脸像花儿一样美丽，与美丽属于近义关系，春风满面形\n容人心情愉快，满脸笑容，与兴奋无明显逻辑关系，前后逻辑关系不一致，排除；\nB 项，楚楚动人形容美好的样子引人怜爱，与美丽属于近义关系，春风满面与愉快属\n于近义关系，前后逻辑关系一致，当选；\nC 项，心地善良指德行好，慈善，与美丽无明显逻辑关系，春风满面与滋润无明显逻\n辑关系，排除；\nD 项，眉开眼笑形容高兴愉快的样子，与美丽无明显逻辑关系，春风满面与高兴属于\n近义关系，前后逻辑关系不一致，排除。\n故正确答案为B。\n第十七组："},{"q":"潮涨：潮落（  ）","options":["出生：死亡","白天：黑夜","开灯：关灯","起飞：降落"],"a":3,"e":"【答案】D\n【解析】对应关系+反对关系。题干逻辑关系：潮涨与潮落是潮水的两种不同状态，\n二者反对关系，且是可以循环发生的。\nA 项，出生与死亡是人的两种状态，但是不能循环出现，与题干逻辑关系不一致，排\n除；\nB 项，白天与黑夜是一天中的两个时间段，二者属于矛盾关系，与题干逻辑关系不一\n致，排除；\nC 项，开灯与关灯是灯的两种不同状态，二者属于矛盾关系，与题干逻辑关系不一\n致，排除；\nD 项，起飞与降落是飞机的两种状态，二者属于反对关系，且是可以循环出现的，与\n题干逻辑关系一致，当选。\n故正确答案为D。"},{"q":"旗开得胜：马到成功（  ）","options":["拨乱反正：沉冤昭雪","牛高马大：虎穴得子","水到渠成：瓜熟蒂落","缘木求鱼：鹰击长空"],"a":2,"e":"【答案】C\n【解析】近义关系。题干逻辑关系：旗开得胜比喻事情刚一开始，就取得好成绩，马\n到成功形容工作刚开始就取得成功，二者属于近义关系。\nA 项，拨乱反正指的是消除混乱局面，恢复正常秩序，沉冤昭雪指的是沉积很久的冤\n情得到洗刷，二者无明显逻辑关系，排除；\nB 项，牛高马大比喻人长得高大强壮，虎穴得子比喻诗文贴切中肯，且深得其要旨，\n二者无明显逻辑关系，排除；\nC 项，水到渠成比喻条件成熟，事情自然会成功，瓜熟蒂落指时机一旦成熟，事情自\n然成功，二者属于近义关系，与题干逻辑关系一致，当选；\nD 项，缘木求鱼比喻方向或办法不对头，不可能达到目的，鹰击长空指雄鹰振翅飞翔\n于辽阔的天空，比喻有雄心壮志的人在广阔的领域施展自己的才能，二者无明显逻辑关\n系，排除。\n故正确答案为C。"},{"q":"语言：思想（  ）","options":["行为：品格","头部：大脑","粉笔：黑板","纸张：知识"],"a":0,"e":"【答案】A\n【解析】对应关系。题干逻辑关系：语言是表达思想的方式，二者属于对应关系。\nA 项，行为是表现品格的方式，二者属于对应关系，与题干逻辑关系一致，当选；\nB 项，大脑是头部的一部分，二者为组成关系，排除；\nC 项，粉笔与黑板属于配套使用的关系，与题干逻辑关系不一致，排除；\nD 项，纸张与知识为载体对应关系，与题干逻辑关系不一致，排除。\n故正确答案为A。"},{"q":"（  ）对于疾病相当于新闻对于（  ）","options":["细菌；报道","病毒；关注","药品；直播","病房；感动"],"a":1,"e":"【答案】B\n【解析】因果关系。代入选项，分析逻辑关系。\nA 项，细菌对于疾病，细菌会导致疾病产生，属于因果关系；新闻对于报道，报道新\n闻，是动宾关系，前后逻辑不一致，排除；\nB 项，病毒对于疾病，病毒导致疾病产生，是因果关系；新闻对于关注，新闻会导致\n被人们所关注，也是因果关系。前后逻辑关系一致，当选；\nC 项，药品对于疾病，药品可以治疗疾病，是对应关系；新闻对于直播，直播新闻是\n动宾关系。前后逻辑不一致，排除；\nD 项，病房对于疾病，疾病要在病房里治疗，地点对应，新闻对于感动，没有明显逻\n辑关系。前后逻辑不一致，排除。\n故正确答案为B。"},{"q":"茶树：茉莉花茶（  ）","options":["梅树：梅花糕","小麦：肉夹馍","螃蟹：蟹黄包","冬瓜：冬瓜糖"],"a":2,"e":"【答案】C\n【解析】原料对应。茉莉花茶是将茶叶和茉莉鲜花经过拼合，窨（xūn）制等工艺，\n使茶叶吸收花香而成的茶叶。茉莉花茶的部分材料是茶叶，茶叶是茶树的一部分。\nA 项，梅花糕只是形状类似梅花，其原料不包含梅花，与题干逻辑关系不一致，排\n除；\nB 项，肉夹馍的部分材料是面粉，不是小麦的一部分，面粉是由小麦加工出来的，排\n除；\nC 项，蟹黄包的部分材料是蟹黄，是螃蟹的一部分，与题干逻辑关系一致，当选；\nD 项，冬瓜糖是用冬瓜熬制出来的，材料只有冬瓜，与题干逻辑关系不一致，排除。\n故正确答案为C。"},{"q":"进士：状元（  ）","options":["河水：海水","银河：天文","学位：博士","宪法：民法"],"a":2,"e":"【答案】C\n【解析】种属关系。进士包括状元、榜眼、探花等等，状元是进士中的第一名，二者\n为种属关系。\nA 项，河水和海水都是水，属于并列关系，与题干逻辑关系不一致，排除；\nB 项，银河是天文学的研究范围，二者属于对应关系，与题干逻辑关系不一致，排\n除；\nC 项，学位包括学士、硕士、博士等，其中博士是等级最高的学位，属于种属关系，\n与题干逻辑关系一致，当选；\nD 项，宪法和民法都属于法律，宪法为上位法，民法为下位法，但不属于种属关系，\n与题干逻辑关系不一致，排除。\n故正确答案为C。"},{"q":"出口：进口：贸易顺差（  ）","options":["征税：纳税：财政收入","买进：卖出：盈利","支出：收入：赤字","还债：借债：债务"],"a":2,"e":"【答案】C\n【解析】对应关系。题干逻辑关系：出口大于进口时产生贸易顺差，三者均为量值，\n属于对应关系。\nA 项，征税的目的是取得财政收入，二者属于目的对应关系，与题干逻辑关系不一\n致，排除；\nB 项，卖出大于买进时产生盈利，但是词语顺序颠倒，与题干逻辑关系不一致，排\n除；\nC 项，支出大于收入时产生赤字，三者属于对应关系，且三者均为量值，与题干逻辑\n关系一致，当选；\nD 项，借债、还债均非量值，与题干逻辑关系不一致，排除。\n故正确答案为C。"},{"q":"虚数：复数（  ）","options":["法律：刑法","麦子：水稻","祥林嫂：《祝福》","人工智能：计算机科学"],"a":3,"e":"【答案】D\n【解析】种属关系。题干逻辑关系：虚数是复数的一种，二者属于种属关系。\nA 项，刑法是一种法律，二者属于种属关系，但二者位置颠倒，排除；\nB 项，麦子与水稻均属于粮食，二者属于并列关系，与题干逻辑关系不一致，排除；\nC 项，祥林嫂是《祝福》中的人物，二者属于对应关系，与题干逻辑关系不一致，排\n除；\nD 项，人工智能是一种计算机科学，二者属于种属关系，与题干逻辑关系一致，当\n选。\n故正确答案是D。"},{"q":"鸿雁：笺札：书信（  ）","options":["月老：红娘：媒人","乾坤：天地：宇宙","红豆：相思：恋人","东宫：王子：储君"],"a":0,"e":"【答案】A\n【解析】同一关系。鸿雁和笺札指书信，三者为同一关系。\nA 项，月老和红娘都是指媒人，三者属于同一关系，与题干逻辑关系一致，当选；\nB 项，宇宙中包含天地，二者属于包含关系，与题干逻辑关系不一致，排除；\nC 项，红豆象征相思，二者属于象征关系，与题干逻辑关系不一致，排除；\nD 项，东宫和储君都是指太子，太子属于王子，属于种属关系，与题干逻辑关系不一\n致，排除。\n故正确答案为A。"},{"q":"陆军：空军：作战（  ）","options":["播种机：收割机：农业","汽车：轮船：运输","超市：商场：促销","法院：政府：司法"],"a":1,"e":"【答案】B\n【解析】并列关系+功能对应。题干逻辑关系：陆军与空军均为军队，二为并列关\n系，二的功能是作战。\nA 项，播种机与收割机均为农耕用具，二者是并列关系，农业并不是二者的功能，而\n是二者的使用范围，与题干逻辑关系不一致，排除；\nB 项，汽车与轮船都是运输工具，二者为并列关系，与运输属于功能对应关系，与题\n干逻辑关系一致，当选；\nC 项，超市与商场都是促销的场所，二者与促销属于场所对应关系，与题干逻辑关系\n不一致，排除；\nD 项，法院是司法机关，与政府是并列关系。与题干逻辑关系不一致，排除。\n故正确答案为B。\n第十八组："},{"q":"微信：QQ：MSN（  ）","options":["扫描仪：打印机：墨盒","搜狐：新浪：网易","邮票：邮件：邮箱","电脑：鼠标：显示屏"],"a":1,"e":"【答案】B\n【解析】反对关系。题干逻辑：“微信”“QQ”和“MSN”都是网络通讯软件，三\n者属于并列关系。\nA 项，“墨盒”是“打印机”的一部分，二者属于组成关系，与题干逻辑关系不一\n致，排除；\nB 项，“搜狐”“新浪”和“网易”都是互联网门户网站，三者属于并列关系，与题\n干逻辑关系一致，当选；\nC 项，“邮箱”可以用来投寄“邮件”，二者属于对应关系，与题干逻辑关系不一\n致，排除；\nD 项，“显示屏”是“电脑”的一部分，二者属于组成关系，与题干逻辑关系不一\n致，排除；\n故正确答案为B。"},{"q":"叶公好龙：名副其实（  ）","options":["郑人买履：达权通变","邯郸学步：东施效颦","杞人忧天：庸人自扰","愚公移山：持之以恒"],"a":0,"e":"【答案】A\n【解析】反义关系。题干逻辑：“叶公好龙”比喻自称爱好某种事物，实际上并不是\n真正爱好，而“名副其实”指名声或名义和实际相符，二者属于反义关系。\nA 项，“郑人买履”形容死板，不会变通，而“达权通变”指做事能适应客观情况的\n变化，懂得变通，二者属于反义关系，与题干逻辑关系一致，当选；\nB 项，“邯郸学步”和“东施效颦”都比喻胡乱模仿，导致不好的结果，二者属于近\n义关系，与题干逻辑关系不一致，排除；\nC 项，“杞人忧天”指为没根据的事情而担心，“庸人自扰”指本来没有问题而自己\n自找麻烦，二者属于近义关系，与题干逻辑关系一致，排除；\nD 项，“愚公移山”比喻做事持之以恒、坚持不懈，二者属于近义关系，与题干逻辑\n关系不一致，排除。\n故正确答案为A。"},{"q":"竹子对于（  ）相当于兔子对于（  ）","options":["竹林；兔耳朵","熊猫；草","草本植物；动物","竹笋；狼"],"a":2,"e":"【答案】C\n【解析】种属关系。带入选项判断逻辑关系。\nA 项，“竹子”是“竹林”的一部分，二者属于组成关系；“兔耳朵”是“兔子”的\n一部分，二者属于组成关系，但是词语前后顺序不一致，排除；\nB 项，“竹子”是“熊猫”的食物，二者属于对应关系；“草”是“兔子”的食物，\n二者属于对应关系，但是词语前后顺序不一致，排除；\nC 项，“竹子”是“草本植物”的一种，二者属于种属关系；“兔子”属于“动物”\n的一种，二者属于种属关系，前后逻辑关系一致，当选；\nD 项，“竹笋”是“竹子”的幼芽状态，二者属于对应关系；“兔子”与“狼”都是\n动物，二者属于并列关系，前后逻辑关系不一致，排除。\n故正确答案为C。"},{"q":"大小：轻重：物体（  ）","options":["快慢：缓急：时间","真伪：多少：数据","古今：春秋：历史","是非：对错：答案"],"a":1,"e":"【答案】B\n【解析】反义关系+对应关系。题干逻辑关系：大与小，轻与重均为反义关系，并且\n大小是从体积角度衡量物体，轻重是从重量角度衡量物体，二者与物体属于对应关系。\nA 项，快与慢，缓与急均属于反义关系，快慢是对速度的描述，缓急是对事情紧急程\n度的描述，但均不能用来衡量时间，排除；\nB 项，真与伪，多与少均属于反义关系，并且真伪是从真假角度衡量数据，多少是从\n数量角度衡量数据，二者与数据属于对应关系，与题干逻辑关系一致，当选；\nC 项，古与今属于反义关系，（春秋代表的是一年四季中的两个季节，历史上也存在\n春秋时代，但不能用来衡量历时）与题干逻辑关系不一致，排除；\nD 项，是与非，对与错均属于反义关系，但是非与对错是从同一角度衡量答案，与题\n干逻辑关系不一致，排除。\n故正确答案为B。"},{"q":"正数：零：负数（  ）","options":["中国：日本：美国","干部：群众：党员","熊市：股市：牛市","左边：中间：右边"],"a":3,"e":"【答案】D\n【解析】组成关系。题干逻辑关系：正数零与负数都是实数，三者属于并列关系，并\n且三者相加等于实数的全部。\nA 项，中国、日本与美国都是国家，三者属于并列关系，但是三者相加并不等于国家\n的全部，与题干逻辑关系不一致，排除；\nB 项，干部与党员，二者属于交叉关系，与题干逻辑关系不一致，排除；\nC 项，牛市指价格长期呈上涨趋势的证券市场，熊市指价格长期呈下跌趋势的证券市\n场，二者都是股市的一种，二者与股市属于种属关系，与题干逻辑关系不一致，排除；\nD 项，左边、中间与右边三者属于并列关系，并且三者相加等于水平方位的全部，与\n题干逻辑关系一致，当选。\n故正确答案为D。"},{"q":"基础设施：机场：公路（  ）","options":["英特网：内网：外网","国家机关：行政机关：司法机关","儿童片：动画片：卡通片","体育：武术：咏春拳"],"a":1,"e":"【答案】B\n【解析】种属关系+反对关系。题干逻辑关系：机场与公路都是基础设施，二者属于\n反对关系，二者与基础设施属于种属关系。\nA 项，英特网包含内网和外网，内网和外网属于矛盾关系，与题干逻辑关系不一致，\n排除；\nB 项，行政机关与司法机关都是国家机关，二者属于并列关系，二者与国家机关属于\n包含关系中的种属关系，与题干逻辑关系一致，当选；\nC 项，动画片与卡通片属于同一关系，与题干逻辑关系不一致，排除；\nD 项，咏春拳是武术的一种，二者属于种属关系，与题干逻辑关系不一致，排除。\n故正确答案为B。"},{"q":"大漠对于（  ）相当于草原对于（  ）","options":["黄沙；蒙古包","干旱；牧场","骆驼；羊","绿洲；雪山"],"a":2,"e":"【答案】C\n【解析】场所对应关系。代入选项分析。\nA 项，黄沙是大漠的组成部分，二者为组成关系，蒙古包建在草原上，二者属于场所\n对应关系，前后逻辑关系不一致，排除；\nB 项，干旱是大漠的特征，二者属于属性关系，牧场建在草原上，二者属于场所对应\n关系，前后逻辑关系不一致，排除；\nC 项，骆驼生活在大漠里，二者属于场所对应关系，羊生活在草原上，二者属于场所\n对应关系，前后逻辑关系一致，当选；\nD 项，大漠中可能有绿洲，二者属于或然对应关系，雪山与草原无必然逻辑关系，前\n后逻辑关系不一致，排除。\n故正确答案为C。"},{"q":"（  ）对于绿化相当于（  ）对于丰收","options":["种树；施肥","美化；稻谷","灌溉；收割","园林；乡村"],"a":0,"e":"【答案】A\n【解析】目的对应关系。代入选项分析。\nA 项，种树的目的是绿化，施肥的目的是丰收，均属于目的对应关系，前后逻辑关系\n一致，当选；\nB 项，绿化是环境美化的一种方式，二者属于种属关系，稻谷与丰收无明显逻辑关\n系，排除；\nC 项，绿化过程中需要灌溉，二者属于对应关系，丰收之后要收割，二者属于对应关\n系，但对应方式不一致，排除；\nD 项，通过在园林内种植植被达到绿化的作用，二者属于对应关系，乡村与丰收无明\n显逻辑关系，前后逻辑关系不一致，排除。\n故正确答案为A。"},{"q":"鸳：鸯（  ）","options":["蚱蜢：蝗虫","白猫：黑猫","雄鸡：雌鸡","红男：绿女"],"a":2,"e":"【答案】C\n【解析】矛盾关系。鸳是指雄鸟，鸯是雌鸟，二者属于矛盾关系。\nA 项，蚱蜢和蝗虫，二者为反对关系，与题干逻辑关系不一致，排除；\nB 项，白猫和黑猫，二者为反对关系，与题干逻辑关系不一致，排除；\nC 项，雄鸡和雌鸡，二者为矛盾关系，与题干逻辑关系一致，当选；\nD 项，红男和绿女，二者为反对关系，与题干逻辑关系不一致，排除。\n故正确答案为C。"},{"q":"牵牛花：喇叭花（  ）","options":["乞巧节：七夕节","七巧板：橡皮泥","人行道：车行道","防腐剂：添加剂"],"a":0,"e":"【答案】A\n【解析】同一关系。牵牛花又叫喇叭花，二者属于同一关系。\nA 项，乞巧节又叫七夕节，属于同一关系，当选；\nB 项，七巧板与橡皮泥无明显逻辑关系，排除；\nC 项，人行道与车行道属于并列关系，排除；\nD 项，防腐剂是能抑制微生物活动，防止食品腐败变质的一类食品添加剂，二者属于\n包含关系中的种属关系，排除。\n故正确答案为A 项。\n第十九组："},{"q":"词典：词语（  ）","options":["地图：地点","盲文：阅读","电影：台词","电脑：游戏"],"a":0,"e":"【答案】A\n【解析】对应关系。用词典查询词语，二者属于对应关系。\nA 项，用地图查询地点，二者属于对应关系，与题干逻辑关系一致，当选；\nB 项，阅读与盲文属于动宾关系，与题干逻辑关系不一致，排除；\nC 项，台词是电影的或然组成部分，二者属于或然组成关系，与题干逻辑关系不一\n致，排除；\nD 项，用电脑打游戏，而不是查询游戏，与题干逻辑关系不一致，排除。\n故正确答案为A。"},{"q":"美丽：沉鱼落雁（  ）","options":["独特：举世无双","灵活：身手敏捷","厌恶：嗤之以鼻","粗心：三心二意"],"a":0,"e":"【答案】A\n【解析】近义关系。美丽和沉鱼落雁都可以形容女人长得漂亮，二者是近义关系。\nA 项，举世无双指全世界找不到第二个。形容十分稀有，独特指与众不同，二者是近\n义关系，与题干逻辑关系一致，当选；\nB 项，灵活指人善于变通，思维灵巧，身手敏捷指动作迅捷。二者无明显逻辑关系，\n排除；\nC 项，嗤之以鼻从鼻子里发出冷笑的声音，表示讥笑和蔑视。厌恶是指讨厌，二者无\n明显逻辑关系，排除；\nD 项，粗心形容做事不认真，三心二意指同时做几件事情，指做事不专心，二者无明\n显逻辑关系，排除。\n故正确答案为A。"},{"q":"儿童：女童：未成年（  ）","options":["房屋：桥梁：建筑","小狗：狗崽：犬","佐料：酱油：调料","植物油：椰子油：菜籽油"],"a":1,"e":"【答案】B\n【解析】种属关系。女童是儿童的一种，二者属于种属关系，儿童是未成年的一种，\n二者属于种属关系。\nA 项，桥梁与房屋是组成关系，排除；\nB 项，狗崽是小狗的一种，二者属于种属关系，小狗是犬的一种，二者属于种属关\n系，与题干逻辑关系一致，当选；\nC 项，酱油是调料的一种，与调料是种属关系，调料是指调味用的佐料，调料与佐料\n是种属关系，但与题干顺序相反，与题干逻辑关系不一致，排除；\nD 项，椰子油是植物油的一种，二者是种属关系，菜籽油是植物油的一种，二者也是\n种属关系，与题干逻辑关系不一致，排除。\n故正确答案为B。"},{"q":"储存：光盘：硬盘（  ）","options":["晾晒：绳索：衣架","吃饭：钢叉：锅铲","书写：签字笔：毛笔","游泳：泳圈：泳衣"],"a":2,"e":"【答案】C\n【解析】并列关系+功能对应。光盘与硬盘属于并列关系，二者的主要功能都是用来\n储存，均与储存属于功能对应关系。\nA 项，绳索的主要功能是用来捆绑、连接，而非晾晒，衣架的主要功能是晾晒，与题\n干逻辑关系不一致，排除；\nB 项，锅铲的主要功能是用来做饭，而非吃饭，与题干逻辑关系不一致，排除；\nC 项，签字笔与毛笔属于并列关系，二者的主要功能都是用来书写，均与书写属于功\n能对应关系，与题干逻辑关系一致，当选；\nD 项，泳圈的主要功能是用来保证游泳时的安全，泳衣是游泳时的穿着，游泳并不是\n泳衣的功能，与题干逻辑关系不一致，排除。\n故正确答案为C。"},{"q":"机密：保密：安全（  ）","options":["肥胖：健身：成长","无知：学习：追赶","落后：努力：进步","乐观：笑话：开朗"],"a":2,"e":"【答案】C\n【解析】对应关系。机密通过保密可以获得安全，三者属于对应关系。\nA 项，肥胖通过健身可以获得健康，而非成长，与题干逻辑关系不一致，排除；\nB 项，无知通过学习可以获得知识、进步，而非追赶，与题干逻辑关系不一致，排\n除；\nC 项，落后通过努力可以获得进步，三者属于对应关系，与题干逻辑关系一致，当\n选；\nD 项，乐观与笑话无明显逻辑关系，与题干逻辑关系不一致，排除。\n故正确答案为C。"},{"q":"火：火热（  ）","options":["土：土气","水：水润","金：金黄","木：木讷"],"a":1,"e":"【答案】B\n【解析】属性关系。火热的热是火的必然属性，二者属于属性关系。\nA 项，土气并非土的必然属性，二者无明显逻辑关系，与题干逻辑关系不一致，排\n除；\nB 项，水润的润是水的必然属性，二者属于属性关系，与题干逻辑关系一致，当选；\nC 项，金指黄金时，金黄是金的或然属性，与题干逻辑关系不一致，排除；\nD 项，木讷的讷不是木的必然属性，二者无明显逻辑关系，与题干逻辑关系不一致，\n排除。\n故正确答案为B。"},{"q":"旅行：交通（  ）","options":["生活：工作","吃饭：食物","睡觉：休息","病愈：康复"],"a":1,"e":"【答案】B\n【解析】必要条件。旅行离不开交通，交通是旅行的必要条件，二者属于必要条件关\n系。\nA 项，工作是生活的一部分，但不是必不可少的，二者属于组成关系，与题干逻辑关\n系不一致，排除；\nB 项，吃饭离不开食物，食物是吃饭的必要条件，二者属于必要条件关系，与题干逻\n辑关系一致，当选；\nC 项，睡觉是一种休息，二者属于种属关系，与题干逻辑关系不一致，排除；\nD 项，康复指恢复健康，病愈指病好了，二者属于近义关系，与题干逻辑关系不一\n致，排除。\n故正确答案为B。"},{"q":"猪肉：肥肉：脂肪（  ）","options":["电视机：遥控器：辐射","树木：树叶：叶绿素","蜜蜂：蜂蜜：糖分","花朵：花蕊：花香"],"a":1,"e":"【答案】B\n【解析】组成关系。肥肉是猪肉的组成部分，二者属于组成关系，脂肪是肥肉的组成\n部分，二者属于组成关系。\nA 项，遥控器是电视机的配套工具，二者属于配套使用的对应关系，与题干逻辑关系\n不一致，排除；\nB 项，树叶是树木的组成部分，二者属于包含关系中的组成关系，叶绿素是树叶的组\n成部分，二者属于包含关系中的组成关系，与题干逻辑关系一致，当选；\nC 项，蜂蜜是蜜蜂从开花植物的花中采得的花蜜在蜂巢中经过充分酿造而成的天然甜\n物质，二者属于对应关系，与题干逻辑关系不一致，排除；\nD 项，花蕊是花朵的组成部分，二者属于组成关系，花香是花朵产生的香气，二者属\n于对应关系，与题干逻辑关系不一致，排除。\n故正确答案为B。"},{"q":"爸爸：叔父：兄弟（  ）","options":["哥哥：婶婶：夫妻","妈妈：嫂子：婆媳","姨妈：伯伯：兄妹","奶奶：姑姑：子女"],"a":1,"e":"【答案】B\n【解析】对应关系。爸爸和叔父是兄弟关系，三者属于对应关系。\nA 项，哥哥和婶婶不是夫妻关系，哥哥的妻子是嫂子，与题干逻辑关系不一致，排\n除；\nB 项，妈妈和嫂子是婆媳关系，三者属于对应关系，与题干逻辑关系一致，当选；\nC 项，姨妈指母亲的姐姐或妹妹，伯伯”是对父亲的哥哥的称呼，二者不是兄妹关\n系，与题干逻辑关系不一致，排除；\nD 项，奶奶和姑姑不是子女关系，而是母女关系，与题干逻辑关系不一致，排除。\n故正确答案为B。"},{"q":"为虎添翼：如虎添翼（  ）","options":["好为人师：善为人师","一字不差：一字不落","无所不至：无所不知","耸人听闻：骇人听闻"],"a":0,"e":"【答案】A\n【解析】词语语义。为虎添翼指替老虎加上翅膀，比喻帮助坏人，属于贬义词；如虎\n添翼指如同老虎长了翅膀，比喻强大的事物更加强大了，常用为褒义词。\nA 项，好为人师形容不谦虚，自以为是，属于贬义词；善为人师指善于指导别人，属\n于褒义词。与题干逻辑关系一致，当选；\nB 项，一字不差指一个字也没有更改；一字不落指整篇文章都仔细逐字逐句地阅读或\n背诵，一个字也不落下，二者都属于中性词，与题干逻辑关系不一致，排除；\nC 项，无所不至指没有达不到的地方；无所不知指什么事情都知道，二者都属于中性\n词，与题干逻辑关系不一致，排除；\nD 项，耸人听闻指夸大或捏造事实，使人听了感到惊异或震动，属于中性词；骇人听\n闻指使人听了某事后感到很惊讶、恐惧，属于贬义词，与题干逻辑关系不一致，排除。\n故正确答案为A。\n第二十组："},{"q":"蜘蛛：织网：爬行（  ）","options":["蚕：破蛹：吐丝","蜜蜂：酿蜜：飞行","夜莺：筑巢：歌唱","猎豹：奔跑：捕食"],"a":1,"e":"【答案】B\n【解析】主谓宾关系。蜘蛛与织网属于主谓宾关系，蜘蛛与爬行属于主谓关系，且爬\n行属于蜘蛛的生物学行为。\nA 项，蚕与破蛹属于主谓宾关系，但蚕与吐丝也属于主谓宾关系，与题干逻辑关系不\n一致，排除；\nB 项，蜜蜂与酿蜜属于主谓宾关系，蜜蜂与飞行属于主谓关系，且飞行属于蜜蜂的生\n物学行为，与题干逻辑关系一致，当选；\nC 项，夜莺与筑巢属于主谓宾关系，夜莺与歌唱属于主谓关系，但歌唱是一种拟人的\n表述，而非夜莺的生物学行为，夜莺应该是发出鸣叫，与题干逻辑关系不一致，排除；\nD 项，猎豹与奔跑属于主谓关系，与题干逻辑关系不一致，排除。\n故正确答案为B。"},{"q":"碗：水杯（  ）","options":["玻璃：书包","光：蜡烛","沙发：床","电脑：娱乐"],"a":2,"e":"【答案】C\n【解析】并列关系。碗和水杯均为盛水容器，二者属于并列关系。\nA 项，玻璃和书包无明显逻辑关系，与题干逻辑关系不一致，排除；\nB 项，蜡烛点燃后可以发光，二者属于对应关系，与题干逻辑关系不一致，排除；\nC 项，沙发和床均能用于休息，二者属于并列关系，与题干逻辑关系一致，当选；\nD 项，电脑有娱乐功能，二者属于功能对应关系，与题干逻辑关系不一致，排除。\n故正确答案为C。"},{"q":"秤：重量（  ）","options":["水：浮力","地图：距离","台灯：光亮","尺子：长度"],"a":3,"e":"【答案】D\n【解析】对应关系。秤是用来测量重量的，秤是工具，重量是对象；\nA 项，水有浮力，二者构成属性关系，与题干逻辑关系不一致，排除；\nB 项，通过地图可以计算地图上地点之间的距离，但地图不是测量距离的工具，与题\n干逻辑关系不一致，排除；\nC 项，台灯可以提供光亮，二者构成功能关系，与题干逻辑关系不一致，排除；\nD 项，尺子是用来测量长度的，尺子是工具，长度是对象，与题干逻辑关系一致，当\n选。\n故正确答案为D。"},{"q":"勤奋：学习：进步（  ）","options":["艰苦：创业：失败","努力：工作：成功","喝酒：驾车：车祸","鲁莽：说话：厌恶"],"a":1,"e":"【答案】B\n【解析】偏正关系。勤奋地学习，勤奋与学习属于偏正关系。进步是勤奋地学习的积\n极结果。\nA 项，艰苦地创业，艰苦与创业属于偏正关系，但是失败是艰苦地创业的消极结果，\n与题干逻辑关系不一致，排除；\nB 项，努力地工作，努力与工作属于偏正关系，且成功是努力地工作的积极结果，与\n题干逻辑关系一致，当选；\nC 项，喝酒与驾车均是动词，二者不属于偏正关系，与题干逻辑关系不一致，排除\nD 项，鲁莽地说话，鲁莽与说话属于偏正关系，但是厌恶是鲁莽地说话的消极结果，\n与题干逻辑关系不一致，排除。\n故正确答案为B。"},{"q":"左顾右盼：上下打量（  ）","options":["南来北往：东西奔走","纵横交错：中西合璧","千叮万嘱：一心一意","天高地厚：山清水秀"],"a":0,"e":"【答案】A\n【解析】反对关系。左顾右盼中左与右属于反对关系；上下打量中上与下属于反对关\n系。\nA 项，南来北往中南与北属于反对关系，东西奔走中的东与西属于反对关系，与题干\n逻辑关系一致，当选；\nB 项，纵横交错中纵与交不属于反对关系，中西合璧中的中与西属于反对关系，与题\n干逻辑关系不一致，排除；\nC 项，千叮万嘱中千与万不属于反对关系，一心一意中一与心不属于反对关系，与题\n干逻辑关系不一致，排除；\nD 项，天高地厚中天与地属于反对关系，山清水秀中山与清不属于反对关系，与题干\n逻辑关系不一致，排除。\n故正确答案为A。"},{"q":"少壮不努力，老大徒伤悲：惜时：奋斗（  ）","options":["假作真时真亦假，无为有处有还无：清醒：智慧","天生我材必有用，千金散尽还复来：自信：豁达","苔花如米小，也学牡丹开：自我：认真","它山之石，可以攻玉：谦虚：谨慎"],"a":1,"e":"【答案】B\n【解析】对应关系。少壮不努力，老大徒伤悲表达的道理就是惜时，而正是因为不努\n力才伤悲的，反面论证体现出了奋斗的必要性，三者属于对应关系。\nA 项，假作真时真亦假，无为有处有还无，理解为当你把真实的东西当作虚幻的东西\n来看的时候，那虚假的东西甚至比真实的东西显得更真实，反之也是一样，并无“清醒”\n之意，排除；\nB 项，天生我材必有用，千金散尽还复来体现出了自信的心态，千金散尽指不在乎钱\n财，有豁达之意，三者属于对应关系，与题干逻辑关系一致，当选；\nC 项，苔花如米小，也学牡丹开意思为哪怕那如米粒一般微小的苔花，丝毫也不自惭\n形秽，依然像那美丽高贵的牡丹一样，自豪地盛开，表达自豪之情，而非自我的意思，排\n除；\nD 项，它山之石，可以攻玉意思是别座山上的石头，可以取来制作玉器，也可以用来\n制成美好珍宝，可比喻能帮助自己改正缺点错误的外力，并无谨慎之意，排除。\n故正确答案为B。"},{"q":"拖鞋：皮鞋：场合（  ）","options":["药物：手术：病情","川菜：凉菜：味道","跑步：踢球：体力","茶水：咖啡：爱好"],"a":0,"e":"【答案】A\n【解析】并列关系。拖鞋与皮鞋都是鞋子，二者属于并列关系，并且应该根据不同场\n合选择不同的鞋子，体现的是客观选择。\nA 项，药物与手术都是治疗的方式，二者属于并列关系，并且应该根据不同病情选择\n不同的治疗方式，体现的是客观选择，与题干逻辑关系一致，当选；\nB 项，有的川菜是凉菜，有的凉菜是川菜，二者属于交叉关系，与题干逻辑关系不一\n致，排除；\nC 项，跑步与踢球是两种运动方式，二者属于并列关系，但不是根据体力来进行选\n择，与题干逻辑关系不一致，排除；\nD 项，茶水与咖啡都是饮品，二者属于并列关系，饮品的选择与个人爱好有关，体现\n的是主观选择，排除。\n故正确答案为A。"},{"q":"品质：好坏：质量（  ）","options":["食物：大小：重量","分数：高低：成绩","旅游：远近：兴趣","人口：多少：密度"],"a":1,"e":"【答案】B\n【解析】对应关系+近义词。品质是指人的素质和物品的质量，品质与质量属于近义\n关系，二者均可以用好坏来评判，二者与好坏属于对应关系。\nA 项，食物与重量不属于近义关系，与题干逻辑关系不一致，排除；\nB 项，分数与成绩属于近义关系，二者均可以用高低来评判，二者与高低属于对应关\n系，与题干逻辑关系一致，当选；\nC 项，旅游与兴趣不属于近义关系，与题干逻辑关系不一致，排除；\nD 项，人口与密度不属于近义关系，与题干逻辑关系不一致，排除。\n故正确答案为B。"},{"q":"网购：上网（  ）","options":["读书：书本","喝水：烧水","练字：写字","唱歌：歌唱"],"a":2,"e":"【答案】C\n【解析】必要条件。网购的必要条件是上网，二者属于必要条件关系。\nA 项，读书可以阅读纸质书或者电子书，所以书本不是读书的必要条件，与题干逻辑\n关系不一致，排除；\nB 项，喝水可以不需要烧水，烧水不属于喝水的必要条件，与题干逻辑关系不一致，\n排除；\nC 项，练字的必要条件是写字，二者属于必要条件关系，与题干逻辑关系一致，当\n选；\nD 项，唱歌的必要条件不是歌唱，二者属于近义关系，与题干逻辑关系不一致，排\n除。\n故正确答案为C。"}]},{"id":"dingyi","name":"定义判断","items":[{"q":"势均：力敌（  ）","options":["旗鼓：相当","并驾：齐驱","不相：上下","平分：秋色"],"a":1,"e":"【答案】B\n【解析】近义词。势均指势力均等，力敌指力量相当，二者是近义关系。\nA 项，旗鼓指古代作战以摇旗击鼓指挥进退，相当指差不多，不相上下，二者不是近\n义关系，与题干逻辑关系不一致，排除；\nB 项，并驾指几匹马并排拉着一辆车，齐驱指一齐快跑，二者是近义关系，与题干逻\n辑关系一致，当选；\nC 项，不相指分不出，上下指高低好坏，二者不是近义关系，与题干逻辑关系不一\n致，排除；\nD 项，平分指平均分一半，秋色指秋天景色，二者不是近义关系，与题干逻辑关系不\n一致，排除。\n故正确答案为B。\n第四章定义判断\n第一组："},{"q":"体象障碍是指一个人强迫性地认为自己身体的某些部分有严重的缺陷，并采取特殊的方式来掩盖或“修复”。而这些被感受到的缺陷，通常是想象出来的；即便缺陷确实存在，它的严重性也是被夸大的。根据上述定义，下列符合体象障碍表现的是（  ）","options":["爱美的小王在拍完证件照后让摄影师为其修图","爱干净的小李每天早上花一小时在卫生间洗漱","外表不突出的小高经常宅在家中，不喜欢参加社交活动","身高170 厘米的张女士认为自己身材矮小，每次出门必穿高跟鞋"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：认为有缺陷；掩盖或“修复”。\nA 项，没体现出来小王有什么缺陷，不符合认为有缺陷，不符合题干定义，排除；\nB 项，爱干净不是缺陷，不符合认为有缺陷，不符合题干定义，排除；\nC 项，外表不突出以及不喜欢参加社交活动，不符合认为有缺陷，掩盖或“修复”，\n不符合题干定义，排除；\nD 项，身高170 厘米仍认为自己身材矮小，符合认为有缺陷，每次出门都要穿高跟鞋\n符合掩盖或“修复”，符合题干定义，当选。\n故正确答案为D。"},{"q":"信息影响法则指的是人们往往会对极为熟悉的、形象生动的、特点鲜明的信息产生积极的心理反应，不仅表现得非常敏感，而且容易印象深刻。根据上述定义，下列没有反映信息影响法则的是（  ）","options":["小郑在电视中看到某洗发水广告，他觉得葫芦形产品包装很可爱，于是去超市买了这款洗发水","小林最近加班多，觉得颈部不适，同事推荐给他一款配乐颈椎按摩仪，他试用了一下，觉得效果不错","许多小朋友爱看某款动画片，当商场里出现该动画片里相关人物的玩偶时，小朋友们都会特别兴奋","小李在阅读一本推理小说时，发现作者的写法和自己之前看过的小说完全不同，因此他产生了更大的兴趣"],"a":1,"e":"【答案】B\n【解析】定义判断，选非题。关键词：熟悉的、形象生动的、特点鲜明的。\nA 项，葫芦形产品包装很可爱，符合形象生动的，符合定义，排除；\nB 项，同事推荐的配乐颈椎按摩仪，小林自己对产品并不熟悉，不符合熟悉的，不符\n合定义，当选；\nC 项，商场里出现该动画片里相关人物的玩偶，符合熟悉的、形象生动的，符合定\n义，排除；\nD 项，作者的写法和自己之前看过的小说完全不同，因此他产生了更大的兴趣，符合\n特点鲜明的，符合定义，排除。\n故正确答案为B。"},{"q":"市场补缺者战略是指行业中相对弱小的企业，在竞争中为避免与实力强大的企业正面冲突，选择未被满足的细分市场，向细分市场提供专门的产品或服务，以谋求生存与发展的战略。根据上述定义，下列属于市场补缺者战略的是（  ）","options":["某小型培训机构通过降低学费、免费接送等方法吸引生源","某网商将市场上深受喜爱的卡通形象印制在水杯、优盘上出售，销量很好","某新成立的化妆品公司专门开发生产市场上较为稀缺的适合老年人使用的护肤品","某小型服装生产企业将今年市场上的流行元素融入设计中，生产出物美价廉的女装"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：未被满足的细分市场；提供专门的产品或服务。\nA 项，降低学费、免费接送等方法吸引生源不知是不是属于细分市场的，不符合定\n义，排除；\nB 项，深受喜爱的卡通形象印制在水杯、优盘上出售不是做的专门的产品或服务，不\n符合\n定义，排除；\nC 项，专门开发生产市场上较为稀缺的适合老年人使用的护肤品，符合未被满足的细\n分市场，专门的产品或服务，符合定义，当选；\nD 项，今年市场上的流行元素融入设计中，不符合未被满足的细分市场，专门的产品\n或服务，不符合定义，排除。\n故正确答案为C。"},{"q":"单务合同是指一方只享有权利而不尽义务，另一方只尽义务而不享有权利的合同，该合同中，当事人的权利义务不存在对应关系。根据上述定义，下列属于单务合同的是（  ）","options":["甲因资金周转困难，与乙签订合同，约定将个人名下的一辆越野车抵押给乙，乙一次性出借5 万元给甲","甲与乙签订合同，合同约定甲一次性支付乙10 万元，乙为甲提供市场调研与营销策略服务，期限为2 年","甲与乙准备结婚，甲的父母将名下的一处房产赠予甲，并签订合同，约定该房产仅赠予甲，非夫妻共有财产","甲被公司派至海外工作1 年，甲将个人电脑、家庭影院等贵重设备委托乙保管，并签订合同，支付乙1000 元保管费"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：一方只享有权利；另一方只尽义务；合同。\nA 项，甲付出了越野车，享受了5 万元周转资金，不符合一方只享有权利、另一方只\n尽义务，不符合定义，排除；\nB 项，双方都需要尽义务也都享受权利，不符合一方只享有权利、另一方只尽义务，\n不符合定义，排除\nC 项，甲只享受了得到房屋的权利，而父母只尽了义务，符合定义，当选；\nD 项，乙尽义务并获得报酬享受到权力了，不符合一方只享有权利、另一方只尽义\n务，不符合定义，排除。\n故正确答案为C。"},{"q":"联边是一种为了表达的需要，在特定的语言环境中，连用三个以上的联边字（即偏旁部首相同的字）的修辞方式。运用联边的修辞手法，通过形旁表义，往往具有一定的形象性，看到形旁，人们会对其所表意义产生形象上的联想。根据上述定义，以下哪项不属于联边（  ）","options":["腾欢今日新天地，澎湃潮流沸海江","但见云暗江心，波涛滚滚，杳无踪影","他一个人叽哩咕噜地说些不满意的话","烟锁池塘柳，桃燃锦江堤，炮镇海城楼"],"a":3,"e":"【答案】D\n【解析】定义判断，选非题。关键词：三个以上；偏旁部首相同的字。\nA 项，澎湃潮流沸海江，偏旁部首都是“氵”，符合题干三个以上，偏旁部首相同的\n字，符合题干定义，排除；\nB 项，波涛滚滚，偏旁部首都是“氵”，符合三个以上，偏旁部首相同的字，符合题\n干定义，排除；\nC 项，叽哩咕噜，偏旁部首都是“口”，符合三个以上，偏旁部首相同的字，符合题\n干定义，排除；\nD 项，该项并没有出现连续三个以上偏旁部首相同的字，不符合关键词三个以上，偏\n旁部首相同的字，不符合题干定义，当选。\n故正确答案为D。"},{"q":"自我损耗现象是个人在长期从事某项工作的过程中，出现自我进行意志活动的能力或意愿下降的现象，包括控制环境、控制自我、做出抉择和发起行为等能力或意愿的下降，同时出现职业倦怠、自我消耗但毫无进步的情况。根据上述定义，下列符合自我损耗现象的是（  ）","options":["李某博士论文一直未完成，不断延期，结果在学校读了八年也没有毕业","陈某在杂志社做副主任已经有二十年了，虽然出版了一些个人作品，但没有获得升职的机会","宋某做销售工作将近十年，虽然他换了四五家公司，但由于业绩一般，收入一直没有什么变化","王某一直在档案馆做管理员，一做就是十五年，他对工作感到麻木，也没有改变现状、获得晋升的欲望"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：长期从事某项工作；出现自我意志下降；出现职业倦\n怠、自我消耗但毫无进步的情况。\nA 项，该项并未体现出李某从事某项工作，不符合定义，排除；\nB 项，陈某出版了一些个人作品，不符合“自我进行意志活动的能力或意愿下降”，\n不符合定义，排除；\nC 项，宋某业绩和收入没有变化，不符合“出现职业倦怠、自我消耗但毫无进步的情\n况”，不符合定义，排除；\nD 项，王某一直在档案馆工作，符合“长期从事某项工作”，没有改变现状的欲望，\n属于“同时出现职业倦怠、自我消耗但毫无进步的情况”，符合定义，当选。\n故正确答案为D"},{"q":"社会悖论是指在多人决策的某种场合，每人具有一种至少在某些情形下可得到最优结果并对别人不利的策略，但若所有人均选用这种策略则会导致对所有人都更差的结果。根据上述定义，下列属于社会悖论的是（  ）","options":["王某等三人都想承包村里的鱼塘以增加经济收入，三人因此争得不可开交","村民认为村里的河流有自净能力，都往河里排放生活污水，但家家如此，河流会被严重污染","谈判前，李某充分考虑对方的需求，并根据他们的需求设计了合约，所以在谈判时，李某始终能把握主动","虽然商户交管理费会有一些经济压力，但是却为整个市场的正规化管理提供了经济保障，有利于整个市场所有个体的发展"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词：每人具有一种至少在某些情形下可得到最优结果并对别\n人不利的策略；所有人均选用这种策略则会导致对所有人都更差的结果。\nA 项，王某等三人都想承包鱼塘，争得不可开交，并未造成三人更差的结果，不符合\n定义，排除；\nB 项，村民都往河里排放生活污水，符合“每人具有一种至少在某些情形下可得到最\n优结果并对别人不利的策略”，若每家都如此，河流会污染严重，符合“所有人均选用这\n种策略则会导致对所有人都更差的结果”，符合定义，当选；\nC 项，李某充分考虑对方的需求并根据对方的需求设计合约，不符合“每人具有一种\n至少在某些情形下可得到最优结果并对别人不利的策略”，不符合定义，排除；\nD 项，商户交管理费有压力只是阐述客观状况，不符合“每人具有一种至少在某些情\n形下可得到最优结果并对别人不利的策略”，不符合定义，排除。\n故正确答案为B。"},{"q":"成就动机是个体努力追求自认为重要且有价值的工作，以高标准来要求自己，以取得成功为目标，并尽量使工作达到完美状态的动机。根据上述定义，下列没有体现出成就动机的是（  ）","options":["小刘是一名厨师，他用心做好每一道菜，希望得到用餐者的一致好评","小李是一名篮球运动员，他反复练习投篮希望可以带领队伍取得胜利","小张是一名企业领导，他常告诫手下员工要自觉、高质量地完成工作","小王是一名高中生，他不断复习曾经做错的试题，希望高考中不会再犯错"],"a":2,"e":"【答案】C\n【解析】定义判断，选非题。关键词：个体努力追求自认为重要且有价值的工作；以\n高标准来要求自己，以取得成功为目标，尽量使工作达到完美状态的动机。\nA 项，厨师小刘为了得到用餐者的好评而用心做菜，符合“以高标准来要求自己，以\n取得成功为目标，尽量使工作达到完美状态的动机”，符合定义，排除；\nB 项，篮球运动员小李为了带领队伍取得胜利而反复练习投篮，符合“以高标准来要\n求自己，以取得成功为目标，尽量使工作达到完美状态的动机”，符合定义，排除；\nC 项，领导小张经常告诫手下员工要好好完成工作，是在以高标准来要求他人，并非\n是要求自己，不符合“以高标准来要求自己，以取得成功为目标，尽量使工作达到完美状\n态的动机”，不符合定义，当选；\nD 项，高中生小王为了在高考中不犯错而不断复习做错的试题，符合“以高标准来要\n求自己，以取得成功为目标，尽量使工作达到完美状态的动机”，符合定义，排除。\n故正确答案为C。"},{"q":"排他成本是人们在想要确保不让他人擅自使用其产权时发生的成本。根据上述定义，下列属于排他成本的是（  ）","options":["张某为自家庭院安装栅栏所支出的费用","李某为保护自己的名誉权聘请律师而支付的费用","王某在与外商谈判过程中支付的交通和住宿费用","田某就买卖合同争议向人民法院起诉赵某时支付的诉讼费用"],"a":0,"e":"【答案】A\n【解析】定义判断。关键词：确保不让他人擅自使用其产权时发生的成本。\nA 项，张某安装栅栏的目的是不让他人擅自使用自己的院子，符合关键词“确保不让\n他人擅自使用其产权时发生的成本”，符合定义，当选；\nB 项，为了名誉权而支付的费用，不符合不让他人使用其产权时发生的成本，不符合\n定义，排除；\nC 项，谈判过程支付的交通和住宿费用，不符合不让他人使用其产权时发生的成本，\n不符合定义，排除；\nD 项，诉讼费用，不符合不让他人擅自使用其产权时发生的成本，不符合定义，排\n除。\n故正确答案为A。"},{"q":"个人道德判断能力的发展经历了六个阶段：一是避罚服从取向阶段，为避免惩罚而服从权威或规则；二是相对功利取向阶段，评定行为好坏主要看是否符合自己的利益；三是寻求认可取向阶段，顺从传统要求，谋求大家的赞赏和认可；四是遵守法规取向阶段，服从社会规范，遵守法律权威；五是社会法制取向阶段，看重法律的效力，但认为法律可以应大多数人的要求而改变；六是普遍伦理取向阶段，认为符合公正、平等、尊严等人类最一般原则的行为就是正确的。根据上述定义，如果一个人认为公司员工都参加了聚餐，所以自己也应该参加聚餐，则他的个人道德判断能力所处的发展阶段是（  ）","options":["避罚服从取向阶段","相对功利取向阶段","寻求认可取向阶段","普遍伦理取向阶段"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：顺从传统要求，谋求大家的赞赏和认可；避免惩罚而服\n从权威或规则；评定行为好坏主要看是否符合自己的利益；公正、平等、尊严。\nA 项，参加公司员工聚餐，不符合关键信息“避免惩罚而服从权威或规则”，不符合\n定义，排除；\nB 项，参加公司员工聚餐，不符合关键信息“评定行为好坏主要看是否符合自己的利\n益”，不符合定义，排除；\nC 项，参加公司员工聚餐，符合关键信息“顺从传统要求，谋求大家的赞赏和认\n可”，属于寻求认可取向阶段，符合定义，当选；\nD 项，参加公司员工聚餐，不符合关键信息“符合公正、平等、尊严等人类最一般原\n则行为就是正确的”，不符合定义，排除。\n故正确答案为C。\n第二组："},{"q":"偶例谬误是一种“通则凌驾例外”的谬误，是基于某个通则的存在，而否定例外的存在或正当性。根据上述定义，下列推理中存在偶例谬误的是（  ）","options":["吃肉会长胖，所以吃素一定会瘦","超速是违法的，所以救护车不应该超速","所有马都可以训练为战马，所以海马也可以作战马","我在香港住了七天，有三天下雨，所以香港大约有一半的时间下雨"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词：基于某个通则的存在、否定例外的存在或正当性。\nA 项，两个均为肯定句式的通则，并未体现否定某个通则，不符合定义，排除；\nB 项，“救护车不应该超速”是“超速是违法”的例外，符合定义“基于某个通则的\n存在、否定例外的存在或正当性”，符合定义，当选；\nC 项，两个均为肯定句式的通则，并未体现否定某个通则，不符合定义，排除；\nD 项，两个均为肯定句式的通则，并未体现否定某个通则，不符合定义，排除。\n故正确答案为B。"},{"q":"社会适应是指个人为与社会环境取得和谐的关系而产生的心理和行为的变化。它是个体与各种社会环境因素连续而不断改变的相互作用过程。根据上述定义，下列属于社会适应的是（  ）","options":["到海南半年后，小吴已经完全适应了当地湿润的气候","出国不到三个月，小黄就基本掌握了当地语言，能够听说和阅读","内向的小赵转入销售岗后，与人打交道的机会增多，性格变得活泼起来","小周进入大学后，生活、学习甚至语言都不习惯，常常打电话向家人倾诉"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：个人为与社会环境取得和谐的关系而产生的心理和行为\n的变化；个体与各种社会环境因素连续而不断改变的相互作用过程。\nA 项，小吴适应海南当地的气候，不属于心理变化，不符合定义，排除；\nB 项，小黄掌握了当地的语言，只是学会了一种技能，并非心理上的变化，不符合定\n义，排除；\nC 项，小赵转入销售岗后，与人打交道的机会增多，属于行为上发生了变化；性格变\n得活泼说明其心理上发生了变化，符合定义，当选；\nD 项，小周进入大学后很不习惯，未体现心理和行为上发生变化，不符合定义，排\n除。\n故正确答案为C。"},{"q":"缔约过失责任是指在合同订立过程中，一方因违背其依据诚实信用原则所产生的义务，而致另一方的信赖利益受损，应承担损害赔偿责任；另一方因信赖合同的成立和有效，但由于合同不成立或无效而蒙受不利益，此种不利益即为信赖利益的损失。根据上述定义，下列各项中甲方无需承担缔约过失责任的是（  ）","options":["甲乙双方磋商共同兴建制药厂，甲方以技术出资，并提出乙方需培训相关人员后，方能与乙方签约。乙方出资100 万元培训了相关人员后，甲方发现乙方制药技术存在问题，中止了与乙方的合作","甲方声称有一批优质紫檀木欲出售给乙方，乙方立即与丙方签订了一份紫檀木家具供货协议，并向丙方支付了保证金。结果乙方在与甲方签约前发现甲方欲出售的紫檀木是假冒的","甲方欲以50 万元的价格将自己的房子卖给乙方，要求乙方在10 天内以现金购买。乙方为筹集房款，将新买的汽车以极低的价格卖掉，第9 天去购房时，甲方已将房子卖与丙方并已办理了过户手续","甲方为报复乙方，声称欲以高价购买乙方的一批水果。乙方本有意将水果卖给丙方，遂中止了与丙方的协商。结果甲方在签约前反悔，致使乙方的水果未能及时卖出而腐烂"],"a":0,"e":"【答案】A\n【解析】定义判断。关键词：在合同订立过程中；一方因违背其依据诚实信用原则所\n产生的义务，而致另一方的信赖利益受损，应承担损害赔偿责任；另一方因信赖合同的成\n立和有效，但由于合同不成立或无效而蒙受不利益。\nA 项，甲方中止与乙方的合作，问题由乙方造成，甲没有“违背其依据诚实信用原则\n所产生的义务”，所以无需甲方承担缔约过失责任，当选；\nB 项，乙方在与甲方签约前发现甲方欲出售的紫檀木是假冒的，问题由甲方造成，甲\n“违背其依据诚实信用原则所产生的义务”，所以需要甲方承担缔约过失责任，排除；\nC 项，甲方承诺要求乙方在10 天内以现金购买，乙来购买时，甲方已将房子卖与丙\n方问题由甲方造成，甲“违背其依据诚实信用原则所产生的义务”，所以需要甲方承担缔\n约过失责任，排除；\nD 项，甲方欺骗乙方，致使乙方的水果未能及时卖出而腐烂，问题由甲方造成，甲\n“违背其依据诚实信用原则所产生的义务”，所以需要甲方承担缔约过失责任，排除。\n故正确答案为A。"},{"q":"当人们对一事物持某种态度时，不管该事物是有形的还是无形的，都被称为态度标的物。根据上述定义，下列对态度标的物理解不正确的是（  ）","options":["小李对刚买的一件首饰不满意。小李的态度标的物是首饰","老刘说，这酒真不好喝。老刘的态度标的物是酒","小王对导游的服务不满。小王的态度标的物是导游","老张厌恶儿子的“啃老”行为。老张的态度标的物是“啃老”行为"],"a":2,"e":"【答案】C\n【解析】定义判断，选非题。关键词：人们对一事物持某种态度时该事物便成为态度\n标的物。\nA 项，小李对首饰不满意，首饰属于态度标的物，符合定义，排除；\nB 项，老刘认为酒不好喝，酒属于态度标的物，符合定义，排除；\nC 项，小王对导游的服务不满，导游的服务属于态度标的物，而非导游，不符合定\n义，当选；\nD 项，老张厌恶儿子的啃老行为，啃老行为属于态度标的物，符合定义，排除。\n故正确答案为C。"},{"q":"近因效应是指新出现的具有对立意义的刺激能够把人们心目中已有的印象反转为对立的印象。根据上述定义，下列情形符合近因效应的是：","options":["自从老王到养老院做志愿者后，同事们就对他刮目相看","小林的学习成绩不太好，但是羽毛球水平很高，同学们很羡慕他","一家口碑良好的企业偷税漏税的丑闻被曝光后，公众指责其为“无良企业”","医疗事故发生后，医院诚恳地向患者家属道歉并减免了医药费，家属表示愿意谅解"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：已有的印象反转为对立的印象。\nA 项，该项中只有“刮目相看”一种印象，不符合定义，排除；\nB 项，该项中仅存在“同学很羡慕小林”这一种心理趋向，不存在印象，不符合定\n义，排除；\nC 项，口碑良好的企业丑闻曝光，公众指责其为无良企业，属于“人们心目中已有的\n印象反转为对立印象”，符合定义，当选；\nD 项，医疗事故发生、医院诚恳道歉、家属表示谅解，并未体现家属对医院的“已有\n的印象反转为对立印象”，不符合定义，排除。\n故正确答案为C。"},{"q":"胖尾效应是指统计学意义上的极端情况一反常态地经常出现的现象。根据上述定义，下列现象属于胖尾效应的是（  ）","options":["幸福小区的福利彩票投注站接连5 期都出了一等奖","今年J 省高考的文理科状元都是女生，大家不禁感慨现在男生真的考不过女生了","受厄尔尼诺现象影响，我国南方多地都出现了百年一遇的大暴雨","本届乒乓球比赛中，上届冠军老王发挥失常，居然首轮就被淘汰出局，让人大跌眼镜"],"a":0,"e":"【答案】A\n【解析】定义判断。关键词：统计学意义上的极端情况；一反常态地经常出现。\nA 项，彩票中奖属于“统计学意义上的极端情况”，接连5 期都出了一等奖，属于\n“一反常态地经常出现”，符合定义，当选；\nB 项，文理科状元都是女生，不属于“统计学意义上的极端情况”，不符合定义，排\n除；\nC 项，百年一遇的大暴雨属于“统计学意义上的极端情况”，但并未“一反常态地经\n常出现”，不符合定义，排除；\nD 项，上届冠军老王发挥失常，不属于“统计学意义上的极端情况”，而且也未“一\n反常态地经常出现”，不符合定义，排除。\n故正确答案为A。"},{"q":"布雷斯悖论现象是指在一个交通网络上增加一条路段不仅没有减少交通延滞，反而使整个交通网络上所有出行者的出行时间都增加的现象。根据上述定义，下列属于布雷斯悖论现象的是（  ）","options":["H 市在拆除了一条6 车道高速路，修建成一个方圆8 千米的公园后，很多道路专家惊讶地发现，城市环境改善了，交通状况也没有恶化","为缓解交通拥堵，G 市将市内与主干道相连的几条单行线改为双向通行，结果交通事故明显增多，堵车情况进一步恶化","N 市在城区主干道下方又修建了一条地下隧道，由于入口处和出口处交通汇集，隧道建成后交通反较之前更为拥堵","W 市建了两条贯通城市东—西、南—北的双向4 车道柏油马路后，市内交通不再像以前那么拥堵了"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：在一个交通网络上增加一条路段；没有减少交通延滞使\n整个交通网络上所有出行者的出行时间都增加。\nA 项，未体现“在一个交通网络上增加一条路段”，不符合定义，排除；\nB 项，将几条单行线改为双向通行，并未体现“在一个交通网络上增加一条路段”，\n不符合定义，排除；\nC 项，在城区主干道下方又修建了地下隧道，属于“在一个交通网络上增加一条路\n段”，较之前更为拥堵，体现了“不仅没有减少交通延滞，反而增加出行时间”，符合定\n义，当选；\nD 项，市内交通不再像以前那么拥堵，不符合“不仅没有减少交通延滞，反而增加出\n行时间”，不符合定义，排除。\n故正确答案为C。"},{"q":"过度合理化效应是指给人们报酬让他们做自己喜欢的事会让他们将其行为归因于报酬，这样就会削弱他们的自我知觉——因为兴趣而去做。根据上述定义，下列情形属于过度合理化效应的是（  ）","options":["小李抢救落水儿童，被见义勇为基金会奖励1 万元","某收视率低的电视节目以大奖吸引观众，冲着大奖而来的观众越来越多","随着公司效益的提高，员工因奖金没有相应提高而多有怨言","妈妈为鼓励爱画画的小明，画一幅画奖励他10 元钱，小明画得更多却有些潦草了"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：给人们报酬让他们做自己喜欢的事；将其行为归因于报\n酬；削弱他们的自我知觉——因为兴趣而去做。\nA 项，见义勇为后获得奖励，不属于给其“报酬”，不符合定义，排除；\nB 项，某电视节目收视率低，说明很多观众对这个节目没有兴趣，不符合定义，排\n除；\nC 项，未明确指出员工的工作是“自己喜欢做的事”，不符合定义，排除；\nD 项，小明原本爱画画，说明画画是他“喜欢做的事”，妈妈奖励10 元，属于给小\n明“报酬”，结果小明画得多却越来越潦草，说明小明画画是为了赚钱，体现了“削弱他\n的自我知觉，符合定义，当选。\n故正确答案为D。"},{"q":"防御中的攻势行动是指在有利的时机和态势下，防御部队采取的进攻性行动。根据上述定义，下列军事行动不属于防御中的攻势行动的是（  ）","options":["对突入阵地之敌实施冲击，消灭突入之敌，改善或恢复防御态势","防御的军队对小股进攻之敌实施主动攻击，击退敌人的进攻","直接抗击敌人冲击的分队，对冲击受挫滞留于阵地前沿之敌实施主动攻击，以出击消灭敌人，稳定防御态势","被包围的部队组织精干小分队，跳出包围圈，插到敌人侧后袭扰敌人，钳制围攻之敌"],"a":3,"e":"【答案】D\n【解析】定义判断，选非题。关键词：在有利的时机和态势下；防御部队采取的进攻\n性行动。\nA 项，敌人突入阵地，防御部队实施冲击，属于“防御部队采取的进攻性行动”，符\n合定义，排除；\nB 项，小股进攻之敌，说明敌军人数少，符合“在有利的时机和态势下”，防御部队\n主动攻击，属于“进攻性行动”，符合定义，排除；\nC 项，滞留于阵地前沿之敌，说明敌军战斗力较弱，符合“在有利的时机和态势\n下”，防御部队主动攻击，属于“进攻性行动”，符合定义，排除；\nD 项，被包围的部队，说明并不处于“有利的时机和态势”，不符合定义，当选。\n故正确答案为D。"},{"q":"鸟笼效应是一个心理学概念，它是指人们会在偶然获得一件原本不需要的物品的基础上，继续添加更多与之相关而自己不需要的东西。根据上述定义，下列符合鸟笼效应的是（  ）","options":["雯雯在网上购物，为了参与“满减”活动比预期多买了好几件商品","刘阿姨去超市买菜，发现清洁用品正好在打折，忍不住买了一堆","丽丽买裙子送了条毛衣链，她觉得没有毛衣可以搭配，又买了件毛衣，但却从没穿过","小玲的男朋友送了她一束花，她很开心，还专门去买了漂亮的花瓶"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：偶然获得一件原本不需要的物品；继续添加更多与之相\n关而自己不需要的东西。\nA 项，雯雯参与满减多买商品，是有目的的行为，不属于“偶然获得”，不符合定\n义，排除；\nB 项，刘阿姨买了一大堆打折的清洁用品，这些物品是日用品，不属于“原本不需要\n的物品”，不符合定义，排除；\nC 项，丽丽被赠送一个毛衣链，属于“偶然获得一件原本不需要的物品”，她为了与\n毛衣链搭配而买了一件毛衣，却从未穿过，属于“继续添加更多与之相关而自己不需要的\n东西”，符合定义，当选；\nD 项，小玲收到花，专门买了用来保存花的花瓶，未体现“继续添加更多与之相关而\n自己不需要的东西”，不符合定义，排除。\n故正确答案为C。\n第三组："},{"q":"完全归纳推理又称完全归纳法，是以某类中每一对象（或子类）都具有或不具有某一属性为前提，推出该类对象全部具有或不具有该属性为结论的归纳推理。根据上述定义，下列属于完全归纳推理的是（  ）","options":["美国居民的祖先都是从国外迁徙来的。早期的居民是美洲印第安人，他们是几千年前从亚洲迁徙来的。后来的居民是欧洲人，他们是在250 年至350 年前作为殖民地开拓者来到这里的","在很早的时候，中国就发明了指南针、造纸术、活字印刷术和火药，所以，中国是世界文明发展最早的国家之一","凡有所学，皆成性格。读书使人充实，讨论使人机智，笔记使人准确，读史使人明智，读诗使人灵秀，数学使人周密，物理使人深刻，伦理使人庄重","世界各国人民历来就相互进行科技的引进和交流。西方国家引进了中国古代的“四大发明”；日本的明治维新，主要是引进了欧洲的技术；今天许多国家种植的玉米、马铃薯，都是美洲印第安人培育出来的"],"a":0,"e":"【答案】A\n【解析】定义判断。关键词：前提：某类中每一对象（或子类）都具有或不具有某一\n属性；结论：该类对象全部具有或不具有该属性。\nA 项，美国早期居民和后来的居民是美国居民的全部对象，以二者为前提，推出美国\n居民都是从国外迁徙过来的结论，符合定义，当选；\nB 项，前提是中国在很早的时候就有四大发明，得出中国是世界文明发展最早的国家\n之一，并不符合该类对象全部具有或不具有该属性。不符合定义，排除；\nC 项，读书、讨论、笔记、读史、读诗、数学、物理、伦理等，并不是“所学”的全\n部对象，不符合定义，排除；\nD 项，西方国家、日本、今天的许多国家，并不是世界上的所有国家，不符合定义，\n排除。\n故正确答案为A。"},{"q":"体验式教学是指通过创造实际的情境和机会，呈现或再现、还原教学内容，使学生在亲历的过程中理解并建构知识、发展能力、产生情感、生成意义的教学观和教学形式。根据上述定义，下列不属于体验式教学的是（  ）","options":["在详细讲解了相关的知识要领和操作程序后，教练坐到了副驾驶的位置，换小李坐上驾驶位，开车上路","教授《股票原理》课程的赵教授要求每位学生以3000 元本金开设一个股票账户，学期结束时以交易的次数和账户余额评定成绩","某大学策划了“重走长征路，祖国在我心”爱国主义教育活动，分批组织学生重走当年红军长征时爬过的雪山、走过的草地","为了帮助学生摆脱“哑巴式英语”的困境，王老师用心搜集了大量原汁原味反映英国人日常生活交际的视频供学生观摩"],"a":3,"e":"【答案】D\n【解析】定义判断，选非题。关键词：创造实际的情景和机会；使学生亲历。\nA 项，小李坐上驾驶位，“亲历”驾车的“实际情景”，符合定义，排除；\nB 项，学生用3000 元开通股票账户并进行交易，“亲历”股市的“实际情景”，符\n合定义，\n排除；\nC 项，学生重走红军长征时爬过的雪山、走过的草地，“亲历”长征的“实际情\n景”，符合定义，排除；\nD 项，学生观看英国人日常生活交际的视频，并未“亲历”英国人日常生活的“实际\n情景”，不符合定义，当选。\n故正确答案为D。"},{"q":"非爱行为，指以爱的名义，对自己亲近的人进行非爱性的掠夺，即违背他人主观意愿，在精神与行为方面强制控制，迫使对方按照施控者的意愿去行为做事，这一行为往往发生在夫妻、恋人、父母与子女等最亲近的人之间。根据上述定义，下列属于非爱行为的是（  ）","options":["张某按照医嘱，要求女儿每三个小时做一次牵引，以消除疼痛","林某强迫儿子每天练琴3 小时，争取在钢琴大赛中取得好成绩","陈某为防止患精神病的女儿逃逸，将其关在地下室禁止其出入","李某按照轮流陪护协议，要求妻子前往医院陪护患重病的母亲"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词：违背他人主观意愿；迫使对方按照施控者的意愿去行为\n做事。\nA 项，张某要求女儿每三小时做一次牵引，女儿的主观意愿不明确，不符合定义排\n除；\nB 项，李某强迫儿子每天练琴3 小时，“强迫”可以表明违背了儿子的主观意愿，符\n合定义，当选；\nC 项，陈某将患精神疾病的女儿关在地下室，此时女儿的主观意愿没有表明，不符合\n定义，排除；\nD 项，李某按照陪护协议规定要求妻子陪护母亲，不是迫使对方按照施控者的意愿行\n为做事，不符合定义，排除。\n故正确答案为B。"},{"q":"心理人类学是介于文化人类学与心理学之间的交叉学科，主要研究并了解文化对所属社会成员产生影响的心理机制，发现在个体水平上的心理变量与在总体水平上的文化、社会、经济、生态和生物变量之间的关系。根据上述定义，下列选项属于心理人类学研究范畴的是（  ）","options":["“五四”前后诗歌风格的比较","当代流行话语下的社会主流价值","草原文明与蒙古民族性格的养成","从《背影》看作者对父亲态度的变化"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：文化；对所属社会成员；产生影响的心理机制。\nA 项，只是比较了不同时期的诗歌风格，并没有体现对社会成员的心理影响，不符合\n定义，排除；\nB 项，讨论的是当代话语下的主流价值，不是文化对社会成员的影响，不符合定义，\n排除；\nC 项，草原的文化对于草原人民性格的影响，符合定义，当选；\nD 项，《背影》的作者对父亲态度的转变，没有上升到文化对所属社会成员的影响，\n不符合定义，排除。\n故正确答案为C。"},{"q":"我国婚姻法规定，禁止直系血亲和三代以内旁系血亲结婚。直系血亲是指和自己有直接血缘关系的亲属，三代以内旁系血亲是指与己身出自同一父母或同一祖父母、外祖父母，除直系血亲外的所有血亲。根据上述定义，下列选项中的甲和乙可以结婚的是（  ）","options":["张某是甲（女）的姨父，乙系张某的儿子","李某是乙（女）的姑父，甲系李某的儿子","甲是林某与前夫的儿子，乙是林某与后夫的女儿","王某是张某的舅舅，甲系王某的儿子，乙系张某的女儿"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：禁止直系血亲和三代以内旁系血亲结婚；直系血亲是指\n和自己有直接血缘关系的亲属；三代以内旁系血亲是指与己身出自同一父母或同一祖父\n母、外祖父母，除直系血亲外的所有血亲。\nA 项，甲的姨与乙的母亲是同一人，甲与其姨有血亲关系，乙与其母亲也有血亲关\n系，因此两人有血亲关系。所以不能结婚，排除；\nB 项，乙的姑姑与甲的母亲是同一人，乙与其姑姑有血亲关系，甲与其母亲也有血亲\n关系，因此两人有血亲关系。所以不能结婚，排除；\nC 项，甲与乙是同母异父，属于三代以内旁系血亲，所以不能结婚，排除；\nD 项，王某是张某的舅舅，甲系王某儿子，乙系张某女儿，甲、乙二人不符合题干定\n义，可以结婚，当选。\n故正确答案为D。"},{"q":"木椅子效应是指将成绩相等的两组学生分别安排坐在舒适的沙发椅和很不舒服的木椅子上学习，不久之后，坐木椅子的学生学习成绩要比坐沙发椅的学生成绩高出许多。原因是坐木椅子的学生因为不舒服而不断调整坐姿，表面看来好像不安而好动，实质却因此给脑部供应了更多的血液和营养；而坐沙发椅的学生，由于舒适而一动不动，致使血液循环相对减慢，脑部得到的血液和营养相对减少，学习效果因此就差了一些。根据上述定义，下列选项最能体现木椅子效应的是（  ）","options":["某学生从小到大饱受责罚，学习成绩一直不理想","某家长为鼓励孩子暑天学习，每天为其提供冷饮","小刚每天步行上学和回家，风雨无阻，成绩很好","搬入新书房一个月后，小明的成绩名次一路攀升"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：“不舒服的木椅子”；“成绩高”。\nA 项，“学习成绩一直不理想”不属于“成绩高”，不符合定义，排除；\nB 项，“暑天为孩子提供冷饮”不属于“不舒服的木椅子”，不符合定义，排除；\nC 项，“小刚步行上下学”属于“不舒服的木椅子”，“学习好”属于“成绩高”，\n符合定义，当选；\nD 项，“搬入新书房”是将学习环境变得更好了，不属于“不舒服的木椅子”，不符\n合定义，排除。\n故正确答案为C。"},{"q":"随着科学技术的发展，人机交流已经成为现实，这其中的关键是脑机接口技术。所谓脑机接口，就是连接大脑与计算机之间的信息系统，可让大脑直接和计算机沟通。脑机接口可以从大脑传递信息到计算机，又可以从计算机传递信息进入大脑。根据上述定义，下列应用不属于脑机接口技术的是（  ）","options":["某游戏玩家的大脑植入一部装置，通过该装置用意念控制机械手，端起杯子喝茶","某游戏玩家佩戴一套义肢设备，经过多次练习，凭着坚强意志力，实现行走","某游戏玩家佩戴一种脸部饰品，饰品根据佩戴者的情绪变化作出相应的指示动作","某游戏玩家戴上一套高科技耳机，集中注意力，通过精神控制小球躲避障碍"],"a":1,"e":"【答案】B\n【解析】定义判断，选非题。关键词：“连接大脑与计算机”\nA 项，大脑植入装置后用意念控制机械手，属于“连接大脑与计算机”，符合定义，\n排除；\nB 项，佩戴义肢设备凭着意志力实现行走，不属于“连接大脑与计算机”，不符合定\n义，当选；\nC 项，饰品根据佩戴者的情绪变化作出相应的指示动作，情绪变化是受大脑控制的，\n属于“连接大脑与计算机”，符合定义，排除；\nD 项，“带上高科技耳机通过精神控制小球飞越各种障碍”，属于“连接大脑与计算\n机”，符合定义，排除。\n故正确答案为B。"},{"q":"数据挖掘（Datamining）是指从大量的存储数据中利用统计、情报检索、模式识别、在线分析处理和专家系统（依靠过去的经验）等方法或技术，发现隐含在其中、事先不知道但又是潜在有用的信息和知识的信息处理过程。根据上述定义，下列选项不属于数据挖掘应用的是（  ）","options":["某高校要求教师使用网上教学管理系统，录入学生的期末考试成绩，以便借助短信群发软件告知学生成绩","某国际快递和物流公司使用RFID（无线射频识别）技术在不同时间点跨境全程监控和调整药品装运的温度","某大型网上书店在客户选购一种图书时，推出“购买该商品的用户还购买了”等栏目，从而增加可观收益","某全球零售企业在分析上一年度消费者购物行为后推出“尿布啤酒”促销举措，使得二者销量大幅增加"],"a":0,"e":"【答案】A\n【解析】定义判断，选非题。关键词：大量的存储数据；发现潜在有用的信息。\nA 项，只是说教师利用教学管理系统录成绩，并没有从大量存储数据中“发现潜在有\n用的信息”，不符合定义，当选；\nB 项，某公司的药品符合“大量的存储数据”，监控并调整药品装运温度符合“发现\n潜在有用的信息”符合定义，排除；\nC 项，“客户选购图书”产生“大量的存储数据”，向客户推荐其他潜在需求的书品\n符合“发现潜在有用的信息”，符合定义，排除；\nD 项，“上一季度消费者购物行为”符合“大量的存储数据”，“推出新的促销举\n措”符合“发现潜在有用的信息”，符合定义，排除。\n故正确答案为A。"},{"q":"描写就是用生动形象的语言，把人物或景物的状态具体地描绘出来。从描写的角度分，可分为正面描写和侧面描写。正面描写是指直接展现景物、环境的特点或通过描写人物的外貌、心理和行动来体现人物的个性特征；侧面描写又叫间接描写，是从侧面的角度烘托人物形象、景物特征或相关事态。根据上述定义，下列选项既有正面描写，又有侧面描写的是（  ）","options":["一道残阳铺水中，半江瑟瑟半江红","大漠风尘日色昏，红旗半卷出辕门","天姥连天向天横，势拔五岳掩赤城","千里莺啼绿映红，水村山郭酒旗风"],"a":2,"e":"【答案】C\n【解析】定义判断。正面描写：①直接展现景物、环境的特点，②通过描写人物的外\n貌、心理和行动来体现人物的个性特征；侧面描写：从侧面的角度烘托人物形象、景物特\n征或相关事态。\nA 项，“一道残阳铺水中”描写的是夕阳斜照在江面上；“半江瑟瑟半江红”描写的\n是江水是一半绿色一半红色。两句都属于“直接展现景物、环境的特点”，都是正面描\n写，不符合定义，排除。\nB 项，“大漠风尘日色昏”描写的是大漠刮起了狂风遮天蔽日，属于“直接展现景\n物、环境的特点”；“红旗半卷出辕门”描写的是战士们半卷着红旗，向前挺进，走出辕\n门，属于“直接描写人物的行动”。两句都是正面描写，不符合定义，排除。\nC 项，“天姥连天向天横”描写的是天姥山高耸入云，连着天际，横向天外，属于\n“直接展现景物、环境的特点”；“势拔五岳掩赤城”意思是山势高峻超过五岳，盖过赤\n城山，\n通过对比从侧面凸显了天姥山的高，属于“从侧面的角度烘托景物特征”。前半句是\n“正面描写”，后半句是“侧面描写”，符合定义，当选。\nD 项，“千里莺啼绿映红”描写的是在广阔的江南大地上，黄莺欢快的鸣唱，绿树映\n衬着红花；“水村山郭酒旗风”描写的是傍水的村庄，依山的城郭，酒旗在迎风招展。两\n句都属于“直接展现景物、环境的特点”，都是正面描写，不符合定义，排除。\n故正确答案为C。"},{"q":"心理会计是指人们在心里无意识地把财富划归不同的账户进行管理，并对结果（尤其是经济结果）加以编码、分类和估价的过程，且不同的心理账户有不同的记账方式和心理运算规则。小到个体、家庭，大到企业集团，都有一套或隐或显的心理账户系统，其心理记账方式与经济学和数学的运算方式都不相同，因此经常以非预期的方式影响着决策，使个体的决策违背最简单的理性经济法则。根据上述定义，下列选项最能体现心理会计现象的是（  ）","options":["小陈已经攒够购买相机的钱，但他一定要等领到年底奖金再买相机","整日忧心忡忡的小李将自己全部存款的四分之三用于购买人寿保险","小王在两家不同银行都有储蓄卡，但他总是去离家更近的银行取款","小刘因公司奖励出游某地感觉不错，后来自费重游此地却感觉不佳"],"a":0,"e":"【答案】A\n【解析】定义判断。关键词：无意识；归不同的账户进行管理。\nA 项，年终奖和平时攒的钱都属于收入，用来买相机时这两类财富并无区别，但小陈\n一定要领到年终奖后才买相机，说明小陈“在心里无意识地”将平时攒的钱和年终奖“划\n归到了不同的账户进行管理”，符合定义，当选；\nB 项，小李将存款的四分之三用来购买保险，是有意识地将财富划归不同的账户进行\n管理，不符合定义，排除；\nC 项，小王在两家不同银行都有储蓄卡，属于现实层面的不同账户，而不是心理上\n的，不符合定义，排除；\nD 项，小刘获得的是公司的出游奖励，但出游只是活动，不属于小刘的财富，不符合\n定义，排除。\n故正确答案为A。\n第四组："},{"q":"博喻又称连比，就是用几个喻体从不同角度反复设喻去说明一个本体。博喻运用得当，能给人留下深刻的印象。运用博喻能加强语意，增添气势。博喻能将事物的特征或事物的内涵从不同侧面、不同角度表现出来，这是其他类型的比喻所无法达到的。根据上述定义，下列属于博喻的是（  ）","options":["这个整天同钢铁打交道的技术员，他的心倒不像钢铁那样","试问闲愁都几许？一川烟草，满城飞絮，梅子黄时雨","上海人叫小瘪三的那批角色，也很像我们的党八股，干瘪得很，样子十分难看","桃花潭水深千尺，不及汪伦送我情"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词：用几个喻体从不同角度反复设喻去说明一个本体\nA 项，把心比喻为钢铁，是从单一角度设喻，不符合“从不同角度反复设喻”不符合\n定义，排除；\nB 项，把“一川烟草”“满城风絮”“梅子黄时雨”多项景色比喻“闲愁”，符合\n“从不同角度反复设喻”，符合定义，当选；\nC 项，把角色比喻为党八股，是从单一角度设喻，不符合“从不同角度反复设喻”，\n不符合定义，排除；\nD 项，把汪伦与李白之间的感情之深比喻为超过千尺潭水的深度，是从单一角度设\n喻，不符合“从不同角度反复设喻”，不符合定义，排除。\n故正确答案为B。"},{"q":"初级群体指的是由面对面互动所形成的、具有亲密的人际关系和浓厚的感情色彩的社会群体；次级群体指的是其成员为了某种特定的目标集合在一起，通过明确的规章制度结成正规关系的社会群体。根据上述定义，下列涉及次级群体的是（  ）","options":["亲友团来到比赛现场为小李助威","小赵要到大城市上学了，山里的乡亲们都到村口为他送行","小王考上了研究生，公司的同事一起为他庆贺","20 年之后，小张儿时的玩伴建立了一个微信群"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：某种特定的目标；明确的规章制度。\nA 项，“亲友团”没有明确的规章制度，不属于次级群体，并且具有“亲密的人际关\n系和浓厚的感情色彩”，属于初级群体，不符合定义，排除；\nB 项，“乡亲们为其送行”没有明确的规章制度，并且具有“亲密的人际关系和浓厚\n的感情色彩”，属于初级群体，不符合定义，排除；\nC 项，“公司的同事为他庆贺”，公司一定有“明确的规章制度”，并且有特定的目\n标，即为了公司更好的发展。符合定义，符合定义，当选；\nD 项，“儿时的玩伴建立了一个微信群”，没有明确的规章制度，并且具有“亲密的\n人际关系和浓厚的感情色彩”，属于初级群体，不符合定义，排除。\n故正确答案为C。"},{"q":"择一的因果关系是指两个或者两个以上的行为人都实施了可能对他人造成损害的危险行为，并且已经造成了损害结果，但是无法确定其中谁是加害人。根据上述定义，下列存在择一的因果关系的是（  ）","options":["甲、乙两人在搬卸货物过程中因操作不当，造成货物损坏","甲在乙的饮水中下毒，乙喝下后在毒发前又因琐事与丙发生争吵，丙一怒之下用刀刺死了乙","甲、乙共同绑架了丙，甲负责向丙的家人索要赎金，乙为避免被丙认出，将丙残忍杀害","甲、乙、丙三人带着相同的猎枪和子弹外出狩猎，甲、乙看到一只猎物出现在丙附近，二人同时开枪，结果其中一枪打中了丙"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：可能对他人造成损害；无法确定其中谁是加害人。\nA 项，“造成货物损坏”，损害的是货物而不是人，不符合“可能对他人造成损\n害”，不符合定义，排除；\nB 项，“丙一怒之下用刀刺死了乙”，可以确定丙为加害人，不符合“无法确定其中\n谁是加害人”，不符合定义，排除；\nC 项，“乙为避免被丙认出，将丙残忍杀害”，可以确定加害人为乙，不符合“无法\n确定其中谁是加害人”，不符合定义，排除；\nD 项，“甲乙二人同时开枪，丙在附近”符合“可能对他人造成损害”，“结果其中\n一枪打中了丙”，并不知道打中丙的是谁，符合“无法确定其中谁是加害人”，符合定\n义，当选。\n故正确答案为D。"},{"q":"不规则需求是指某些物品或者服务的市场需求在不同季节，或一周不同日子，甚至一天不同时间上下波动很大的一种需求状况。据上述定义，下列哪项属于不规则需求（  ）","options":["早晚高峰期出租车供不应求","某品牌牙刷分为软、硬、中三种以面向不同消费者","某电商店庆打折，活动当天点击量剧增","某博物馆引进一批梵高画作巡展，游客蜂拥而至"],"a":0,"e":"【答案】A\n【解析】定义判断。关键词：不同时间；上下波动很大。\nA 项，出租车早晚需求高，其他时候需求低，体现了不同时间的需求波动性大，符合\n定义，当选；\nB 项，只是说了牙刷的软硬程度适合不同消费者，没有体现不同的时间，不符合定\n义，排除；\nC 项，点击量剧增，不代有需求，不符合定义，排除；\nD 项，某博物馆引进一批梵高画作巡展，游客蜂拥而至，没有体现不同的时间，不符\n合定义，排除。\n故正确答案为A。"},{"q":"企业从银行或海外取得外汇借款后并不是直接使用外汇资金，而是将外汇结汇给银行，取得人民币资金加以使用，这种现象称之为贷款替代。根据上述定义，下列哪项属于贷款替代（  ）","options":["人民币升值后，一些企业纷纷减少人民币负债，增加外汇负债，然后再用人民币进行投资","国内经济过热，商业银行对人民币贷款的发放从紧。某贸易公司出于财务考虑转向外资银行贷款，获得外币资金","王明觉得人民币利率高于美元，因此他申请美元贷款，然后将外汇结汇给银行，从而获得人民币资金","小宇出国旅游前去银行兑换了一些外币，到国外后他使用信用卡结算，回国后用人民币还款"],"a":0,"e":"【答案】A\n【解析】定义判断。关键词：企业、取得外汇借款、取得人民币资金。A 项，增加外\n汇负债符合取得外汇借款，再用人民币进行投资符合定义取得人民币资金，符合定义，当\n选；\nB 项，贸易公司获得外币资金不属于使用人民币资金，不符合定义，排除；C 项，王\n明不属于企业，不符合定义，排除；D 项，小宇不属于企业，不符合定义，排除。\n故正确答案为A。"},{"q":"选择性曲解是指人们面对客观事物，经常会不自觉地把外界输入的信息与头脑中早已存在的模式相结合，从而出现根据自己固有的价值体系和既定的情感好恶来解释所接受信息的倾向。根据上述定义，下列属于选择性曲解的是（  ）","options":["爱屋及乌","指鹿为马","按图索骥","度日如年"],"a":0,"e":"【答案】A\n【解析】定义判断。关键词：“既定的情感好恶”。\nA 项，“爱屋及乌”比喻爱一个人而连带地关心与他有关的人或物，与“情感好恶”\n有关，符合定义，当选；\nB 项，“指鹿为马”比喻故意颠倒黑白，混淆是非，与“情感好恶”无关，不符合定\n义，排除；\nC 项，“按图索骥”按照线索去寻找，与“情感好恶”无关，不符合定义，排除；\nD 项，“度日如年”形容困苦的日子长久难熬，与“情感好恶”无关，不符合定义，\n排除。\n故正确答案为A。"},{"q":"扩大论题和缩小论题在辩论赛中很常见。在相互的辩驳中，辩手们常常故意扩大对方的论题，将对方的论题推到荒谬的地步，以利于本方的反驳和进攻；同时为了利于本方立论与防守，辩手们又常常故意缩小本方的论题。根据上述定义，下列采用了扩大论题的是（  ）","options":["将论题“中学生异性交往弊大于利”解释成“中学生异性过分密切交往必定弊大于利”","将论题“人性本恶”解释成“人具有与生俱来的本能和欲望，因此人性是恶的”","将论题“德国人很严谨”解释成“所有德国人都很严谨”","将论题“人性本善”解释成“没有人不是善的”"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：“扩大对方的论题”。\nA 项，“中学生异性过分密切交往必定弊大于利”相较于“中学生异性交往弊大于\n利”为缩小论题，不符合定义，排除；\nB 项，“人性本恶”解释成“人具有与生俱来的本能和欲望，因此人性是恶的”，仅\n仅为解释说明，并没有论题的扩大，不符合定义，排除；\nC 项，“德国人很严谨”即“所有德国人都很严谨”，二者为同一关系，并没有论题\n的扩大，不符合定义，排除；\nD 项，“人性本善”意为“人刚出生的时候本来是善良的”，而“没有人不是善的”\n是泛指所有人都善良，为论题的扩大，符合定义，当选。\n故正确答案为D。"},{"q":"内隐学习是指一种无需意志努力的潜意识的学习。这种学习的特点在于人们潜意识地获得某种知识，而且无需意志努力就可以将这些知识提取出来，并应用于特定任务的操作中。根据上述定义，下列不属于内隐学习的是（  ）","options":["生长在京剧世家的孩子耳濡目染，很小就会唱京剧","小张在高考前做了大量数学习题，因此在数学考试中获得高分","小李经常看别人下象棋，时间一长，他也掌握了下象棋的方法","儿童无需系统地学习语词和语法规则，不知不觉地就会说母语"],"a":1,"e":"【答案】B\n【解析】定义判断，选非题。关键词：“无需意志努力的潜意识的学习”。\nA 项，“耳濡目染，很小就会唱京剧”，属于“无需意志努力的潜意识的学习”，符\n合定义，排除；\nB 项，“高考前做了大量数学习题”，说明考高分是因为做了习题，有意识的学习，\n不符合定义，当选；\nC 项，“经常看别人下象棋，时间一长，他也掌握了下象棋的方法”，说明掌握下象\n棋的方法是看别人下棋潜移默化学会的，符合定义，排除；\nD 项，“无需系统地学习语词和语法规则，不知不觉地就会说母语”，“不知不觉学\n会”说明是潜移默化过学会的，符合定义，排除。\n故正确答案为B。"},{"q":"注意分为内源性和外源性注意。内源性注意是指个体根据自己的目标或意图来分配注意，支配行为，是主动注意；外源性注意是指由个体外部信息引起的个体注意，是被动注意。根据上述定义，下列属于内源性注意的是（  ）","options":["根据客户的要求，广告设计师特别关注了大量以温馨家园为题材的售楼广告素材","“轰”的一声响，大家不由地都回头看了一眼","六一儿童节，公园里奇幻的魔术表演受到许多小朋友和家长的喜爱","超市琳琅满目的商品，包括各异、颜色鲜亮，吸引了许多顾客的眼球"],"a":0,"e":"【答案】A\n【解析】定义判断。关键词：“根据自己的目标或意图来分配注意”、“主动注\n意”。\nA 项，“特别关注”说明是主动的根据自己的意图来分配注意，符合定义，当选；\nB 项，大家回头看，是被“轰”的一声响所吸引的，属于“个体外部信息引起的个体\n注意”，属于外源性注意，不符合定义，排除；\nC 项，“魔术受到小朋友喜欢”，“魔术”也属于外部的信息，属于外源性注意，不\n符合定义，排除；\nD 项，“商品吸引顾客”，属于外部信息引发个体注意，不符合定义，排除。\n故正确答案为A。"},{"q":"顺从型互动是指行动者之间发生性质相同或方向一致的行动过程，常有三种形式：有意无意向他人发出信号或暗示，并引起他人反应；不经过考量，直接按照他人的方式去行动；行动者在他人压力下接受他人行动方式，并且照做。根据上述定义，下列不属于顺从型互动的是（  ）","options":["小文对新来的家教老师不满意，但无奈于父母的苦心和已缴的学费，还是开始了家教课程","护士阿姨一边说“不哭啊，一点都不疼”，一边在毛毛的手臂上注射，毛毛果然没哭","大家对小刘的业务能力有目共睹，连素来挑剔的老主任也赞成选小刘为业务主管","很多投资者寻找项目时什么热就投资什么，股票热炒时炒股票，翡翠热时炒翡翠"],"a":2,"e":"【答案】C\n【解析】定义判断，选非题。关键词：“有意无意向他人发出信号或暗示”、“不经\n过考量，直接按照他人的方式去行动”、“在他人压力下接受他人行动方式”。\nA 项，小文是受父母的压力从而开始家教课程，属于“在他人压力下接受他人行动方\n式”，符合定义，排除；\nB 项，“不哭啊，一点都不疼”属于“有意无意向他人发出信号或暗示”，符合定\n义，排除；\nC 项，“老主任也赞成选小刘为业务主管”不符合上述定义的任意一项，不符合定\n义，当选；\nD 项，“什么热就投资什么”属于“不经过考量，直接按照他人的方式去行动”，符\n合定义，排除。\n故正确答案为C。\n第五组"},{"q":"群体极化指的是群体成员中存在的某一种倾向性，通过群体相互影响而使结果得到加强并趋于极端化，从而偏离某种合理性的现象。群体极化通常存在两种情形，一种是使结果变得更为冒险甚至激进，称为冒险偏移；一种是使结果变得更加保守，称为谨慎偏移。根据上述定义，下列哪项中的现象不涉及群体极化（  ）","options":["一部略带瑕疵的电影在某网络论坛被批驳得一无是处","经过表决，答辩委员会一致否决了某同学的博士论文答辩","对某人的不良行为，大家均保持沉默，这使得他气焰更加嚣张","足球比赛中甲队因犯规被判点球，甲队球迷表示极大不满，并纷纷向场内投掷杂物"],"a":1,"e":"【答案】B\n【解析】定义判断，选非题。关键词：“群体相互影响”“偏离合理性”。\nA 项，“电影论坛”存在群体相互影响，“略带瑕疵被批的一无是处”符合偏离合理\n性，符合定义，排除；\nB 项，“答辩委员会”表决是每人独立的意见表达，不存在相互影响，不符合定义，\n当选；\nC 项，“大家均沉默”体现群体间影响，“气焰更加嚣张”符合偏离合理，符合定\n义，排除；\nD 项，“纷纷投掷杂物”属于群体互相影响，“因犯规被罚点球而球迷不满”也已经\n偏离了合理，符合定义，排除。\n故正确答案为B。"},{"q":"包容性增长即为倡导机会平等的增长，最基本的含义是公平合理地分享经济增长。它涉及平等与公平的问题，寻求的是社会和经济的协调发展及可持续发展，与单纯追求经济增长相对立。根据上述定义，下列哪项不涉及包容性增长（  ）","options":["增进社会不同阶层的相互理解，对各种社会矛盾增加容忍度","还田于海，退耕于林，延长禁捕期，对山林进行保护性封育","反对投资和贸易的地方保护主义，提倡投资和贸易自由化","在发展经济的同时充分重视社会保障体系的建立"],"a":0,"e":"【答案】A\n【解析】定义判断，选非题。关键词：“机会平等的增长”“寻求社会和经济协调可\n持续发展”。\nA 项，“社会阶层相互理解”没有体现经济增长，不符合定义，当选；\nB 项，“对山林进行保护性封育”是经济可持续发展的做法，符合定义，排除；\nC 项，“提倡投资和贸易自由化”体现了机会平等的增长，符合定义，排除；\nD 项，“发展经济并且重视社会保障”体现社会和经济协调可持续发展，符合定义，\n排除。\n故正确答案为A。"},{"q":"根据我国有关规定，职工遇有下列情形之一的，可以认定为工伤：（一）在工作时间和工作场所内，因工作原因受到事故伤害的；（二）在工作时间和工作场所内，因履行工作职责受到暴力等意外伤害的；（三）因工外出期间，由于工作原因受到伤害或者发生事故下落不明的；（四）在上下班途中，受到非本人负主要责任的交通事故或者城市轨道交通、客运轮渡、火车事故伤害的。根据上述规定，下列情形中可以认定为工伤的是（  ）","options":["周某开车在下班途中违章驾驶，与前车发生追尾事故，导致颅骨骨折","交警小李因纠正王某的违章行为引起王某不满，在上班途中遭到王某的殴打","赵某在车间加班时因操作不当，手指被绞进机器中，事后被鉴定为二级伤残","张经理为加深与同事的感情，在工作日邀请同事共进午餐，结果同事在用餐后不慎摔伤"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：“因工作原因”“因履行工作职责”“上下班途中非本\n人责任的交通事故”。\nA 项，“违章驾驶”是周某自己责任发生的交通事故，不符合定义，排除；\nB 项，上下班途中的交通事故才是工伤，下班途中遭到殴打不符合定义，排除；\nC 项，在车间手指受伤，符合因工作原因受伤，符合定义，当选；\nD 项，摔伤非工作原因，不符合定义，排除。\n故正确答案为C。"},{"q":"动物福利指的是尊重动物的权利、保护生态环境，促进人与动物协调发展。动物福利主要包括：生理福利，即无饥渴之忧虑；环境福利，即让动物有适当的居所；卫生福利，即尽量减少动物的伤病；行为福利，即保证动物表达天性的自由；心理福利，即减少动物恐惧和焦虑的心情。根据上述定义，下列哪项不涉及动物福利（  ）","options":["为了科研目的对动物进行活体实验时注射麻药","采取多种奖励方式，激发猴子表演高难度动作","在山区修建高速公路时预留多处动物过桥涵洞","养鸡场让母鸡在山林中自由觅食，提高产蛋率"],"a":1,"e":"【答案】B\n【解析】定义判断，选非题。关键词:“尊重动物”“生理福利”“环境福利”“卫\n生福利”“行为福利”“心理福利”选择不涉及的一项。\nA 项，“对动物做实验注射麻药”减少了动物恐惧和焦虑的心情，符合定义，排除；\nB 项，“激发猴子表演高难度动作”违背了动物的天性，不尊重动物，不符合定义，\n当选；\nC 项，“给动物留过桥涵洞”体现了动物的环境福利，符合定义，排除；\nD 项，“母鸡自由觅食”保证了动物表达天性的自由，符合定义，排除。\n故正确答案为B。"},{"q":"客体行政文化是指作为行政管理对象的个人、群体和组织对行政主体（主要是指行政机关）的行为做出合理的评价，其评价标准会因各自利益的不同而呈现多样性。根据上述定义，下列属于客体行政文化的是（  ）","options":["某地环保部门加大对污染严重企业的监管力度，其严肃执法的态度受到当地群众的一致好评","小王是某政府部门工作人员，工作认真负责，他的主管领导和同事都认为小王是一名合格的工作者","个体经营者张某未按规定缴税，税务部门向其下达限期缴纳税款的通知书，张某不但置乏不理，还责怪税务部门不该向其征税","某市工商部门为支持当地中小企业的发展，根据有关法律法规对这些企业实施优惠政策，这一举措得到了广大中小企业经营者的欢迎"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：“行政管理对象对行政主体”“合理的评价”。\nA 项，“当地群众对环保部门一致好评”群众不是环保部门的管理对象，不符合定\n义，排除；\nB 项，小王的领导和同事认为小王是合格工作者，这里不存在行政管理，不符合定\n义，排除；\nC 项，张某是税务部门的管理对象，但其责怪税务部门不该交税是不合理的评价，不\n符合定义，排除；\nD 项，中小企业是工商部门的管理对象，工商部门的举措受到企业欢迎，是合理的评\n价，符合定义，当选。\n故正确答案为D。"},{"q":"差别化信贷是指对不同地区、不同行业、不同群体、不同用途的信贷额度和还贷方式采取差别对待的政策。这是国家对经济进行宏观调控的重要手段，通过差别化信贷遏制两极分化趋势、促进社会公平、促进经济结构调整和全面可持续发展。根据上述定义，下列选项中属于差别化信贷的是（  ）","options":["2008 年年初，央行放宽商业银行信贷规模，全国性商业银行在原有信贷规模基础上调增5%，地方性商业银行在原有信贷规模基础上调增10%，共新增约2000 亿元贷款","某商业银行规定：贷款不满一年提前还款，收取不低于实际还款额三个月的利息；贷款满一年后提前还款，则收取不低于实际还款额一个月的利息","新购房政策规定：购买首套住房，且套型建筑面积在90 平米以下的家庭，可以享受首付款20%的政策；如果首套住房套型面积大于90 平米，贷款首付款比例不得低于30%","2009 年，某国际银行对中小企业的贷款总额较去年增长14%，同时又推出“幸福时贷”无担保个人贷款，18—55 岁的本地居民可获得最高50 万元的贷款"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：“还款方式差别对待”，“国家宏观调控手段”。\nA 项，央行放宽商业银行信贷规模，不存在还款方式，不符合定义，排除；\nB 项，某商业银行自己的规定，不属于国家宏观调控，不符合定义，排除；\nC 项，对于不同面积的住房首付款比例不同，是一种宏观调控手段且符合还款方式的\n差别对待，符合定义，当选；\nD 项，“某国际银行”不是国家宏观调控，不符合定义，排除。\n故正确答案为C。"},{"q":"相对剥夺感是指人们在与那些既和自己地位相近，又不完全等同于自己的人或群体做比较时，由价值期待和价值能力不一致的认知所产生的一种心理状态。根据上述定义，下列属于相对剥夺感的是（  ）","options":["参加学生会竞选的人数比往年多了一倍，小燕感到竞选的压力更大了","王某从海外名校学成归来，总觉得在单位里无法施展自己的才华和能力","小张经常出色地完成各项工作，项目组其他人认为小张就是喜欢表现自己","小杨原本认为自己的工作还不错，但是参加同学聚会后，他觉得跟同学相比显得没有前途"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：“和自己地位相近的人比较”“价值期待与价值能力不\n一致”。\nA 项，小燕感到有压力是因为竞选人数多了，并没有拿自己与他人比较，不符合定\n义，排除；\nB 项，王某无处施展才华也没有体现与他人比较，不符合定义，排除；\nC 项，“项目组的人认为小张喜欢表现自己”是别人对于小张的评价，没有小张的心\n理，不符合定义，排除；\nD 项，“小杨原本觉得自己工作还不错”是对于自己的期待，但是通过比较显得自己\n“没有前途”是自我期待与价值能力不一致造成的心理落差，符合定义，当选。\n故正确答案为D。"},{"q":"研究中把实际观测或调查的一部分个体称为样本，研究对象的全部称为总体。抽样误差是指抽样方法本身所引起的误差，即样本指标值与被推断的总体指标值之差。根据上述定义，下列不涉及抽样误差的是（  ）","options":["调查员因为粗心、疏忽等原因将样本数据登记错误","通过随机拨打电话了解大众对某品牌洗发水的忠诚度","要了解某班学生数学水平，将他们的数学期中考试成绩进行统计分析","要调查全国城市居民婚姻满意度，选取北京200 名已婚者作为调查对象"],"a":0,"e":"【答案】A\n【解析】定义判断，选非题。关键词：“抽样方法本身引起的误差”。\nA 项，“调查员粗心”将数据登记错误，是人为造成的，不符合定义，当选；\nB 项，“随机拨打电话”肯定会有大量的人调查不到，产生的误差就是抽样方法本身\n造成的。符合定义，排除；\nC 项，了解学生数学水平，只对期中考试成绩进行分析，得到数据肯定不够精准，这\n也是方法造成的误差。符合定义，排除；\nD 项，调查全国居民婚姻满意度，只选取北京200 名调查对象，调查不够全面造成的\n误差也是调查方法本身造成的。符合定义，排除。\n故正确答案为A。"},{"q":"军事上的电子欺骗指的是利用电子设备对己方的相关信息进行伪装或者虚假模拟，欺骗敌方的电子侦察，使敌方对己方部署、作战能力和作战企图等产生错误判断，从而达到迷惑和扰乱敌方的目的。根据上述定义，下列涉及电子欺骗的是（  ）","options":["军事演习时蓝军故意丢失伪造的电子作战地图，佯装泄露己方情报","某国将无人机藏匿于敌国领空，冒充敌国领导人编制、发布虚假命令","二战中盟军虚设了一个司令部，用通讯设备源源不断地发送各种“指挥命令”","驻扎在太平洋小岛的某部为其计算机系统设置了数量庞大的仿真数据库"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：“对己方信息进行伪装或者模拟”“欺骗敌方电子侦\n察”。\nA 项，“故意丢失地图”不是对自己信息的伪装或者模拟，不符合定义，排除；\nB 项，“冒充敌国领导发假命令”伪装的是对方不是自己，不符合定义，排除；\nC 项，“虚设司令部”是对自己信息的模拟去欺骗敌方，符合定义，当选；\nD 项，“设置仿真数据库”没有体现对敌方电子侦察的欺骗，不符合定义，排除。\n故正确答案为C。"},{"q":"统计性歧视，是指将一个群体的典型特征推断为群体中的个体具有的特征，并将此特征作为对个体的评价标准。根据上述定义，下列属于统计性歧视的是（  ）","options":["小莉觉得周围许多金牛座的人都不太诚实，她就认为金牛座的人都不诚实可靠","公司认为某高校毕业生工作稳定性不够，该校的优秀毕业生小刘因此未被公司录取","某专家根据北京市过去十年的降雨量推断今年的降雨量将与往年的平均值基本持平","一名外国游客在旅游区随手乱扔垃圾，周围人们认为来自这个国家的人素质普遍较低"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词：“群体特征推断为群体中个体特征”。\nA 项，“周围许多金牛座的人”为个体，“觉得金牛座的人都不可靠”是个体特征推\n断到整体，不符合定义，排除；\nB 项，“某高校毕业生稳定性不够”是整体的特征，因此不录取该校毕业生小刘，是\n将群体特征推断到了小刘这个个体上，符合定义，当选；\nC 项，“今年降雨量”不包括在“过去十年”这个群体当中，不符合定义，排除；\nD 项，“外国游客乱扔垃圾”“认为这个国家人素质普遍低”，是由个体推断整体特\n征，不符合定义，排除。\n故正确答案为B。\n第六组："},{"q":"“社会人”假设是组织行为学家提出的一种与管理有关的人性假设。“社会人”假设认为，人们在工作中得到的物质利益对于调动其生产积极性是次要的，人们最重视在工作中与周围的人友好相处，良好的人际关系对于调动人的工作积极性起决定作用。根据上述定义，下列哪项是基于“社会人”假设的管理方式（  ）","options":["员工的奖金与绩效挂钩，并且实行秘薪制","鼓励、支持员工利用业余时间参加职业培训","对不同年龄层的员工实行不同的管理措施","上级和下级不同程度地参与企业决策的研究和讨论"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：“良好的人际关系对于调动人的工作积极性起决定作\n用”。\nA 项，奖金与绩效没涉及到“人际关系”，不符合定义，排除；\nB 项，业余时间参加职业培训没涉及到“人际关系”，不符合定义，排除；\nC 项，实行不同的管理措施都没涉及到“人际关系”，不符合定义，排除；\nD 项，强调上级和下级共同参与，是一种人际交流符合“人际关系”，符合定义，当\n选。\n故正确答案为D。"},{"q":"顺从是指互动中的一方自愿或主动地调整自己的行为，按另一方的要求行事，即一方服从另一方。顺应的含义比顺从更广泛，除了有顺从的含义外，还指互动的双方或各方都调整自己的行为，以实现互相适应。根据上述定义，下列行为属于顺应的是（  ）","options":["王某经常将垃圾堆放在家门口，影响了居民楼内的环境卫生，邻居们向他提出意见后，王某家门口变得干净起来","小燕经常出色地完成各项工作，经理根据小燕的表现在员工大会上表扬了她，并给予奖励","某食品厂因存在不正当竞争行为，被工商部门处以20 万元罚款，该厂以罚款过重为由提起行政复议，上级工商部门作出罚款10 万元的决定","强盛公司与荣发公司有意进行合作，经过多轮激烈地磋商，双方都降低了自己的条件，从而实现了合作目标"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：“互动的双方或各方都调整自己的行为”。\nA 项，只是王某单方面调整不符合关键词“双方都调整”，不符合定义，排除；\nB 项，根本没有调整行为不符合关键词“双方都调整”，不符合定义，排除；\nC 项，是单方面调整不符合关键词“双方都调整”，不符合定义，排除；\nD 项，强盛公司与荣发公司双方都降低了自己的条件，符合定义，当选。\n故正确答案为D。"},{"q":"体验营销是指企业采用让目标顾客观摩、聆听、尝试、试用等方式，使其亲身体验企业提供的产品或服务，让顾客实际感知产品或服务的品质或性能，从而促使顾客认知，喜好并购买的一种营销方式。根据上述定义，下列采用了体验营销方式的是（  ）","options":["某美容公司举办了一场以“亲子教育”为主题的消费者联谊会，把“为消费者着想”的经营理念传递给潜在的客户","某服装公司邀请批发商参加其产品推广介绍会，在会上安排了表演、小竞赛、新产品试用等活动","某公司为维护行业领军地位，多次举办全国性的行业讨论会，邀请其部分消费者参与研讨","某化妆品公司先打开国外市场，树立国际品牌形象，然后在国内以电视购物的方式传播销售，逐步占领国内市场"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词：“使其亲身体验企业提供的产品或服务”。\nA 项，把经营理念传递给潜在的客户，没有“使消费者产品体验”，不符合定义，排\n除；\nB 项，安排的表演、小竞赛、新产品试用等活动使顾客对产品有了体验，符合定义，\n当选；\nC 项，邀请其部分消费者，没有“使消费者产品体验”，不符合定义，排除；\nD 项，以电视购物的方式传播销售，没有体验到产品，没有“使消费者产品体验”，\n不符合定义，排除。\n故正确答案为B。"},{"q":"行政指令是指行政主体依靠行政组织的权威，运用行政手段，包括行政命令、指示、规定、条例及规章制度等措施，按照行政组织的系统和层次进行行政管理活动的方法。根据上述定义，下列描述不属于行政指令的是（  ）","options":["体育局局长签发嘉奖令，表彰在全运会上取得优异成绩的运动员和教练员","消费者协会同中国家用电器协会正式发布《太阳能热水器选购指南》","市教育局紧急电话通知，要求全市中小学、幼儿园加强校园安全管理","市消防大队对未经消防设计备案擅自施工的违法工程下发《责令改正通知书》"],"a":1,"e":"【答案】B\n【解析】定义判断，选非题。关键词：行政主体。\nA 项，“体育局”符合行政主体，符合定义，排除；\nB 项，“消费者协会”是对商品和服务进行社会监督的保护消费者合法权益的全国性\n社会组织，不是行政主体，不符合定义，当选；\nC 项，“市教育局”符合行政主体，符合定义，排除；\nD 项，“市消防大队”符合行政主体，符合定义，排除。\n故正确答案为B。"},{"q":"政策性收益是指由于某些政策、法规的变动而导致的个体收益，这种收益不会导致整个社会财富的增长，只会导致整个社会财富的重新分配。根据上述定义，下列涉及政策性收益的是（  ）","options":["由于市相关部门联合整治经营环境，小张经营的书店效益明显好转，每月营业额增加5000 元","歹徒意欲行凶，小王挺身而出制服了歹徒，因此获得市政府见义勇为奖5 万元","由于国家加大西部开发力度，某县获得了5000 万元专项水利建基金","由于利率调整，小李的存款利息比此前每月增加100 元"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：政策性收益是指由于某些政策、法规的变动而导致的个\n体收益。\nA 项，“市相关部门联合整治经营环境”不涉及“政策、法规的变动”不符合定义，\n排除；\nB 项，市政府因小王见义勇为授奖不涉及“政策、法规的变动”不符合定义，排除；\nC 项，某县获得了5000 万元，不是“个体收益”不符合定义，排除；\nD 项，“利率调整”符合“政策、法规的变动”，小李的存款利息增加100 元是“个\n体收益”，符合定义，当选。\n故正确答案为D。"},{"q":"反应性相倚是指在沟通过程中，沟通双方都以对方的行为作为自己行为的依据，做出相应的反应，而并不按照原来的计划进行沟通。根据上述定义，下列属于反应性相倚的是（  ）","options":["妈妈得知小明考试失利准备劝慰一番，但她发现小明的情绪并未受到影响，于是放弃了劝慰小明的打算","王厂长在大会上宣读了关于加强劳动纪律的发言稿，由于制定的措施不合理，职工在下面议论纷纷，但他还是完成了自己的发言","张老师认为他为学生准备的口试题目并不难，但是仍有一些学生回答不出，当学生要求张老师提示时，张老师断然拒绝","小李同意按照编辑意见修改稿件，但希望保留原文的写作风格，与编辑沟通后，编辑表示同意"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：反应性相倚是指沟通双方都并不按照原来的计划进行沟\n通。\nA 项，只有妈妈单方面改变计划，不满足双方，不符合定义，排除；\nB 项，王厂长按照原计划完成了发言，按照原来的计划，与定义相反，不符合定义，\n排除；\nC 项，张老师断然拒绝，也是按照原来计划进行，与定义相反，不符合定义，排除；\nD 项，小李和编辑相互理解，都做出让步，体现了“双方不按照原计划”，符合定\n义，当选。\n故正确答案为D。"},{"q":"附款行政行为是指除行政法规明确规定外，行政主体根据实际需要在主内容基础上附加从属性内容的行政行为。这里的附款就是附加条件，是行政主体规定（而不是行政法规规定）的某种将来不确定事实或行为，该条件是否符合将决定法律行为的效力。根据上述定义，下列属于附款行政行为的是（  ）","options":["某省物价局在关于小儿广谱止泻口服液的价格批复中规定该药物每盒不得高于36元，此价格从2009 年9 月30 日起执行","某税务所对王某（现在外地打工）偷税行为作出的处理决定是：处王某罚款1500元，所处罚款及所欠税款待王某回乡后缴清","交通警察李某对超速驾驶的刘某作出罚款100 元的处罚决定，同时告知刘某应在规定的时间内到指定地点缴纳罚款，逾期需缴纳滞纳金","某市人民政府为发展地方经济，规划未来五年内在本市南部建立高新技术产业开发区，吸引一批高新技术企业前来投资"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词：“除行政法规明确规定外”、“从属性内容”。\nA 项，“物价局规定药价及执行时间”，属于行政法规明确规定，并无从属性内容，\n不符合定义，排除；\nB 项，“税务所对王某做出罚款决定”，属于行政法规明确规定，“待王某回乡后缴\n清”，属于从属性内容，符合定义，当选；\nC 项，“交警作出罚款处罚，并告知时间地点”，是属于行政法规明确规定，并无从\n属性内容，不符合定义，排除；\nD 项，“地方经济规划”，并不属于行政法规明确规定，不符合定义，排除。\n故正确答案为B。"},{"q":"反向诱导是指政府、媒体等主体所采取的措施或者宣传活动，在实际的社会生活中不但没有收到预期的效果，反而导致了与预期相反的社会现象大量出现。根据上述定义，下列属于反向诱导的是（  ）","options":["某影院为了让观众摘下帽子，在银幕上打出通告：“本院允许老年人戴帽观赏。”结果通告一出，许多观众纷纷摘下了帽子","某单位要求员工统一着装，结果招致单位很多女员工的强烈反对，最后只好不了了之","高温季节供水相对紧张，某市自来水公司贴出告示，告知市民近期不会停水，结果导致很多市民在家中大量囤水备用","某电视台播放预防心理疾病的讲座，很多市民对号入座，觉得自己得了心理疾病，纷纷打电话咨询"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：“与预期相反的社会现象大量出现”。\nA 项，影院通告允许老年人戴帽观赏，也就是不允许非老年人戴帽观赏，“很多观众\n纷纷摘下了帽子”，说明与预期相同，不符合定义，排除；\nB 项，“最后只好不了了之”，无法得知是否大量出现与预期相反的社会现象，不符\n合定义，排除；\nC 项，“告知市民近期不会停水”，目的是让大家不囤水，但结果“市民大量囤水备\n用”，与预期相反的社会现象大量出现，符合定义，当选；\nD 项，“播放预防心理疾病的讲座”，让大家预防，现市民纷纷打电话咨询，目的也\n是预防，故明并没有大量出现与预期相反的社会现象，不符合定义，排除。\n故正确答案为C。"},{"q":"仿生设计学以自然界万事万物的“形”“色”“音”“功能”“结构”等为研究对象，有选择地在设计过程中应用这些特征原理，同时结合仿生学的研究成果，为设计提供新的思想、新的原理、新的方法和新的途径。其中，结构仿生设计学主要研究生物体和自然界物质存在的内部结构原理在设计中的应用问题，适用于产品设计和建筑设计。根据上述定义，下列属于结构仿生设计的是（  ）","options":["设计师根据鱼鳔的作用原理发明了潜艇","科学家发明了能够模仿鱼类声音的电子诱鱼器","受变色龙的启发，军方设计出适用于野外作战的迷彩服","我们的祖先有巢氏受鸟类在树上筑巢的启发，发明“巢居”以防御猛兽的攻击"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：“内部结构原理”。\nA 项，潜艇是利用鱼鳔贮存气体的多少，而上浮下潜的原理，并不是内部结构原理，\n不符合定义，排除；\nB 项，电子诱鱼器是利用的声音而并非内部结构原理，不符合定义，排除；\nC 项，迷彩服是利用变色龙的变色隐匿而并非内部结构原理，不符合定义，排除；\nD 项，“巢居”是利用鸟类在树上筑巢的结构而建造，属于内部结构原理，符合定\n义，当选。\n故正确答案为D。"},{"q":"非正式组织是指人们在共同工作或相互接触中，以感情、性格、爱好相投为基础形成的若干人群。这些群体不受正式组织的行政部门和管理层次等的限制，也没有明确规定的正式结构，但在其内部形成一些特定的关系结构，自然涌现出自己的“领导者”，形成一些不成文的行为准则和规范。根据上述定义，下列提及的人群属于非正式组织的是（  ）","options":["老王过生日，邀请了十多位同事在自己家中聚会","小刘下班后和本单位的几名年轻人一起踢足球","小张是校学生会文艺部部长，经他介绍，几名同学参加了文艺演出","几位退休职工自发成立老人曲艺社，利用周末时间在社区演出"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：“非正式组织”。（定义本身也可以作为关键词，强调\n“组织”）\nA 项，老王生日聚会并不能形成一个组织，不符合定义，排除；\nB 项，小刘和同事踢球并不能形成一个组织，不符合定义，排除；\nC 项，几名同学参加了文艺演出，但文艺演出只是一次活动，并不能形成一个组织，\n不符合定义，排除；\nD 项，自发成立老人“曲艺社”，已经形成一定组织，符合定义，当选。\n故正确答案为D。\n第七组："},{"q":"差别比例税率是指一种税设两个或两个以上的税率，不同纳税人按不同比例计算应纳税额的税率；累进税率是指随着征税对象的数额由低到高逐级累进，所使用的税率也随之逐级提高的税率。根据上述定义，下列各项中所提到的税率，属于差别比例税率的是（  ）","options":["对于某企业来说，需缴纳25%的企业所得税，还需缴纳5%的营业税","我国个人所得税中对工资薪金所得适用的税率随工资薪金所得增多而逐渐增多，从5%到45%共分为九档","2009 年1 月20 日至12 月31 日，我国对1.6 升及以下排量的乘用车按5%征收车辆购置税，对1.6 升以上排量乘用车按10%征收车辆购置税","我国自2009 年1 月1 日起实施成品油税费改革，将成品油价内征收的汽油消费税单位税额每升提高0.8 元，即由每升0.2 元提高到1 元"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词“一种税设两个或两个以上的税率”。\nA 项，企业所得税和营业税是两种税，不符合定义，排除；\nB 项，属于累进税，不符合定义，排除；\nC 项，同一种税，不同排量的车收取不同的税，符合定义，当选；\nD 项，税费改革，税收提高了，不符合定义，排除。\n故正确答案为C。"},{"q":"美国社会学家默顿将社会功能划分为显功能和潜功能两个层次，显功能是有助于系统的调整和适应的客观后果，这种适应和调整是系统中的参与者所期望达到或能预料、认识到的；潜功能是没有被预料也没有被认识的客观后果。下列选项不包含对潜功能描述的一项是（  ）","options":["电视剧《渴望》播放期间，万人空巷，社会治安明显好转","张某根据自己的家庭收入状况，贷款30 万买了一套房子，由于利率上升，自己的生活变得捉襟见肘","为抵御外族入侵，秦始皇修筑了长城，客观上促进了我国民间建筑工艺的发展","来自偏远山区的小刘为了摆脱贫困，让父母过上好日子，从小刻苦学习，做事认真，没几年功夫就成为一家大型企业的负责人，也使自己成为家乡父老教育孩子的榜样"],"a":1,"e":"【答案】B\n【解析】定义判断，选非题。关键词“没有被预料也没有被认识的客观后果”。\nA 项，《渴望》会导致治安好转是没有预料到的，符合定义，排除；\nB 项，属于个人行为，不是社会层面的，不符合定义，当选；\nC 项，长城促进了民间工艺发展，符合定义，排除；\nD 项，小刘的成功是没有预料到的，成为家乡父老教育孩子榜样体现出一定的社会效\n应，因此属于潜功能，符合定义，排除。\n故正确答案为B。"},{"q":"角色模糊是指个人所体验到的工作角色定位的不确定性，包括工作职责的不确定、工作目标的不确定等，因此常造成工作流程上的混乱和工作效率的低下。根据上述定义，下列属于角色模糊的是（  ）","options":["张大夫身兼数职，是某医院骨科主任，同时又担任该医院的副院长、该地区医学会委员等，工作繁忙使他日益憔悴","苏丽刚升任客服部的副总监，有些事务她不知道是否该自己处理，如果处理了是否会超出目前的权限，也不知道去问谁，对于这些事务她通常就不处理","小陈刚当上小学老师，想跟学生做朋友，尽管她现在跟学生的关系很亲密，可她发现学生们不怕她，不听话，甚至作业也不交","小张刚参加工作，满怀热情，一心想在工作岗位上充分发挥自己的专业特长，但却不得不经常做些与其专业无关的工作，他因此觉得心理落差很大"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词“工作角色定位的不确定性”、“工作流程上的混乱和工\n作效率的低下”。A 项，张大夫只是身体憔悴，而对于工作角色没有表现出混乱，不符合\n定义，\n排除；B 项，由于刚升任副总监，苏丽不清楚副总监的工作职责，导致效率下降，符\n合定义，\n当选；C 项，小陈清楚自己的身份是教师以及职责，不符合定义，排除；D 项，小刚\n因为工作内容非其专业，导致心理出现落差，但并非工作效率问题，不符合定义，排除。\n故正确答案为B。"},{"q":"生态入侵是指人们有意识或者无意识地把某些生物带入适宜其栖息和繁衍的地区，使得该生物种群不断扩大，分布区不断稳定地扩展，从而危害当地的生产和生活，改变当地生态环境的过程。根据上述定义，下列属于生态入侵的是（  ）","options":["某实验室由于管理不当将试验用的致病性结核菌株散播了出去，造成结核病在周围居民中流行","美国科学家将从我国引进的野生大豆与当地品种杂交，培育出抗大豆萎黄病的优良品种，该品种现已彻底取代了美国传统大豆","某地发生大面积放射性核素泄露，使某种植物发生变异，其繁殖能力超强，逐渐取代了该地域内的其他植物","产于南美洲的凤眼莲花朵艳丽，曾经作为观赏植物被我国引进，致使云南滇池因为凤眼莲的疯狂蔓延而鱼虾绝迹"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词“生物种群不断扩大”“危害当地的生产和生活”“改变\n当地生态环境的过程”。\nA 项，致病性结核菌对人产生了危害，并非生态环境，不符合定义，排除；\nB 项，优良品种取代传统大豆，没有危害当地的生产和生活，不符合定义，排除；\nC 项，原有植物发生变异，而非引入某种外来生物，不符合定义，排除；\nD 项，凤眼莲导致鱼虾绝迹，破坏当地生态系统，符合定义，当选。\n故正确答案为D。"},{"q":"宜家效应是指劳动会增加人们对劳动成果的感情，当人们自己动手制作东西时，他们都会觉得自己的创作特别有价值。根据上述定义，下列最能体现宜家效应的是（  ）","options":["让人们亲手做折纸，然后连同他人做的折纸放在一起竞价，结果大家都愿意为自己做的折纸出更高的价钱","某公司为方便人们制作蛋糕，推出方便蛋糕粉，使蛋糕的制作非常简单","某家具生产商生产的家具需要顾客买回家后，按照产品说明书来完成家具的拼装组合工作","学校鼓励学生自己动手制作各种教具，不仅锻炼了学生的动手能力，还节约了教学成本"],"a":0,"e":"【答案】A\n【解析】定义判断。关键词“劳动”“自己动手”“特别有价值”。\nA 项，折纸付出了自己劳动，价钱更高显示出特别有价值。符合定义，当选；\nB 项，没有涉及人们自己的劳动，只是售卖制作蛋糕的原材料，并没有说明人们在做\n蛋糕，不符合定义，排除；\nC 项，自己组合拼装，但没有显示出特别有价值，不符合定义，排除；\nD 项，依然不涉及自己的劳动特别有价值这条，不符合定义，排除。\n故正确答案为A。"},{"q":"证实性偏见是指过于关注支持自己决策的信息。当我们在主观上认为某种观点正确的时候，往往倾向于寻找那些能够支持这一观点的信息，而忽略掉那些可能推翻这一观点的信息。根据上述定义，下列属于证实性偏见的是（  ）","options":["小张前天夜里梦见自己的钱包被偷，昨天钱包真的被偷了；昨晚他又梦见自己被车撞，结果今天一整天没敢出门","小张总觉得室友最近的表现很反常，好像出什么事了，第二天公安局的人找到小张询问情况，证实了他的猜测，室友被扯进了一起盗窃案","自从小王产生辞职的念头以后，总觉得经理处处刁难他，甚至看不起他，就连经理和他开个玩笑，都认为是对他的嘲笑","小林今年未考上重点大学，他明知是因为自己实力不够，但他总是对同学说：“要不是考试前患了感冒，我肯定考得更好。”"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词“观点正确”“寻找支持信息，忽略推翻的信息”。\nA 项，不涉及寻找支持信息，不符合定义，排除；\nB 项，小张没有寻找证据支持自己的猜测，不符合定义，排除；\nC 项，辞职念头产生后，将经理的玩笑都当做是对自己的嘲笑，寻找信息支持自己，\n符合定义，当选；\nD 项，小林主观上知道自己实力不够，即不认为自己观点正确，不符合定义，排除。\n故正确答案为C。"},{"q":"存疑时有利于被告原则是指在刑事诉讼中遇到事实无法查清或查清事实所需成本过高的情况，依照有利于被告的原则判决。根据上述定义，下列表现符合该原则的是（  ）","options":["因缺少直接证据证实被告人有罪，法院对被告人做出无罪判决","无法确定某犯罪行为是否超过追诉时效时，应当追诉","检察机关认为被告人犯罪情节显著轻微，决定免于起诉","法院在认定被告人犯有数罪或一罪之间存在疑问时，发回公安机关补充侦查"],"a":0,"e":"【答案】A\n【解析】定义判断。关键词“事实无法查清或查清事实所需成本过高”“有利于被告\n的原则判决”。\nA 项，缺少证据说明事实难以查清，判无罪有利于被告，符合定义，当选；\nB 项，追诉意味着对被告不利，不符合定义，排除；\nC 项，犯罪事实能够查清，不符合定义，排除；\nD 项，法院确定被告有罪，只是无法确定存在几条罪责，不符合定义，排除。\n故正确答案为A。"},{"q":"同类群体影响力是指人们对他人（尤其是类似群体）的行为总会做出某种反应；类似程度越高，影响力就越大。比如对某种良好行为规范大力宣传，往往会成为所谓的“磁心”，吸引人们仿效。下列做法中不会带来同类群体影响力的是（  ）","options":["某地节水办告知那些用水量高的用户，他们的用水量明显高出了周围的邻居","某森林公园设置告示牌，告知偷盗林木者将受到高于林木价钱10 倍的罚款","酒店在房间内放置标语，提醒客人大多数客人都不是每天要更换毛巾","老师在墙报上贴小红花，表扬那些完成作业好，守纪律的小学生"],"a":1,"e":"【答案】B\n【解析】定义判断，选非题。关键词“人们对他人（尤其是类似群体）的行为总会做\n出某种反应”。\nA 项，节水办的告知会导致用水量高的用户注意节约用水，向周围的邻居学习，属于\n同类群影响，符合定义，排除；\nB 项，告示牌是给公园的游客看的，但游客的行为不会受到偷盗林木者的影响，不符\n合定义，当选；\nC 项，标语会导致客人向大多数人学习，符合定义，排除；\nD 项，获得小红花的学生会带动其他学生，符合定义，排除。\n故正确答案为B。"},{"q":"蓄积器官是毒物在体内的蓄积部位，毒物在蓄积器官内的浓度高于其他器官，但对蓄积器官不一定显示毒作用。这种毒作用也可以通过某种病理生理机制，由另一个器官表现出来，这种器官叫作效应器官。根据上述定义，下列判断正确的是（  ）","options":["大气污染物中的铅经肺吸收后可转移并积存于人的骨骼中，损害骨骼造血系统，所以铅的蓄积器官是肺","大气污染物中的二氧化硫经人体的上呼吸道和气管吸入人体，并直接刺激上呼吸道和气管，所以上呼吸道和气管是蓄积器官","有机磷酸酯农药作用于神经系统，会造成神经突触处乙酰胆碱蓄积，使人产生流涎、瞳孔缩小等症状，所以神经系统是有机磷酸酯的效应器官","沉积于网状内皮系统的放射性核素对肝、脾损伤较重，引起中毒性肝炎，所以网状内皮系统是蓄积器官"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词“毒物在蓄积器官内的浓度高于其他器官”“不一定显示\n毒作用”。\nA 项，存积于骨骼中，所以蓄积器官应该是骨骼，不符合定义，排除；\nB 项，上呼吸道受到刺激，但并没有说在此毒物沉积，不符合定义，排除；\nC 项，神经系统应该是蓄积器官，不符合定义，排除；\nD 项，在网状皮层系统积蓄，所以它是蓄积器官，符合定义，当选。\n故正确答案为D。"},{"q":"偶然防卫是指在客观上被害人正在或者即将对被告人或他人的人身进行不法侵害，但被告人主观上没有认识到这一点，出于非法侵害的目的而对被害人使用了武力，客观上起到了人身防卫的效果。根据上述定义，下列行为不属于偶然防卫的一项是（  ）","options":["甲与乙积怨很深，某日发生冲突后，甲回家拿了手枪打算去杀乙，两人在路上正好碰上，甲先开枪杀死了乙，但开枪时不知乙的右手已抓住口袋中的手枪正准备对其射击","甲正准备枪杀乙时，丙在后面对甲先开了一枪，将其打死，而丙在开枪时并不知道甲正准备杀乙，纯粹是出于报复泄恨的目的杀甲，结果保护了乙的生命","甲与乙醉酒后发生激烈冲突，两人相互厮打至马路上，正当甲要捡起路边砖头击打乙时，围观群众中有人喊“警察来啦”，甲受惊吓不慎跌落路边河沟溺水身亡，乙安全无事","甲身穿警服带着电警棍，冒充警察去“抓赌”，甲抓住乙搜身时，乙将甲打伤后逃离，甲未能得手"],"a":2,"e":"【答案】C\n【解析】定义判断，选非题。关键词“客观上被害人正在进行不法侵害”“被告人主\n观上没有认识到这一点”“对被害人使用了武力，客观上起到了人身防卫的效果”。\nA 项，被害人是乙，被告人是甲，甲开枪前不知道乙要杀自己，符合定义，排除；\nB 项，被害人是甲，被告人是丙，丙在开枪时不知道甲要杀人，符合定义，排除；\nC 项，被害人是甲，但甲的死亡是由于受惊吓不慎跌落，而非武力导致，不符合定\n义，当选；\nD 项，被害人甲，被告人乙，乙在打伤甲时不知甲的真实身份，符合定义，排除。\n故正确答案为C。\n第八组："},{"q":"垂直绿化指的是利用攀援植物向空中生长进行纵向绿化的一种方式，以期达到在有限面积内最大限度地利用空气和阳光来提高绿化的效率。根据上述定义，下列涉及垂直绿化的是（  ）","options":["爬山虎爬满了墙头和屋顶","松树林从山脚一直延伸到山顶","利用巴根草匍匐攀援的特性，人们在沙漠中逐渐开拓出一片绿洲","在丘陵地区，人们常使用飞机从空中播种的方式对山地进行绿化"],"a":0,"e":"【答案】A\n【解析】定义判断。关键词：利用攀援植物向空中生长。\nA 项，爬山虎属于攀援植物，爬满墙头和屋顶是向空中生长，符合定义，当选；\nB 项，松树不属于攀援植物，不符合定义，排除；\nC 项，沙漠中的巴根草为匍匐生长，不是向空中生长，不符合定义，排除；\nD 项，没有出现攀援植物，不符合定义，排除。\n故正确答案为A。"},{"q":"赋、比、兴指的是诗歌的三种表现手法。赋：铺陈直叙，把思想感情及其有关的事物平铺直叙地表达出来；比：类比，以彼物比此物，使此物更加生动具体、鲜明浅近；兴：先言他物，然后借以联想，引出诗人所要表达的事物、思想、感情。根据上述定义，下列诗句中使用了“比”的是（  ）","options":["死生契阔，与子成说。执子之手，与子偕老","七月流火，九月授衣。春日载阳，有鸣仓庚","我心匪石，不可转也。我心匪席，不可卷也","手如柔荑，肤如凝脂。领如蝤蛴，齿如瓠犀"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：以彼物比此物。\nA 项，表现的是忠贞不渝的情谊，没有用到比喻的手法，不符合定义，排除；\nB 项，描写了不同时间点人们的家事生活，没有用到比喻的手法，不符合定义，排\n除；\nC 项，“我心匪石，不可转也”意思是我的心不是石头不能随便转移。并没有拿其他\n事物比喻我心，没有用到比喻的手法，不符合定义，排除；\nD 项，将手指比作白嫩的茅草芽，皮肤比作脂膏，颈项比作天牛的幼虫儿，牙齿比作\n葫芦子。采用了比喻的手法，符合定义，当选。\n故正确答案为D。"},{"q":"经济学中，系统内部个别效率较高的组织的出现，会对其他效率较低的组织的存在和发展构成破坏或抑制，人们把这种作用称为“顶尖效应”。由于个人之间、地区之间、国家之间的发展不平衡，因此“顶尖效应”是普遍存在的。根据上述定义，下列有助于避免“顶尖效应”的是（  ）","options":["发达国家甲与经济落后国家乙之间的贸易交易费用下降，导致乙国的资金外流","某地制定新政，加大对中小企业的扶持力度，同时对垄断行业进行调控，限制规模","某粮食生产企业一直不景气，在采用先进栽培技术后，企业生产规模扩大，销售份额开始提升","某地规定，对于优秀留学归国人员可参照其学历或专业水平直接授予相应等级的专业技术职称，不受任何年限等限制"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词：效率较高的组织对效率较低的组织构成破坏或抑制，本\n题选择可以避免“顶尖效应”的一项。\nA 项，发达国家甲与落后国家乙之间交易费用下降，导致了乙国发展困难，属于“顶\n尖效应”，而非避免“顶尖效应”，不符合定义，排除；\nB 项，新政策加大了对中小企业的扶持，对垄断行业调控，保护了中小企业的发展，\n可以避免“顶尖效应”，符合定义，当选；\nC 项，没有出现效率较高的组织，不符合定义，排除；\nD 项，优秀留学归国人员是个人，而非组织，不符合定义，排除。\n故正确答案为B。"},{"q":"正惩罚是指当个体发出某种行为后，引发外部对其行为的某种反应，导致令该个体不愉快的后果，使个体今后发出此行为的可能性降低。负惩罚是指当个体发出某种行为后，撤销令个体愉快的后果，使个体今后发出此行为的可能性降低。根据上述定义，下列属于正惩罚的是（  ）","options":["禁烟标识贴出后，在办公室吸烟的人明显减少","母亲要求小明不写作业不得出去玩","某人因酒驾被处罚后，再没有酒驾","冰棍解暑，所以夏天冰棍很畅销"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：个体发出某种行为后；引发外部对其行为的某种反应；\n导致令该个体不愉快的后果；使个体今后发出此行为的可能性降低。\nA 项，没有出现个体的某种行为，不符合定义，排除；\nB 项，母亲要求小明不写作业不得出去玩，属于个体发出某种行为之前的预防，不符\n合定义，排除；\nC 项，某人酒驾符合“个体发出某种行为”，受到惩罚符合“令个体不愉快的后\n果”，再不酒驾符合“今后发生此行为的可能性降低”，符合定义，当选；\nD 项，没有出现个体行为，不符合定义，排除。\n故正确答案为C。"},{"q":"疑罪是指司法机关对被告人是否犯罪或罪行轻重难以确证的情况。疑罪从无原则是现代刑法“有利被告”思想的体现，是无罪推定原则的具体内容之一，即在既不能证明被告人有罪又不能证明被告人无罪的情况下，推定被告人无罪。根据上述定义，下列采用了疑罪从无原则的是（  ）","options":["赵六因盗窃他人网络密码被起诉，但由于赵六被证明从来不使用网络，法院判其无罪","史某和汤某打架，两人都受了伤，因无法确定谁先动手，法庭建议庭外和解","钱某因涉嫌投毒被起诉，后因证据不足，法院判决钱某无罪","张三起诉李四侵权，但因拿不出任何证据，结果败诉"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：现代刑法；既不能证明被告人有罪又不能证明被告人无\n罪的情况下，推定被告人无罪。\nA 项，赵六不使用网络可以证明其是无罪的，不符合定义，排除；\nB 项，“双方打架受伤，法庭建议庭外和解”为民事行为，不属于刑事案件，不符合\n定义，排除；\nC 项，因没有证据证明钱某投毒，所以法院判其无罪，符合定义，当选；\nD 项，“侵权”为民事行为，不属于刑事案件，不符合定义，排除。\n故正确答案为C。"},{"q":"隐域性是指自然地理现象在受到局部的地形、水文、土壤、气流、洋流、季风等因素的影响下，在地球表面不按或偏离纬向地带性规律分布的特性，它使地带性分布规律变得不鲜明，使自然环境变得更具复杂性与多样性。以下属于隐域性分布的是（  ）","options":["关汉卿《窦娥冤》中描写的“六月飞雪”","余秋雨所描写的丝绸之路上的“月牙泉”","岑参在诗中所描述的“北风卷地白草折”","电影《木乃伊归来》中所出现的大沙漠"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词：自然地理现象；受到局部的多因素影响；在地球表面不\n按或偏离纬向地带性规律分布的特性。\nA 项，“六月飞雪”是气候现象，不是自然地理现象，不符合定义，排除；\nB 项，“月牙泉”是沙漠中的自然地理现象，一般情况下沙漠中无泉水，属于不按地\n带性规律分布，符合定义，当选。\nC 项，“北风卷地白草折”是气候现象，不是自然地理现象，不符合定义，排除；\nD 项，大沙漠是自然地理现象，没有出现“偏离纬向地带性规律分布的特性”，不符\n合定义，排除。\n故正确答案为B。"},{"q":"垂直搜索引擎是针对某一个行业的专业搜索引擎，是对网页资源中的某类专门的信息进行一次整合，定向分字段抽取出需要的数据进行处理后再以某种形式返回给用户。根据上述定义，下列应用与垂直搜索引擎关系最为密切的是（  ）","options":["在某个购物网站上在线购买鞋子","登陆央视网站查询某个城市天气","用百度音乐搜索自己爱听的歌曲","在图书馆网站上查询该馆的藏书"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：某一个行业。\nA 项，购物网站所卖东西范围较广，并不只卖鞋子，不符合“某一个行业”，不符合\n定义，排除；\nB 项，央视网站并不是只针对天气预报这个行业，不符合定义，排除；\nC 项，百度音乐搜索是针对音乐这一行业，符合定义，当选；\nD 项，图书馆网站只针对于本图书馆内部藏书，不涉及图书行业，不符合定义，排\n除。\n故正确答案为C。"},{"q":"概念的内涵是指概念所反映的事物具有的本质属性（或特有属性），它是从质的方面反映概念的，概念的外延是指具有概念所反映的本质属性（或特有属性）的那些事物，它是从量的方面反映概念的。内涵和外延的反变关系是指具有属种关系的概念之间所具有的一种相互联系、相互制约的关系，一个概念的外延越大，它的内涵越少；一个概念外延越小，它的内涵越多。反之，一个概念的内涵越多，它的外延越小；一个概念内涵越少，它的外延越大。根据上述定义，下列哪组概念体现了概念内涵与外延的反变关系（  ）","options":["司法机关，最高审判机关，最高人民法院","水杯，热水杯，大号热水杯","中国，新疆，乌鲁木齐","中国人，文学家，鲁迅"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词：具有属种关系的概念之间。\nA 项，最高审判机关和最高人民法院是同一关系，并非属种关系，不符合定义，排\n除；\nB 项，热水杯是水杯的一种，大号热水杯是热水杯的一种，属种关系，符合定义，当\n选；\nC 项，新疆是中国的组成部分，并非属种关系，不符合定义，排除；\nD 项，文学家和中国人是交叉关系，并非属种关系，不符合定义，排除。\n故正确答案为B。"},{"q":"时间知觉是对客观现象延续性和顺序性的感知，时间知觉的信息，既来自于外部，也来自内部。外部信息包括计时工具，也包括宇宙环境的周期性变化，内部信息是机体内部的一些有节奏的生理过程和心理活动。根据上述定义，下列没有包含时间知觉信息的是（  ）","options":["东边日出西边雨，道是无晴却有晴","三更灯火五更鸡，正是男儿读书时","人有悲欢离合，月有阴晴圆缺","月出惊山鸟，时鸣春涧中"],"a":0,"e":"【答案】A\n【解析】定义判断，选非题。关键词：时间知觉信息；宇宙环境的周期性变化。\nA 项，描写的是东边有太阳而西边在下雨，体现的是不同的天气状况，没有宇宙环境\n周期性变化，不符合定义，当选；\nB 项，“三更”、“五更”指的是时间变化，符合定义，排除；\nC 项，“月有阴晴圆缺”月亮的形状变化体现了宇宙环境周期性变化，符合定义，排\n除；\nD 项，“月出”指的是宇宙环境的周期性变化，符合定义，排除。\n故正确答案为A。\n第九组："},{"q":"土壤是岩石在风化作用下破碎，物理化学性质改变后形成结构疏松的风化壳，风化壳在气候与生物的作用下，经历很长时间形成的地表物质。与土壤自然形成过程无关的外来物质被称为土壤侵入体。根据上述定义，下列属于土壤侵入体的是（  ）","options":["戈壁滩中大量的沙砾","河床上存在的大量鹅卵石","考古发掘中挖出的砖瓦","岩缝中生长的野草"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：与自然形成过程无关。\nA 项，“沙砾”是自然形成的物质，不符合“与自然形成过程无关”，不符合定义，\n排除；\nB 项，“鹅卵石”是自然形成的物质，不符合“与自然形成过程无关”，不符合定\n义，排除；\nC 项，“砖瓦”是人工制造的产物，与“自然形成过程无关”，符合定义，当选；\nD 项，“野草”是自然生长的地表物质，不符合“与自然形成过程无关”，不符合定\n义，排除。\n故正确答案为C。"},{"q":"党政机关公文是党政机关实施领导、履行职能、处理公务的具有特定效力和规范体式的文书。其中命令（令）适用于公布行政法规和规章、宣布施行重大强制性措施、批准授予和晋升衔级、嘉奖有关单位和人员。意见适用于对重要问题提出见解和处理办法。批复适用于答复下级机关请示事项。函适用于不相隶属机关之间商洽工作、询问和答复问题、请求批准和答复审批事项。根据上述定义，下列选项中应添加批复的是（  ）","options":["《国务院办公厅关于进一步加强资本市场中小投资者合法权益保护工作的——》","《国务院办公厅关于黑龙江双鸭山经济开发区升级为国家级经济技术开发区的——》","《国务院关于在我国统一实行法定计量单位的——》","《国务院关于同意设立陕西西咸新区的——》"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：答复下级机关请示事项。\nA 项，《国务院办公厅关于进一步加强资本市场中小投资者合法权益保护工作的—\n—》是宣布实施重大强制措施，属于命令，排除；\nB 项，《国务院办公厅关于黑龙江双鸭山经济开发区升级为国家级经济技术开发区的\n——》是对于重要问题提出的见解，属于意见，不符合定义，排除；\nC 项，《国务院关于在我国―实行法定计量单位的——》宣布实施重大强制措施，属\n于命令，不符合定义，排除；\nD 项，《国务院关于同意设立陕西西咸新区的——》是答复下级机关“设立陕西西咸\n新区的请示，符合定义，当选。\n故正确答案为D。"},{"q":"合成字是合体字中一个比较特殊的门类，它原本是汉语中一个常用的词语、词组，但由于这些词语、词组在方言中使用的频率很高，就把这些词语在讲究字形美观的前提下原封不动地组合成了一个独有的汉字。根据上述定义，下列汉字根据其意思不属于合成字的是（  ）","options":["氼，读作nì，古同“溺”，沉没，沉溺","嘦，读作jiào，方言，“只要”的意思","覅，读作fiào，表示否定，相当于“不要”","尠，读作xiǎn，意思是稀有的、罕见的"],"a":0,"e":"【答案】A\n【解析】定义判断，选非题。关键词：原本是汉语中一个常用的词语、词组。\nA 项，“氼”中“水人”不符合“原本是汉语中一个常用的词语、词组”，不符合定\n义，当选；\nB 项，“嘦”原本是“只要”，符合“原本是汉语中一个常用的词语、词组”，排\n除；\nC 项，“覅”原本是“勿要”，符合“原本是汉语中一个常用的词语、词组”，排\n除；\nD 项，“尠”原本是“甚少”，符合“原本是汉语中一个常用的词语、词组”，排\n除。\n故正确答案为A。"},{"q":"真理是指客观事物及其规律在人的意识中的正确反映。真理可以分为理性真理和事实真理两种。理性真理指的是具有普遍性和必然性的真理，其反面是不可能的；事实真理指的是具有偶然性的真理，其反面是可能的。根据上述定义，下列属于理性真理的是（  ）","options":["月晕而风，础润而雨","如果a 大于b 且b 大于c，那么a 大于c","恩惠要一点点地施舍才具有最大效益","一个人如果违反了法律，就一定会受到法律的制裁"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词：理性真理；其反面是不可能的。\nA 项，“月晕而风，础润而雨”意为月晕出现了，将要刮风；础石湿润，就要下雨，\n但是有时候月晕出现了也没风，础石湿润，也并非下雨，其反面是可能的，不符合定义，\n排除；\nB 项，a＞b 且b＞c，则必然得出a 大于c，其反面是绝对不可能的，符合定义，当\n选；\nC 项，反面：有时恩惠一起施舍也会具有最大效益，故其反面是可能的，不符合定\n义，排除；\nD 项，反面：部分违法分子现仍没有受到法律的制裁，故其反面也是可能的，不符合\n定义，排除。\n故正确答案为B。"},{"q":"直观教学是指利用教具作为感官传递物，向学生展示相关内容，以达到提高学习效率或效果的一种教学方式。直观教学包括实物直观、模象直观和言语直观。实物直观通过直接感知实际事物而进行；模象直观通过对实物的模拟性形象来直接感知；言语直观是在形象化的语言作用下，通过学生对语言的物质形式（语音、字形）的感知及对语义的理解而进行的一种直观形式。根据上述定义，下列不属于上述三种直观教学的是（  ）","options":["请学生在课后阅读整篇小说内容并撰写读后感","暑期带着学生去工厂和农村进行实地参观访问","请学生分角色朗读戏剧作品，或通过上台表演来体会人物性格","在艺术鉴赏课上，使用幻灯片给学生展示西方油画的经典之作"],"a":0,"e":"【答案】A\n【解析】定义判断，选非题。关键词：实物直观通过直接感知实际事物而进行；模象\n直观通过对实物的模拟性形象来直接感知；言语直观通过形象化的语言，学生对语言的物\n质形式（语音、字形）感知和语义的理解。\nA 项，阅读小说之后谈自己的感想，均未涉及以上三个定义关键词，不符合定义，当\n选；\nB 项，“去工厂和农村进行实地参观访问”是通过直接感知实际事物而进行的，符合\n实物直观定义，排除；\nC 项，“分角色朗读”符合“学生对语言的物质形式（语音、字形）感知和语义的理\n解”，“上台表演来体会人物性格”符合“对实物的模拟性形象来直接感知”，符合定\n义，排除；\nD 项，通过幻灯片展示油画，符合模象直观定义，排除。\n故正确答案为A。"},{"q":"负启动效应是指人们由于之前受到某一刺激的影响而使之后对同一类型刺激的知觉加工过程变得困难的心理现象。其中知觉加工过程是指外界事物作用于人的感官后，头脑中产生的对事物的认识和理解的过程。根据上述定义，下列属于负启动效应的是（  ）","options":["先给被试人员呈现一组汉字，里面有“海”这个字，随后让他们写出部首是“氵”的字时，这些人写出“海”的几率并未增大","先在黑板上给一组被试人员呈现词语“桌子”，后播放语音“椅子”，一段时间后，请被试人员分别说出看到和听到的词语，发现很多人答错了","请被试人员回答屏幕中显示的词语的颜色，先向其呈现词语“绿色”（字体为红色），再呈现词语“蓝色”（字体为绿色），发现被试人员辨识颜色变得困难","给被试人员呈现一张未完成的画，随着画越来越完整，被试人员逐渐辨认出画的内容，过一段时间后再给他们呈现这个未完成的画，他们会更早辨认出画的内容"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：之前受到某一刺激的影响；之后对同一类型刺激的知觉\n加工过程变得困难。\nA 项，“呈现”一组汉字与“写出”字，不属于“同一类型刺激”，不符合定义，排\n除；\nB 项，“呈现词语‘桌子’”是视觉刺激，“后播放语音‘椅子’”是听觉刺激，不\n属于“同一类型刺激”，不符合定义，排除；\nC 项，“呈现词语‘绿色’（字体为红色），再呈现词语‘蓝色’（字体为绿色）”\n都属于视觉刺激，符合“同一类型刺激”，“辨识颜色变得困难”符合“之后对同一类型\n刺激的知觉加工过程变得困难”，符合定义，当选；\nD 项，“他们会更早辨认出画的内容”是使加工过程变得容易，不符合定义，排除。\n故正确答案为C。"},{"q":"数字鸿沟指的是由于信息化和互联网的影响，人们的信息获取、信息处理和信息传播都是通过数字化技术来实现的，由此造成了不同个体、群体或者国家在思想意识、经济、文化和政治等方面的差距越来越大。根据上述定义，下列不涉及数字鸿沟的是（  ）","options":["放假回家的小宋和同学用手机聊天，满口网络新词，一旁的奶奶一句也听不懂","小赵整天痴迷于网络游戏，父母多次苦口婆心地劝说，均没有效果，为此小赵和父母发生了多次争执","东部某镇种植的水果尚未成熟就已经通过网络平台被订购一空，而西部某乡质优价廉的水果由于无人知晓只能烂在树上","一些西方国家利用其技术积累，在大数据处理方面取得了绝对的优势，他们进一步实行技术封锁，使得某些国家在大数据分享方面一筹莫展"],"a":1,"e":"【答案】B\n【解析】定义判断，选非题。关键词：造成在多方面的差距越来越大。\nA 项，小宋通过手机学习到的网络新词，奶奶一句也听不懂，造成奶奶和小宋语言之\n间差距越来越大，符合定义，排除；\nB 项，“争执”不属于小赵与父母的差距越来越大，不符合定义，当选；\nC 项，东西部水果情况不同，是由于网络因素造成两地区的经济差距，符合定义，排\n除；\nD 项，一些西方国家大数据处理获得优势，其他国家在此技术方面一筹莫展，这是由\n于技术导致国家技术之间的差距，符合定义，排除；\n故正确答案为B。"},{"q":"叶龄指数指的是禾谷类作物主茎已出叶数与最终总叶数的比值，是衡量作物生长进程的重要指标之一。根据上述定义，下列关于叶龄指数的说法一定正确的是（  ）","options":["稻谷的叶龄指数与其生长进程成正比","荞麦的叶龄指数越大则其产量也越高","小麦的叶龄指数最大值为100%","玉米的平均叶龄指数大于高粱"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：主茎已出叶数与最终总叶数的比值。\nA 项，是否与其生长进程成正比，题干未提及，排除；\nB 项，荞麦的叶龄指数与产量之间的关系，题干未提及，排除；\nC 项，当小麦长出所有叶子后其叶龄指数最大，为100%，当选；\nD 项，题干未给出玉米与高粱叶龄指数的关系，排除。\n故正确答案为C。"},{"q":"图灵测试是测试者在与被测试者（一个人和一台机器）隔开的情况下，通过一些装置（如键盘）向被测试者随意提问。问过一些问题后，如果被测试者有超过30%的答复不能使测试者确认出哪个是人、哪个是机器，那么这台机器就通过了测试，并被认为具有人类智能。据上述定义，以下哪项中的测试一定通过了图灵测试（  ）","options":["对机器甲40%的答复所有人都确认其为机器","对机器乙60%的答复测试者能确认其为机器或人","对机器丙30%的答复有90%的某小区居民确认其为机器","对机器丁30%的答复只有10%的某校大学生不能确认其为机器"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词：有超过30%的答复不能使测试者确认出哪个是人、哪个\n是机器，那么这台机器就通过了测试，并被认为具有人类智能。”测试结果可能存在三中\n情况：①确认其为机器；②确定其为人；③不能确定其为机器或人。\nA 项，40%的答复可以确定为机器，即①为40%；②和③共为60%，其中③的占比不\n确定，排除；\nB 项，60%的答复可以确定其为机器或人，即①和②共为60%，③必然占40%，符合\n关键词“有超过30%的答复不能使测试者确认出哪个是人、哪个是机器。”因此一定可以\n通过图灵测试，当选；\nC 项，机器丙有30%的答复90%的某小区居民能够确认其为机器，即①为27%；②和\n③共为73%，其中③的占比不确定，排除；\nD 项，机器丁有30%的答复只有10%的在校大学生不能确认其为机器，即②和③为\n3%，其中③的占比不确定，排除。\n故正确答案为B。"},{"q":"产品责任是指产品有缺陷，存在可能危及人身、财产安全的危险，造成产品的消费者、使用者或者其他第三者人身或其他直接财产损失后，缺陷产品的生产者、销售者应当承担的特殊的侵权法律责任。根据上述定义，下列受害人可因产品责任要求侵权损害赔偿的是（  ）","options":["甲购买了一辆新车，一次与朋友王某驾车外出时，汽车因电路质量问题发生自燃，致使王某被烧伤","乙购买了一件大衣，大衣上没有洗涤标志和成分说明，营业员也未告知应如何洗涤。大衣水洗后严重缩水","丙购买了一部新手机，一次因质量问题自动关机，无法开启，致使丙漏接了客户的电话，损失了一笔大额订单","丁的电视机使用了20 年，图像不清晰时拍几下就好了，一次丁在拍打电视机时，电视机发生爆炸，将丁炸伤，后经检验发现是显像管老化造成的"],"a":0,"e":"【答案】A\n【解析】定义判断。关键词：产品有缺陷；可能危及人身、财产安全的危险；造成直\n接财产损失。\nA 项，“汽车因电路质量问题发生自燃”符合“产品有缺陷”，“致使王某被烧伤”\n符合“危及人身安全”，符合定义，当选；\nB 项，大衣洗后严重缩水，并不代表产品有缺陷，不符合定义，排除；\nC 项，手机质量问题属于产品缺陷，但是漏接电话，损失大额订单是间接财产损失，\n不符合“直接财产损失”，排除；\nD 项，电视机已超出使用年限，不属于产品缺陷，不符合定义，排除。\n故正确答案为A。\n第十组："},{"q":"水利工程是用于控制和调配自然界的地表水和地下水，达到除害兴利目的而修建的工程。根据上述定义，下列不涉及水利工程的是（  ）","options":["城市污水处理厂利用微生物分解吸收水中的有机物","水电站利用水力发电技术，将水能转化为电能","农业上建设合理开发利用地下水的灌溉设施，以满足作物生长需要","在水利枢纽中设河岸泄洪道以防止因洪水超过水库容量而漫顶造成溃坝"],"a":0,"e":"【答案】A\n【解析】定义判断，选非题。关键词：控制和调配；除害兴利。\nA 项，对污水的净化处理，不是对于水的控制和调配，这是环保工程而非水利工程，\n不符合定义，当选；\nB 项，水利发电站是人为地将水的动能、势能转化为电能的过程，是对水的控制，符\n合定义，排除；\nC 项，建设地下水灌溉设施是人为地将地下水调配到地表以达到“兴利”的目的，符\n合定义，排除；\nD 项，设河岸泄洪道是人工地控制地表水，其目的是“除害”，符合定义，排除。\n故正确答案为A。"},{"q":"语句的示意功能是指通过语句表达某种通知、告诫、命令或请求，目的在于要求别人按照语句表达的思想，做出或不做出某种行为。根据上述定义，下列没有反映语句的示意功能的是（  ）","options":["全体学生请到操场集合","请您务必不要践踏草坪","禁止生产假冒伪劣产品","销售部现在应该在开会"],"a":3,"e":"【答案】D\n【解析】定义判断，选非题。关键词：做出或不做出某种行为。\nA 项，请到操场集合，要求学生做出某种行为反应，符合定义，排除；\nB 项，务必不要践踏草坪，告诫他人不要做出某种行为，符合定义，排除；\nC 项，禁止生产假冒伪劣产品，要求他人不能做出某种行为，符合定义，排除；\nD 项，“现在应该在开会”是一种对状态的描述，未要求任何人做或不做某种行为，\n不符合定义，当选。\n故正确答案为D。"},{"q":"货币性资产是指持有的现金及将以固定或可确定金额的货币收取的资产，包括现金、应收账款和应收票据以及准备持有至到期的债券等。非货币性资产则是指货币性资产以外的资产，这些资产在将来为企业带来的经济利益（即货币金额）是不固定的或不可确定的。根据上述定义，下列属于货币性资产的是（  ）","options":["某服装厂的库存货物","某汽车公司用于出租的车辆","某通讯企业旗下手机品牌的商标权","某化工集团按照国家规定获得的技术补贴"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：持有的现金；固定或可确定金额的资产。\nA 项，“库存货物”未来转化为货币时会受到市场经济的影响，无法确定其金额，排\n除；\nB 项，“出租的车辆”会受到使用时间长短的影响，无法确定其金额，排除；\nC 项，商标权是无形资产，交易时金额不确定，排除；\nD 项，“国家规定获得的技术补贴”是可确定金额的货币，符合定义，当选。\n故正确答案为D。"},{"q":"火力投射密度是指军事行动中军事部门在单位时间内的最大弹药发射量。它是现代军事学中衡量作战部队战斗力的重要指标之一。根据上述定义，以下属于通过增大火力投射密度来加强部队战斗力的是（  ）","options":["某步兵师在普通士兵中选拔特等射手编入狙击班，进而能够更有效地杀伤敌人的有生力量","某国将其部队列装的半自动步枪全部更换为全自动步枪，增加了子弹的发射频率","某炮兵部队将原计划两小时的炮火掩护时间延长为三小时，更有效地杀伤了掩体中的敌人","某军事科研单位研制出更先进的炮火定位系统，能够将火力打击的误差由半径200米缩小到50 米"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词：单位时间内的最大弹药发射量。\nA 项，“特等射手”体现的是射手的准确度，并非弹药发射量的变化，不符合定义，\n排除；\nB 项，“增加了子弹的发射频率”则单位时间内的发射量会增加，符合定义，当选；\nC 项，“两小时的炮火掩护时间延长为三小时”是时间的延长，与单位时间内的弹药\n发射量无关，不符合定义，排除；\nD 项，“误差由半径200 米缩小到50 米”是准确率提升，与单位时间内的弹药发射\n量无关，不符合定义，排除。\n故正确答案为B。"},{"q":"埋伏营销是指企业利用媒体和公众对重大事件的关注，通过举办与重大事件相关的活动，使自己与重大事件产生关联，从而引起消费者的联想和媒体的注意。这类营销通常是隐蔽的、突发的，不以赞助者的身份出现，却对自己的品牌悄无声息地进行了宣传。根据上述定义，下列不属于埋伏营销的是（  ）","options":["某矿泉水公司邀请著名运动员为其代言，并将广告投放在电视媒体的黄金时段和一些大型酒店的视频媒体中","地震发生后，某户外用品公司向灾区捐赠价值100 万元的帐篷，并举行了捐赠仪式","某市举办中小学生知识竞赛，一出版集团在现场向参与者免费发放其出版的图书","世界一级方程式锦标赛比赛期间，观众席中时不时会有人挥舞着印有某轮胎企业商标的彩色旗帜"],"a":0,"e":"【答案】A\n【解析】定义判断，选非题。关键词：对自己的品牌悄无声息地进行了宣传。\nA 项，请运动员代言不符合与重大事件结合的宣传行为，不符合定义，当选；\nB 项，捐赠帐篷是与重大事件结合的宣传行为，对自己的品牌悄无声息地进行了宣\n传，符合定义，排除；\nC 项，某市举办中小学生知识竞赛属于重大事件，免费发放图书是与重大事件结合的\n宣传行为，对自己的品牌悄无声息地进行了宣传，符合定义，排除；\nD 项，世界一级方程式锦标赛比赛属于重大事件，观众挥舞带有企业商标的旗帜是与\n重大事件结合的宣传行为，对自己的品牌悄无声息地进行了宣传，符合定义，排除。\n故正确答案为A。"},{"q":"著名科学家、科学史学家普赖斯：提出如果K 代表参与某一专业领域的人数，那么这个数字的平方根大致等于为这个领域做出一半贡献的排名在前的那部分人的人数。根据上述定义，下列符合普赖斯观点的是（  ）","options":["某国出版协会统计了本国的期刊，发现与经济有关的期刊大约有150 种，所有与经济有关的科研论文中，有一半发表在其中的13 种期刊上","某县有20 万农业人口，统计发现，过去一年全县的粮食总产量中，大约一半粮食产量是由450 位左右的种粮大户贡献的","某组织统计过去一年全世界公开举办的音乐会的演奏曲目，发现所有演奏曲目是由大约250 位作曲家完成的，其中大约一半的曲目来自于16 位作曲家","某销售奢侈品的网店过去一年的访问量为10 万人次，但去年全部的销售额中，大约一半的销售额是由其中大约300 位固定客户提供的"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：专业领域；人数。\nA 项，期刊数量不属于“人数”，不符合定义，排除；\nB 项，“农业人口”包含范围广泛，不属于某一专业领域，不符合定义，排除；\nC 项，“作曲家”属于专业领域人群，符合定义，当选；\nD 项，“访问量”是指访问网站的人数，不属于某一专业领域，不符合定义，排除。\n故正确答案为C。"},{"q":"自由落体运动是指物体只在重力作用下从静止开始下落的运动。这种运动只有在真空条件下才能发生，在有空气时，如果空气的阻力作用比较小，可以忽略不计，则物体的下落可以近似看作自由落体运动。根据上述定义，下列可以近似看作自由落体运动的是（  ）","options":["熟透了的苹果从树上被风吹落","飞行中的飞机被导弹击中坠落","抛过来的皮球没被接住，掉在地上","冬日中午，冰棱融化后从屋檐掉下"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：只在重力作用下；从静止开始。\nA 项，苹果被风吹落，受到了风的作用力，并非只在重力作用下，不符合定义，排\n除；\nB 项，飞机被导弹击中，受到外力作用，并非只在重力作用下，不符合定义，排除；\nC 项，“抛过来的皮球”是运动中的物体，并非从静止开始，不符合定义，排除；\nD 项，冰棱融化后从屋檐掉下，只受到重力作用，符合定义，当选。\n故正确答案为D。"},{"q":"参照依赖是指个体基于某个参照点对得失价值进行判断，参照点之上，个体感受是收益，反之感受为损失。损失和收益的感知取决于参照点的选择。根据上述定义，下列不属于参照依赖的是（  ）","options":["张女士因为生育和哺乳不得不暂停工作半年，失去了很多客户，心里很苦恼，但看到自己健康活泼的儿子，又变得高兴起来","小张原本对收入很满意，他听说跟自己同时进公司、现在同是项目经理的小李收入比自己高10%后，对收入没有那么满意了","研究者设计了一项实验：告知被试他们邻居的月水电支出比他们低，结果发现被试下个月的家庭能耗显著降低了","姐姐期中考试得了99 分，期末考试得了95 分，妈妈批评了她；弟弟期中考试得了75 分，期末考试得了85 分，妈妈奖励了他"],"a":2,"e":"【答案】C\n【解析】定义判断，选非题。关键词：参照点之上，个体感受是收益，反之感受为损\n失，即重点强调参照点的不同感受不同。\nA 项，张女士以工作为参照点，感受为苦恼；以儿子为参照点，感受为收益。参照点\n的不同感受不同。符合定义，排除；\nB 项，小张以自己的收入为参照点，感受为满意；以小李的收入为参照点，感受为损\n失。参照点的不同感受不同。符合定义，排除；\nC 项，参照点为“邻居的月水电支出”，但没有提到个体感受的不同，不符合定义，\n当选；\nD 项，妈妈以“姐姐的99 分”为参照点，妈妈感受是不满意。以“弟弟的75 分”为\n参照点时，妈妈感受是满意，符合定义，排除。\n故正确答案为C。"},{"q":"隐匿定位策略是指当一类产品不被消费者看好时，公司能够在不打破产品种类界限的情况下，合法地利用某些策略消除消费者对这类产品的偏见，使消费者转而接受它们，实现更好的销量。根据上述定义，下列没有运用隐匿定位策略的是（  ）","options":["某公司生产的游戏机销量不佳，公司决定将产品升级并提出创建家庭娱乐平台的概念，该游戏机因此变得畅销","某公司开发了家庭机器人，但消费者并不感兴趣。该公司调整思路，推出一种可爱的、不做家务的机器狗，一上市就大受欢迎","某公司推出一种小型电脑，由于定价高而鲜有问津。该公司在产品宣传中强调其可作为移动数字化设备等，与低端产品区分开，从而打开销路","某公司推出新款SUV 车型，但少有人问津，于是公司又推出一款价格昂贵的跑车，消费者觉得SUV 性价比更高，纷纷购买"],"a":1,"e":"【答案】B\n【解析】定义判断，选非题。关键词：不被消费者看好；消费者转而接受它们。\nA 项，“游戏机销量不佳”符合不被看好，“该游戏机因此变得畅销”符合消费者转\n而接受它们，符合定义，排除；\nB 项，“机器人”消费者并不感兴趣，符合不被看好，但上市受欢迎的是“机器狗”\n而非“机器人”，不符合消费者转而接受它们，不符合定义，当选；\nC 项，“定价高而鲜有问津”符合不被看好，“与低端产品区分开，从而打开销路”\n符合消费者转而接受它们，符合定义，排除；\nD 项，“推出新款SUV 车型，但少有人问津”符合不被看好，“消费者觉得SUV 性\n价比更高，纷纷购买”符合消费者转而接受它们，符合定义，排除。\n故正确答案为B。"},{"q":"传递关系指的是对任意的元素A、B、C 来说，若元素A 与元素B 有某关系并且元素B 与元素C 有该关系，则元素A 与元素C 也有该关系。反传递关系指的是若元素A 与元素B 有某种关系并且元素B 与元素C 有该关系，但元素A 与元素C 没有该关系。根据上述定义，下列关系属于传递关系的是（  ）","options":["自然数中的大于关系","生活中的同学关系","家庭中的父子关系","食物链的天敌关系"],"a":0,"e":"【答案】A\n【解析】定义判断。关键词A 与B 有某关系，B 与C 有该关系，A 与C 也有该关系。\nA 项，自然数中的大于关系：A＞B、B＞C，必然会得到A＞C，符合定义，当选；\nB 项，A 是B 的同学，B 是C 的同学，但A 与C 未必是同学关系,不符合定义，排除；\nC 项，A 是B 的父亲，B 是C 的父亲，A 与C 不是父子关系，不符合定义，排除；\nD 项，A 是B 的天敌，B 是C 的天敌，A 与C 未必是天敌关系，不符合定义，排除。\n故正确答案为A。\n第十一组："},{"q":"伦理信用是指人们交往中由一定的预先约定、契约、承诺、誓言等引发的一种伦理关系，其蕴涵的合理秩序则凝结为遵守诺言、履行约定的道德准则，人们基于对信用伦理关系合理秩序的理解和规则的践行便形成了相应的道德品行。根据上述定义，下列涉及伦理信用的是（  ）","options":["陈某看到一群人在围殴邻居的孩子，他一边报警，一边跑上前去大声喝止","赵某答应了丈夫的临终请求，在丈夫去世后，对丈夫前妻留下的两个孩子视如己出，将他们抚养成人","王某父亲曾借给张某10 万元，王父去世后，王某要求张某还钱","李某家乡发生洪涝灾害，不少农民颗粒无收，父亲要求他发动其公司员工和微信圈朋友捐钱捐物"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词：预先；遵守诺言。\nA 项，碰巧遇到围殴邻居孩子，此事属于临时发生，不是预先约定，不符合定义，排\n除；\nB 项，赵某预先答应了丈夫的请求，有预先约定。将他们抚养成人，符合遵守诺言，\n符合定义，当选；\nC 项，是王某父亲与张某的约定，此伦理信用与王某无关，不符合定义；同时王某要\n求张某还钱，不确定张某是否履行约定，不符合定义，排除；\nD 项，洪涝灾害是突发情况，没有预先约定，不符合定义，排除。\n故正确答案为B。"},{"q":"定向调控指政府针对不同调控领域，制定清晰明确的调控政策，使调控更具针对性。相机调控指政府根据市场情况和各项调节措施的特点，灵活决定当前应采取哪一种或几种政策措施，重在“预调、微调”。定向调控是“做什么”，相机调控是“怎么做”。根据上述定义，下列属于相机调控的是（  ）","options":["甲国政府于年初提出了经济增长率和就业水平的“下限”、物价涨幅的“上限”等工作目标","乙国政府提出“双引擎”策略：一是对小微企业、“三农”等市场主体“减负”；二是支持公共产品、公共服务建设，拉动投资。由各地制定具体措施","丙国政府根据一二三四线城市房地产市场的不同特点，制定了有针对性的契税、房贷政策","丁国政府实行产品和服务的生产及销售完全由自由市场的自由价格机制所引导、产权明晰的经济政策"],"a":2,"e":"【答案】C\n【解析】题干中的关键信息是相机调控：“政府根据市场情况和各项调节措施的特\n点”、“灵活决定当前应采取措施”、“预调、微调”、“怎么做”。\nA 项，提出了工作目标，是“做什么”，属于定向调控，排除；\nB 项，乙国仅提出策略，但是具体措施由各地制定，是“做什么”，属于定向调控，\n排除；\nC 项，丙国“制定了有针对性的契税、房贷政策”，是“怎么做”，属于相机调控，\n符合定义，当选；\nD 项，完全由自由市场引导，政府无调控行为，不符合定义，排除。\n故正确答案为C。"},{"q":"法律的当然解释是指法律虽然没有明确规定某一事项，但依规范目的，该事项应当被解释为适用这一法律规定。其解释方法有举重以明轻和举轻以明重。前者是指对于某一应当被允许的行为，举一个情节比其严重而被允许的规定，以说明其应当被允许。后者是指对于某一应当被禁止的行为，举一个情节比其轻微而被禁止的规定，以说明其应当被禁止。根据上述定义，下列判断正确的是（  ）","options":["法律规定禁止在公园采摘树叶，依据举轻以明重，在公园攀折树枝的行为应当被禁止","唐律规定主人打死夜无故入人家者无罪，依据举轻以明重，主人打伤夜无故入人家者无罪","法律规定禁止携带小型动物，依据举重以明轻，携带大型动物的行为应当被禁止","法律规定16 周岁以下的未成年人不承担刑事责任，依据举重以明轻，15 周岁的未成年人不承担刑事责任"],"a":0,"e":"【答案】A\n【解析】定义判断。关键词：举重以明轻：某一应当被允许的行为，举一个情节比其\n严重而被允许的规定；“举轻以明重：某一应当被禁止的行为，举一个情节比其轻微而被\n禁止的规定”。\nA 项，“攀折树枝”属于应被禁止的行为，“采摘树叶”属于比“攀折树枝”更轻的\n行为，满足“举一个情节比其轻微而被禁止的规定”，符合举轻以明重，当选；\nB 项，“打伤人”属于被允许的行为，不符合“举轻以明重”，排除；\nC 项，“携带大型动物”是被禁止的行为，不符合“举重以明轻”排除；\nD 项，“15 周岁的未成年人”包含在“16 周岁以下的未成年人”中，不存在情节的\n轻重比较，排除；\n故正确答案为A。"},{"q":"系统脱敏法是一种心理治疗法，当患者面前出现引起焦虑和恐惧的刺激物时，引导患者放松，使患者逐渐消除焦虑与恐惧，不再对该刺激物产生病理性反应。它包括快速脱敏法和接触脱敏法等。前者是治疗者陪伴病人置身于令病人感到恐惧的情景，直到病人不再紧张为止。后者是通过示范，让病人逐渐与所惧怕的对象接触，最终达到克服恐惧的目的。根据上述定义，如果要治疗一名特别害怕蛇的孩子，下列治疗方法中属于接触脱敏法的是（  ）","options":["让孩子旁观别人触摸、拿起和放下蛇的过程后，再慢慢让孩子逐渐接近和触摸蛇","带孩子去室内蛇类养殖场，看各种不同种类的蛇，看多了自然就不再害怕了","给孩子讲有关蛇的有趣的童话故事，引发孩子开心的情绪，逐渐减少对蛇的恐惧","录下孩子看见蛇后恐惧害怕的表情和动作，然后一遍又一遍地把这些视频放给孩子看"],"a":0,"e":"【答案】A\n【解析】定义判断。关键词：通过示范；病人逐渐与对象接触。\nA 项，“旁观别人触摸”属于示范，“孩子逐渐触摸蛇”符合“与所惧怕对象接\n触”，符合定义，当选；\nB 项，带孩子去看蛇，是治疗者陪伴病人，属于快速脱敏法，不符合定义，排除；\nC 项，听到的是与蛇有关的故事，未与蛇接触，不符合定义，排除；\nD 项，没有示范，也没有与所惧怕的对象的接触，不符合定义，排除。\n故正确答案为A。"},{"q":"独立证明法和归谬法是间接论证的两种方法，其中独立证明法是通过证明与被反驳命题相矛盾的命题为真，从而确定被反驳命题为假的方法。归谬法就是由所要反驳的命题为真，引出荒谬的结论，从而证明所要反驳的命题为假。根据上述定义，下列论证中使用了独立证明法的是（  ）","options":["甲：人类是由猿猴进化而来的。乙：不可能！有哪一个人见过，哪一只猴子变成了人？","甲：天不生仲尼，万古如长夜。乙：难道仲尼以前的人都生活在黑暗之中？","甲：人性本恶。乙：如果真的人性本恶，那么道德规范又从何而来呢？","甲：温饱是谈道德的先决条件。乙：温饱绝不是谈道德的先决条件。古往今来，没有解决衣食之困的社会也在谈道德。"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：相矛盾的命题，且要证明“相矛盾的命题”为真。\nA 项，没有出现“相矛盾的命题”，不符合定义，排除；\nB 项，“如长夜”和“生活在黑暗之中”属于偷换概念，没有出现“相矛盾的命\n题”，不符合定义，排除；\nC 项，“如果真的人性本恶，道德规范又从何而来呢？”证明了人性本恶的荒谬，属\n于归谬，不符合定义，排除；\nD 项，乙和甲是“相矛盾的命题”，通过证明乙命题为真，所以甲命题为假，符合定\n义，当选。\n故正确答案为D。"},{"q":"投射测验是指采用某种方法绕过受测者的心理防御，在他们不防备的情况下探测其真实想法。在实际测验中，测试者往往会给受测者一些模糊刺激，观察他们对这些模糊刺激做出的反应，进而得出测试结论。根据上述定义，下列属于投射测验的是（  ）","options":["为了选拔合唱队员，音乐课上老师让每一位同学唱一首歌","饭店老板临时外出，让顾客自行将钱放在柜台的盒子里","老张想考察几个年轻人，下班离开前故意将钱包落在办公桌上","在考生面试进场前，考官故意将一些散乱的书堆在考场入口处"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：绕过受测者的心理防御；给受测者一些模糊刺激。\nA 项，音乐课上让学生唱歌，是课堂教学正常的环节，未体现绕过受测者的心理防\n御，且表述的内容很准确，未体现给受测者一些模糊刺激，不符合定义，排除；\nB 项，老板明确告知顾客该怎么做，未体现绕过受测者的心理防御和给受测者一些模\n糊刺激，不符合定义，排除；\nC 项，落在办公桌上的钱包相对显眼，未体现给受测者一些模糊刺激，不符合定义，\n排除；\nD 项，参加面试的考生的心理防御主要针对面试本身，考官故意将一些散乱的书堆在\n考场入口以观察考生的反应，体现了绕过受测者的心理防御，同时考生注意力主要集中在\n面试，书堆对于考生而言属于模糊刺激，符合定义，当选。\n故正确答案为D。"},{"q":"纵向整合是指整个产业链上下游之间进行的整合，其主要目的是控制某种资源，保障供应，如收购上游原料供应商或拥有某种渠道、扩大销售等。横向整合是生产和销售相同或相似产品、经营相似业务、提供相同劳务的企业间的合并，其主要目的是把一些规模较小的企业联合起来，组成企业集团，实现规模效益。根据上述定义，下列属于横向整合的是（  ）","options":["老张为保证其酒店食材供应质量，建设了一个蔬菜和渔场养殖基地","因经济不景气、楼市疲软，某房地产商开始进军电子商务领域","某公司为拓展业务，与某高校联合，走产学研结合的路子","某著名奶制品生产商收购了一家乳产品公司85%的股份"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：生产和销售相同或相似产品；提供相同劳务的企业间的\n合并。\nA 项，酒店和蔬菜，渔场养殖基地属于产业链的上下游，属于纵向整合，不符合横向\n整合的定义，排除；\nB 项，因经济不景气、楼市疲软，某房地产商开始进军电子商务领域，房地产和电子\n商务并非产业链上下游，也不是相似业务，不符合横向整合定义和纵向整合定义，排除；\nC 项，某高校不属于企业，且高校跟企业之间不属于企业间的合并，不符合定义，排\n除；\nD 项，奶制品和乳制品属于相似产品，且两者之间的收购行为，属于企业间的合并，\n符合定义，当选。\n故正确答案为D。"},{"q":"用典是指引用古籍中的故事或词句的一种修辞手法，该修辞可以丰富而含蓄地表达有关的内容和思想，也称“用事”。用典可分为明典、暗典、翻典三种。明典，令人一望即知其所用之典故；暗典是指字面上看不出用典之痕迹，须详加玩味，方能体会；翻典，即反用典故原意，使文章产生意外之效果。根据上述定义，下列选项不属于翻典手法的是（  ）","options":["周公吐哺，天下归心","随意春芳歇，王孙自可留","东风不与周郎便，铜雀春深锁二乔","可堪回首，佛狸祠下，一片神鸦社鼓"],"a":0,"e":"【答案】A\n【解析】定义判断，选非题。关键词：反用典故原意，产生意外之效果。\nA 项，诗句出自曹操的《短歌行》，典故是周公吐哺，周公礼贤下士，求才心切，进\n食时多次吐出实物停下来不吃，急于迎宾，后以周公吐哺表现在位者礼贤下士，在诗句中\n是使用明典，不符合翻典定义，当选；\nB 项，出自王维的《山居秋暝》，该诗原出自淮南小山的《招隐士》的王孙兮归来，\n山中兮不可以久留，其中的王孙原指贵族子弟，后来泛指隐居的人，属于反用典故，符合\n翻典定义，排除；\nC 项，出自杜牧的《赤壁》，原意为当年东风不帮周瑜的话，东吴二乔就会被深锁在\n铜雀台中，这里的用典是草船借箭与东吴二乔，意在借古讽今，符合翻典定义，排除；\nD 项，佛（bì）狸祠：北魏太武帝拓跋焘小名佛狸，他曾反击刘宋，两个月的时间\n里，兵锋南下，五路远征军分道并进，从黄河北岸一路穿插到长江北岸。在长江北岸瓜步\n山建立行宫，即后来的佛狸祠。神鸦：指在庙里吃祭品的乌鸦。社鼓：祭祀时的鼓声。译\n为：怎么能回首啊，当年拓跋焘的行宫外竟有百姓在那里祭祀，乌鸦啄食祭品，人们过着\n社日，只把他当作一位神祇来供奉，而不知道这里曾是一个皇帝的行宫。作者在这里是运\n用的时间对比，以往日辉煌来衬托今日的萧瑟。当年威严的皇家禁地,到了南宋,老百姓只\n把佛狸祠当作一位神祇来奉祀供奉，而不知道它过去曾是一个皇帝的行宫，其用典意在借\n古讽今，符合翻典的定义，排除。\n故正确答案为A。"},{"q":"职业基因是指每个人的职业方向都与自己的某种气质相匹配，这种气质是在人际交往中潜移默化而形成的一种带有强烈个人色彩的心理修养。根据上述定义，下列现象中符合职业基因理论的是（  ）","options":["小明的父母都是教师，最终小明也选择了教师职业","小红从小爱看动画片，长大后成为一名动漫设计师","性情开朗、活泼好动的小丁应聘为某商城销售人员","快言快语的小李毕业当了两年医生后变得慢条斯理"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：职业方向和气质相匹配；带有强烈个人色彩的心理修\n养。\nA 项，小明选择教师职业是由于父母都是教师，而小明的气质是否与教师匹配不明\n确，未体现职业方向和气质相匹配，不符合定义，排除；\nB 项，小红爱看动画片是兴趣爱好，而并非气质，未体现职业方向和气质相匹配，不\n符合定义，排除；\nC 项，小丁性情开朗、活泼好动属于一种气质类型，体现了带有强烈个人色彩的心理\n修养，且这种气质是销售人员所需要的，体现了职业方向和气质相匹配，符合定义，当\n选；\nD 项，小李气质的改变是已经进行职业方向选择后，并非在开始时自己的职业和气质\n相匹配，不符合定义，排除。\n故正确答案为C"},{"q":"农业干旱是指在作物生育期内，由于土壤水分不足而造成作物体内水分亏缺，影响作物正常生长发育。水文干旱是指由于降水的长期短缺而造成某段时间内地表水或地下水收支不平衡，出现水分短缺，使江河流量、湖泊水位、水库蓄水等减少的现象。社会经济干旱是指由自然系统与人类社会经济系统中水资源供需不平衡造成的异常水分短缺现象，如果需大于供，就会发生社会经济干旱。根据上述定义，下列选项属于社会经济干旱范畴的是（  ）","options":["一月未雨，某著名河流流域出现大规模的河床裸露现象","地铁建设施工队不慎挖破水管，导致几个小区停水一天","常年少雨致使某工业区推行按时段浮动征收水费的办法","半月不曾下雨，某地水稻出现穗长缩短，稻穗减少现象"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：自然系统与人类社会经济系统；水资源供需不平衡；异\n常水分短缺现象。\nA 项，一月未雨，出现河床裸露现象，属于由于降水的长期短缺而造成某段时间内地\n表水或地下水收支不平衡，属于水文干旱，不符合社会经济干旱的定义，排除；\nB 项，地铁建设挖破水管而导致小区停水，是一次意外导致的，未体现社会经济，不\n符合社会经济干旱的定义，排除；\nC 项，常年少雨导致工业区会面临需大于供的现象，且按时段浮动征收水费，体现了\n由自然系统与人类社会经济系统中水资源供需不平衡造成的异常水分短缺现象，符合社会\n经济干旱的定义，当选；\nD 项，半月不下雨而导致水稻出现穗长缩短，稻穗减少现象，属于土壤水分不足而造\n成作物体内水分稀缺，影响作物正常生长发育，属于农业干旱，不符合社会经济干旱的定\n义，排除。\n故正确答案为C。\n第十二组："},{"q":"信息文化是人们借助信息、信息资源、信息技术，从事信息活动所形成的文化形态，它是信息社会特有的文化形态，是信息社会中人们的生活样式。信息文化包括信息社会的物质文化、精神文化和制度文化。根据上述定义，下列属于信息文化现象的是（  ）","options":["扶贫办将扶贫干部拉入“扶贫微信群”，通过微信布置工作任务","莱布尼茨关于发明“人工语言”代替“自然语言”的思想，最终在20 世纪中叶得以实现","二战时期，交战国均聘请数学家、逻辑学家破译敌对方的军事电报代码","人工智能与仿生学成为当今大学的热门专业，吸引了众多学生报考"],"a":0,"e":"【答案】A\n【解析】定义判断。关键词：信息；文化。\nA 项，通过微信布置工作任务，属于借助信息形成的文化活动，符合定义，当选；\nB 项，发明人工语言代替自然语言不属于借助信息形成的活动，不符合定义，排除；\nC 项，聘请数学家逻辑学家不属于借助信息形成的文化活动，不符合定义，排除；\nD 项，热门专业吸引学生报考不属于借助信息形成的文化活动，不符合定义，排除。\n故正确答案为A。"},{"q":"罪恶关联是指通过指出某个被社会妖魔化的个人或群体也认同某观点，以此诋毁该观点。罪恶关联是一种非形式逻辑谬误，经常被有意或者无意地应用到论证场合。根据上述定义，下列属于罪恶关联的是（  ）","options":["小明成绩很差，他这道题的解题思路肯定不正确","这企业的毛绒玩具可能是用“黑心棉”做的，买他们的产品就等于支持他们的违法行为，你最好不要买给孩子","这种人才测评方法是德国纳粹军人发明的，所以我们不应该用这种不人道的方法评价","这演员演戏只会瞪眼耍帅对口型，现在居然被评为“年度最佳男主角”，这里面肯定有黑幕"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：被社会妖魔化；认同某观点；诋毁该观点。\nA 项，小明成绩很差不属于被社会妖魔化的个人，不符合定义，排除；\nB 项，买黑心棉等于支持违法行为不属于被社会妖魔化的个人，不符合定义，排除；\nC 项，德国纳粹军人是被社会妖魔化的人，这种人才测评方法是德国纳粹军人发明的\n属于被社会妖魔化的人认同此观点，所以我们不应该用这个方法，属于诋毁此观点，符合\n定义，当选；\nD 项，只会瞪眼耍帅对口型的演员居然被评为年度最佳男主角，不属于某个被社会妖\n魔化的个人或群体也认同某观点，不符合定义，排除。\n故正确答案为C。"},{"q":"怀旧疗法是指通过回顾过去的事件、情感及想法，帮助老年痴呆患者增加幸福感、提高生活质量及对现有环境的舒适感知能力。根据上述定义，下列选项中，最有可能使用了怀旧疗法的是（  ）","options":["张阿姨自从老伴儿去世后，情绪很低落，女儿将她送回老家疗养一段时间后，她心态变好了","文教授退休后身体状况时好时坏，但搬回大学后，马上就精神了","70 岁的老张最近有些健忘，但他自己一拿起老照片就能讲起这些照片背后的故事","退休后的老张很孤独，一出门就找不到家，家人听取医生建议给他播放革命老歌舒缓情绪，一段时间后情况有所改善"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：回顾过去；老年痴呆患者；增加幸福感、提高生活质\n量。\nA 项，张阿姨情绪低落不属于老年痴呆患者，不符合定义，排除；\nB 项，文教授退休后身体状况时好时坏不属于老年痴呆患者，不符合定义，排除；\nC 项，老张最近有些健忘可能属于老年痴呆患者，拿照片讲老故事不属于通过回顾过\n去提高生活质量，不符合定义，排除；\nD 项，老张一出门就找不到家可能属于老年痴呆患者，听革命老歌舒缓情绪，一段时\n间后情况有所改善属于通过回忆过去提高生活质量，符合定义，当选。\n故正确答案为D。"},{"q":"虚拟财产是一种能为人所支配的具有财产价值的权利，它是以电磁数据为形式存在于网络空间。虚拟财产具有虚拟性、价值性和可转让性特征。根据上述定义，下列属于虚拟财产的是（  ）","options":["司机老王的上世纪八十年代经典歌曲的磁带","设计师用电脑软件创作的，保存在光盘中的设计作品","经扫描并存储在移动硬盘的电子版家庭旧照片","小明从爸爸那里获得的6 位数QQ 号"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：电磁数据为形式存在于网络空间。\nA 项，磁带不符合“电磁数据为形式存在于网络空间”，不符合定义，排除；\nB 项，保存在光盘中，不符合“电磁数据为形式存在于网络空间”，不符合定义，排\n除；\nC 项，存储在移动硬盘不符合“电磁数据为形式存在于网络空间”，不符合定义，排\n除；\nD 项，6 位数QQ 号属于电磁数据的形式存在于网络空间，符合定义，当选。\n故正确答案为D。"},{"q":"学术图书是指内容涉及某学科或某专业领域，具有一定创新性，对专业学习、研究具有价值的图书，通常在书中有文献注释或参考文献，书后有索引，学术专著是指对某一学科或领域或某一专题进行较为集中、系统、全面、深入论述，对特定问题有独到见解，且大多“自成体系”的单著或二三人合著的学术著作。根据上述定义，下列属于学术专著的是（  ）","options":["某学术委员会编辑的学科词条工具书","某届学术会议的参会人员提交的学术论文","张教授作为学科带头人，总结多年教学经验，组织学科老师编写了全国第一本面向本专业研究生的高质量教材","小王的优秀博士生毕业论文"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：某一学科或领域或某一专题；深入论述。\nA 项，学科词条工具书不属于深入论述，不符合定义，排除；\nB 项，参会人员提交的学术论文，不属于某一学科或领域或某一专题的深入论述，不\n符合定义，排除；\nC 项，面向本专业研究生的高质量教材属于某一学科或领域或某一专题的深入论述，\n符合定义，当选；\nD 项，优秀博士生毕业论文，不属于某一学科或领域或某一专题的深入论述，不符合\n定义，排除。\n故正确答案为C。"},{"q":"校园欺凌是指在幼儿园、中小学及其合理辐射区域内发生的教师或者学生针对学生的持续性的心理性或者物理性攻击行为，这些行为会使受害者感受到精神上的痛苦。根据上述定义，下列不属于校园欺凌的是（  ）","options":["某高中体育委员经常假借“不认真锻炼”之名体罚同学","中学拉拉队成员小华每天都被队员们嘲笑“皮肤黑”“饭量大”","小学生小强与同桌因一时口角而打架，他担心第二天还会发生冲突，怎么也不愿意去学校","半年以来，儿童小龙在放学的路上经常被几个高年级的学生拦着索要零花钱，他非常害怕，但又不敢告诉老师和家长"],"a":2,"e":"【答案】C\n【解析】定义判断。选非题。关键词：针对学生；持续性；攻击行为。\nA 项，经常体罚同学属于对学生持续性的攻击行为，符合定义，排除；\nB 项，被队员们嘲笑皮肤黑饭量大，属于对学生持续性的心理攻击行为，符合定义，\n排除；\nC 项，小强担心第二天发生冲突因此不去学校不属于持续性的攻击行为，不符合定\n义，当选；\nD 项，小龙在放学的路上经常被拦着索要零花钱，属于对学生持续性的攻击行为，符\n合定义，排除。\n故正确答案为C。"},{"q":"增强现实技术是一种将真实世界信息和虚拟世界信息“无缝”集成的新技术，是把原本在现实世界的一定时间空间范围内很难体验到的实体信息（视觉、声音、味道、触觉等）。通过电脑等科学技术，模拟仿真后再叠加将虚拟的信息应用到真实世界，被人类感官所感知，从而达到超越现实的感官体验。根据上述定义，下列选项不属于增强现实技术的是（  ）","options":["某海底漫游系统通过交互体验设备让用户与虚拟场景中的海洋生物互动、嬉戏","某游戏运用追踪器侦测用户运动，并通过头盔显示器为用户提供包含虚拟景观的视野","某艺术家引导用户在物理空间中遵循播放器的指令行动进而成为其所设计情境的参与者","某科学家研制的智能隐形眼镜通过无线技术接收手机数据，并将手机上的图像投射到眼睛上"],"a":3,"e":"【答案】D\n【解析】定义判断，选非题。关键词：真实世界和虚拟世界信息无缝集成；通过电脑\n等科学技术。\nA 项，交互体现设备是通过电脑等科学技术，让用户与虚拟海洋生物嬉戏，体现了真\n实世界和虚拟世界信息无缝集成，符合定义，排除；\nB 项，追踪器和头盔显示器，体现了通过电脑等科学技术，让游戏用户在现实中感受\n虚拟景观的视野，体现了真实世界和虚拟世界信息无缝集成，符合定义，排除；\nC 项，遵循播放器的指令，体现了通过电脑等科学技术，让观众在所处的物理空间上\n成为艺术家设计景观的参与者，体现了真实世界和虚拟世界信息无缝集成，符合定义，排\n除；\nD 项，通过无线技术接收的是数据，但最终投射到眼睛上的是手机图像，两者都是静\n态事物展现，不能构成虚拟世界，未体现真实世界和虚拟世界信息无缝集成，不符合定\n义，当选。\n故正确答案为D。"},{"q":"虚假记忆综合症是指一个人的认同和人际关系以一种创伤经历的记忆为中心，这种记忆在客观上是虚假的，但病人却对此深信不疑，它在病人内心是非常逼真的，几乎就是一种“客观现实”。根据上述定义，下列属于虚假记忆综合症的是（  ）","options":["甲在被蛇咬过后，看见所有像蛇一样的东西，会感到恐惧","乙参加婚庆不由自主回忆起自己结婚时的情境并感到幸福","丙看到路边可怜的乞丐会勾起痛苦的回忆而产生怜悯之心","丁通过反复洗手来排除内心强烈的肮脏感获得心灵的平静"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：创伤经历的记忆为中心；客观上是虚假的。\nA 项，被蛇咬过是真实的记忆，不属于记忆在客观上是虚假的，不符合定义，排除；\nB 项，结婚感受到幸福，是美好的记忆，不属于以创伤经历的记忆为中心，并且结婚\n的情景是真实的，不属于记忆在客观上是虚假的，不符合定义，排除；\nC 项，丙痛苦的回忆是真实存在的，不属于记忆在客观上是虚假的，不符合定义，排\n除；\nD 项，丁通过反复洗手来排除内心强烈的肮脏感说明之前是发生过不好的事情，存在\n回忆，属于创伤经历的记忆为中心，反复洗手来确保干净，属于记忆在客观上是虚假的，\n符合定义，当选。\n故正确答案为D。"},{"q":"社会协同治理机制是指政府出于治理需要，通过发挥其主导作用，构建制度化的沟通渠道与参与平台，在始终保护并尊重社会的主体地位以及社会自身的运作机制和规律下，加强对社会的支持培育，并与社会一起，发挥社会在自主治理、参与服务、协同管理等方面的作用，形成政府主导、社会协同、共建共享的社会治理新格局。根据上述定义，下列属于社会协同治理的是（  ）","options":["由街道协调区工商局、城管大队等不定期开展联合执法，共同整治辖区内的经营秩序","市政府整合社会资源，在社区配备街道干部、民警、社工等人员，设立服务台，服务社区居民","由教育局、民政局、公安局等共同在行政服务大厅为企业和个人提供一站式行政审批办证服务","由省工商局、高级人民法院、中国人民银行某省分行共同签署协议，对失信企业实施信用联合监管"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词：政府主导、社会协同、共建共享。\nA 项，街道协调区工商局、城管大队，不属于政府主导，不符合定义，排除；\nB 项，市政府整合社会资源，属于政府主导，让其他部门多方参与，共同管理，属于\n社会协同、共建共享，符合定义，当选；\nC 项，教育局、民政局、公安局是政府部门，但不涉及社会参与，未体现社会协同、\n共建共享，不符合定义，排除；\nD 项，工商局、高级人民法院、中国人民银行都是政府部门，但不涉及社会参与，未\n体现社会协同、共建共享，不符合定义，排除。\n故正确答案为B。"},{"q":"行政比例原则是指行政主体实施行政行为应兼顾行政目标的实现和相对人权益的保护。如果初始行政目标可能对相对人权益造成某种不利影响，应使这种不利影响限制在尽可能小的范围和限度内，保持二者处于适度的比例。根据上述定义，下列选项符合行政比例原则的是（  ）","options":["王某因在商业区摆地摊，被城市管理部门以无证经营为由罚款5 万元","谭某在批准建设的三层楼房上加盖二层，被责令拆除加盖的二层楼房","马某醉酒驾车，酒精含量为300mg/100ml，被处3 个月拘役，缓刑一年","张某和李某互殴，张某将李某打成轻微伤，被处罚款500 元并拘留15 天"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词：相对人权益的保护；不利影响限制在尽可能小的范围和\n限度内。\nA 项，王某因为无证经营，被城市管理部门罚款，是行政部门正常的执法行为，不是\n对相对人权益的侵犯，不需要相对人权益的保护，不符合定义，排除；\nB 项，在批准建设的三层楼房上加盖两层是不合法行为，责令其拆除，是对相对人权\n益造成的不利影响，但仅要求拆除加盖的两层，未对剩下三层加以要求，体现了将这种不\n利影响限制在尽可能小的范围和限度内，符合定义，当选；\nC 项，马某醉酒驾驶，被处以拘留，是正常的执法行为，不是对相对人权益的侵犯，\n不需要相对人权益的保护，且该行为属于刑法，不属于行政法规的范围，不符合定义，排\n除；\nD 项，两人互殴而导致李某受伤，张某被处罚，是行政部门正常的执法行为，不是对\n相对人权益的侵犯，不需要相对人权益的保护，不符合定义，排除。\n故正确答案为B。\n第十三组："},{"q":"群落的分层现象是指不同的生物种出现于地面以上不同的高度和地面以下不同的深度，从而使整个群落在垂直方向上呈现上下分层分布的现象，这一现象也被称为群落的垂直结构。根据上述定义，下列没有反映群落分层现象的是（  ）","options":["森林中层栖息着山雀、啄木鸟等鸟类，林冠层则栖息着柳莺、交嘴等鸟类","自然保护区中的松柏高低错落，有的树根交错，互相缠绕，形成独特的层次感","海洋中，上层生活着浮游生物，中层生活着不同的鱼类，下层生活着海星等底栖生物","热带雨林中，乔木植物由于高大往往遮住了阳光，其下方生长着耐阴喜湿的草本植物"],"a":1,"e":"【答案】B\n【解析】定义判断，选非题。关键词：不同的生物种、出现于地面以上不同的高度、\n地面以下不同的深度。\nA 项，山雀、啄木鸟、柳莺、交嘴等鸟类符合“出现于地面以上不同的高度”，排\n除；\nB 项，松柏高低错落，说明松树柏树高低不等，没有明显分层，不符合“不同高度或\n深度”，当选；\nC 项，浮游生物、不同的鱼类和海星等底栖生物，符合“地面以下不同的深度”，排\n除；\nD 项，乔木植物、草本植物符合“出现于地面以上不同的高度”，排除。\n故正确答案为B。"},{"q":"化学抗性是指人或动植物由于长期大量使用抗生素或化学药物、使机体的病原体产生适应性或抵抗力，使得原药效降低的现象。其中，病原体是造成人或动植物感染疾病的微生物、寄生虫或其他媒介。根据上述定义，下列没有反映化学抗性的是（  ）","options":["对玉米地使用呋喃丹后线虫骤减，但5 年后，线虫不再对药物敏感，又开始繁殖","某产棉区种棉过程中发现一些棉株能天然抵抗棉铃虫侵害，于是广泛种植该种类棉花","喂鸡的饲料中含有抗生素，当鸡体内的细菌产生抗药性后，人们食用该种鸡肉，也会被该细菌感染","为防治水稻白叶枯病，某县城村庄在田间大量施用药物噻枯唑，几年后白叶枯病菌产生了抗药性"],"a":1,"e":"【答案】B\n【解析】定义判断，选非题。关键词：使用抗生素或化学药物。\nA 项，使用呋喃丹，符合“使用抗生素或化学药物”，排除；\nB 项，广泛种植该种类棉花，不符合“使用抗生素或化学药物”，当选；\nC 项，喂鸡的饲料中含有抗生素，符合“使用抗生素或化学药物”，排除；\nD 项，在田间大量施用药物噻枯唑，符合“使用抗生素或化学药物”，排除。\n故正确答案为B。"},{"q":"作为人体的生理功能、免疫能识别“自己”和“非己”成分，破坏和排斥侵入人体的抗原物质（如病菌等），或自身产生的损伤细胞和肿瘤细胞等，以维持健康。非消除性免疫是免疫的一种类型，指宿主感染寄生虫后不能清除或不能完全清除已经建立了感染的寄生虫，但对同种寄生虫的再感染具有一定程度的抵抗力。根据上述定义，下列反映了非消除性免疫的是（  ）","options":["热带利什曼原虫引起疖肿，当人体获得免疫力后原虫完全被清除，临床症状消失，不再感染","人体感染疟原虫后，体内疟原虫未被清除，维持低虫血症，但人体对这类感染具有一定的抵抗力","人体被血吸虫感染后出现发热、肝脾肿大症状，使用驱虫药后治愈，再感染时对入侵的童虫有一定的抵抗力","甲流病毒H1N1 感染了某些人群后，这些人体内的吞噬类细胞会将病毒吞噬从而治愈，获得免疫力，但他们仍会感染H7N9 型甲流"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词：感染寄生虫后不能清除或不能完全清除。\nA 项，原虫完全被清除，不符合“感染寄生虫后不能清除或不能完全清除”，排除；\nB 项，疟原虫未被清除，维持低虫血症，符合“感染寄生虫后不能清除或不能完全清\n除”，当选；\nC 项，使用驱虫药后治愈，治愈说明感染的寄生虫能清除，不符合“感染寄生虫后不\n能清除或不能完全清除”，排除；\nD 项，甲流病毒，不符合“寄生虫”，排除。\n故正确答案为B。"},{"q":"人们通常把因环境污染和环境破坏而对公众和社会所造成的危害叫做公害。公害病是公害发生的地区性疾病。其特征包括：①由人类活动造成的环境污染所引起；②损害健康的环境污染因素复杂；③其流行一般具有长期陆续发病的特征，还可能累及胎儿，危害后代；④属新病种，有些发病机制还不清楚，缺乏特效疗法。根据上述定义，下列不属于公害病的是（  ）","options":["人们食用了被镉污染的水稻后罹患骨痛病，骨骼疼痛难忍，无特效疗法","某地区玉米、小麦受到霉菌（尤其是镰刀菌）感染后会产生毒素，人们食用后会破坏人体骨骼生长，导致四肢短小","某地区使用重油燃料，排出废气中含有大量的二氧化硫，造成了严重的大气污染，引起当地居民罹患支气管哮喘、肺气肿等疾病","含无机汞的工业废水排入水体后，被细菌转化为毒性更强的甲基汞，富集于水生生物体内，人们长期食用后出现神经系统损伤，波及后代"],"a":1,"e":"【答案】B\n【解析】定义判断，选非题。关键词：由人类活动造成的环境污染所引起。\nA 项，镉污染的水稻，符合“由人类活动造成的环境污染所引起”，排除；\nB 项，玉米、小麦受到霉菌（尤其是镰刀菌）感染，不符合“由人类活动造成的环境\n污染所引起”，当选；\nC 项，排出废气中含有大量的二氧化硫，造成了严重的大气污染，符合“由人类活动\n造成的环境污染所引起”，排除；\nD 项，含无机汞的工业废水排入水体后，被细菌转化为毒性更强的甲基汞，符合“由\n人类活动造成的环境污染所引起”，排除。\n故正确答案为B。"},{"q":"清洁生产是指不断采取改进设计、使用清洁的能源和原料、采用先进的工艺技术与设备、改善管理、综合利用等措施，从源头削减污染，提高资源利用效率，减少或者避免生产、服务和产品使用过程中污染物的产生和排放，以减轻或者消除环境危害的生产方式。根据上述定义，下列不涉及清洁生产的是（  ）","options":["企业淘汰有毒有害的原材料，并在全部排放物和废物离开生产过程以前，尽最大可能减少它们的排放量和毒性","企业采用少废、无废的生产工艺技术和高效生产设备，减少生产过程中的各种危险因素和有毒有害的中间产品","企业选择再使用与再循环性的材料，这样可以通过提高环境质量和减少成本获得经济与环境收益","企业主动设置控制污染物排放标准，严格控制内部各部门污染物排污口，引进治污设备，使排放的污染物通过治理达到排放标准"],"a":3,"e":"【答案】D\n【解析】定义判断，选非题。关键词：从源头削减污染。\nA 项，淘汰有毒有害的原材料以减少它们的排放量和毒性，符合“从源头削减污\n染”，排除；\nB 项，采用少废、无废的生产工艺技术和高效生产设备减少危险因素和有毒有害的中\n间产品，符合“从源头削减污染”，排除；\nC 项，选择再使用与再循环性的材料以获得经济与环境收益，符合“从源头削减污\n染”，排除；\nD 项，引进治污设备，使排放的污染物通过治理达到排放标准，是产品生产过程之后\n的污染治理过程，不符合“从源头削减污染”，当选。\n故正确答案为D。"},{"q":"叙述视角是指叙述语言中对故事内容进行观察和讲述的特定角度。其中，内视角指的是叙述者只借助某个人物的感觉和意识，从他的视觉、听觉及感受的角度去传达一切，叙述者等同于该人物本身，即叙述者所知道的同该人物知道的一样多。根据上述定义，下列反映了内视角的是（  ）","options":["《金锁记》中，作者采用全知全能的叙述方式，掲示了曹七巧等人的悲剧命运","《白象似的群山》中，作者置身于所有角色之外，客观叙述故事中的人物命运","《孔乙己》中，作者即故事中的小伙计，用旁观者的口吻描写其所见所闻","《包法利夫人》中，作者以局外人的身份展示情节，给读者极大的想象空间"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：只借助某个人物的感觉和意识。\nA 项，作者采用全知全能的叙述方式，不符合“只借助某个人物的感觉和意识”，排\n除；\nB 项，作者置身于所有角色之外，不符合“只借助某个人物的感觉和意识”，排除；\nC 项，选作者即故事中的小伙计，符合“只借助某个人物的感觉和意识”，当选；\nD 项，作者以局外人的身份展示情节，不符合“只借助某个人物的感觉和意识”，排\n除。\n故正确答案为C。"},{"q":"光周期指的是昼夜周期中光照期和暗期长短的交替变化。植物在生长发育进程中，必须经过一定时间的适宜光周期后才能开花，否则会一直处于营养生长状态而不开花。这种昼夜长短影响植物开花的现象称为光周期现象。根据上述定义，下列没有反映光周期现象的是（  ）","options":["大豆性喜暖，种子在10—12℃开始发芽，如遇低温则结荚延迟，低于14℃不能开花","天仙子必须满足一定天数的8.5—11.5 小时日照才能开花，如果日照长度短于8.5小时它就不能开花","秋菊在每天14 小时的长日照下进行茎叶营养生长，在每天12 小时以上的黑暗与10℃的夜温下才能够开花","芹菜是长日照型植物，需要14 小时以上的日照才可抽薹开花，冬季需适当人工补充光照以满足其生长需求"],"a":0,"e":"【答案】A\n【解析】定义判断，选非题。关键词：昼夜长短影响植物开花。\nA 项，低于14℃不能开花，涉及温度，而非“昼夜长短”，不符合定义，当选；\nB 项，日照长度短于8.5 小时它就不能开花，符合“昼夜长短影响植物开花”，排\n除；\nC 项，每天12 小时以上的黑暗与10℃的夜温下才能够开花，符合“昼夜长短影响植\n物开花”，排除；\nD 项，需要14 小时以上的日照才可抽薹开花，符合“昼夜长短影响植物开花”，排\n除。\n故正确答案为A。"},{"q":"似不注意和似注意都是注意的一种，其中似不注意是指貌似不注意一事物而实际的心理活动却十分注意这一事物，而似注意是指表面上注意某些事物，但实际上心里却想着其他事物。根据上述定义，下列属于似不注意的是（  ）","options":["小李参加部门会议时，心里一直在想下个月休假去哪里玩","传说王羲之在书法创作时太过投入，有一次竟将馒头蘸着墨汁食用","学生在教室里听课，突然从外面进来一个人，这时学生就会中断听课不由自主地注意进来的人","刑事侦查人员在人群中发现了侦缉对象，为了不打草惊蛇，往往选择假装没看见，然后悄悄靠近，最后岀其不意地将对象抓获"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：貌似不注意；实际的心理活动却十分注意。\nA 项，参加会议时，心里一直在想下个月休假去哪里玩，属于表面上注意,但实际上心\n里却想着其他事物，未体现“貌似不注意”，不符合定义，排除；\nB 项，创作时太过投入，不符合“貌似不注意”，不符合定义，排除；\nC 项，听课时注意力被进来的人打断，不符合“貌似不注意”，不符合定义，排除；\nD 项，假装没看见，符合“貌似不注意”，悄悄靠近，最后出其不意地将对象抓获，\n符合“实际的心理活动却十分注意”，符合定义，当选。\n故正确答案为D。"},{"q":"岩石在基本上处于固体状态下，受到温度、压力及化学活动性流体的作用，发生矿物成分、化学成分、岩石结构与构造变化的地质作用，称为变质作用。地表的风化作用和其他外生作用（沉积作用等）引起岩石的物理变化，不属于变质作用。根据上述定义，下列反映了变质作用的是（  ）","options":["沙漠昼夜温差大，岩石在日间受热膨胀，晚间冷却收缩，逐渐形成砂砾","煤在隔绝空气条件下加热到850℃，保持7 分钟，其成分会分解成气体和液体","含有盐分的溶液渗入火成岩的裂缝中，当溶液蒸发留下盐晶体，盐晶受热后膨胀令岩石瓦解","宇宙中的巨大陨石高速降至地球表面，冲击岩石发生爆炸形成陨石坑，坑内岩石变化形成各种冲击岩"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：岩石处于固体状态下，受到温度、压力及化学活动性流\n体的作用；发生矿物成分、化学成分、岩石结构与构造变化的地质作用。\nA 项，沙漠昼夜温差大，岩石在日间受热膨胀，晚间冷却收缩，逐渐形成砂砾，是物\n理变化，不属于变质作用，不符合定义，排除；\nB 项，把煤隔绝空气，持续保持7 分钟，说明是人为过程，不属于地质作用，不符合\n定义，排除；\nC 项，盐晶受热后膨胀令岩石瓦解，是物理变化，不属于变质作用，不符合定义，排\n除；\nD 项，冲击岩石发生爆炸形成陨石坑，符合“岩石处于固体状态下，受到温度、压力\n及化学活动性流体的作用”，岩石变化形成各种冲击岩，符合“发生矿物成分、化学成\n分、岩石结构与构造变化的地质作用”，符合定义，当选。\n故正确答案为D。"},{"q":"不道德行为是指打破了日常行为规范的行为。按照行为动机，可分为无意不道德行为和故意不道德行为，前者指在没有意识到行为的不道德属性时做出的不道德行为；后者指个体明知道行为违背了道德规范，但仍采取的不道德行为。根据上述定义，下列属于故意不道德行为的是（  ）","options":["小刘收受男方彩礼后，男方悔婚，小刘根据当地风俗不退还男方彩礼","某企业为了增加品牌的热度，多次曝光企业的内幕，吸引了社会关注","某明星善于通过资助慈善事业获得免费的社会宣传效应","某公司明知合同条款对乙方不公平，仍假装承诺将履行合同"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：明知道；违背了道德规范；仍采取不道德行为。\nA 项，小刘根据当地风俗不退还彩礼不属于不道德的行为，不符合定义，排除；\nB 项，曝光自己企业的内幕不属于不道德的行为，不符合定义，排除；\nC 项，明星资助慈善事业不属于不道德的行为，不符合定义，排除；\nD 项，明知合同条款对乙方不公平，仍假装承诺履行合同属于明知道不道德仍要去\n做，符合定义，当选。\n故正确答案为D。\n第十四组："},{"q":"印象管理是指人试图控制他人对自己形成的印象的过程。一个人留给他人的印象表明了他人对其的知觉、评价，甚至会使他人形成对其的特定应对方式。因而，为了给他人留下好的印象，得到他人好的评价与对待，人会用一种给他人造成特定印象的方式来自我表现。印象管理的运用，尤其要避免某些表演崩溃，包括无意动作、不合时宜的闯入、闹剧等。根据上述定义，下列选项最能体现印象管理运用的是（  ）","options":["沙子龙在夜静人稀时，关好门，舞出一套断魂枪，微微一笑说：“不传不传”","许衡看到人们摘食路边的梨解渴，不为所动，说：“梨虽无主，而吾心有主”","一向沉静温柔的小美在毕业之际，承受不住与同学离别的感伤，突然嚎啕大哭","岳飞的母亲为了激励岳飞奋勇抗金，用针在其背上刺了四个字：“精忠报国”"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词：试图控制他人；对自己形成的印象；为了留下好的印\n象。\nA 项，夜静人稀，关好门，不符合控制他人，排除；\nB 项，看到人们摘梨，说梨虽无主，而吾心有主，符合试图控制他人、对自己形成的\n印象，当选；\nC 项，小美嚎啕大哭，不符合为了留下好的印象，排除；\nD 项，刺字是为了激励岳飞抗金，并非是为了留下好的印象，排除。\n故正确答案为B。"},{"q":"联觉是一种感觉器官受到刺激时引起性质完全不同的其他感觉的现象。它是不同感觉间相互作用的结果，也是一种条件反射现象。联觉现象在所有感觉中都存在，表现有个别差异。在现实生活中，由于某一种事物属性的出现经常伴随着另一种事物属性的出现，这两种事物属性所引起的感觉之间就形成了固定的条件联系。根据上述定义，下列选项不属于联觉的是（  ）","options":["小徐看到涂成蓝色的墙壁，浑身充满凉意","各种菜肴香味飘来，小刘听到了旋律变化","小李对人十分热情，人们都说他好像一团火","看到写在纸上的手机号，小冯感到阵阵发麻"],"a":2,"e":"【答案】C\n【解析】定义判断，选非题。关键词：一种感觉器官；引起其他感觉。\nA 项，看到是视觉，凉意对温度的感受，符合一种感觉器官、引起其他感觉定义，排\n除；\nB 项，菜香是嗅觉，听到是听觉，符合一种感觉器官、引起其他感觉定义，排除；\nC 项，热情和像一团火，热情是性格，不符合感觉器官，当选；\nD 项，看到是视觉，发麻是神经系统感觉，符合一种感觉器官、排除引起其他感觉，\n排除。\n故正确答案为C。"},{"q":"疼痛共情的偏好性，是指个体对他人疼痛的感知、判断和情绪反应，总是由于个体与他人之间的亲疏远近关系或情感认同程度不同而不同。根据上述定义，下列没有体现疼痛共情的偏好性的是（  ）。","options":["小明看到《西游记》里的白骨精被孙悟空打死，高兴得跳了起来","小张看到外来游客不幸溺水而亡，从此再也不敢去那条河里游泳","小李在看歌剧《白毛女》时跳上戏台拉住喜儿，不让黄世仁抢走","小红听奶奶回忆自己在旧社会的苦日子时，禁不住潸然泪下"],"a":1,"e":"【答案】B\n【解析】定义判断，选非题。关键词：个体对他人疼痛的感知、判断和情绪反应；由\n于个体与他人的亲疏远近关系的不同而不同。\nA 项，白骨精被打死，高兴的跳起来，符合个体对他人疼痛的感知、判断和情绪反\n应，排除；\nB 项，小张看到有人溺水而亡，之后不敢再去那条河，没有涉及对溺水游客的“疼痛\n的感知、判断和情绪反应”，不符合定义，当选；\nC 项，上台拉住喜儿，不让黄世仁抢走，符合个体对他人疼痛的感知、判断和情绪反\n应，由于亲疏关系远近，符合定义，排除；\nD 项，听奶奶回忆，禁不住潸然泪下，体现了个体对他人疼痛的感知、判断和情绪反\n应，符合定义，排除。\n故正确答案为B。"},{"q":"热传导是介质内无宏观运动时的传热现象，其在固体、液体和气体中均可发生。但严格而言，只有在固体中才是纯粹的热传导，在流体（泛指液体和气体）中又是另外一种情况，流体即使处于静止状态，也会由于温度梯度所造成的密度差而产生自然对流，因此在流体中热对流与热传导可能会同时发生。根据上述定义，下列选项不存在热传导现象的是（  ）","options":["海洋上层高温水体和下层低温水体因温度差而交换","铁棒的一端放入热水中，另一端温度升高","太阳照射，导致地球表面温度升高","在热水中加入冷水，热水变成温水"],"a":2,"e":"【答案】C\n【解析】定义判断，选非题。关键词：介质内无宏观运动时的传热现象，可发生在固\n体、液体和气体中；在固体中是纯粹的热传导；在流体中热对流与热传导可能同时发生。\nA 项，海洋上层水体温度高，下层水体温度低，由于温度梯度可使流体的粒子从温度\n较高的地方移至温度较低的地方，发生热对流的同时发生热传导，符合定义；排除；\nB 项，铁棒是固体，将其一端放入热水中，可使热从铁棒高温的一端传递到低温的一\n端，发生热传导，符合定义，排除；\nC 项，太阳能通过辐射转移到地球，属于热辐射，没有涉及热传导，不符合定义，当\n选；\nD 项，热水与冷水混合，由于温度高低的差异，可使流体的粒子从高温区域移至低温\n区域，发生热传导，符合定义，排除。\n故正确答案为C。"},{"q":"亲环境行为是指个体通过减少或消除自身活动对环境的负面影响以达到改善生态系统结构的行为。它的本质是通过有效减轻环境问题实现环境改善，核心任务是构造环境稳态友好型的社会。根据上述定义，下列选项属于亲环境行为的是（  ）","options":["植树造林","低碳出行","细水长流","围海造田"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词：个体通过减少或消除自身活动对环境的负面影响；改善\n生态系统结构的行为。\nA 项，植树造林，是增加了新的树木，不符合定义；排除；\nB 项，低碳出行，符合减少自身活动对环境的负面影响，当选；\nC 项，细水长流，不是具体的某种行为，不符合定义，排除；\nD 项，围海造田，增加了行为，不是减少的，不符合定义，排除。\n故正确答案为B。"},{"q":"积极强化是指用某种有吸引力的结果对某一行为进行奖励和肯定，以期在类似条件下重复这一行为。消极强化是指在行为出现时把不愉快的刺激撤销或减少，这样也可以增加行为频率。根据上述定义，下列选项属于积极强化的是（  ）","options":["君子一日三省其身","杀鸡骇猴以儆效尤","重赏之下必有勇夫","从轻发落戴罪立功"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：有吸引力的结果对行为的奖励和肯定；重复这一行为。\nA 项，君子三省吾身，是每天自省，未体现有吸引力的结果，不符合定义；排除；\nB 项，杀鸡骇猴，是为了减少这一行为出现的次数，不符合定义，排除；\nC 项，重赏，符合有吸引力的结果，勇夫，重复这一行为，符合定义，当选；\nD 项，从轻发落戴罪立功，不符合奖励和肯定，不符合定义，排除。\n故正确答案为C。"},{"q":"社会计算的内涵包括两个层面：一是社会的计算化，二是计算的社会化。社会的计算化是指通过人们在互联网上留下的海量而且相互关联的数据足迹，对人们的社会活动进行追踪、检索、汇编、计量和运算。计算的社会化则是指互联网创造了一种环境、一个平台，使人们能够广泛地参与计算过程，从而在数据的挖掘、分析和应用等方面获得更高效率。根据上述定义，下列现象符合计算的社会化的是（  ）","options":["某购物平台根据用户购物经历，定期向用户推荐商品","某手机导航软件能为用户自动生成一个月来的行踪图","全班同学在暑假田野调查结束后合作制成精美的相册","小陈在众筹平台匿名捐款后，受助者上门送来感谢信"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：互联网创造；环境；平台，人们广泛参与计算过程；获\n得更高效率。\nA 项，根据用户经历，不符合人们广泛参与计算过程，不符合定义；排除；\nB 项，用户在导航软件的行程，不涉及人们能够广泛地参与计算过程，不符合计算的\n社会化定义，不符合定义，排除；\nC 项，全班同学合作制成精美的相册并没有说明是否运用互联网，有可能制作的是实\n体相册，不符合“互联网创造了一种环境、一个平台”，不符合计算的社会化定义，排\n除；\nD 项，众筹平台符合互联网创造了一种环境、一个平台，小陈在众筹平台匿名捐款\n后，受助者上门送来感谢信，说明受助者在互联网上主动参与了计算以及数据的发掘分\n析，找到了小陈的信息，符合人们能够广泛地参与计算过程，并且“在数据的发掘、分析\n和应用等方面获得更高效率”，符合“计算的社会化”定义，当选。\n故正确答案为D。"},{"q":"外部性是指经济当事人的生产和消费行为对其他经济当事人的生产和消费行为施加的有益或者有害影响的效应。正外部性是指某个经济行为个体的活动使他人或社会受益，而受益者无需花费代价。负外部性是指某个经济行为个体的活动使他人或社会受损，而造成负外部性的人却没有为此承担成本。根据上述定义，下列选项属于正外部性的是（  ）","options":["经过农田的蒸汽机车，喷出火花飞到农民种植的麦穗上","飞速行驶的火车尖锐的汽笛声吓跑在农田吃稻谷的小鸟","某工厂在村庄建起了扶贫车间，为村民就近就业提供便利","某工厂排出了大量废水和有害气体，给周围居民带来健康危害"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词：经济行为；使他人受益；受益者无需花费代价。\nA 项，火花飞到麦穗上，没有让他人受益，不符合定义，排除；\nB 项，汽笛声吓跑吃稻谷的小鸟，让种田的农民受益了，而农民无需花费代价，符合\n经济行为、使他人受益、受益者无需花费代价，当选；\nC 项，某工厂在村庄建起了扶贫车间，村民仍需付出劳动力才能赚取工资，没有体现\n受益者无需花费代价，不符合定义，排除；\nD 项，带来危害，不符合使他人受益，排除。\n故正确答案为B。"},{"q":"错觉是完全不符合刺激本身特征的失真的或扭曲事实的知觉经验，生活中，凭知觉经验所作的解释显然是失真的，甚至是错误的。幻觉是在没有相应的外界客观事物直接作用下发生的不真实感知。幻觉具有与真实知觉类似的特点，但它是虚幻的。正常人在某些特殊的状态下，如强烈的情绪体验并伴有生动的想象、回忆，或期待的心情、紧张的情绪，或处于催眠状态，都可能会出现幻觉。在入眠或醒觉状态的过程中，也会发生幻觉。根据上述定义，下列属于幻觉的是（  ）","options":["杯弓有蛇影，草木疑皆兵","相看两不厌，唯有敬亭山","寝兴目存形，遗音犹在耳","蝉噪林逾静，鸟鸣山更幽"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：没有相应的外界客观事物；发生的不真实感知。\nA 项，杯弓有蛇影，草木疑皆兵，弓和草木，都有相应的外界事物，不符合定义，排\n除；\nB 项，是诗人与敬亭山相看而不厌，视敬亭山为人生知己，达到物我和谐、物我相忘\n的境界。敬亭山是外界客观事物，不符合没有相应的外界客观事物，不符合定义，排除；\nC 项，意思是在这种悲伤的追怀和祭奠中，亡妻那端庄的身影仿佛又浮现在诗人眼\n前，那温柔的嗓音又回荡在耳边。亡妻的身影和声音都是“虚幻的”，是诗人“在没有相\n应的外界客观事物直接作用下发生的不真实感知”，因极度难过想念而产生的幻觉，符合\n定义，当选；\nD 项，蝉、树林、鸟是外界客观事物，不符合没有相应的外界客观事物，排除。\n故正确答案为C。"},{"q":"社会收缩是指人类聚落中人口持续流失，由此引发相应地区经济社会环境和文化在空间上的衰退过程。根据收缩行为是否是聚落行为主体主动采取的规划策略或管理措施，可以分为主动社会收缩和被动社会收缩。根据上述定义，下列选项属于主动社会收缩的是（  ）","options":["某市因疏解核心区功能导致城区人口下降","2019 年我国春运人口迁移规模近30 亿人次","某产煤大县因资源枯竭导致就业吸纳能力下降","某制造业基地因产业升级导致房屋空置率居高不下"],"a":0,"e":"【答案】A\n【解析】定义判断。关键词：人口持续流失；衰退过程；主体主动采取规划策略或措\n施。\nA 项，疏解核心区功能，符合主体主动采取的规划策略或管理措施，城区人口下降符\n合人口持续流失，符合定义，当选；\nB 项，春运人口迁移不符合“人口持续流失”，不符合定义，排除；\nC 项，资源枯竭不符合主动采取的规划策略或管理措施，不符合定义，排除；\nD 项，房屋空置率居高不下是因为产业升级，而不是人口持续流失，不符合定义，排\n除。\n故正确答案为A。\n第十五组："},{"q":"比例原则是指行政机关实施行政行为应兼顾行政目标的实现和适当性手段的选择，保障公共利益和相对人权益的均衡，如为实现行政目标可能对相对人权益造成某种不利影响时，应将这种不利影响限制在尽可能小的范围和限度内，保持二者处于适度的比例。根据上述定义，行政机关的下列行为最符合比例原则的是（  ）","options":["夫妻二人在家中发生口角，吵闹声较大，公安机关以扰乱公共秩序为由对二人处以罚款500 元的处罚","交通运输局交通执法员黄某在查处车辆超载的过程中，殴打超载冲卡企图逃逸的司机","规划局批准某公司建造九层商业楼，该公司私自加盖至十二层，规划局认定为违章建筑，要求其把楼房全部拆除","市政府计划建设化工项目，论证后认为该项目会对附近的国家级风景区和居民生活区造成严重污染，遂将该项目叫停"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：行政机关；实施行政行为；将这种不利影响限制在尽可\n能小的范围和限度内；保障公共利益和相对人权益的均衡。\nA 项，公安局采取行政手段保障公众利益，但对“对二人处以罚款500 元的处罚”没\n有体现适度保障相对人权益，不符合定义，排除；\nB 项，执法员殴打超载的司机，使用的手段不是行政手段且侵害了相对人权益，没有\n保障相对人的权益，不符合定义，排除；\nC 项，规划局批准九层，后要求将建筑全部拆除，没有体现保障相对人的权益，不符\n合定义，排除；\nD 项，市政府采取行政措施叫停污染项目，保障了景区和居民的权益，符合定义，当\n选。\n故正确答案为D。"},{"q":"严格指示词是指一个语言表达式所具有的如下性质：它所指示的对象不会随着该表达式被使用的具体情境而发生改变。这些情境通常包括表达式的使用主体、表达式被使用的时间、地点、世界状态等等。根据上述定义，下列属于严格指示词的是（  ）","options":["现任联合国秘书长","世界上身高最高的人","经常坐在教室第一排正中间的同学","最小的素数"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：指示的对象、不会随具体情境而改变。\nA 项，随着时间的改变，现任联合国秘书长的担任者会随着时间的变化而变化，下一\n任未必是他，100 年后必然不是他。不符合题干定义，排除；\nB 项，随着时间的改变，世界上身高最高的人随着时间的变化而变化，100 年后必然\n不是他，不符合题干定义，排除；\nC 项，随着时间、地点等因素的改变，坐在教室第一排正中间的同学可能是班内任何\n个体，不符合题干定义，排除；\nD 项，最小的素数不会随具体情境的改变而改变，符合题干定义，当选。\n故正确答案为D。"},{"q":"同病异治是指中医对相同疾病采取不同的治法，达到治病求本的治疗效果；异病同治是指不同的疾病在发展过程中出现性质相同的症状，因而可以采用同样的中医治疗方法。根据上述定义，下列属于异病同治的是（  ）","options":["外感风热，内有蕴热的表里俱实之证，宜解表和攻里之药同时并用","久痢脱肛和胃下垂，均为中气下陷之证，可用升提中气之法治疗","麻疹初期疹未出透，治疗宜宣肺透疹；中期肺热明显，治疗宜清热解毒","风热感冒宜用辛凉解表法治疗，风寒感冒宜用辛温解表法治疗"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词：不同的疾病、相同性质的症状、同样的中医治疗方法。\nA 项，外感风热、内有蕴热是一种病，没有出现不同疾病，不符题干定义，排除；\nB 项，久痢脱肛和胃下垂是两种不同疾病，中气下陷是相同性质的症状，采用中气之\n法是同样的中医治疗方法。符合题干定义，当选；\nC 项，麻疹是一种疾病，没有出现不同疾病，不符题干定义，排除；\nD 项，风热感冒和风寒感冒是患病原因不同，但都是感冒。没有不同疾病出现，不符\n合题干定义，排除。\n故正确答案为B。"},{"q":"物候现象是生物随着气候一年四季的周期性变化而发生的相应季节性变化的现象。影响物候现象的因素主要包括海拔的差异、经度的差异、纬度的差异和时间的差异。下列诗句反映的物候现象受到海拔差异影响的是（  ）","options":["日出江花红胜火，春来江水绿如蓝","人间四月芳菲尽，山寺桃花始盛开","竹外桃花三两枝，春江水暖鸭先知","羌笛何须怨杨柳，春风不度玉门关"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词：生物、相应季节性变化、海拔的差异、经度的差异、纬\n度的差异、时间的差异。\nA 项，日出江花红胜火，是江花由于时间差异出现的变化，不符合定义，排除；\nB 项，四月山外的百花都已凋谢时，山上的桃花正在盛开。体现桃树由于海拔差异而\n出现的季节性变化，符合题干定义，当选；\nC 项，竹林外两三枝桃花初放，桃花最先感知到春意。体现桃花随时间差异而出现的\n季节性变化，不符合题干定义，排除；\nD 项，意为何必用羌笛吹起那哀怨的杨柳曲，埋怨春光迟迟。没有体现杨柳的季节性\n变化，不符合题干定义，排除。\n故正确答案为B。"},{"q":"公平世界谬误是指人们倾向于认为我们生活的世界是公平的，一个人获得成就是因为他肯定做对了什么，所以这份成就是他应得的；一个人遭遇不幸，他自己也有责任、甚至是咎由自取。根据上述定义，下列没有反映公平世界谬误的是（  ）","options":["可怜之人必有可恨之处","天网恢恢，疏而不漏","一分耕耘，一分收获","谋事在人，成事在天"],"a":3,"e":"【答案】D\n【解析】定义判断，选非题。关键词：人们、倾向于、世界公平、成就、做对什么、\n不行、咎由自取。\nA 项，可怜人的不如意是由于自己的过错导致的，符合一个人的不幸自己也有责任，\n排除；\nB 项，作恶的人逃脱不了国法的惩处，符合一个人的不幸是咎由自取，排除；\nC 项，有付出就有回报，符合一个人获得成就是因为他做对了什么，排除；\nD 项，人们付出努力之后可能成功，也可能不成功。不符合题干定义，当选。\n故正确答案为D。"},{"q":"按照先后顺序排列的两个数字或者字母称为序对，如2a、e3、dm 等等，序对中的第一个数字或者字母称为前项，第二个称为后项。函项指的是由若干序对构成的一个有限序列，其中每个序对的前项都是字母，后项都是数字，并且对于任一序对，如果前项相同则后项必定相同。根据上述定义，下列哪项属于函项（  ）","options":["a3、b5、d6、p1、e3","f4、h4、gm、y2、x2","p3、c4、d6、p6、m8","b3、5a、8n、P1、66"],"a":0,"e":"【答案】A\n【解析】定义判断。关键词：前项是字母；后项是数字；如果前项相同，则后向必定\n相同。\nA 项，每一个序对都符合上述定义，当选；\nB 项，第三个序对“gm”，后项不是数字，排除；\nC 项，第一个与第四个序对，“p3”“p6”，前项相同，但后项不同，排除；\nD 项，第二个、第三个和第六个序对，“5a”“8n”“66”，前项不是字母，排除；\n故正确答案为A"},{"q":"诉前财产保全是指利害关系人因情况紧急，若不立即申请财产保全将会使其合法权益受到难以弥补的损害，起诉前向人民道院，由人民法院采取的一种财产保全措施。根据上述定义，下列不属于诉前财产保全的是（  ）","options":["甲与乙签订购销合同，甲给乙200 万元预付款后，发现乙有欺诈行为，无力履行合同，遂请求人民法院冻结200 万元预付款","银行甲与公司乙签订协议，甲向乙提供5000 万元贷款，分3 期还清，第一笔到期时乙无力归还，甲向法院申请查封乙的财产","甲欠乙10 万元，乙多次找甲还钱未果，得知甲有一辆轿车，乙向法院申请将甲的轿车予以查封，再将甲告上法庭","工厂甲向信用社乙贷款500 万元，甲无法按期归还。乙随即起诉，审理期间得知甲已将设备转卖，遂请求法院查封甲正在出售的大楼"],"a":3,"e":"【答案】D\n【解析】定义判断，选非题。关键词：起诉前。\nA 项，发现欺诈行为，遂请求人民法院冻结200 万元预付款，符合“起诉前”，排\n除；\nB 项，第一笔到期时乙无力归还，向法院申请查封乙的财产，符合“起诉前”，排\n除；\nC 项，向法院申请将甲的轿车予以查封，再将甲告上法庭，符合“起诉前”，排除；\nD 项，乙随即起诉，审理期间得知甲已将设备转卖，遂请求法院查封甲正在出售的大\n楼，是起诉后，不符合“起诉前”，当选；\n故正确答案为D。"},{"q":"员工帮助计划是由企业为员工设置的一套长期的、系统的福利项目，通过专业人员对员工及其直系亲属提供专业指导和咨询，旨在帮助解决员工及其家庭成员的各种心理和行为问题，提高员工在企业中的工作绩效。根据上述定义，下列属于员工帮助计划的是（  ）","options":["项目经理小祁的父亲最近去世了，小祁很悲痛，工作效率受到很大影响，总经理特批了一笔慰问款","司机小方驾车外出工作期间交通肇事致人死亡，公司聘请律师为小方做从轻处罚的辩护，最终小方获刑三年","职员小欣情绪低落，有自杀的念头，经医院诊断为重度抑郁症，需住院治疗。公司启动援助机制，为小欣支付了住院费用","会计师老王的儿子没有考上大学，老王夫妇很烦恼，互相指责。在公司心理专员的指导下，老王改善了与妻子的沟通方式，情绪逐渐好转"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：专业指导和咨询；解决员工及其家庭成员的各种心理和\n行为问题。\nA 项，特批了一笔慰问款，不符合专业指导和咨询，排除；\nB 项，聘请律师为小方做从轻处罚的辩护，不符合解决员工及其家庭成员的各种心理\n和行为问题，排除；\nC 项，为小欣支付了住院费用，不符合专业指导和咨询，排除；\nD 项，公司心理专员的指导，符合专业指导和咨询。改善了沟通方式，情绪逐渐好\n转，符合解决员工及其家庭成员的各种心理和行为问题，当选。\n故正确答案为D。"},{"q":"变文和连文是古汉语中常用的修辞方法。变文是指为了避重而在相邻近的句子中案用同义词来表达相同的意义。连文是指本来要表达甲，而连带说道乙，使两个相关的词连在一起，但突出表达其中一个词的意义。下列使用连文这一修辞方法的是（  ）","options":["《易经·系辞上传》：“鼓之以雷霆，润之以风雨”","《史记·淮阴侯列传》：“置之死地而后生，置之亡地而后存”","诸葛亮《出师表》：“受任于败军之地，奉命于危难之间”","贾谊《过秦论》“南取汉中，西举巴蜀，东割膏腴之地，北收要害之郡”"],"a":0,"e":"【答案】A\n【解析】定义判断。关键词：两个相关的词连在一起，但突出表达其中一个词的意\n义。\nA 项，“风雨”符合两个相关词连用，而在“润之以风雨”这句话中，能够起到\n“润”的作用只有雨，突出强调了“雨”这个词，符合定义，当选；\nB 项、D 项中未出现两个相关词连用，不符合定义，排除；\nC 项，“危难”符合两个相关词连用，但在“奉命于危难之间”这句话中，并未突出\n强调某一个词，不符合定义，排除；\n故正确答案为A。\n第十六组："},{"q":"超前纠结指的是在平庸的人群中，有正确洞见的人当其观点不被接受、不被相信，对事情的发展无能为力时，所表现出的无奈、压抑和痛苦的心情。根据上述定义，下列最能体现超前纠结的是（  ）","options":["古来圣贤皆寂寞，惟有饮者留其名","举世皆浊我独清，世人皆醉我独醒","无可奈何花落去，似曾相识燕归来","醉卧沙场君莫笑，古来征战几人回"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词：“在平庸的人群中”、“正确洞见的人当其观点不被接\n受、不被相信，对事情的发展无能为力时”、“所表现出的无奈、压抑和痛苦的心情”。\nA 项，诗句的意思是“自古以来圣贤无不是冷落寂寞的，只有会喝酒的人才能够流传\n美名。”该诗句说明作者李白只图一醉方休，表达了诗人旷达的胸怀，没有体现出“正确\n洞见的人当其观点不被接受、不被相信，对事情的发展无能为力”，不符合定义，排除；\nB 项，诗句的意思是“世界上的人都是污浊的，唯独我干净、清白；众人都已醉倒，\n唯独我一人清醒。”该诗句是屈原被排挤，被冠以奸邪的罪名，遭到了放逐后所作，符合\n“在平庸的人群中”“正确洞见的人当其观点不被接受、不被相信，对事情的发展无能为\n力时”，也符合“所表现出的无奈、压抑和痛苦的心情”，符合定义，当选；\nC 项，诗句的意思是“那花儿落去我也无可奈何，那归来的燕子似曾相识”，该诗句\n表达了春的消逝，时光的流逝，都是不可抗拒的自然规律，虽然惋惜流连也无济于事，不\n符合“正确洞见的人当其观点不被接受、不被相信，对事情的发展无能为力时”，不符合\n定义，排除；\nD 项，诗句的意思是“醉就醉吧，醉卧在沙场上有什么呢，请不要见笑，从古至今征\n战的人有几个是活着回来的。”表达了豪放、开朗、兴奋的感情，还有视死如归的勇气，\n不符合“所表现出的无奈、压抑和痛苦的心情”，不符合定义，排除。\n故正确答案为B。"},{"q":"算术平均数描述了一组数据的平均趋势，是所有数据之和除以数据个数所得之商。在统计学中使用时应注意：出现极端数值、模糊不清的数据或者不同质的数据时，均不能计算算术平均数。根据上述定义，下列适于计算算术平均数的是（  ）","options":["某社区统计该社区居民的平均年龄，其中包括10 岁以下儿童204 人，90 岁以上老人26 人","某公司统计35 岁以下青年职工的年平均收入，发现基本处于10—12 万元之间，其中有一人为公司高管，年收入百万元以上","某学校统计本校青少年平均身高，将该校学前部、小学部和中学部全部学生计算在内","某市统计该市各区县留守儿童的平均数量，其中外出务工人员数量较多的区县无法进行准确统计，只提供了估算数据"],"a":0,"e":"【答案】A\n【解析】定义判断。关键词：“描述了一组数据的平均趋势”、“所有数据之和除以\n数据个数所得之商”、“出现极端数值、模糊不清的数据或者不同质的数据时，均不能计\n算算术平均数”。\nA 项，10 岁以下儿童204 人，90 岁以上老人26 人，这些都是该社区居民，所以在统\n计该社区居民的平均年龄，要统计在内，适用于计算算数平均数，当选；\nB 项，某公司统计35 岁以下青年职工的年平均收入，一人年收入百万元以上，其他\n人基本处于10~12 万元之间，年收入百万以上的公司高管与年收入10~12 万元的普通员工\n相比，属于“极端数值”，不适于计算算术平均数，排除；\nC 某，学校统计本校青少年平均身高，青少年一般是指自上初中到高中毕业，包括\n“中学部”，但不包括“学前部、小学部”，所以，“学前部、小学部和中学部”属于\n“不同质的数据”，不适于计算算术平均数，排除；\nD 项，某市统计该市各区县留守儿童的平均数量，其中外出务工人员数量较多的区县\n无法进行准确统计，只提供了估算数据，估算出的数据属于“模糊不清的数据”，不适于\n计算算术平均数，排除。\n故正确答案为A。"},{"q":"动物辅助治疗是一种以动物为媒介，通过人与动物的接触，改善或维持残障人士的身体状况，或帮助他们加强与外部世界的互动，进而促进康复、适应社会的过程。根据上述定义，下列情形不属于动物辅助治疗的是（  ）","options":["性情温和的迷你猪适合陪伴自闭症患者，减轻他们面对人群时产生的焦虑","卷尾猴能够帮助体障者完成日常生活中的简单动作，如开关门、操控遥控器等","鼬獾会在主人精神病发作之际，发出叫声，警示主人，让主人可以及时服药","英国短毛猫性格温顺且不具有攻击性，喜静且贴近主人，适合陪伴独自生活的老年人"],"a":3,"e":"【答案】D\n【解析】定义判断，选非题。关键词：“以动物为媒介”、“通过人与动物的接触，\n改善或维持残障人士的身体状况，或帮助他们加强与外部世界的互动”。\nA 项，迷你猪陪伴自闭症患者，符合“以动物为媒介”，减轻自闭症患者面对人群时\n产生的焦虑，符合“通过人与动物的接触，改善或维持残障人士的身体状况”，符合定\n义，排除；\nB 项，卷尾猴帮助体障者完成简单动作，符合“以动物为媒介”，体障者能够开关\n门、操控遥控器，符合“通过人与动物的接触，改善或维持残障人士的身体状况”，符合\n定义，排除；\nC 项，鼬獾能够警示精神病人及时吃药，符合“以动物为媒介”，在主人发病时发出\n叫声，警示主人，符合“通过人与动物的接触，改善或维持残障人士的身体状况”，符合\n定义，排除；\nD 项，独自生活的老年人不是残障人士，不符合定义，当选。\n故正确答案为D。"},{"q":"合理使用是指在法律明文规定的情形下，非商业性使用他人已经发表的作品，可以不经著作权人许可，也不必向其支付报酬。“法律明文规定的情形”主要包括：（1）为个人学习、研究或者欣赏，使用他人已经发表的作品；（2）免费表演已经发表的作品；（3）对设置或者陈列在室外公共场所的艺术作品进行临摹、绘画、摄影、录像；（4）将已经发表的以汉语言文字创作的作品翻译成少数民族语言文字作品出版发行。根据上述规定，下列属于合理使用的是（  ）","options":["甲在班级聚会上演唱了戊未发表的一首歌曲","乙将一部英文作品翻译成蒙文作品出版发行","丙公司拍摄公共广场的雕塑作品后，将其制作成图片发行","丁为撰写论文，复印了庚发表在某期刊上的论文作参考"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：“在法律明文规定的情形下”、“非商业性使用他人已\n经发表的作品”、“为个人学习、研究或者欣赏，使用他人已经发表的作品”、“免费表\n演已经发表的作品”、“对设置或者陈列在室外公共场所的艺术作品进行临摹、绘画、摄\n影、录像”、“将已经发表的以汉语言文字创作的作品翻译成少数民族语言文字作品出版\n发行”。\nA 项，甲唱了一首戊尚未发表的歌曲，不符合“非商业性使用他人已经发表的作品”\n和“免费表演已经发表的作品”，不符合定义，排除；\nB 项，乙将英文作品翻译成蒙文作品，这里的英文作品不符合“将已经发表的以汉语\n言文字创作的作品翻译成少数民族语言文字作品出版发行”，不符合定义，排除；\nC 项，丙公司拍摄雕塑作品后进行发行，属于商业用途，不符合“非商业性使用他人\n已经发表的作品”，不符合定义，排除；\nD 项，丁为了撰写论文复印和参考了庚已经发表的论文，参考论文符合“在法律明文\n规定的情形下”和“为个人学习、研究或者欣赏，使用他人已经发表的作品”，同时，丁\n没有用作商业用途，符合“非商业性使用他人已经发表的作品”，符合定义，当选。\n故正确答案为D。"},{"q":"编剧式观影者是指看影视剧不介意被剧透，甚至会提前查询剧情介绍、翻遍各种影评的人。这种观影者追求掌控剧情发展的感觉，不喜欢出乎意料。根据上述定义，下列属于编剧式观影者的是（  ）","options":["小王看了一部好的影片后，觉得应该和女朋友一起分享，于是邀请女朋友到电影院观影，还向她介绍了电影的主要内容","小杜对任何事情都讲求理性思维，对于电影，他只有在了解了权威评价、剧情内容、画面特征等情况后，才有观赏的冲动","小李酷爱悬疑类影片，他喜欢陶醉在烧脑的剧情中，心情随着剧情而起伏，他经常假想自己就是一名侦探，对他人总是投出审视的目光","张大爷的老伴退休后整天在家看电视剧，对很多电视剧的剧情都了如指掌，还经常将剧情讲述给张大爷"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词：“看影视剧不介意被剧透”、“会提前查询剧情介绍、\n翻遍各种影评的人”。\nA 项，小王向女朋友介绍电影剧情，但没有说女朋友是否介意被剧透，不符合“看影\n视剧不介意被剧透”，不符合定义，排除；\nB 项，小杜对于电影在了解权威评价、剧情内容、画面特征等情况后，才有观赏的冲\n动，符合“会提前查询剧情介绍、翻遍各种影评的人”，符合定义，当选；\nC 项，小李喜欢陶醉在烧脑的剧情中，但没有涉及喜欢提前知道剧情，不符合“会提\n前查询剧情介绍、翻遍各种影评的人”，不符合定义，排除；\nD 项，张大爷的老伴喜欢将电视剧剧情讲述给张大爷，但没有说张大爷是否介意被剧\n透，不符合“看影视剧不介意被剧透”，不符合定义，排除。\n故正确答案为B。"},{"q":"愧疚补偿策略指的是不直接提出要求，而强调由于对方的责任导致自己处于困境，使对方产生愧疚心理，从而使对方补偿自己的一种策略。根据上述定义，下列反映了愧疚补偿策略的是（  ）","options":["甲向李某倾诉由于误信了他群发的信息，导致自己被骗得很惨，李某于是免息借钱给甲做生意以求得心安","乙上班迟到被领导批评，回家后责怪妻子没有及时叫醒他，并要求妻子以后负责夜里带孩子，妻子答应了他","丙开车邀请陈某一起郊游，途中丙不慎扭伤了脚，只得请假休养，陈某感到非常内疚，决定帮助丙接送孩子上下学","丁在庄某家做保洁时不慎摔伤，庄某听家政公司说丁家庭非常困难，主动替丁支付了5000 元的治疗费用"],"a":0,"e":"【答案】A\n【解析】定义判断。关键词：“不直接提出要求”、“强调由于对方的责任导致自己\n处于困境”、“使对方产生愧疚心理，从而使对方补偿自己”。\nA 项甲向李某倾述由于李某的原因他被骗的很惨，符合“强调由于对方的责任导致自\n己处于困境”，李某于是免息借钱给甲做生意以求得心安，符合“使对方产生愧疚心理，\n从而使对方补偿自己”，符合定义，当选；\nB 项，乙要求妻子以后负责夜里带孩子，不符合“不直接提出要求”，不符合定义，\n排除；\nC 项，丙请假休养，但并没有和陈某说这件事情，不符合“强调由于对方的责任导致\n自己处于困境”，不符合定义，排除；\nD 项，庄某听家政公司说丁家庭非常困难，并不是丁某自己强调家庭困难，不符合\n“强调由于对方的责任导致自己处于困境”，不符合定义，排除；\n故正确答案为A。"},{"q":"客观—价值谬误是一种错误的推理，其前提是一个事实性的描述，而结论所表述的则是一个涉及价值意义的描述，而且这种推理没有预设明显的价值判断前提。根据上述定义，下列属于客观-价值谬误的是（  ）","options":["人与人之间应该进行更多地交流和沟通，更多地理解和包容，世界上的民族国家将越来越少","既然人人都要遵纪守法，那我们就应该对法律多一份尊重，对规则多一份敬畏","世界变得越来越城市化，因此人们就不应该继续诗意地栖居在农村","这个地区的绿化率在不断提高，其空气质量也将不断改善"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：“前提是一个事实性的描述”、“结论所表述的则是一\n个涉及价值意义的描述”、“这种推理没有预设明显的价值判断前提”。\nA 项，人与人之间应该进行更多地交流和沟通，更多地理解和包容，属于涉及价值意\n义的描述，世界上的民族国家将越来越少，属于陈述的事实，不符合“前提是一个事实性\n的描述”、“结论所表述的则是一个涉及价值意义的描述”，不符合定义，排除；\nB 项，既然人人都要遵纪守法，属于涉及价值意义的描述，那我们就应该对法律多一\n份尊重，对规则多一份敬畏，也属于涉及价值意义的描述，不符合“前提是一个事实性的\n描述”、“结论所表述的则是一个涉及价值意义的描述”，不符合定义，排除；\nC 项，世界变得越来越城市化，符合“前提是一个事实性的描述”，因此人们就不应\n该继续诗意地栖居在农村，符合“结论所表述的则是一个涉及价值意义的描述”，符合定\n义，当选；\nD 项，这个地区的绿化率在不断提高，属于陈述的事实，其空气质量也将不断改善，\n也属于陈述的事实，不符合“前提是一个事实性的描述”、“结论所表述的则是一个涉及\n价值意义的描述”，不符合定义，排除。\n故正确答案为C。"},{"q":"社交裂变是一种利益驱动的商业模式，通过人与人之间的社交促进产品的传播与销售，本质上是通过利益驱动激励客户从而形成裂变。根据上述定义，下列不属于社交裂变的是（  ）","options":["某微商客户挑选好某个商品后，分享在自己的社交圈，好友帮助砍价后，客户可以低价购买，同时也宣传了该商品","某微信用户在购买到自己喜欢的商品后，经常拍照发在朋友圈中，慢慢地大家都知道她喜欢购买高档奢侈品","某电商平台的客户成功购买商品后，分享其链接，所有点击的人都能获得商家提供的随机金额的优惠券","某咖啡店的老顾客参加“邀请好友免费喝咖啡”的活动后，可以获取一张套餐券"],"a":1,"e":"【答案】B\n【解析】定义判断，选非题。关键词：“通过人与人之间的社交促进产品的传播与销\n售”、“通过利益驱动激励客户从而形成裂变”。\nA 项，微商客户通过在自己的社交圈中分享商品促进了产品的传播和销售，符合关键\n词“通过人与人之间的社交促进产品的传播与销售”，微商客户通过在朋友圈分享获得了\n好友的砍价，继而可以通过较低的价格购买到产品，符合关键词“通过利益驱动激励客户\n从而形成裂变”，符合定义，排除；\nB 项，微信用户在购买到自己喜欢的商品后，通过拍照在朋友圈中分享，继而起到产\n品宣传的效果，符合关键词“通过人与人之间的社交促进产品的传播与销售”，但选项中\n未体现出商家对微商客户的激励，不符合关键词“通过利益驱动激励客户从而形成裂\n变”，不符合定义，当选；\nC 项，电商平台通过让购买成功的客户分享其链接来宣传自己，符合关键词“通过人\n与人之间的社交促进产品的传播与销售”，所有点击的人都能获得商家提供的随机金额的\n优惠券，符合定义关键词“通过利益驱动激励客户从而形成裂变”，符合定义，排除；\nD 项，咖啡店通过让老顾客邀请好友免费喝咖啡来促进产品的传播和销售，符合关键\n词“通过人与人之间的社交促进产品的传播与销售”，老顾客通过参加“邀请好友免费喝\n咖啡”活动可以获取一张套餐券，符合定义关键词“通过利益驱动激励客户从而形成裂\n变”，符合定义，排除。\n故正确答案为B。"},{"q":"培养基是指供给微生物、植物或动物（或组织）生长繁殖的，由不同营养物质组合配制而成的营养基质，一般都含有碳水化合物、含氮物质、无机盐、维生素、水等物质。天然培养基是利用动物、植物或微生物包括其提取物制成的培养基；合成培养基是根据天然培养基的成分，用化学物质模拟合成、人工设计而配制的培养基；半组合培养基是以化学试剂配制为主，同时还加有少量天然成分的培养基。根据上述定义，下列属于半组合培养基的是（  ）","options":["为研究鸡胚细胞的生长，在一定比例的盐水氨基酸溶液中加入少量玉米汁制成的培养基","为促进乳酸菌生长，使用小麦的麦芽汁制成的培养基","为加速诱发绿萝生长，将有机成分、矿物元素、琼脂等按3：1：2 的比例制成的培养基","为观察产气荚膜梭菌的生成，在1000 毫升新鲜牛奶中加入10 毫升硫酸亚铁制成的培养基"],"a":0,"e":"【答案】A\n【解析】定义判断，多定义。关键词：培养基：“供给微生物、植物或动物（或组\n织）生长繁殖的，由不同营养物质组合配制而成的营养基质，一般都含有碳水化合物、含\n氮物质、无机盐、维生素、水等物质”。天然培养基：“利用动物、植物或微生物包括其\n提取物制成”。合成培养基：“根据天然培养基的成分，用化学物质模拟合成、人工设计\n而配制的培养基”。半组合培养基：“以化学试剂配制为主，同时还加有少量天然成分的\n培养基”。\nA 项，“在一定比例的盐水氨基酸溶液中加入少量玉米汁制成的培养基”说明该培养\n基是以盐水氨基酸溶液为主，以少量玉米汁为辅，且盐水氨基酸溶液是一种化学试剂，玉\n米汁是从玉米中提取而来，为天然成分，符合关键词“以化学试剂配制为主，同时还加有\n少量天然成分的培养基”，符合“半组合培养基”定义，当选；\nB 项，麦芽汁是从麦芽中提取而来，是天然成分，但选项中并未提及“化学试剂”，\n不符合关键词“以化学试剂配制为主，同时还加有少量天然成分的培养基”，不符合定\n义，排除；\nC 项，“有机成分、矿物元素、琼脂等按3：1：2 的比例制成”说明该培养基主要以\n有机成分、矿物元素、琼脂为主，选项中未涉及少量天然成分，不符合关键词“以化学试\n剂配制为主，同时还加有少量天然成分的培养基”，不符合“半组合培养基”定义，排\n除；\nD 项，“在1000 毫升新鲜牛奶中加入10 毫升硫酸亚铁制成的培养基”说明该培养基\n是以新鲜牛奶为主，以硫酸亚铁为辅，而新鲜牛奶是天然成分，硫酸亚铁为化学试剂调配\n而成，不符合关键词“以化学试剂配制为主，同时还加有少量天然成分的培养基”，不符\n合“半组合培养基”定义，排除。\n故正确答案为A。\n第十七组："},{"q":"团体迷思，指团体在决策过程中，由于成员倾向让自己的观点与团体一致，因而令整个团体缺乏不同的思考角度，不能进行客观分析。一些值得争议的观点、有创意的想法或客观的意见不会有人提出、或者是遭到忽视及隔离。根据上述定义，下列属于团体迷思的是（  ）","options":["小赵提的一个建议遭到了领导否决，他以后再也不提意见了","在会议上大家都不发表意见，可一走出会议室就议论纷纷","老王性格内向，不习惯在单位大会上发表个人见解","公司管理很混乱，看不到希望，大家都懒得提意见"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词：成员倾向让自己的观点与团体一致；整个团体缺乏不同\n的思考角度，不能进行客观分析。\nA 项，小赵不提意见是因被领导否决，而非“倾向让自己的观点与团体一致”，且未\n明确体现团体观点，不符合定义，排除；\nB 项，在会议上大家都不发表意见，走出会议室就议论纷纷，说明大家其实有很多意\n见，只是因为“倾向让自己的观点与团体一致”，未在会上发表自己的意见，符合定义，\n当选；\nC 项，老王不发表个人见解是因其性格内向，而非“倾向让自己的观点与团体一\n致”，且未明确体现团体观点，不符合定义，排除；\nD 项，大家不提意见是因为认为公司管理混乱，看不到希望，而非“倾向让自己的观\n点与团体一致”，且未明确体现团体观点，不符合定义，排除。\n故正确答案为B。"},{"q":"揭短营销是一种通过暴露自己的短处或是不足来进行营销的手段。揭短营销表面上揭露了企业的短处，实际上是对商品的客观评价。根据上述定义，下列情形属于揭短营销的是（  ）","options":["卖苹果的摊主故意说自己的苹果酸，引得路人买他的苹果","某公司宣扬产品优点的同时，也告知顾客产品的不足之处","某商家在宣传自己的产品时，揭露同行的产品存在的弱点","酒厂故意在商店打碎一瓶酒，以此吸引顾客的注意"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词：暴露自己的短处或是不足来进行营销，表面上揭露了企\n业的短处，实际上是对商品的客观评价。\nA 项，摊主说苹果酸，不属于“企业的短处”，不符合定义，排除；\nB 项，告知产品的不足之处，体现了“表面上揭露了企业的短处，实际上是对商品的\n客观评价”，符合定义，当选；\nC 项，揭露同行的产品存在的弱点，不符合“暴露自己的短处或是不足”，不符合定\n义，排除；\nD 项，故意在商店打碎一瓶酒，是想通过酒的香气吸引顾客，但不是“暴露自己的短\n处或是不足”，不符合定义，排除。\n故正确答案为B。"},{"q":"社会公共消费，是指以社会和集体作为消费单位，在社会或集体范围内为满足其成员的共同需要而消费各种消费资料和劳务的一种消费需求，是在社会或集体范围内共同进行的消费。根据上述定义，下列情形不属于社会公共消费的是（  ）","options":["中小学生的义务教育消费","单位为员工提供体育健身设施","单位为优秀工作者发放奖金","某市为60 岁以上老人发放福利金"],"a":2,"e":"【答案】C\n【解析】定义判断，选非题。关键词：社会和集体作为消费单位；在社会或集体范围\n内为满足其成员的共同需要。\nA 项，义务教育是为了满足中小学生的“共同需要”而进行的消费，符合定义，排\n除；\nB 项，体育设施是为了满足单位员工的“共同需要”而进行的消费，符合定义，排\n除；\nC 项，奖金只针对优秀工作者发放，是为了满足个体或集体中的少数人的需要而进行\n的消费，不符合定义，当选；\nD 项，福利金是为了满足60 岁以上老人的“共同需要”而进行的消费，符合定义，\n排除。\n故正确答案为C。"},{"q":"如若对某人提出一个很大而又易被拒绝接受的要求，接着向他提出一个小一点的要求，那么他接受这个小要求的可能性，比直接向他提出这个小要求而被接受的可能性大得多，这种现象被称为门面效应。根据上述定义，下列情形符合门面效应的是（  ）","options":["商业谈判时，公司先提出一个较高的报价，后面不得已下调","和他人初步认识时不提过分要求，等到关系熟了后再提要求","小王想请两天假，他故意向领导说请5 天，领导说最多3 天","买菜时，老梁跟摊贩讨价还价，以双方都能接受的价格成交"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：提出一个很大而又易被拒绝接受的要求，接着向他提出\n一个小一点的要求；接受这个小要求的可能性，比直接向他提出这个小要求而被接受的可\n能性大得多。\nA 项，后面不得已下调，说明不是公司本来想提出的“小要求”，不符合定义，排\n除；\nB 项，初步认识时不提过分要求，等到关系熟了后再提要求，不符合接连提出两个要\n求，且没有体现“比直接提出小要求被接受的可能性提高”，不符合定义，排除；\nC 项，想请两天假是“小要求”，但没有直接提出，而是先提出请五天假这个“大要\n求”，使得最终“小要求被接受”，符合定义，当选；\nD 项，以双方都能接受的价格成交，最终价格不一定是双方本来的“小要求”，且讨\n价还价不符合接连提出两个要求，不符合定义，排除。\n故正确答案为C。"},{"q":"史华兹论断认为，所有的坏事情，只有在我们认为它是不好的情况下，才会真正成为不幸事件。面对挫败，是自暴自弃，让它成为不可逆转的事实，还是让它变成促使重新奋发的动力，取决人们的主观努力。能从坏中看好，积极对待，反而会有个好结果。根据上述定义，下列情形不符合史华兹论断的是（  ）","options":["大成眼睛失明，但他学习盲人按摩，成为职业技能大赛冠军","公司重奖对其服务投诉的消费者，获得了社会的普遍赞赏","出了生产事故后，车间进行整改，成为企业安全生产标兵","某企业出了质量丑闻后，积极自责自纠，最终却仍然倒闭"],"a":3,"e":"【答案】D\n【解析】定义判断，选非题，关键词：面对挫败；从坏中看好，积极对待，反而会有\n个好结果。\nA 项，眼睛失明是“坏事情”，但学习盲人按摩，成为职业技能大赛冠军是“积极对\n待”，重新奋发，最终取得“好结果”，符合定义，排除；\nB 项，服务投诉是“坏事情”，重奖投诉者，是“积极对待”，重新奋发，最终获得\n赞赏是“好结果”，符合定义，排除；\nC 项，出了生产事故是“坏事情”，车间进行整改，是“积极对待”，重新奋发，成\n为企业安全生产标兵，是“好结果”，符合定义，排除；\nD 项，出了质量丑闻是“坏事情”，虽然自责自纠，但倒闭不属于“好结果”，不符\n合定义，当选。\n故正确答案为D。"},{"q":"微商，一般是指以个人为单位的、利用web3.0 时代所衍生的载体渠道，将传统方式与互联网结合，不存在区域限制，且可移动地实现销售渠道新突破的小型个体行为。根据上述定义，以下属于微商的是（  ）","options":["某大型化妆品公司在微信账号上销售商品，吸引了一大批消费者","某眼镜店通过大力宣传吸引了许多年轻消费者进店购买","李某开的饭店为周边居民提供电话预定上门送外卖的服务","张某在市中心的服装店生意不错，他在微信上卖出的更多"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：以个人为单位；小型个体行为；利用web3.0 时代所衍\n生的载体渠道，将传统与互联网结合。\nA 项，某大型化妆品公司，不符合以个人为单位和小型个体行为，主体错误，不符合\n定义，排除；\nB 项，通过大力宣传吸引了许多年轻消费者进店购买，没有体现利用web3.0 时代所\n衍生的载体渠道，将传统与互联网结合，不符合定义，排除；\nC 项，电话订餐和上门送外卖的服务，没有体现利用web3.0 时代所衍生的载体渠\n道，将传统与互联网结合，不符合定义，排除；\nD 项，张某在市中心的的服装店符合以个人为单位，利用微信售卖属于以提供各种实\n惠服务为主，符合定义，当选。\n故正确答案为D。"},{"q":"组织学习，是指组织为了实现发展目标、提高核心竞争力而围绕信息或知识技能所采取的各种行动，是组织不断努力改变或重新设计自身以适应持续变化的环境的过程。根据上述定义，以下属于组织学习的是（  ）","options":["我国某大型国企派人学习科技课程","李明为了晋升去参加周末管理课程","某外企工作团队节假日去三亚度假","某集团组织新进员工开展户外拓展"],"a":0,"e":"【答案】A\n【解析】定义判断。关键词：组织；为了实现发展目标，提高核心竞争力；围绕信息\n或知识技能所采取的各种行动。\nA 项，某大型国企属于组织，派人学习科技课程属于围绕信息或知识技能所采取的行\n动，符合定义，当选；\nB 项，李明是个人，不是组织，主体错误，不符合定义，排除；\nC 项，度假的目的不是为了实现发展目标，也不属于围绕信息或知识技能所采取的行\n动，不符合定义，排除；\nD 项，开展户外拓展，不属于为了实现发展目标，提高核心竞争力，围绕信息或知识\n技能所采取的行为，不符合定义，排除。\n故正确答案为A。"},{"q":"赤潮，又称“红潮”。赤潮是海洋中一种或多种微小浮游植物、原生动物或细菌，在一定的环境条件下突发性迅速增殖或聚集，引起一定海域范围在一段时间内变色的自然生态现象。赤潮是一种海洋生物灾害。通常水体颜色因赤潮生物的数量、种类而呈红、黄、绿和褐色等。根据上述定义，以下最有可能属于赤潮现象的是（  ）","options":["我国长江中游多次发生水体变蓝现象","位于尼泊尔博克拉市区的贝格纳斯湖湖水曾变红","日本濑户内海、有明海等水域频繁发生水体变红","美国密西西比河部分水域发生洪灾，水中含大量泥沙"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：是海洋中一种或多种微小浮游植物、原生动物或细菌，\n在一定的环境条件下突发性迅速增殖或聚集；引起一定海域范围在一段时间内变色的自然\n生态现象。\nA 项，长江是河流，不是海洋，主体错误，不符合定义，排除；\nB 项，贝格纳斯湖是湖泊，不是海洋，主体错误，不符合定义，排除；\nC 项，内海、有明海属于海洋，频繁发生水体变红属于一定海域范围在一段时间内变\n色，符合定义，当选；\nD 项，水中含大量泥沙并没有引起一定海域范围在一段时间内变色，不符合定义，排\n除。\n故正确答案为C。"},{"q":"网络小说，是指由作者创作并首次在网络上发表，并以连载模式形成的小说。和传统小说相比，网络小说偏重于娱乐性和读者阅读时的体验。根据上述定义，以下属于网络小说的是（  ）","options":["小张将自己考研的坎坷经历写成文章发表在网上，很多考研的学生看过之后很受感动，转发次数上百万","小黄根据姥姥讲的民间故事，写了长篇灵异小说发表在网站上，每日更新，小说完结后出版社主动与小黄联系，打算出版","小金根据《西游记》绘制长篇连环画，每天在网上连载发表，受到很多网友的追捧","小姜将生活中的不文明现象写成一篇微小说发表在网上，电视台编导与他联系，想把他的小说拍摄成文明宣传片"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词：由作者创作并首次在网络上发表；并以连载模式形成的\n小说；偏重于娱乐性和读者阅读时的体验。\nA 项，将考研经历写成文章发表，不符合连载模式形成的小说，不符合定义，排除；\nB 项，根据姥姥讲的民间故事，写了长篇灵异小说符合由作者创作并首次在网络上发\n表，\n每日更新符合连载模式，灵异小说符合偏重于娱乐性和读者阅读时的体验，符合定\n义，当选；\nC 项，连环画不符合连载模式形成的小说，不符合定义，排除；\nD 项，将不文明现象写成一篇微小说没有体现以连载模式形成的小说，不符合定义，\n排除。\n故正确答案为B。"},{"q":"《科学技术期刊管理办法》对科技期刊的定义为：具有固定刊名、刊期、年卷或年月顺序编号、印刷成册、以报道科学技术为主要内容的连续出版物。这一定义限定了科技期刊的刊载内容、外观和出版方式。根据上述定义，以下属于科技期刊的是（  ）","options":["《中国首届砂石生产技术交流会论文集》","《青年文摘》","《哈尔滨工程大学学报》","《汽车新型光源科技研讨会会议纪要》"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：具有固定刊名、刊期、年卷或年月顺序编号；印刷成\n册；以报道科学技术为主要内容；连续出版物。\nA 项，《中国首届砂石生产技术交流会论文集》只是本届交流会论文的合集，不是连\n续出\n版物，不符合定义，排除；\nB 项，《青年文摘》是以青少年为读者受众群体的文摘刊物，不符合以报道科学技术\n为主要内容，不符合定义，排除；\nC 项，《哈尔滨工程大学学报》是理工科综合性学术期刊（月刊），符合定义，当\n选；\nD 项，《汽车新型光源科技研讨会会议纪要》是记录研讨会会议情况的公文，不符合\n连续出版物，不符合定义，排除。\n故正确答案为C。\n第十八组："},{"q":"异称词是指不同的社会群体，不同的地区或不同的时代对同一事物的不同称呼。依据上述定义，下列不属于异称词的是（  ）","options":["老一辈的人仍习惯把火柴称作“洋火”","明代时人们一般把蛤蟆称为癞施或田鸡","四川人说的红苕其实就是河南人说的红薯","现在售货员很多时候会称女顾客为“美女”"],"a":3,"e":"【答案】D\n【解析】定义判断，选非题。定义关键词：对同一事物的不同称呼。\nA 项，老一辈的人仍习惯把火柴称作“洋火”，属于对火柴这同一事物的不同称呼，\n符合定义，排除；\nB 项，明代时人们一般把蛤蟆称为癞施或田鸡，属于对蛤蟆这同一事物的不同称呼，\n符合定义，排除；\nC 项，四川人说的红苕其实就是河南人说的红薯，属于对红薯这同一事物的不同称\n呼，符合定义，排除；\nD 项，只出现一个社会群体，不符合不同的社会群体，不符合定义，当选。\n故正确答案为D。"},{"q":"自然界有这样一种现象：当一株植物单独生长时，显得矮小、单调，而与众多同类植物一起生长时，则根深叶茂，生机盎然，人们把类似植物界中这种相互影响、相互促进的现象，称为“共生效应”。根据上述定义，下列最符合共生效应的是（  ）","options":["亲小人，远贤臣，此后汉所以倾颓也","和狼生活在一起，你只能学会嚎叫；和那些优秀的人接触，你就会受到良好的影响","某品牌为摆脱个体经营的局限，采取连锁经营的方式扩大经营范围，销量随之大大提高","某大学一寝室，六名同学入学成绩有高有低，四年里六人每天结伴学习，最后都考上了重点大学的研究生"],"a":2,"e":"【答案】C\n【解析】定义判断。定义关键词：单独生长，显得矮小；众多同类一起生长，生机盎\n然；相互促进。\nA 项，后汉王朝覆灭的原因是亲小人远贤臣，没有体现出“相互促进”的现象，不符\n合定义，排除；\nB 项，比较的是和狼接触与和优秀的人接触的区别，比较两种“共同生长”的区别，\n并没有体现“单独生长”和“共同生长”的区别，不符合定义，排除；\nC 项，某品牌个体经营有局限，体现“单独生长，显得矮小”，连锁经营销量提高，\n体现“众多同类一起生长，生机盎然”，“相互促进”，符合定义，当选；\nD 项，只说明6 人结伴学习，未体现“单独生长，显得矮小”，不符合定义，排除。\n故正确答案为C。"},{"q":"霍桑效应是指由于受到额外的关注而引起努力或绩效上升的情况。根据上述定义，下列情形属于霍桑效应的是（  ）","options":["某公司经理经常给新招的员工发邮件，鼓励员工好好工作","初三学生小王因沉迷游戏学习成绩下滑，老师严肃批评了他，他很惭愧","某电气公司总裁常用“如果你想，你就可以”激励科研团队完成构想","数学教师常常私下称赞几名学生聪明，数月后这几人数学成绩均有不同程度的提高"],"a":3,"e":"【答案】D\n【解析】定义判断。定义关键词：受到额外的关注而引起努力或绩效上升。\nA 项，经理给新招的员工发邮件，未体现“引起努力或绩效上升”，不符合定义，排\n除；\nB 项，老师严肃批评了他，他很惭愧，未体现“引起努力或绩效上升”，不符合定\n义，排除；\nC 项，总裁鼓励科研团队，未体现“引起努力或绩效上升”，不符合定义，排除；\nD 项，老师私下夸学生，体现“额外的关注”，导致学生成绩有所提高，体现“引起\n努力或绩效上升”，符合定义,当选。\n故正确答案为D。"},{"q":"社会行为模式是指社会多数成员共同创造、认可或遵守的行为方式，是人们社会交往的结果，社会行为模式一旦形成，就具有重复性、稳定性和常规性，与群体共存，并由个人的具体行为表现出来。根据上述定义，下列不属于社会行为模式的是（  ）","options":["男耕女织","日出而作，日暮而归","尊老爱幼","宁为玉碎，不为瓦全"],"a":3,"e":"【答案】D\n【解析】定义判断，选非题。定义关键词：社会多数成员共同遵守的行为方式。\nA 项，男耕女织是古代男女分工的体现，体现“社会多数成员共同遵守的行为方\n式”，符合定义，排除；\nB 项，日出而作，日暮而归说的是多数人的普遍生产方式，体现“社会多数成员共同\n遵守的行为方式”，符合定义，排除；\nC 项，尊老爱幼是社会传统美德，得到社会成员的认可，体现“社会多数成员共同遵\n守的行为方式”，符合定义，排除；\nD 项，宁为玉碎，不为瓦全，表达的是个人的宁折不屈的态度，未体现“社会多数成\n员共同遵守的行为方式”，不符合定义，当选。\n故正确答案为D。"},{"q":"无意注意是指没有预定目的，无需意志努力，不由自主地对一定事物所发生的注意。无意注意时，心理活动对一定事物的指向和集中是由一些主观和客观条件所引起的。根据上述定义，下列不属于无意注意的是（  ）","options":["上课时学生突然被窗外飞进来的蝴蝶所吸引","肚子饿的小明一进房间就看见了桌上的面包","小红埋头完成家庭作业，不知不觉过了很久","人们在绿油油的草地上一眼就看到了小红花"],"a":2,"e":"【答案】C\n【解析】定义判断，选非题。定义关键词：没有预定目的；无需意志努力；不由自主\n地对一定事物所发生的注意。\nA 项，蝴蝶是突然飞进来的，符合“没有预定目的”，被蝴蝶吸引，符合“无需意志\n努力”，“不由自主地对一定事物所发生的注意”，符合定义，排除；\nB 项，小明进屋之前未预料到会有面包，符合“没有预定目的”，一进房间就看见面\n包，体现“无需意志努力”，“不由自主地对一定事物所发生的注意”，符合定义，排\n除；\nC 项，小红埋头完成家庭作业，写作业需要意志努力，不符合“无需意志努力”，完\n成作业是小红的目标，不符合“没有预定目的”，不符合定义，当选；\nD 项，人们之前未预料到草地上会有红花，符合“没有预定目的”，一眼就看到了小\n红花，符合“无需意志努力”，“不由自主地对一定事物所发生的注意”，符合定义，排\n除。\n故正确答案为C。"},{"q":"裂变思维是指在思考和解决问题时，不受已知的或现成的方式、规则和范畴的约束，从一个问题的中心点向外辐射发散，进行多方向、多角度、多层次的思维活动。根据上述定义，下列情形体现了裂变思维的是（  ）","options":["某屠宰场将牛肉分为肥肉和瘦肉，并分为牛腩、牛腱子、牛百叶、牛舌等出售","某公司研究人员设计制作了一种多功能文具盒，里面装有学生平时所用的大部分文具","潮汐时间每天向后推迟48 分钟，雀鲷鹭则每天推迟约50 分钟到海边觅食，因此它们总是海滩上的第一批食客","沙蚕在涨潮时，从沙滩里钻出来，在海水中觅食，落潮时就钻入沙滩里，某人在落潮时模仿海水涨潮的声音，捕捉到大量沙蚕"],"a":3,"e":"【答案】D\n【解析】定义判断。定义关键词：不受已知的或现成的规则的约束；从一个问题的中\n心点向外辐射发散。\nA 项，将牛肉细分部位出售，是根据人们需求市场需要的规则影响，不符合“不受已\n知的或现成的规则的约束”，不符合定义，排除；\nB 项，多功能文具盒在功能上进行改良，是根据学生的需要设计的，不符合“不受已\n知的或现成的规则的约束”，不符合定义，排除；\nC 项，雀鲷鹭一直在潮汐时间之后来觅食，觅食时间受到潮汐的影响，不符合“不受\n已知的或现成的规则的约束”，不符合定义，排除；\nD 项，某人在落潮时模仿沙蚕钻入沙滩里，不符常人的做法，属于“不受已知的或现\n成的规则的约束”，符合定义，当选。\n故正确答案为D。"},{"q":"“用名以乱实”指的是任意改变约定俗成的“名”（即概念）的界说和范围，扰乱人们对“实”（即客观事物本身）的认识。根据上述定义，下列属于“用名以乱实”的是（  ）","options":["杀盗人非杀人","马并非有四条腿，你见过海马有腿吗","我是这个小区的，小区的绿地是公共的，当然也是我的","没有所谓的高山和深渊，因为高原上的深渊比平原的高山还高"],"a":1,"e":"【答案】B\n【解析】定义判断。定义关键词：任意改变约定俗成的概念的范围；扰乱对客观事实\n本身的认识。\nA 项，意思是杀犯盗窃罪的人不同于杀一般无罪的人，所以不算杀人，“盗人”和\n“人”，本身讨论的就是两个概念之间的关系，所以不属于“改变约定俗成的概念的界说\n和范围”“扰乱对客观事物本身认识”，不符合定义，排除；\nB 项，海马本身并不属于马的概念，而这里让它们有联系，属于“改变约定成俗的概\n念的界说和范围”，你见过海马有腿吗，把海马归类于马，改变了马的“实”，属于“扰\n乱对马这个客观事物的认识”，符合定义，当选；\nC 项，小区的业主与小区的绿地，指代的都是小区的界说和范围，不属于“改变约定\n俗成的概念的界说和范围”，不符合定义，排除；\nD 项，将事物的实际状态进行比较得到结论，不属于“改变约定俗成的概念的界说和\n范围”，不符合定义，排除。\n故正确答案为B。"},{"q":"经济学中的鳄鱼法则，来源于这样一种场景认知：假定一只鳄鱼咬住你的脚，如果你用手去试图挣脱你的脚，鳄鱼便会同时咬住你的脚与手，你愈挣扎，就被咬住的越多，所以万一鳄鱼咬住了你的脚，你唯一的办法就是牺牲一只脚。根据上述定义，下列做法符合鳄鱼法则的是（  ）","options":["甲长期持有一支股票，两年翻了两番，最近走势涨跌不定，甲决定将这支股票抛售","丈夫乙有严重的心理疾患，经常喝酒之后暴打妻子丙，酒醒后又跪地认错，丙一次次原谅了乙","高某刚刚注册了一家公司，结果由于国家政策调整，公司原定投资方向不可能盈利，高某决定将公司注销","秦某报名参加一个考试的培训，发现老师上得并不好，管理也混乱，但是考虑到没有退款条约，还是坚持每天去上课"],"a":2,"e":"【答案】C\n【解析】定义判断。定义关键词：鳄鱼咬住你的脚；愈挣扎，就被咬住的越多；牺牲\n一只脚。即：不再挽回已损失的，而保护未损失的不被损坏，及时止损。\nA 项，走势涨跌不定，市场未确定是否有损失，未体现“鳄鱼咬住了脚，发生损\n失”，不符合定义，排除；\nB 项，妻子丙被暴打，体现“鳄鱼咬住了脚”，但丙一次次原谅了乙，不属于“牺牲\n一只脚，及时止损”，不符合定义，排除；\nC 项，公司原定投资方向不可能盈利，属于“鳄鱼咬住了脚，发生损失”，高某决定\n将公司注销，属于“牺牲一只脚，及时止损”，符合定义，当选；\nD 项，发现老师上得并不好，管理也混乱，属于“鳄鱼咬住了脚，发生损失”，但还\n是坚持去上课，不属于“牺牲一只脚，及时止损”，不符合定义，排除。\n故正确答案为C。"},{"q":"棘轮效应是人的消费习惯形成之后有不可逆性，即易于向上调整，而难于向下调整。根据上述定义，下列符合棘轮效应的是（  ）","options":["赵老师生意失败，变卖了公司资产和名下房产后，还欠银行20 多万元，但为了出行方便，他没有用自己的高档汽车抵债","李某买彩票中了500 万大奖后没有告诉任何人，偷偷把钱存到银行，还和从前一样正常上班、下班，而且工作更积极了","一夜暴富的老朱频繁出入高档消费场所，过着挥金如土的生活，很快就入不敷出，回到之前的生活状态，旁人都嘘唏不已，他自己却安之若素","王老汉从农村来城里带孙子，因心疼电费舍不得用空调，借口说不习惯空调吹出的冷风，让儿子买一台和老家一样的落地电风扇用来降温消暑"],"a":0,"e":"【答案】A\n【解析】定义判断。定义关键词：人的消费习惯易向上调整，而难向下调整。\nA 项，生意失败后，虽有欠款，但为了出行方便，他没有用自己的高档汽车抵债，属\n于“消费习惯难向下调整”，符合定义，当选；\nB 项，李某中奖之后继续上班，工作更积极，未体现“消费习惯的上调或下调”，不\n符合定义，排除；\nC 项，老朱一夜暴富挥金如土，符合“消费习惯向上调整”，但回到以前的状态也安\n之若素，说明消费习惯也可以向下调整，不属于“难于向下调整”，不符合定义，排除；\nD 项，王老汉从农村来城里带孙子，因心疼电费舍不得用空调，属于消费习惯难于向\n上调整，不属于“易于向上调整”，不符合定义，排除。\n故正确答案为A。"},{"q":"主观小量是指通过某些特殊的词语表达出来的，带有说话人认为数量小，程度低或时间短等主观色彩的现象，说话人的这种对数量、程度、时间的看法与数量、程度、时间本身的实际大小或高低没有必然联系。根据上述定义，下列不属于主观小量的是（  ）","options":["小张对小李说：“他们三个上次都没有来参加聚会。”","母亲对读高一的儿子说：“快了，你还有两年就毕业了。”","经理对员工小高说：“你工作不够努力，这个礼拜只加了两天班。”","校长对班主任说：“你们班怎么组织的？义务劳动才去了三十个人。”"],"a":0,"e":"【答案】A\n【解析】定义判断，选非题。定义关键词：通过特殊词语表达；带有说话人主观色\n彩。\nA 项，小张说三个上次都没有来，表述的是客观的事实，不符合“带有说话人主观色\n彩”，不符合定义，当选；\nB 项，母亲说的快了，还有两年毕业，符合“通过特殊词语表达”，表达的是妈妈认\n为儿子很快就毕业了，实际上两年时间并不短，符合“带有说话人主观色彩”，符合定\n义，排除；\nC 项，经理说这个礼拜只加了两天班，符合“通过特殊词语表达”，经理认为加班时\n间少，符合“带有说话人认为时间短的主观色彩”，符合定义，排除；\nD 项，校长说的义务劳动才去了三十个人，表达的校长认为参加活动的人数少，符合\n“通过特殊词语表达”，“带有说话人认为数量少的主观色彩”，符合定义，排除。\n故正确答案为A。\n第十九组："},{"q":"组织控制是指组织用各种规章制度和奖惩手段来约束组织成员行为，以保证组织的决策和指令能够有效地贯彻执行，维护组织的各项秩序。根据上述定义，下列最能体现组织控制的是（  ）","options":["某高校不断加强对外交流，派遣访问学者的名额逐年增加","某公司每年举办新人入职会，以便让新加入团队的成员忙熟悉环境","某生产厂商为了提高员工生产积极性，薪酬计算由原来的计时绩效改为计件绩效","某外企实行上班打卡制，如果员工去见客户可以不用打卡，但须在前一天向上级报告"],"a":3,"e":"【答案】D\n【解析】定义判断。关键词：目的为：“约束组织成员行为”。\nA 项，高校的目的为“加强对外交流”而非“约束组织成员行为”，不符合定义，排\n除；\nB 项，公司的目的为“让新加入团队的成员忙熟悉环境”而非“约束组织成员行\n为”，不符合定义，排除；\nC 项，生产厂商的目的为“提高员工生产积极性”而非“约束组织成员行为”，不符\n合定义，排除；\nD 项，“实行上班打卡制”就是约束成员的行为，符合定义，当选。\n故正确答案为D。"},{"q":"矩阵对策是指处于利益竞争的两个关系主体，各自可选的策略有限，且在一局对策中双方得失和为零的现象，即要不成功、要不失败。对策中，一方真正成功的措施应该是，针对对方所采取的行动相应地制定有利于自己的应对策略，各方选择的策略必定是自己对对方策略预测的最佳反应。根据上述定义，下列属于矩阵对策的是（  ）","options":["在进入奥运女子排球决赛后，某国家队重新安排队员阵容和出场顺序","齐王和田忌按原条件重新赛马，并约定每局比赛须用同等级的马参赛","劳资双方进行薪资谈判，经过反复的讨价还价，最终双方都作出让步","丈夫要去踢球，妻子要去看电影，儿子要去游乐园，最后三人去郊游"],"a":0,"e":"【答案】A\n【解析】定义判断。关键词：“处于利益竞争的两个关系主体”；“要不成功、要不\n失败”；“制定有利于自己的应对策略”。\nA 项，“排球决赛”即“处于利益竞争的两个关系主体”，决赛必然有胜有负，属于\n“要不成功、要不失败”，“重新安排阵容和出场顺序”属于“制定有利于自己的应对策\n略”，符合定义，当选；\nB 项，“每局比赛须用同等级的马参赛”已经制定好了规则，不符合“制定有利于自\n己的应对策略”，不符合定义，排除；\nC 项，“最终双方都作出让步”不符合“要不成功、要不失败”，不符合定义，排\n除；\nD 项，“丈夫、妻子、儿子”属于三个主体，不符合“处于利益竞争的两个关系主\n体”，不符合定义，排除。\n故正确答案为A。"},{"q":"签名效应是指当人们在纸上写下自己名字时，大脑中的自我意识会加强，此时看到喜欢的东西，更容易把物品和自己联系起来，产生“这个东西真适合我”等想法，从而激发购买欲望。根据上述定义，下列现象可用签名效应解释的是（  ）","options":["快递公司坚持“先签字后验货”的做法","采取实名捐款的办法能够募捐到更多善款","中介公司要求租客在看房前签订《看房协议书》","手术前，患者被要求在《知情同意书》上签字"],"a":2,"e":"【答案】C\n【解析】定义判断。关键词：“激发购买欲望”。\nA 项，快递公司先签字后验货，这个东西已经买了，不存在购买欲望，不符合定义，\n排除；\nB 项，“捐款”与“购买”无关，不符合定义，排除；\nC 项，中介公司要求租客看房前签协议，是为了激发租客租房子的欲望，符合定义，\n当选；\nD 项，手术签字与“购买”无关，不符合定义，排除。\n故正确答案为C。"},{"q":"角色混同指的是将自己所具有的不同角色相混淆，而发生的导致背离角色期待和角色规范的行为。根据上述定义，下列哪项属于角色混同（  ）","options":["老李是某局局长，对于儿子提出的要求，他常常不自觉地说：“这事得和其他同志研究研究。”为此，他多次受到妻子的批评","小王是个游戏迷，他常常将工作中的同事假想成游戏中的玩家，也常常将游戏中的玩家想象成自己的某个同事","庄周梦见自己变成蝴蝶，醒过来之后惊惶不一，庄周不知自己梦中变成了蝴蝶，还是蝴蝶梦中变成了自己","到北京来打工的某外省青年有时不自觉地说起家乡话，常常弄得同事莫名其妙"],"a":0,"e":"【答案】A\n【解析】定义判断。关键词：“所具有的不同角色相混淆”。\nA 项，老李即是“局长”，又是“父亲”，他与儿子说话用的是“局长”的角色，属\n于“所具有的不同角色相混淆”，符合定义，当选；\nB 项，小王将工作的同事假想成游戏的玩家，并非他自己所具有的角色，不符合定\n义，排除；\nC 项，庄周不知自己是蝴蝶还是自己，但是蝴蝶是他梦到的，而非他所具有的角色，\n不符合定义，排除；\nD 项，说家乡话与角色无关，不符合定义，排除。\n故正确答案为A。"},{"q":"红旗原则是指如果侵犯著作权的事实是显而易见的，网络服务商就不能装作看不见，或以不知道侵权的理由来推脱责任。根据上述定义，下列适用红旗原则的情形是（  ）","options":["未经用户许可，某客户端软件就能够自动扫描，获取用户个人数据","甲某利用网络服务商提供的免费存储空间，非法经营盗版影视作品","乙某上传正在首播的某热门电视剧，并被网站编辑推荐到下载首页","丙某通过第三方在有下载功能的互联网电视上获取未经授权的节目"],"a":1,"e":"【答案】B\n【解析】定义判断。关键词：“侵犯著作权”；“网络服务商”。\nA 项，“获取用户个人数据”属于侵犯个人隐私权，不符合“侵犯著作权”，排除；\nB 项，“非法经营盗版影视作品”属于“侵犯著作权”，并且提到了“网络服务\n商”，符合定义，当选；\nC 项，某热门电视剧被网站编辑推荐到下载首页，并没有提到其是“侵犯著作权”，\n不符合定义，排除；\nD 项，“获取未经授权”属于“侵犯著作权”，但其并没有提到“网络服务商”，不\n符合定义，排除。\n故正确答案为B。"},{"q":"研究表明，城市化率越高，消费需求就越多元化，消费时间就越长；发达城市人群60%以上的消费发生在夜间。据此，经济学界提出了“夜间经济”概念，即一种基于时段划分的商业形态，指从每日下午6 点到次日凌晨6 点所发生的三产服务业方面的商业活动，包括购物、餐饮、旅游、娱乐等。根据上述定义，以下属于夜间经济打造项目的是（  ）","options":["H 市计划打造9 条特色商业示范街区，并在街区内培育100 家连锁品牌商业企业","N 市今年的施政议题之一是让城市夜晚亮起来，人气聚起来，市民夜生活火起来","M 拟于今年年底前建成4 个能满足市民和国内外游客多元消费需求的地标型夜市","S 市围绕三处名胜古迹建设三条商业步行街，方便所有人昼夜购物、进餐、娱乐"],"a":2,"e":"【答案】C\n【解析】定义判断。定义关键词：从每日下午6 点到次日凌晨6 点；三产服务业方面\n的商业活动，包括购物、餐饮、旅游、娱乐等。\nA 项，特色商业示范街区,未明确体现运营时间，不符合定义，排除；\nB 项，让城市夜晚亮起来，属于城市亮化工程，是市政工程，不属于“商业活动”，\n不符合定义，排除；\nC 项，地标型夜市，符合营业时间为“下午6 点到次日凌晨6 点”，且满足游客消费\n需求，属于“三产服务业方面的商业活动”，符合定义，当选；\nD 项，商业步行街可以满足人民昼夜购物、进餐、娱乐，说明营业时间是白天和夜\n间，不只是“每日下午6 点到次日凌晨6 点”，不符合定义，排除。\n故正确答案为C。"},{"q":"近几年，大学生“慢就业”渐渐成为一种现象。慢就业是指一些大学生毕业后既不打算马上就业也不打算继续深造，而是暂时选择游学、支教、备考、社区服务、在家陪父母或者创业考察等，慢慢考虑人生道路的现象。根据上述定义，以下各位应届大学毕业生中哪位选择的不是慢就业（  ）","options":["张毅已开始北上广深游，打算边考察边学习边思考未来发展方向","李明正积极备考选调生、公务员和事业单位，直到考上一个为止","王莉在社区做义工，拟做到暑假结束，再去办理研究生入学手续","赵芳一直找不到理想工作，决定先在家陪陪父母，等待合适机会"],"a":2,"e":"【答案】C\n【解析】定义判断，选非题。定义关键词：大学生毕业后既不打算马上就业也不打算\n继续深造；暂时选择游学、支教、备考、社区服务、在家陪父母或者创业考察等。\nA 项，开始北上广深游，边考察边学习边思考未来发展方向，符合“既不打算马上就\n业也不打算继续深造”，属于“游学、创业考察”，符合定义，排除；\nB 项，准备几大考试，符合“既不打算马上就业也不打算继续深造”，属于“备\n考”，符合定义，排除；\nC 项，暑假结束，再去办理研究生入学手续，说明其将继续深造，不符合定义，当\n选；\nD 项，找不到理想工作，等待合适机会，符合“既不打算马上就业也不打算继续深\n造”，属于“在家陪父母”，符合定义，排除。\n故正确答案为C。"},{"q":"“C 位”是2018 年度十大网络用语之一。其中“C”有多种解释，最普遍的一种认为是英文单词center 的缩写，是中央、中心的意思。“C 位”一般指舞台中央或艺人在宣传海报的中间位置，现被引申为各种场合中最重要、最核心和最受关注的位置。根据上述定义，以下哪项表述没有涉及C 位（  ）","options":["专家合影时，德高望重的M 院士坐在中间位置","上海中心大厦高632 米位于上海市东部功能区","腾讯、阿里巴巴、百度是中国互联网核心企业","B 院士是我国量子通信研究领域的首席科学家"],"a":1,"e":"【答案】B\n【解析】定义判断，选非题。定义关键词：最重要、最核心和最受关注的位置。\nA 项，坐在中间位置，符合“最重要、最核心和最受关注的位置”，符合定义，排\n除；\nB 项，只说明了该大厦的高度和地理位置，未强调“最重要、最核心和最受关注”，\n不符合定义，当选；\nC 项，核心企业，体现了“最核心的位置”，符合定义，排除；\nD 项，首席科学家，体现了“最重要、最核心和最受关注的位置”，符合定义，排\n除。\n故正确答案为B。"},{"q":"随意后注意是注意的一种，是指一种自觉的、有预定目的的、不需要意志努力的注意。根据上述定义，下列属于随意后注意的是（  ）","options":["小明为买到某歌手的演唱会门票，熬夜关注网上售票信息","小红因故上课迟到了，在进门的时候，全班的人都看着她","小华不知不觉中被“夕阳西下，小桥流水”的美景所吸引","小亮在掌握了文言文知识后，主动开始欣赏古典文学名著"],"a":3,"e":"【答案】D\n【解析】定义判断。定义关键词：自觉的、有预定目的的、不需要意志努力。\nA 项，关注售票信息，说明“有预定目的的”，但熬夜关注，说明“需要意志努\n力”，不符合定义，排除；\nB 项，小红迟到了，全班人才会看她，对她的注意没有“预定目的”，不符合定义，\n排除；\nC 项，不知不觉被吸引，说明不是“自觉的、有预定目的的”，不符合定义，排除；\nD 项，主动欣赏文学名著，体现了“自觉的、有预定目的的”，且已掌握文言文知识\n再阅读名著是比较容易的，符合“不需要意志努力”，符合定义，当选。\n故正确答案为D。"},{"q":"所谓手段善，也可以称之为“结果善”，它表现为手段自身为恶，而结果通常为善，并且结果的善与自身的恶相减，净余额为善。依据上述定义，以下不属于手段善的是（  ）","options":["大风预警","外科手术","冬季冬泳","断尾求生"],"a":0,"e":"【答案】A\n【解析】定义判断，选非题。定义关键词：手段自身为恶；结果通常为善。\nA 项，大风预警是气象部门针对未来的恶劣天气做出的示警，提醒单位和个人做好预\n防措施，减少大风天气可能带来的灾害，未体现“手段自身为恶”，不符合定义，当选；\nB 项，外科手术一般指在体表进行切、割、缝，如脓肿引流、肿物切除、外伤缝合\n等，是一种破坏组织完整性（切开），或使完整性受到破坏的组织复原（缝合）的操作，\n体现了“手段自身为恶”，但手术后往往可使生病的人或动物恢复健康，体现了“结果通\n常为善”，符合定义，排除；\nC 项，冬泳会使身体收到强烈的刺激“手段自身为恶”，但冬泳可以强健体魄体现了\n“结果通常为善”，符合定义，排除；\nD 项，断尾指当壁虎、蜥蜴等动物被天敌咬住尾巴或遭遇危险的时候，往往会自断尾\n巴，断尾时往往会承受剧痛，体现了“手段自身为恶”，但通过断尾，牺牲局部，可以保\n全整体，延续生命，体现了“结果通常为善”，符合定义，排除。\n故正确答案为A。\n第二十组："},{"q":"生物识别技术，即通过计算机与光学、声学、生物传感器和生物统计学原理等高科技手段密切结合，利用人体固有的生理特性（如指静脉、人脸、虹膜、指纹等）和行为特征（如笔迹、声音、步态等）来进行个人身份的鉴定。根据上述定义，下列最可能运用了生物识别技术的是（  ）","options":["受害者在旁听了嫌疑人的数码电话录音后，确定了他就是当时的袭击者","警方在犯罪现场找到一张外卖送货小票，通过查询网上外卖订购系统信息，锁定了几个犯罪嫌疑人","某涉密场所设置了严格的门禁，人们只有在密码输入正确且在电阻屏上手写出具有进入权限的工作人员姓名后才能进入","某公司为考核员工出勤情况，引进了指纹打卡机，员工上班时必须输入指纹报到"],"a":3,"e":"【答案】D\n【解析】定义判断。定义关键词：计算机与高科技手段的结合；利用人体固有的生理\n特性（指静脉、人脸、虹膜、指纹等）和行为特征（笔迹、声音、步态等）进行个人身份\n的鉴定。\nA 项，数码电话录音，未体现使用“计算机”，不符合定义，排除；\nB 项，通过查询网上系统信息，未体现“计算机与高科技手段的结合”，且主要是通\n过查询订单来锁定嫌疑人，未体现“利用人体固有的生理特性和行为特征进行个人身份的\n鉴定”，不符合定义，排除；\nC 项，输入密码和书写电阻屏体现了“计算机与高科技手段的结合”，但输入密码正\n确未体现“利用人体固有的生理特性”，手写姓名只是判断姓名正确与否，并不是为了判\n断笔迹，未体现“利用人体固有的行为特征”，不符合定义；\nD 项，通过指纹打卡机鉴定身份，符合“通过计算机与高科技手段密切结合”、“利\n用人体固有的生理特征（指纹）”、“进行个人身份的鉴定”，符合定义，当选。\n故正确答案为D。"},{"q":"健康教育是为促进人们自发地、自觉地接受并采取有益于健康的行为与生活方式，根除或者减少对健康有影响的危险因素，预防疾病并达到促进身心健康和提高生活质量的目标而开展的有组织、有计划的系统的社会教育活动。根据上述定义，下列属于健康教育的是（  ）","options":["某公司在乡下举办健康知识讲座，并以此为机会向老人们推销保健品","某高校开设的一门“心理健康”选修课非常受同学们欢迎，甚至附近的市民都来蹭课","周日某医院组织医务人员在小区广场举行义诊活动，免费为居民提供测血压、量体温以及医疗咨询等服务","为防范入秋以来老年人心脑血管疾病高发的现象，社区每年9 月份都会聘请知名专家针对老年居民举行系列讲座，普及相关医疗知识"],"a":3,"e":"【答案】D\n【解析】定义判断。定义关键词：为促进人们自发地、自觉地接受并采取有益于健康\n的行为与生活方式；促进身心健康和提高生活质量；有组织、有计划的系统的社会教育活\n动。\nA 项，公司在乡下举办健康知识讲座的目的是为了向老人推销保健品，不属于“促进\n人们自发地、自觉地接受并采取有益于健康的行为与生活方式”，不符合定义，排除；\nB 项，高校开设心理健康的选修课是学校里正常的课程安排，不属于“社会教育活\n动”，不符合定义，排除；\nC 项，医院在小区进行义诊活动，免费提供测血压、量体温以及医疗咨询等是健康咨\n询、诊断服务，不属于“社会教育活动”，不符合定义，排除；\nD 项，为防范老年疾病，社区每年9 月份展开系列讲座，普及相关医疗知识，其目的\n是为了“促进人们自发地接受并采取有益于健康的行为与生活方式，达到促进身心健康和\n提高生活质量的目标”，同时满足“有组织、有计划的系统的社会教育活动”，符合定\n义，当选。\n故正确答案为D。"},{"q":"反客为主式营销，是指消费者基于对产品质量及企业文化价值的认同，借助网络工具，成为营销活动的主导者，主动发起营销活动或直接参与营销传播的一种新型的网络营销。根据上述定义，下列属于反客为主式营销的是（  ）","options":["某商场新开业，发起朋友圈积“赞”赢奖品活动，利用微信用户的网络传播达到了一定的营销效果","小泉是某手机品牌的忠实粉丝，最近该品牌又开发了一款智能手机，他第一时间购买了该手机，并在网上向朋友们宣传该手机的超凡性能","张阿姨根据网络电视广告购买了一款医疗保健品，使用后觉得效果好，她又把这款保健品介绍给了其他人","小丽兼职做微商卖化妆品，同事们为了照顾她的生意，纷纷帮她在网上转发销售广告"],"a":1,"e":"【答案】B\n【解析】定义判断，选非题。定义关键词：消费者基于对产品质量和企业文化价值的\n认同；借助网络工具；主动发起营销活动或直接参与营销传播。\nA 项，商场发起积赞赢奖活动，是一种奖励式的引导，不属于“消费者基于对产品质\n量和企业文化价值的认同”和“主动发起营销活动”，不符合定义，排除；\nB 项，小泉是某手机品牌的忠实粉丝，属于“对产品质量和企业文化价值的认同”，\n并借助网络主动宣传该手机性能，属于“借助网络工具”和“主动发起营销活动或直接参\n与营销传播”，符合定义，当选；\nC 项，张阿姨购买了一款医疗保健品，觉得很好，属于“消费者基于对产品质量和企\n业文化价值的认同”，直接把保健品介绍给其他人，没有借助网络，不属于“借助网络工\n具”进行宣传，不符合定义，排除；\nD 项，小丽兼职做微商卖化妆品，同事们只是为了照顾她生意帮她宣传，不属于“消\n费者基于对产品质量和企业文化价值的认同”进行主动宣传，不符合定义，排除。\n故正确答案为B。"},{"q":"甜柠檬效应就是个体在追求预期目标失败时，为了冲淡自己内心的不安，就百般提高现已实现的目标的价值，从而达到心理平衡的现象。根据上述定义，下列属于“甜柠檬效应”的是（  ）","options":["小明本来想买一台笔记本电脑，结果却在导购员的劝说下购买了平板电脑，使用后他很满意，并一直向朋友推荐","这几周，小红为自己的销售业绩不断下滑而苦恼；但当她知道自己仍是公司的销售状元时，变得放心多了","小文的数学成绩又让他的辅导老师失望了，老师最后只能用“比起上一次，还是有进步”来安慰自己","据教练估计，小张需要减肥到60 千克才能达到他想要的健身效果，可是小张在减到63 千克时就放弃了，因为他觉得自己足够健美了"],"a":2,"e":"【答案】C\n【解析】定义判断，选非题。关键词：个体追求预期目标失败；为冲淡内心的不安，\n百般提高已实现的目标价值，达到心理平衡。\nA 项，小明原计划买笔记本电脑后变成平板电脑，不属于“个体追求预期目标失\n败”，且他对平板电脑很满意，不属于“内心不安”，不符合定义，排除；\nB 项，小红业绩下滑属于“个体追求预期目标失败”，但”销售冠军“是客观事实，\n不属于“百般提高已实现的目标价值”，不符合定义，排除；\nC 项，老师对小文数学成绩的最初期望是考出一个好成绩，但小文的成绩让老师失望\n了，属于“个体追求预期目标失败”，为了让自己保持希望，老师通过比上一次有进步来\n安慰自己，属于“为冲淡内心的不安，百般提高已实现的目标价值，达到心理平衡”，符\n合定义，当选；\nD 项，教练认为小张减到60 千克才能达到效果，而这个60 千克的目标并不是小张本\n人的预期目标，小张减到自己满意的程度就停止了，不属于“个体追求预期目标失败”，\n不符合定义，排除。\n故正确答案为C。"},{"q":"横向交往和纵向交往是组织内员工通过人际互动构建社会资本过程的两种工具性交往风格。横向交往是指个体通过与自身周围社会地位相似的群体建立广泛联系的过程；纵向交往是指个体能动地与社会中占据主导资源支配的群体建立关系的过程。根据上述定义，下列属于纵向交往的是（  ）","options":["每到节假日，院长都会代表学院去慰问对学院作出巨大贡献的退休干部","老刘对自己家的保姆非常满意，为了让保姆过完春节后继续过来工作，他赠送了保姆探亲的往返机票","老张为了能够继续顺利地承包村里的鱼塘，主动和村民搞好关系，每年春节都给村民免费发放几条鱼","某家长为了让班级任课老师严格要求自己的孩子，节假日都会给老师们发去问候的短信"],"a":3,"e":"【答案】D\n【解析】定义判断，选非题。定义关键词：个体能动地；与社会中占据主导资源支配\n的群体建立关系。\nA 项，院长代表学院去慰问属于“个体能动地”，但这些干部已经退休，并没有占据\n学院主导资源支配权，不属于“社会中占据主导资源支配的群体”，不符合定义，排除；\nB 项，老刘赠送保姆机票属于“个体能动地”，但是保姆属于个人，与保姆搞好关\n系，未体现“与社会中占据主导资源支配的群体建立关系”，不符合定义，排除；\nC 项，老张通过免费发放鱼主动地和村民搞好关系，属于“个体能动地”，但村民和\n老张地位是相似的，都不担任社会重要职位，主要的并且引领村中事物发展的是村委会，\n村民不属于“社会中占据主导资源支配的群体”，不符合定义，排除；\nD 项，某家长节假日主动发短信和老师搞好关系，属于“个体能动地”，且老师在学\n校占据教育资源分配的主导地位，体现了“与社会中占据主导资源支配的群体建立关\n系”，符合定义，当选。\n故正确答案为D。"},{"q":"拟态，是指某些生物在进化过程中具有与另一种生物或周围自然界物体的相似的形态，这种相似性很高，几乎难以分辨，可以保护某一物种或两个物种。根据上述定义，下列选项属于拟态的是（  ）","options":["海豚、企鹅和带鱼虽然分别属于鲸类、鸟类和鱼类，但为了适应海洋生活，都进化出了流线形的身体","北极熊生活在白雪皑皑的北极，为了掩护自己捕食时不被猎物过早发现，皮毛逐渐变成与周围环境相似的白色","大鲵，俗名娃娃鱼，已在地球上生活了数亿年，其受到刺激时的叫声酷似人类婴儿哭声，让人听到不忍心伤害，对一些猎食动物也有威慑作用","杜鹃会将与宿主卵酷似的卵产在宿主巢内，其雏鸟在孵出后不久就会将宿主雏鸟挤出巢外，独享体型只有自己一半大小的宿主父母的喂食"],"a":3,"e":"【答案】D\n【解析】定义判断，选非题。定义关键词：在进化过程中具有与另一种生物或周围自\n然界物体的相似的形态相似性很高，几乎难以分辨；③可以保护某一物种或两个物种。\nA 项，海豚、企鹅和带鱼都进化出的流线形的身体，与周围自然界物体（即海洋环\n境）并不具备极大的相似性，很容易分辨，且三种动物并没有在进化过程中对彼此模仿，\n而是由于处于相同的环境中形成的相似形态，不符合定义，排除；\nB 项，北极熊的皮毛逐渐变为与周围的环境相似的白色，只是颜色发生变化，但形态\n并没有发生改变，这是北极熊的保护色，没有体现了“某些生物在进化过程中具有与另一\n种生物或周围自然界物体的相似的形态”，不符合定义，排除；\nC 项，娃娃鱼的哭声酷似婴儿哭声，声音不是形态，不属于“与另一种生物具有相似\n的形态”，不符合定义，排除；\nD 项，杜鹃产的卵与宿主卵酷似，符合“相似性很高，几乎难以分辨”，将宿主雏鸟\n挤出巢外符合“可以保护某一物种或两个物种”，符合定义，当选。\n故正确答案为D。"},{"q":"隐性饥饿，是指机体由于营养不平衡或者缺乏某种维生素及人体必需矿物质，同时又存在其他营养成分过度摄入，从而产生隐蔽性营养需求的饥饿症状。根据上述定义，下列属于隐性饥饿的是（  ）","options":["陈大爷下定决心节食，他最近以青菜和苹果代替主食，不沾油荤，终于有一天因饥饿难耐晕倒在地","小白为了获得健美身材，坚持每日六餐，每餐分量很少，分别含有主食、蔬果、蛋奶等，但同时高强度的健身训练还是让他浑身酸痛、疲惫不堪","王大爷因为肠胃虚弱，以清粥热汤作为主要饮食养生，不常吃大鱼大肉和生冷瓜果，后来因饮食缺少蛋白质和维他命而导致记忆力减退","小李喜欢高盐、高糖分、高热量的垃圾食品，对医生的劝说无动于衷，在数年后的体检中发现自己存在高血糖、高血脂、高血压等问题"],"a":2,"e":"【答案】C\n【解析】定义判断。定义关键词：由于营养不平衡或者缺乏某种维生素及人体必需矿\n物质，同时又存在其他营养成分过度摄入；产生隐蔽性营养需求的饥饿症状。\nA 项，陈大爷晕倒在地是因为节食，以青菜和苹果代替主食，不沾油荤，表现出饥饿\n症状，并非“产生隐蔽性营养需求的饥饿症状”，不符合定义，排除；\nB 项，小白浑身酸痛和疲惫不堪是因为高强度的健身训练，而不是“由于营养不平衡\n或者缺乏某种维生素及人体必需矿物质”，不符合定义，排除；\nC 项，王大爷记忆力减退是因为缺少蛋白质和维他命，体现了“缺乏某种维生素及人\n体必需矿物质”，记忆力减退属于“产生隐蔽性营养需求的饥饿症状”，符合定义，当\n选；\nD 项，小李存在三高问题并不是“缺乏某种维生素及人体必需矿物质”，不符合定\n义，排除。\n故正确答案为C。"},{"q":"谶纬之学即对未来的一种政治预言，谶纬本身并不是科学的，但受现实条件的局限，常被人们利用。根据上述定义，下列利用了谶纬之学的是（  ）","options":["大泽乡起义前，吴广在深夜模仿狐狸的声音大喊“大楚兴，陈胜王”","汉武帝在位期间拓西域，退匈奴，史学家们将“武”字巧妙地诠释为“止戈为武”，以此来称赞他为华夏赢得平稳发展时间的历史功绩","国外一些不法分子编写预言某时某地将发生地质灾难的藏头诗并发布在网络，以达到扰乱民心的效果","某位老人在家中财物被盗之后将自己的遭遇告诉了老李，老李看了老人手相后表示他还有大难，需要破财才能化解"],"a":0,"e":"【答案】A\n【解析】定义判断。定义关键词：对未来的一种政治预言；本身并不是科学的，但受\n现实条件的局限，常被人们利用。\nA 项，大楚兴，陈胜王，属于“对未来的政治预言”，这句话由狐狸喊出是“不科学\n的”，但受当时现实条件的局限，被陈胜、吴广所利用，符合定义，当选；\nB 项，史学家对汉武帝历史功绩的称赞，是对历史的总结，并不是“预言”，不符合\n定义，排除；\nC 项，不法分子散布谣言预测地震，是对地质情况的预言，并不是“政治预言”，不\n符合定义，排除；\nD 项，老李的预测，是对个人的预测，并不是“政治预言”，不符合定义，排除。\n故正确答案为A。"},{"q":"镶嵌，是指为了把话说得轻缓或郑重些，有时故意用几个无关紧要的字有规则地镶在一个词或语句里，一般以镶加虚词和数字最为常见。它可分为镶字、嵌字和拼字三类。镶字，指在词语中插进别的词以延长音节或强调语意，以镶加虚字和数字最为常见；嵌字，指将一句话或一组相关的词语分散插入不同的语句之中，使其隐晦曲折，精巧风趣，发人深思；拼字，指将联合词组中的两个词或合成词中的两个语素分开来间错使用。根据上述定义，下列属于拼字的是（  ）","options":["他比我学问高，但办起事来，我不输他一丝一毫","现在呀，老百姓过日子还是会精打细算、前思后想","一去二三里，烟村四五家，亭台六七座，八九十枝花","他们这一路嘻嘻哈哈、打打闹闹的，真是人老心不老啊"],"a":1,"e":"【答案】B\n【解析】定义判断。定义关键词：将联合词组中的两个词或合成词中的两个语素分\n开；间错使用。\nA 项，“一丝一毫”属于将词组“丝毫”中加数字“一”，目的是为了“延长音节或\n强调语意”，属于镶字，不符合定义，排除；\nB 项，“精打细算”“前思后想”属于将“精细”和“打算”、“前后”和“思想”\n分开，属于将“语素分开间错使用”，符合定义，当选；\nC 项，通过将“一二三、四五、六七、八九十”这些数字插入到不同语句当中，目的\n是为了“使其隐晦曲折，精巧风趣，发人深思”，属于嵌字，不符合定义，排除；\nD 项，“嘻嘻哈哈”和“打打闹闹”属于将“嘻哈”和“打闹”重复使用，但并未体\n现“间错使用”，不符合定义，排除。\n故正确答案为B。"},{"q":"沉默行为是指面对管理制度或生产活动等方面的隐患，为了避免人际冲突，害怕遭受打击报复或维护自身脸面等原因而有意保留自己想法的行为。根据上述定义，下列属于沉默行为的是（  ）","options":["小王看到同事小赵的计划书有个明显的错误而没有指出来，在接下来与小赵的评比中小王的计划方案获得通过","老张意识到小明最近老是上班时间唱歌已经影响到了别人工作，但考虑到他是自己的徒弟，老张不但不向领导报告，还和其他抱怨的同事争辩","尽管小马就如何提高顾客对公司服务的满意度有见解，由于前面发言的同事已经基本谈到该问题，所以小马也就没再接着说","小刘尽管在新产品开发报告会上有想法，但考虑到该想法尚不成熟，贸然提出可能会影响工作进度，因此在会上也就没发表意见"],"a":3,"e":"【答案】D\n【解析】定义判断。定义关键词：面对管理制度或生产活动等方面的隐患；为了避免\n人际冲突，害怕遭受打击报复或维护自身脸面等原因；有意保留自己想法。\nA 项，小王没有说出小赵计划书中的一处明显的错误，是想在接下来的评比中获得胜\n出，是为了自己能在竞争中保持优势才没有指出来，并不是为了“避免人际冲突，害怕遭\n受打击报复或维护自身脸面等”，不符合定义，排除；\nB 项，小明唱歌影响到别人，不属于“管理制度或生产活动等方面的隐患”，老张因\n小明是自己的徒弟去和同事争辩，表明其没有“避免人际冲突”，也不是“害怕遭受打击\n报复或维护自身脸面等”，且去争辩是直接表达了自己想法的行为，没有“保留自己想\n法”，不符合定义，排除；\nC 项，小马没有接着说是因为前面发言的同事已经基本谈到该问题，而不是“为了避\n免人际冲突，害怕遭受打击报复或维护自身脸面等”，不符合定义，排除；\nD 项，小刘对新产品有想法，说明他认为新产品的开发可能存在问题，属于“面对管\n理制度或生产活动等方面的隐患”，由于考虑到该想法尚不成熟，贸然提出可能会影响工\n作进度，符合“为了避免人际冲突或维护自身脸面”，没发表意见，说明“有意保留自己\n想法”，符合定义，当选。\n故正确答案为D。"}]}]};
